int* createStateList(int* states, int numStates, struct FSA* fsa, int lastIndex) {
    int* newStateList = (int*)malloc((numStates + 1) * sizeof(int));
    if (!newStateList) return NULL;

    for (int i = 0; i <= lastIndex; i++) {
        newStateList[i] = states[i];
    }

    struct FSA* current = &fsa;
    while (current->next) {
        current = current->next;
    }
    current->next = newStateList;

    return newStateList;
}
