int loadResourceBundle(const char* filePath) {
    int numItems = 0;
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        return -1; // Error opening the file
    }

    ResourceBundle bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        fclose(file);
        return -2; // Memory allocation error
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char* buffer = malloc(fileSize);
    if (buffer == NULL) {
        free(bundle);
        fclose(file);
        return -3; // Memory allocation error
    }

    fread(buffer, 1, fileSize, file);
    fclose(file);

    numItems = parseBundle(buffer, fileSize); // assuming a function to parse the bundle

    free(buffer);
    free(bundle);
    return numItems;
}

