char* appendSlash(char* str, int sizeLimit) {
    int len = strlen(str);
    char* result;

    if(len >= sizeLimit)
        return NULL;

    result = malloc(len + 2); // add 1 for the slash and 1 for the null terminator

    strcpy(result, str);
    result[len] = '/';
    result[len+1] = '\0';

    return result;
