#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 10

int main() {
    FILE *file = fopen("input.txt", "r");
    char *line = NULL;
    size_t line_len = 0;

    if (file == NULL) {
        printf("Error opening file.\n");
        return -1;
    }

    while (getline(&line, &line_len, file) != -1) {
        int i = 0;
        char *token = strtok(line, " ");
        double total = 0.0;

        for (; token != NULL; i++, token = strtok(NULL, " ")) {
            if (i >= MAX_FIELDS - 2)
                break;

            total += atof(token);
        }

        printf("%s", line);

        for (int j = 0; j < i; j++) {
            printf(", %s", strtok(line, " "));
        }

        double avg = (total / (double)(i)) * 2;
        printf(", %.2f\n", avg);

        free(line);
        line = NULL;
        line_len = 0;
    }

    free(line);

    fclose(file);
    return 0;
}
