typedef struct {
    int value;
    struct Node* left;
    struct Node* right;
} Node;

Node* insertOffset(Node* root, int offset) {
    if (root == NULL) {
        Node* newNode = malloc(sizeof(Node));
        newNode->value = offset;
        newNode->left = NULL;
        newNode->right = NULL;
        return newNode;
    }

    if (offset < root->value) {
        root->left = insertOffset(root->left, offset);
    } else if (offset > root->value) {
        root->right = insertOffset(root->right, offset);
    } else {
        // Offset already present in tree
        return root;
    }

    return root;
}

