typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TiffInfo;

TiffInfo parseTIFF(const char *filename) {
    TiffInfo info = {0, 0, 0};

    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        return (TiffInfo){.bitsPerSample=-1};
    }

    uint16_t sampleFormat = 0;
    TIFFGetField(tif, TIFF_FIELD_SAMPLEFORMAT, &sampleFormat);

    switch (sampleFormat) {
        case SAMPLE_FORMAT_BIT:
            info.bitsPerSample = TIFFGetFieldAsShort(tif, TIFF_FIELD_BITSPERSAMPLE);
            break;
        case SAMPLE_FORMAT_UCCD8:
        case SAMPLE_FORMAT_UCCD16:
            if (info.bitsPerSample != 8 && info.bitsPerSample != 16) {
                info.bitsPerSample = -1;
            }
            break;
        default:
            info.bitsPerSample = -1;
    }

    uint16_t samplesPerPixel = TIFFGetFieldAsShort(tif, TIFF_FIELD_SAMPLESPERPIXEL);
    info.samplesPerPixel = samplesPerPixel;

    int extraSamples = TIFFGetFieldAsShort(tif, TIFF_FIELD_EXTRASAMPLES);
    info.extraSamples = extraSamples;

    TIFFClose(tif);

    return info;
}
