int dns_resolution(const char *hostname, u_char **ip_address) {
    struct hostent *host;
    int error = 0;

    if ((host = gethostbyname(hostname)) == NULL) {
        error = 1; // Error occurred
        return error;
    }

    char *address = inet_ntop(AF_INET, (struct in_addr *)host->h_addr, NULL, 0);
    if (!address) {
        error = 2; // Error occurred
        return error;
    }

    size_t address_len = strlen(address);

    *ip_address = malloc((address_len + 1) * sizeof(char));
    if (*ip_address == NULL) {
        error = 3; // Memory allocation failed
        return error;
    }

    strcpy(*ip_address, address);
    free(address);

    return 0;
}
