#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int receive_file(char *filename, char *mode) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char buffer[1024];
    FILE *fp;

    // Create a UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set up server address
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(12345); // Replace with your port number

    inet_pton(AF_INET, "127.0.0.1", &(serv_addr.sin_addr)); // Localhost IP

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connection failed");
        return -1;
    }

    fp = fopen(filename, mode);
    if (!fp) {
        perror("file opening failed");
        close(sockfd);
        return -1;
    }

    while (1) {
        memset(buffer, '\0', sizeof(buffer));
        int bytes_received = recv(sockfd, buffer, 1024, 0);

        if (bytes_received < 0) {
            perror("recv failed");
            fclose(fp);
            close(sockfd);
            return -1;
        }
        else if (bytes_received == 0) {
            break; // Connection closed
        }

        fwrite(buffer, sizeof(char), bytes_received, fp);
    }

    fclose(fp);
    close(sockfd);

    return 0;
}

