#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    int string_count = 0;
    int total_strings = 0;

    size_t line_len = 0;
    char *line = NULL;

    while (getline(&line, &line_len, file) != -1) {
        if (*line == '!') {
            // Count the strings
            ++string_count;
        } else if (*line == '\'') {
            // Extract the string
            line++;
            size_t i = 0;
            for (; *line && *line != '\''; line++) {
                i++;
            }
            line++;
            char *str = malloc((i + 1) * sizeof(char));
            strncpy(str, line - i - 1, i);
            str[i] = '\0';
            total_strings++;
            free(str);
        } else if (*line == '\n' || *line == '\0') {
            // Ignore empty lines
            continue;
        }
    }

    free(line);

    fclose(file);
    return string_count + total_strings;
}
