#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    int lines = 0;
    FILE *input_file = NULL;
    FILE *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("This program reads input file line by line and counts the number of lines.\n");
            printf("It accepts command line options --manpage, -cs, and -o output_file.\n\n");
            exit(EXIT_SUCCESS);
        } else if (strcmp(argv[i], "-cs") == 0) {
            // code to handle -cs option
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            if (strlen(argv[i]) > 2) {
                output_file = fopen(&argv[i][2], "w");
                if (output_file == NULL) {
                    perror("Error opening output file");
                    exit(EXIT_FAILURE);
                }
            } else {
                printf("Error: -o option requires a filename.\n");
                exit(EXIT_FAILURE);
            }
        } else if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-cs] [-o output_file] input_file\n", argv[0]);
            exit(EXIT_SUCCESS);
        }

        if (strcmp(argv[i], "input.txt") != 0 && !strncmp(argv[i], "-o", 2)) {
            printf("Error: No input file provided.\n");
            printf("Usage: %s [-cs] [-o output_file] input_file\n", argv[0]);
            exit(EXIT_FAILURE);
        }

        if (strcmp(argv[i], "input.txt") == 0) {
            input_file = fopen(argv[i], "r");
            if (input_file == NULL) {
                perror("Error opening input file");
                exit(EXIT_FAILURE);
            }
        } else if (input_file != NULL && !strncmp(argv[i], "-o", 2)) {
            if (output_file != NULL) {
                fprintf(output_file, "%s\n", argv[i]);
            } else {
                printf("%s\n", argv[i]);
            }
        }

        if (input_file != NULL) {
            char line[1024];
            while (fgets(line, sizeof(line), input_file)) {
                lines++;
            }
            fclose(input_file);
        }

    }

    if (output_file != NULL) {
        printf("Number of lines: %d\n", lines);
        fclose(output_file);
    } else {
        printf("Number of lines: %d\n", lines);
    }

    return 0;
}
