int* expandArray(int* arr, int newSize) {
    int* newArr;

    // Calculate the total size needed
    int totalSize = sizeof(int) * (newSize > 0 ? newSize : (arr != NULL ? arr[0] : 1));

    // Dynamically allocate memory for new array
    newArr = (int*)malloc(totalSize);

    if (newArr == NULL)
        return NULL;

    // Copy elements from old array to new array, expanding as necessary
    if (arr != NULL) {
        int* src = arr;
        int* dst = newArr;

        for (int i = 0; i < newSize && i < (arr != NULL ? sizeof(int) * arr[0] : 1); i++) {
            *(dst + i) = *(src + i);
        }
    }

    // Free old array if it was not null
    if (arr != NULL)
        free(arr);

    return newArr;
}
