char* lexicalAnalyzer(char* str) {
    char tokens[] = {"int", "float", "+", "-", "*", "/", "%", "=", "<", ">=", "<=", ">",
                     "==", "!=", "&&", "||", "&", "|", "^", "~", "++", "--", "<<", ">>"};
