int compressTIFF(TIFF* tiff, uint8_t** buffer) {
    // Check if TIFF structure is valid
    if (!tiff) {
        return -1;
    }

    // Get the number of scanlines in the TIFF file
    uint32_t numScanlines = tiff->imageWidth * tiff->imageLength;

    // Create a new TIFF file for compressed data
    TIFF* compressedTIF = TIFFOpen("compressed.tif", "w");
    if (!compressedTIF) {
        return -1;
    }

    // Set the image dimensions and compression parameters in the new file
    compressedTIF->imageWidth = tiff->imageWidth;
    compressedTIF->imageLength = tiff->imageLength;

    for (uint32_t i = 0; i < numScanlines; i++) {
        uint8_t* scanline = buffer[i];
        // Reverse the order of pixels in each scanline
        for (int j = 0; j < tiff->imageWidth / 2; j++) {
            uint8_t temp = scanline[j];
            scanline[j] = scanline[tiff->imageWidth - 1 - j];
            scanline[tiff->imageWidth - 1 - j] = temp;
        }

        // Compress and write the scanline to the new file
        if (TIFFWriteScanline(compressedTIF, buffer[i], i) != 0) {
            TIFFClose(compressedTIF);
            return -1;  // Compression failed
        }
    }

    // Free memory allocated for the buffer
    for (uint32_t i = 0; i < numScanlines; i++) {
        free(buffer[i]);
    }
    free(*buffer);

    // Close the new file
    TIFFClose(compressedTIF);
    return 0;
}
