void parse_ip_options(unsigned char *packet, int len) {
    unsigned short opt_len;
    unsigned char *options = (unsigned char *) packet + sizeof(struct ip);
    while(len >= 4) {
        opt_len = *(unsigned short *) options;
        if(opt_len < 2 || len < opt_len + 2)
            break;
        if(opt_len & 1)
            opt_len = ((opt_len >> 1) * 2) + 2;
        printf("Option type: %x, length: %d\n", *(unsigned char *) (options+2), opt_len);
        options += opt_len;
        len -= opt_len;
    }
}
