struct DownstreamHost {
    char* hostname;
    int dataPort;
    int healthPort;
};

struct HostsAndPorts {
    int numDownstreamHosts;
    struct DownstreamHost** downstreamHosts;
};

struct HostsAndPorts parseHostsAndPorts(const char* hostsAndPortsStr) {
    struct HostsAndPorts result = {0, NULL};
    const char* currentHost = hostsAndPortsStr;
    int numDownstreamHosts = 0;

    while (*currentHost != '\0') {
        if (*currentHost == '\n' || *currentHost == '\r') {
            // new host
            struct DownstreamHost* downstreamHost = (struct DownstreamHost*)malloc(sizeof(struct DownstreamHost));
            char* hostname = strsep(&currentHost, ':');
            int dataPort = atoi(strsep(&currentHost, ':'));
            int healthPort = atoi(strsep(&currentHost, '\0'));
            downstreamHost->hostname = strdup(hostname);
            downstreamHost->dataPort = dataPort;
            downstreamHost->healthPort = healthPort;

            if (result.downstreamHosts == NULL) {
                result.downstreamHosts = (struct DownstreamHost**)malloc(sizeof(struct DownstreamHost*));
            } else {
                struct DownstreamHost** temp = (struct DownstreamHost**)realloc(result.downstreamHosts, sizeof(struct DownstreamHost*) * ++numDownstreamHosts);
                result.downstreamHosts = temp;
            }
            result.downstreamHosts[numDownstreamHosts - 1] = downstreamHost;
        } else {
            // still parsing current host
            currentHost++;
        }
    }

    result.numDownstreamHosts = numDownstreamHosts;

    return result;
}

