int calculate_average_size(int num_blocks, int** block_sizes) {
    int total_size = 0;
    for (int i = 0; i < num_blocks; i++) {
        total_size += block_sizes[i][0];
    }
    int average_size = total_size / num_blocks;

    // Reserve space for random characters
    int reserved_size = average_size * 0.1;

    // Calculate the size of the distribution array
    int distribution_size = (average_size + reserved_size) * 100;

    return distribution_size;
}

int* allocate_distribution_array(int distribution_size) {
    return (int*)malloc(distribution_size * sizeof(int));
}
