bson* lua_to_bson(lua_State *L) {
    bson* doc = bson_new();
    int top2 = lua_gettop(L);
    if (top2 < 2) return NULL;

    switch (lua_tointeger(L, -2)) {
        case 10:
            bson_append_null(doc, "bsontype", NULL);
            break;
        case 11: {
            lua_pushvalue(L, -2);
            lua_pushstring(L, "([0-9]+)");
            int regex = luaL_loadstring(L, "-1");
            lua_insert(L, -2);
            lua_getfield(L, -1, "match");
            char* pattern = luaL_checkstring(L, -1);
            bson_append_regex(doc, "bsontype", NULL, pattern, 0);
            break;
        }
    }

    bson_finish(doc);
    return doc;
}
