```c
int parse_font_spec(char **spec) {
    if (*spec == NULL || **spec == '\0') return 0;

    // Skip over leading hyphens
    while (**spec == '-') (*spec)++;

    char *token = strtok(*spec, " -");
    if (token == NULL) return 0; // No font type face

    int font_type_face = 0; // Assume default font type face (e.g. serif)
    for (char *c = token; *c != '\0'; c++) {
        if (*c >= 'a' && *c <= 'z') font_type_face |= (1 << ('a' - *c));
    }

    token = strtok(NULL, " -");
    int font_style = 0; // Assume default font style (e.g. normal)
    for (char *c = token; *c != '\0'; c++) {
        if (*c >= 'a' && *c <= 'z') font_style |= (1 << ('a' - *c));
    }

    token = strtok(NULL, " -");
    int font_size = 0;
    while (token) {
        char *end = NULL;
        font_size = strtol(token, &end, 10);
        if (*end != '\0') break; // Not a number
        return font_type_face | (font_style << 8) | font_size;
    }

    return 0; // Invalid font specification
}

