void init_uart(void) {
    UBRR1H = (UBRR1H & 0xF0) | (25 << 4);
    UBRR1L = 25;
    UCSR1B = (UCSR1B & ~((1<<RXEN)|(1<<TXEN))) | (1<<TXEN)|(1<<RXEN);
}

int main(void) {
    init_uart();

    char data[] = "Hello, UART!";
    int len = strlen(data);

    for(int i=0; i<len; i++) {
        while (!(UCSR1A & (1 << UDRE)));
        UDR1 = data[i];
    }

    while (!(UCSR1A & (1 << RXC))) {}
    char received;
    received = UDR1;

    while(received != '\0') {
        while (!(UCSR1A & (1 << RXC))) {}
        received = UDR1;
    }

    return 0;
}
