TIGValue* concatenateStrings(TIGValue* str1, int index, TIGValue* str2) {
    int len1 = strlen(str1->value);
    int len2 = strlen(str2->value);

    TIGValue* result = malloc(sizeof(TIGValue));
    result->type = TYPE_STRING;
    char* buffer = malloc((len1 + 1 + len2) * sizeof(char));

    for (int i = 0; i < index && i < len1; i++) {
        buffer[i] = str1->value[i];
    }

    int j = 0, k = index;
    while (j < len1 || k < len2) {
        if (j < len1) {
            buffer[k++] = str1->value[j++];
        }
        if (k < len2) {
            buffer[k] = str2->value[k - len2];
            k++;
        }
    }

    buffer[len1 + len2] = '\0';
    result->value = buffer;
    return result;
}

