struct scheduler *scheduler_init(int num_threads, int *thresholds, size_t threshold_size, void (*cpu_assign)(int), pthread_mutex_t *mutex) {
    struct scheduler *sched = malloc(sizeof(struct scheduler));
    if (!sched) return NULL;

    sched->threads = malloc(num_threads * sizeof(pthread_t));
    if (!sched->threads) {
        free(sched);
        return NULL;
    }

    sched->thresholds = malloc(threshold_size * sizeof(int));
    if (!sched->thresholds) {
        free(sched->threads);
        free(sched);
        return NULL;
    }

    memcpy(sched->thresholds, thresholds, threshold_size * sizeof(int));

    sched->cpu_assign = cpu_assign;
    sched->mutex = mutex;

    for (int i = 0; i < num_threads; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, NULL, NULL) != 0) {
            free(sched->threads);
            free(sched->thresholds);
            free(sched);
            return NULL;
        }
        sched->threads[i] = thread;
    }

    return sched;
}

