uint8_t packet_data[256]; // assume maximum packet size of 256 bytes
uint16_t checksum = 0;
int awaiting_ack = 0;

void transmit_packet() {
    for (size_t i = 0; i < sizeof(packet_data); i++) {
        // assuming serial transmission function here, replace with your own
        serial_transmit(packet_data[i]);
    }

    // calculate and send checksum
    uint16_t calc_checksum = 0;
    for (size_t i = 0; i < sizeof(packet_data); i++) {
        calc_checksum += packet_data[i];
    }
    serial_transmit((uint8_t)(calc_checksum >> 8));
    serial_transmit((uint8_t)calc_checksum);

    awaiting_ack = 1;
}
