typedef struct {
    char** strings;
    int size;
    int count;
} Stack;

Stack* create_stack() {
    Stack* s = (Stack*)malloc(sizeof(Stack));
    s->strings = NULL;
    s->size = 1;
    s->count = 0;
    return s;
}

void push_string(Stack* s, char* str) {
    if(s->count >= s->size) {
        int new_size = s->size * 2 + 1;
        char** temp = (char**)realloc(s->strings, sizeof(char*) * new_size);
        for(int i = s->size; i < new_size; i++) {
            temp[i] = NULL;
        }
        s->strings = temp;
        s->size = new_size;
    }

    if(s->strings[s->count]) free(s->strings[s->count]);
    s->strings[s->count] = (char*)malloc(strlen(str) + 1);
    strcpy(s->strings[s->count], str);
    s->count++;
}

void print_stack(Stack* s) {
    for(int i = 0; i < s->count; i++) {
        printf("%s\n", s->strings[i]);
    }
}
