typedef struct {
    char* hostname;
    int port;
} Server;

Server** splitServers(char* servers) {
    char* token = strtok(servers, ",");
    Server** serverList = NULL;
    int size = 0;

    while(token != NULL) {
        Server* server = (Server*)malloc(sizeof(Server));
        char* colonPos = strchr(token, ':');
        if(colonPos == NULL || colonPos[1] == '\0') {
            free(server);
            return NULL;
        }
        *colonPos = '\0';
        server->hostname = token;
        server->port = atoi(&colonPos[1]);
        token = strtok(NULL, ",");
        serverList = (Server**)realloc(serverList, sizeof(Server*) * ++size);
    }

    return serverList;
}

