void* encryption(int flag, void *arr1, int len1, void *arr2, int len2, void *res, int len_res) {
    unsigned char *a = (unsigned char *)arr1;
    unsigned char *b = (unsigned char *)arr2;
    unsigned char *r = (unsigned char *)res;

    if(flag == 0x01) {
        for(int i = 0; i < len1 && i < len2; i++) {
            r[i] = a[i] ^ b[i];
        }
    } else if(flag == 0x02) {
        for(int i = 0; i < len1; i++) {
            if(i + 1 < len1)
                r[i] = a[i+1];
            else
                r[i] = a[0];
        }
    } else if(flag == 0x04) {
        for(int i = 0; i < len1 && i < len2; i++) {
            r[i] = a[i] & b[i];
        }
    } else if(flag == 0x08) {
        for(int i = 0; i < len1; i++) {
            int temp = (int)a[i];
            temp = (temp >> 1) | ((temp & 1) << 7);
            r[i] = (unsigned char)temp;
        }
    } else if(flag == 0x10) {
        for(int i = 0; i < len1; i++) {
            int temp = (int)a[i];
            temp = ((temp << 1) | (temp >> 7)) & 0xFF;
            r[i] = (unsigned char)temp;
        }
    }

    return res;
}
