char* process_input(char* input) {
    char* stack = (char*)malloc(1000);
    if (!stack) {
        return NULL;
    }
    char* stack_top = stack;
    int line_len = strlen(input);

    for(int i=0; i<line_len; i++) {
        *stack_top++ = input[i];
    }

    *stack_top++ = '\n';
    *stack_top = '\0'; // null-terminate the string

    char* token = strtok(stack, " ");
    if(token == NULL) {
        return stack;
    }

    int arg_count = 1; // function name is always first argument
    for (; token != NULL; token = strtok(NULL, " ")) {
        arg_count++;
    }

    *stack_top++ = '(';
    *stack_top++ = '\0'; // null-terminate the string

    return stack;
}
