cl_command_queue createCommandQueue(cl_context context, cl_device_id deviceID) {
    cl_int status;
    cl_command_queue queue;

    // Check if the device supports command queues
    size_t infoSize = 0;
    clGetContextInfo(context, CL_CONTEXT_INFO_STATUS_ONLY, 0, NULL, &infoSize);
    char *contextInfo = (char *)malloc(infoSize);
    clGetContextInfo(context, CL_CONTEXT_INFO_STATUS_ONLY, infoSize, contextInfo, NULL);

    // Create the command queue
    status = clCreateCommandQueue(context, deviceID, 0, &queue);
    if(status < 0) {
        free(contextInfo);
        return NULL;
    }

    free(contextInfo);
    return queue;
}
