char* replace_substrings(char** str, char* fmt) {
    int len = strlen(*str);
    int fmt_len = strlen(fmt);
    char* result = malloc(len + fmt_len + 1);
    char* res_pos = result;
    char* str_pos = *str;

    while (*str_pos != '\0') {
        if (strncmp(str_pos, fmt, fmt_len) == 0) {
            int i;
            for (i = 0; i < fmt_len; i++) {
                *(res_pos++) = *(fmt + i);
            }
            str_pos += fmt_len;
        } else {
            *(res_pos++) = *str_pos;
            str_pos++;
        }
    }

    *(res_pos) = '\0';
    *str = result;
    return *str;
}

