struct pollfd* dynamic_pollset(int initial_size) {
    int new_size = initial_size;
    struct pollfd* old_set = NULL;
    struct pollfd* new_set;

    while (1) {
        new_set = realloc(NULL, sizeof(struct pollfd) * new_size);
        if (!new_set)
            return NULL; // error

        if (old_set) {
            memcpy(new_set, old_set, sizeof(struct pollfd) * initial_size);
            free(old_set);
        }
        else {
            new_set[0].fd = -1;
            new_set[0].events = 0;
            new_set[0].revents = 0;
        }

        old_set = new_set;

        if (new_size == initial_size)
            break;

        initial_size *= 2; // double the size
    }

    return old_set;
}

