fun ste_lambda_expression_bindings(tree) {
  let lambda_entry = {type: 'RHO_FUNCTION', children: []};
  let bindings = {};

  // Register variable bindings
  for (let child in tree.children) {
    if (child.type == 'IDENT') {
      let ident_name = child.name;
      let binding_value = child.value;
      bindings[ident_name] = binding_value;
      ste_register_ident(ident_name, binding_value);
    }
  }

  // Add lambda entry as child of current syntax tree entry
  tree.children.push(lambda_entry);

  // Set current syntax tree entry to the new lambda entry
  tree = lambda_entry;

  // Register bindings from node
  register_bindings_from_node(tree, tree.left_child);

  // Set current syntax tree entry to parent of the new lambda entry
  tree = tree.parent;
}

