#include <md5.h>
#include <stdio.h>

char* generateSharedSecret(const char* inputString, int timestamp, unsigned long entropy) {
    MD5_CTX ctx;
    unsigned char buffer[1024];
    char secret[33];
    int i = 0;

    // Initialize the MD5 context
    MD5_Init(&ctx);

    // Add the input string to the hash
    MD5_Update(&ctx, inputString, strlen(inputString));

    // Add the timestamp to the hash
    unsigned char* timestampBytes = (unsigned char*) &timestamp;
    for (int j = 0; j < 4; j++) {
        MD5_Update(&ctx, timestampBytes + j, 1);
    }

    // Add the entropy value to the hash
    unsigned char* entropyBytes = (unsigned char*) &entropy;
    for (int j = 0; j < sizeof(unsigned long); j++) {
        MD5_Update(&ctx, entropyBytes + j, 1);
    }

    // Get the final hash
    MD5_Final(buffer, &ctx);

    // Convert the hash to a hexadecimal string
    for (i = 0; i < 16; i++) {
        sprintf(secret + i*2, "%02x", buffer[i]);
    }
    secret[32] = '\0';

    return strdup(secret);
}

