char* formatData(void* addr, size_t size, int type, char* fmt) {
    if (size > (size_t)4096) {
        return "Error: Data size exceeds available memory";
    }

    char* result = malloc(size + 1);
    if (!result) {
        return "Error: Memory allocation failed";
    }

    switch (type) {
        case 0: // int
            for (size_t i = 0; i < size; i++) {
                int val;
                memcpy(&val, addr, sizeof(int));
                sprintf(result + i * sizeof(int), fmt, val);
            }
            break;
        case 1: // char*
            strcpy(result, (char*)addr);
            break;
        default:
            return "Error: Unknown data type";
    }

    result[size] = '\0';
    return result;
}

