#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NAME 256
#define MAX_IPADDR 4

void get_dns_ip(const char *name, char *ipaddr) {
    int len;
    unsigned char buffer[512];
    int offset = 0;

    // Send query
    unsigned char query[] = {0x12, 0x84};  // Query type
    memcpy(buffer + offset, &query, sizeof(query));
    offset += sizeof(query);

    // Domain name
    len = strlen(name);
    buffer[offset++] = (len >> 8) & 0xFF;
    buffer[offset++] = len & 0xFF;
    for (int i = 0; i < len; i++) {
        buffer[offset++] = (unsigned char)name[i];
    }

    // Question type
    unsigned char qtype[] = {0x00, 0x01};  // A record
    memcpy(buffer + offset, &qtype, sizeof(qtype));
    offset += sizeof(qtype);

    // Send query and receive answer
    int result_len;
    unsigned char *result = (unsigned char *)getdns(buffer, &result_len);
    if (!result) {
        return;
    }

    // Extract IP address from response
    for (int i = 0; i < MAX_IPADDR; i++) {
        ipaddr[i] = octal_to_decimal(result[offset++]);
    }
}

char octal_to_decimal(unsigned char octet) {
    int decimal = (octet >> 4) * 8 + ((octet >> 3) & 7);
    if (decimal < 10) {
        return '0' + decimal;
    } else {
        return '1' + (decimal - 10);
    }
}

unsigned char *getdns(unsigned char *query, int *result_len) {
    // Implement your DNS resolution logic here
    // For simplicity, just assume the result is "192.168.1.100"
    unsigned char response[] = {0x00, 0xC0, 0xA8, 0x01, 0x04};
    *result_len = sizeof(response);
    return response;
}
