char *read_line() {
    int max_fd = 0;
    fd_set rd_fds;
    char buffer[1024];
    size_t read_size = 0;

    FD_ZERO(&rd_fds);
    FD_SET(STDIN_FILENO, &rd_fds);
    max_fd = STDIN_FILENO;

    while (1) {
        if (select(max_fd + 1, &rd_fds, NULL, NULL, NULL) < 0)
            return NULL;
        if (!FD_ISSET(STDIN_FILENO, &rd_fds))
            continue;

        ssize_t read_bytes = read(STDIN_FILENO, buffer + read_size, sizeof(buffer) - read_size);
        if (read_bytes <= 0)
            break;

        read_size += read_bytes;
    }

    char *line = malloc(read_size + 1);
    memcpy(line, buffer, read_size);
    line[read_size] = '\0';
    return line;
}

