char* extractTime(char* str) {
    char* start = str;
    while (*str != '\0' && (*str < '0' || *str > '9')) {
        str++;
    }
    if (*str == '\0') return NULL; // no time value found

    char time[20] = {0};
    int len = 0;

    for (; *str != '\0'; str++) {
        if (isdigit(*str)) {
            time[len++] = *str;
        } else if (*str == '+' || *str == '-') {
            break;
        }
    }

    time[len] = '\0';

    char* colon = strrchr(time, ':');
    if (colon) {
        *colon = '\0';
        colon++;
    }

    int hours = atoi(strtok(time, ":"));
    int minutes = atoi(strtok(NULL, ":"));
    int seconds = atoi(strtok(NULL, ":"));

    if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59 || seconds < 0 || seconds > 59) {
        return NULL; // invalid time value
    }

    char* result = (char*)malloc(9);
    sprintf(result, "%02d:%02d:%02d", hours, minutes, seconds);

    return result;
}

