char* currentLine;
int bytesRead;
int lineCapacity = 256;
int linePosition;

void pushBack(char* buffer) {
    int i;
    for(i = linePosition; i > 0; i--) {
        buffer[i] = buffer[i-1];
    }
    bytesRead -= strlen(buffer);
    linePosition--;
}

char* getNextLine(char* file, char* buffer) {
    if (bytesRead > 0) {
        pushBack(buffer);
    }

    bytesRead = 0;
    linePosition = 0;

    currentLine = fgets(buffer, lineCapacity, file);

    if (currentLine == NULL) {
        return NULL;
    }

    buffer[strcspn(currentLine, "\n")] = '\0'; // remove the newline character
    bytesRead = strlen(buffer);
    linePosition = bytesRead;

    while (linePosition < lineCapacity - 1 && buffer[linePosition] != '\n' && buffer[linePosition] != '\r') {
        linePosition++;
    }

    if (buffer[linePosition - 1] == '\n' || buffer[linePosition - 1] == '\r') {
        buffer[linePosition++] = '\0'; // add the null character
    } else {
        buffer[lineCapacity - 1] = '\0'; // add the null character
        linePosition++;
    }

    return currentLine;
}
