    int opt;
    extern char *optarg;
    extern int optind;

    static int verbose = 0;
    static int quiet = 0;
    static char **files = NULL;
    static int file_count = 0;

    while ((opt = getopt(argc, argv, "vq")) != -1) {
        switch(opt) {
            case 'v':
                verbose = 1;
                break;
            case 'q':
                quiet = 1;
                break;
        }
    }

    argc -= optind;
    argv += optind;

    for(int i = 0; i < argc; i++) {
        files = (char **) realloc(files, (file_count + 2) * sizeof(char *));
        files[file_count] = strdup(argv[i]);
        file_count++;
    }

    sqlite3_initialize();
}
