char** createHttpRequest(char* verb, char* path, char* version) {
    int requestLen = strlen(verb) + strlen(path) + strlen(version) + 3; // 3 for " ", "\n", and NULL
    char** request = (char**)malloc((requestLen + 1) * sizeof(char*));
    if (!request) return NULL;
    char temp[requestLen];
    sprintf(temp, "%s %s HTTP/%s\n", verb, path, version);
    char** tokens = strtok_r(temp, " ", &temp);
    int i = 0;
    while (tokens != NULL && i < requestLen) {
        request[i++] = malloc(strlen(tokens) + 1);
        strcpy(request[i - 1], tokens);
        tokens = strtok_r(NULL, " ", &temp);
    }
    request[i] = NULL; // null-terminate the array
    return request;
}

