```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 100
#define NUM_OF_ATHLETES 5

typedef struct {
    char code[MAX_SIZE];
    int hours;
} Athlete;

Athlete athletes[NUM_OF_ATHLETES] = {
    {"A001", 10},
    {"A002", 20},
    {"A003", 30},
    {"A004", 40},
    {"A005", 50}
};

void searchAthlete(char* code) {
    int i;
    for (i = 0; i < NUM_OF_ATHLETES; i++) {
        if (strcmp(athletes[i].code, code) == 0) {
            printf("Code: %s\nHours: %d\n", athletes[i].code, athletes[i].hours);
            return;
        }
    }
    printf("Athlete not found.\n");
}

void addAthlete() {
    Athlete newAthlete;
    printf("Enter code: ");
    scanf("%s", newAthlete.code);
    printf("Enter hours: ");
    scanf("%d", &newAthlete.hours);

    // Add the athlete to the array
    int i;
    for (i = 0; i < NUM_OF_ATHLETES; i++) {
        if (strcmp(athletes[i].code, newAthlete.code) == 0) {
            printf("Code already exists. Please choose another.\n");
            return;
        }
    }

    // Add the athlete to the end of the array
    for (i = NUM_OF_ATHLETES - 1; i > 0; i--) {
        athletes[i] = athletes[i - 1];
    }
    athletes[0] = newAthlete;

    printf("Athlete added successfully.\n");
}

void updateHours() {
    char code[MAX_SIZE];
    int hours;
    Athlete* athlete;

    printf("Enter code: ");
    scanf("%s", code);

    // Find the athlete
    int i;
    for (i = 0; i < NUM_OF_ATHLETES; i++) {
        if (strcmp(athletes[i].code, code) == 0) {
            athlete = &athletes[i];
            break;
        }
    }

    if (i >= NUM_OF_ATHLETES) {
        printf("Athlete not found.\n");
        return;
    }

    printf("Enter new hours: ");
    scanf("%d", &hours);
    athlete->hours = hours;

    printf("Hours updated successfully.\n");
}

int main() {
    int choice;
    while (1) {
        printf("1. Search for an athlete\n");
        printf("2. Add a new athlete\n");
        printf("3. Update hours of an existing athlete\n");
        printf("4. Quit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                char code[MAX_SIZE];
                printf("Enter code: ");
                scanf("%s", code);
                searchAthlete(code);
                break;
            case 2:
                addAthlete();
                break;
            case 3:
                updateHours();
                break;
            case 4:
                return 0;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}
```

This program uses a simple array to store the athletes' information. It allows the user to search for an athlete by code, add a new athlete, or update the hours of an existing athlete. The `searchAthlete` function finds and prints the details of an athlete with a given code. The `addAthlete` function adds a new athlete to the end of the array. The `updateHours` function updates the hours of an existing athlete.

Note that this program does not handle cases where the user tries to add or update an athlete whose code is already in use. You might want to add error checking for such situations, depending on your requirements.

