```c
#include <openssl/aes.h>
#include <openssl/err.h>
#include <string.h>

EVP_CIPHER_CTX* aes256_cbc_init(const char* password, int password_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_MD* sha1_md = EVP_sha1();
    unsigned char password_hash[EVP_MAX_MD_SIZE];
    unsigned int password_hash_len;
    if (1 != EVP_Digest(password, password_len, password_hash, &password_hash_len, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    const EVP_CIPHER* aes256_cipher = EVP_aes_256_CBC();
    int key_length = aes256_cipher->block_size * 4;

    unsigned char* derived_key = OPENSSL_malloc(key_length);
    if (!derived_key) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    memcpy(derived_key, password_hash, password_hash_len > key_length ? key_length : password_hash_len);

    if (1 != EVP_SealInit(ctx, aes256_cipher, derived_key, &key_length, NULL, 0, NULL)) {
        OPENSSL_free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));
    if (1 != EVP_SealUpdate(ctx, NULL, NULL, iv, sizeof(iv))) {
        OPENSSL_free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_CIPHER_CTX_set_key_length(ctx, key_length)) {
        OPENSSL_free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (!EVP_CIPHER_CTX_set_iv_length(ctx, sizeof(iv))) {
        OPENSSL_free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, aes256_cipher, derived_key, iv, NULL)) {
        OPENSSL_free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void aes256_cbc_cleanup(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
