int** create_matrix(int* array, int m, int n) {
    int size = sizeof(int*) * (m + 1);
    int** matrix = (int**)malloc(size);

    #pragma omp parallel
    {
        int id = omp_get_thread_num();
        int num_threads = omp_get_num_threads();

        int block_size = (n + num_threads - 1) / num_threads;
        int start = id * block_size;
        int end = min((id + 1) * block_size, n);

        for (int i = 0; i < m; i++) {
            matrix[i] = (int*)malloc(sizeof(int) * n);
            for (int j = start; j < end; j++) {
                matrix[i][j] = array[i * n + j];
            }
        }
    }

    return matrix;
}
