#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* generate_dns_response(char* buffer, int num_services) {
    int offset = 0;
    for (int i = 0; i < num_services; i++) {
        // Copy service name into the buffer
        strcpy(buffer + offset, "service.name.");
        offset += strlen("service.name.") + 1;

        // Create a pointer record with TTL 4 minutes
        *(uint16_t*)(buffer + offset) = htons(0x000a); // Type: PTR
        *(uint16_t*)(buffer + offset + 2) = htons(0x0104); // Class: IN
        *(uint32_t*)(buffer + offset + 4) = htonl(259200); // TTL: 4 minutes
        *(uint32_t*)(buffer + offset + 8) = htonl((offset + 12)); // Pointer to the name
        offset += 12;
    }
    return buffer;
}

