int encode_data(void *buffer, int *fd, int flag) {
    void (*encoder)(void *, void *) = ...; // specify your encoding function here
    size_t length = 0;
    char *encoded_buffer = NULL;

    if (encoder == NULL || buffer == NULL || fd == NULL) {
        return -1;
    }

    encoded_buffer = malloc(1024);
    if (encoded_buffer == NULL) {
        return -1;
    }

    (*encoder)(buffer, &length, encoded_buffer);

    if (write(*fd, encoded_buffer, length) < 0) {
        free(encoded_buffer);
        return -1;
    }

    free(encoded_buffer);

    if (!flag) {
        return length;
    }

    char *modified_encoded_buffer = malloc(length);
    if (modified_encoded_buffer == NULL) {
        return -1;
    }

    for (size_t i = 0; i < length; ++i) {
        modified_encoded_buffer[i] = encoded_buffer[i] + rand() % 256;
    }

    if (write(*fd, modified_encoded_buffer, length) < 0) {
        free(modified_encoded_buffer);
        return -1;
    }

    free(modified_encoded_buffer);

    return length;
}
