int execute_prepared_statement(const char *prepare_sql, ...) {
    MYSQL_STMT *stmt;
    MYSQL_ROW row;
    int num_rows;
    int column_count;
    unsigned long *lengths;

    // Initialize MySQL connection (not shown)
    if (mysql_init() != 0) {
        return -1;
    }

    // Prepare the statement
    stmt = mysql_prepare_stmt(conn, prepare_sql);
    if (!stmt) {
        return -1;
    }

    va_list(ap);
    va_start(ap);

    column_count = mysql_num_fields(stmt);
    lengths = (unsigned long*)malloc(column_count * sizeof(unsigned long));

    for (int i = 0; i < column_count; i++) {
        switch (mysql_field_type(stmt, i)) {
            case MYSQL_TYPE_INT:
                mysql_stmt_bind_param(stmt, &(va_arg(ap, int)));
                break;
            case MYSQL_TYPE_STRING:
                mysql_stmt_bind_param(stmt, &(va_arg(ap, char*)));
                break;
            // Add more types as needed...
        }
    }

    va_end(ap);

    // Execute the statement
    if (mysql_stmt_execute(stmt) != 0) {
        return -1;
    }

    num_rows = mysql_stmt_num_rows(stmt);
    while ((row = mysql_stmt_fetch_result(stmt)) && num_rows > 0) {
        // Process the row data...
        num_rows--;
    }

    free(lengths);

    // Close the statement
    mysql_stmt_close(stmt);

    return num_rows;
}

