#include <numpy/arrayobject.h>
#include <numpy/ndarraytypes.h>

static PyObject *
npqueeze(PyObject *self, PyObject *args) {
    int axis;
    PyArrayObject *arr;
    PyArrayObject *result;

    if (!PyArg_ParseTuple(args, "Oi", &arr, &axis)) {
        return NULL;
    }

    if (axis < 0 || axis >= arr->nd) {
        PyErr_SetString(PyExc_ValueError, "axis is out of bounds");
        return NULL;
    }

    int new_nd = arr->nd - 1;
    PyObject *dtype = PyArray_DescrFromType(arr->typecode);
    if (!dtype) {
        return NULL;
    }

    result = (PyArrayObject *)PyArray_Newshape((PyObject *)arr, &new_nd, NULL);
    if (!result) {
        return NULL;
    }

    int i;
    for (i = 0; i < arr->dimensions[axis]; i++) {
        PyArray_CopyTo(result, arr, axis + 1, i, arr->stride[axis], arr->subarray);
    }

    Py_XDECREF(dtype);

    return (PyObject *)result;
}
