int count_files(char *dir, char *format) {
    DIR *dp;
    struct dirent *entry;
    int count = 0;

    if ((dp = opendir(dir)) == NULL)
        return -1; // error opening directory

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue; // skip dot directories
        char path[1024];
        sprintf(path, "%s/%s", dir, entry->d_name);
        if (is_directory(path)) {
            count += count_files(path, format); // recursive call for subdirectories
        } else {
            FILE *fp;
            if ((fp = fopen(path, "r")) == NULL)
                continue; // error opening file

            char buffer[1024];
            while (fread(buffer, 1, sizeof(buffer), fp) > 0) {
                if (strstr((char *)buffer, format) != NULL)
                    count++;
            }
            fclose(fp);
        }
    }

    closedir(dp);
    return count;
}

int is_directory(char *path) {
    struct stat statbuf;
    if (stat(path, &statbuf) == -1)
        return 0; // error checking file status

    return S_ISDIR(statbuf.st_mode);
}
