char* generatePath(char* directoryPath, char* prefix, int maxSize) {
    int pathLen = strlen(directoryPath) + strlen(prefix);
    char* newPath = (char*)malloc((pathLen > maxSize ? maxSize : pathLen) + 1);

    if (!newPath) return NULL;

    strcpy(newPath, directoryPath);
    strcat(newPath, prefix);
    while (strlen(newPath) >= maxSize) {
        int idx = strlen(newPath) - 1;
        while (idx > 0 && newPath[idx] != '/') idx--;
        if (idx < 0) return NULL; // no '/' found
        newPath[idx] = '\0';
    }

    return newPath;
}

