    FILE *file;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <num_frames> <output_file>\n", argv[0]);
        return 1;
    }

    num_frames = atoi(argv[1]);
    file = fopen(argv[2], "w");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    int i;
    for (i = 0; i < num_frames; i++) {
        fprintf(file, "%d\n", i);
        fflush(file); // flush to see progress
        if (i % 10 == 0) { // every 10 frames, print progress meter
            printf("\rGenerated %d frames...", i);
            if (!fflush(stdout)) { // print newline if error
                perror("Error printing progress");
            }
        }
    }

    printf("\nGenerated %d frames.\n", num_frames);

    fclose(file);
    return 0;
}

