void* traverse_directory(char* root_dir) {
    DIR* dir;
    struct dirent* ent;
    char full_path[1024];
    void* result = NULL;

    if (root_dir && *root_dir != '/') {
        // relative path, make it absolute
        sprintf(full_path, "/%s", root_dir);
        root_dir = full_path;
    }

    dir = opendir(root_dir);
    if (dir) {
        while ((ent = readdir(dir))) {
            if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, ".."))
                continue;

            sprintf(full_path, "%s/%s", root_dir, ent->d_name);

            if (ent->d_type == DT_DIR) {
                result = traverse_directory(full_path);
            }

            if (!result)
                break;
        }
        closedir(dir);
    } else {
        // error handling
    }

    return result;
}
