int parse_file_names(char *buffer, struct filename_info **filenames) {
    char line[1024];
    int line_num = 0;
    while (fgets(line, sizeof(line), buffer)) {
        line[strlen(line) - 1] = '\0'; // remove newline
        if (strchr(line, '/') && strchr(line, '\\')) {
            struct filename_info *info = malloc(sizeof(struct filename_info));
            info->name = strsep(&line, "/\\");
            info->length = strlen(info->name);
            if (info->length <= 255) {
                (*filenames)++; // increment pointer
                (**filenames) = info;
            } else {
                free(info);
            }
        }
    }
    return 0;
}

