#include <unistd.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int* setup_socket(int protocol, char* path, char* name) {
    int sock = socket(AF_INET, SOCK_STREAM, protocol);
    if (sock < 0) {
        return NULL;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(atoi(name));
    inet_pton(AF_INET, path, &addr.sin_addr);

    int timeout = 5000; // in milliseconds
    setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, (void*) &timeout, sizeof(int));
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, (void*) &timeout, sizeof(int));

    return &sock;
}
