    OLEDMessage message_queue[10]; // assume max 10 messages
    int queue_head; // index of the first message in the queue
    int queue_tail; // index of the last message in the queue
} OLEDDisplay;

void processFormInput(char* form_input, OLEDDisplay* display) {
    char query_string[MAX_QUERY_STRING_LENGTH];
    char* query_string_ptr = query_string;
    int query_string_length = 0;

    for (int i = 0; i < strlen(form_input); i++) {
        if (form_input[i] == '&') {
            query_string[query_string_length] = '\0';
            query_string_length = 0;
        } else if (query_string_length < MAX_QUERY_STRING_LENGTH - 1) {
            query_string[query_string_length++] = form_input[i];
        }
    }

    // process the query string here...

    OLEDMessage message;
    strcpy(message.message, "Query received: ");
    strcat(message.message, query_string);
    strcat(message.message, "\0");

    if (display->queue_tail >= 10) {
        display->queue_head = display->queue_tail = 0; // reset queue
    } else {
        display->message_queue[display->queue_tail] = message;
        display->queue_tail++;
    }
