EVP_CIPHER_CTX* generateKeyFromPassword(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_MD* md = EVP_sha256();
    const EVP_PBE_ALGOR* pbe_algor = EVP_aes_256_cbc();

    if (EVP_PBE_CipherInit(ctx, pbe_algor, password, strlen(password), 1) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_PBE_CipherUpdate(ctx, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_PBE_key ctxKey = EVP_PBE_get_key(ctx);
    EVP_CIPHER_CTX_free(ctx);

    return (EVP_CIPHER_CTX*)ctxKey;
}
