void initialize_adapter(int fd) {
    struct ifreq ifr;
    const char *adapter_name = "eth0"; // replace with your adapter name

    // Initialize and reset adapter
    ioctl(fd, SIOCGIFFLAGS, &ifr);
    ifr.ifr_flags &= ~(IFF_UP | IFF_RUNNING);
    ioctl(fd, SIOCSIFFLAGS, &ifr);

    // Clear link configuration flags
    ioctl(fd, SIOCETHTOOL, &ifr);
    ifr.ifr_data.ether_addr[0] = 0;
    ioctl(fd, SIOCSIFLINKSTATE, &ifr);

    // Reset SFP initialization
    ioctl(fd, SIOCSFSPEED, &ifr);

    // Ensure adapter is properly configured and ready for use
    ioctl(fd, SIOCGIFFLAGS, &ifr);
    ifr.ifr_flags |= IFF_UP;
    ioctl(fd, SIOCSIFFLAGS, &ifr);
}
