#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

void *huge_page_map(void *addr) {
    int fd = open(sprint("huge_file_%d", getpid()), O_RDWR | O_CREAT | O_NOATIME, 0644);
    if (fd == -1) return (void *)-1;

    struct stat sb;
    fstat(fd, &sb);
    off_t size = sb.st_size;
    if (ftruncate(fd, huge_page_size())) {
        close(fd);
        return (void *)-1;
    }

    void *mapped_addr = mmap(addr, huge_page_size(), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_addr == MAP_FAILED) {
        close(fd);
        return (void *)-1;
    }

    unlink(sprint("huge_file_%d", getpid()));
    close(fd);
    return mapped_addr;
}
