#include <stdlib.h>
#include <stdio.h>

typedef struct {
    char* name;
    void (*func)(void*, size_t);
    void* param1;
    size_t param2;
} HashCipher;

HashCipher* get_cryptographic_functions() {
    static const HashCipher hashfunctions[] = {
        {"SHA-256", &SHA256, NULL, 0},
        {"SHA-512", &SHA512, NULL, 0},
        {"AES", &AES_encrypt, NULL, 0},
        {"DES", &DES_ecb_encrypt, NULL, 0}
    };

    static const HashCipher ciphers[] = {
        {"RSA", &rsa_public_encrypt, NULL, 0},
        {"Blowfish", &bf_cbc_encrypt, NULL, 0}
    };

    HashCipher* result;
    size_t i;

    // Check for availability
    for (i = 0; i < sizeof(hashfunctions) / sizeof(hashfunctions[0]); i++) {
        if (!hashfunctions[i].name) continue;
    }
    for (i = 0; i < sizeof(ciphers) / sizeof(ciphers[0]); i++) {
        if (!ciphers[i].name) continue;
    }

    // Make sure there are at least some available
    result = malloc((i + 1) * sizeof(HashCipher));
    if (!result) return NULL;

    // Copy the available ones into the result array
    for (size_t j = 0; j < i; j++) {
        result[j] = hashfunctions[j];
        if (j >= sizeof(hashfunctions) / sizeof(hashfunctions[0])) {
            result[j].name = "RSA";
            result[j].func = &rsa_public_encrypt;
            result[j].param1 = NULL;
            result[j].param2 = 0;
        }
    }

    return result;
}

