void *openssl_operation(char *str, int option) {
    EVP_CIPHER_CTX* ctx;
    void *cipher;

    if (option == 1) { // encryption
        ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb8(), NULL, str, strlen(str));
        cipher = EVP_CIPHER_CTX_get_cipher_ctx(ctx);
    } else if (option == 2) { // decryption
        ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cfb8(), NULL, str, strlen(str));
        cipher = EVP_CIPHER_CTX_get_cipher_ctx(ctx);
    }

    return cipher;
}
