void traverse_dir(const char *dir_path, void (*callback)(const char *)) {
    DIR *dir;
    struct dirent *ent;

    dir = opendir(dir_path);
    if (dir == NULL) return;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char full_path[PATH_MAX];
        sprintf(full_path, "%s/%s", dir_path, ent->d_name);

        if (ent->d_type == DT_DIR) {
            if (callback != NULL)
                callback(full_path);
            traverse_dir(full_path, callback);
        } else if (ent->d_type == DT_REG || ent->d_type == DT_UNKNOWN) {
            if (callback != NULL)
                callback(full_path);
        }
    }

    closedir(dir);
}

