void manage_wifi_power(struct wifi_module *module) {
    FILE *fp = fopen(module->power_file, "r+");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    fseek(fp, 0, SEEK_SET);
    int power_state;
    fread(&power_state, sizeof(int), 1, fp);
    printf("Current Wi-Fi module power state: %s\n", power_state ? "On" : "Off");

    int new_state;
    while (1) {
        printf("Enter 0 to turn off or 1 to turn on: ");
        scanf("%d", &new_state);

        if (fseek(fp, 0, SEEK_SET) != 0) {
            perror("Error seeking file position");
            break;
        }

        fwrite(&new_state, sizeof(int), 1, fp);
        fclose(fp);
        return;
    }
}

