#include <stdint.h>
#include <arpa/inet.h>

int send_ethernet_packet(uint16_t type, uint8_t* data, uint16_t dlen) {
    // Create Ethernet header
    uint8_t eth_header[14];
    eth_header[0] = 0xFF; // Destination MAC address (broadcast)
    eth_header[1] = 0xFF;
    eth_header[2] = 0xFF;
    eth_header[3] = 0xFF;
    eth_header[4] = 0xFF;
    eth_header[5] = 0xFF; // Source MAC address
    eth_header[6] = 0x00;
    eth_header[7] = 0x11;
    eth_header[8] = (type >> 8) & 0xFF;
    eth_header[9] = type & 0xFF;

    // Pad data with zeros to a maximum size of 18 bytes
    uint16_t padding_len = 18 - dlen;
    for(int i = 0; i < padding_len; i++) {
        *(data + dlen + i) = 0x00;
    }

    // Create IP header
    uint8_t ip_header[20];
    ip_header[0] = 0x45; // Version (4) and Header Length (5)
    ip_header[1] = 0x00;
    ip_header[2] = 0x00;
    ip_header[3] = 0x01; // TOS
    ip_header[4] = 0x11; // Total Length
    uint16_t total_len = dlen + padding_len + 20;
    ip_header[5] = (total_len >> 8) & 0xFF;
    ip_header[6] = total_len & 0xFF;
    ip_header[7] = 0x00; // Identification
    ip_header[8] = 0x00;
    ip_header[9] = 0x00;
    ip_header[10] = 0x06; // Flags and Fragment Offset (0) + (0)
    ip_header[11] = 0x00;
    ip_header[12] = 0x01; // TTL
    ip_header[13] = 0x07; // Protocol (1 - ICMP, 2 - IGMP, 6 - TCP, 17 - UDP)
    uint16_t checksum = 0x0000;
    for(int i = 14; i < 18; i++) {
        checksum += ip_header[i];
    }
    ip_header[16] = (checksum >> 8) & 0xFF;
    ip_header[17] = checksum & 0xFF;

    // Send the packet
    return sendto(...); // Replace with actual socket and address sending code
}
