size_t insert_string(const char *str, size_t pos, const char *sub) {
    size_t str_len = strlen(str);
    size_t sub_len = strlen(sub);

    if (pos > str_len || pos + sub_len > str_len + 1) {
        return -1; // error: position or substring too long
    }

    char *new_str = malloc((str_len + sub_len + 1) * sizeof(char));
    if (!new_str) {
        return -1; // error: memory allocation failed
    }

    memcpy(new_str, str, pos);
    memcpy(new_str + pos, sub, sub_len);
    memcpy(new_str + pos + sub_len, str + pos, str_len - pos);

    free(str);
    new_str[str_len + sub_len] = '\0';

    return str_len + sub_len;
}
