typedef struct {
    int x;
    int y;
    int lifetime;
    struct blob *next;
} Blob;

Blob *create_blob() {
    Blob *new_blob = (Blob *)malloc(sizeof(Blob));
    new_blob->x = rand() % 10;
    new_blob->y = rand() % 10;
    new_blob->lifetime = rand() % 5 + 1;
    new_blob->next = NULL;
    return new_blob;
}

void update_list(Blob **head, int max_living) {
    Blob *current = *head;
    Blob *prev = NULL;
    while (current != NULL) {
        if (current->lifetime > 0) {
            current->lifetime--;
            if (current->lifetime == 0) {
                if (prev == NULL) {
                    *head = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current);
            } else {
                prev = current;
                current = current->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
}
