#include <openssl/sha.h>
#include <string.h>

int verify_sha1(const unsigned char *buffer, size_t len, const unsigned char *ref) {
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, buffer, len);
    SHA1_Final(hash, &ctx);

    for (int i = 0; i < SHA_DIGEST_LENGTH; i++) {
        if (hash[i] != ref[i]) return 0;
    }

    return 1;
}
