    cublasCreate(&handle);

    // Matrix multiplication
    float alpha = 1.0f, beta = 0.0f;
    cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k,
                &alpha, A, m, B, k, &beta, C, m);

    // Free memory
    cudaFree(A);
    cudaFree(B);
    cudaFree(C);
    cublasDestroy(handle);

    return 0;
}
