    for (int i = 0; i < numVertices; i++) {
        printf("Vertex %d: ", i);
        for (int j = 0; j <= *(((int **)graph)[i]); j++) {
            if (j > 0) {
                printf("%d -> ", j - 1);
            }
        }
        printf("\n");
    }
}

void modifyVertex(int **graph, int numVertices) {
    int v;
    printf("Enter the vertex number to modify: ");
    scanf("%d", &v);
    if (v >= 0 && v < numVertices) {
        int e;
        printf("Enter the new edge weight: ");
        scanf("%d", &e);
        (*((int **)graph)[v]) = e;
    } else {
        printf("Invalid vertex number.\n");
    }
}

void insertVertex(int **graph, int *numVertices, int maxEdges) {
    int v1, v2;
    printf("Enter the new vertex number: ");
    scanf("%d", &v1);
    if (v1 >= 0 && v1 < (*numVertices)) {
        printf("Enter the edges to connect to existing vertices (separated by spaces): ");
        scanf("%d", &v2);
        int i = *numVertices;
        (*numVertices)++;
        for (int j = maxEdges; j > 0; j--) {
            (*((int **)graph)[i])[j] = ((int *)graph)[v1][j - 1];
        }
        (*((int **)graph)[i])[0] = v2;
    } else {
        printf("Invalid vertex number.\n");
    }
}

void freeGraph(int **graph, int numVertices) {
    for (int i = 0; i < numVertices; i++) {
        free(((int *)graph)[i]);
    }
    free(graph);
}
