void evp_cipher_context_process(EVP_CIPHER_CTX* ctx, const void* key, void* data, unsigned int length) {
    unsigned char block[EVP_MAX_BLOCK_LENGTH];
    unsigned int block_length = EVP_CIPHER_CTX_block_size(ctx);

    while (length > 0) {
        if (length < block_length) {
            memset(block, 0x00, block_length);
            memcpy(block, data, length);
            EVP_EncryptUpdate(ctx, block, &block_length, data, length);
            memcpy(data, block, length);
        } else {
            EVP_EncryptUpdate(ctx, block, &block_length, data, block_length);
            memcpy(data, block, block_length);
            data += block_length;
            length -= block_length;
        }
    }
}

