int retrieve_file(const char* filename, const char* ip_addr, int mode) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, ip_addr, &server_addr.sin_addr);

    int connect_status = connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    if (connect_status < 0) {
        close(sockfd);
        return -2;
    }

    char request_packet[] = "GETFILE";
    send(sockfd, request_packet, strlen(request_packet), 0);

    char response_buffer[1024];
    int bytes_received = recv(sockfd, response_buffer, sizeof(response_buffer)-1, 0);
    if (bytes_received < 0) {
        close(sockfd);
        return -3;
    }

    FILE* file_ptr = fopen(filename, mode == 0 ? "wb" : "w");
    if (file_ptr == NULL) {
        close(sockfd);
        return -4;
    }

    char buffer[1024];
    while (1) {
        bytes_received = recv(sockfd, buffer, sizeof(buffer)-1, 0);
        if (bytes_received < 0) {
            fclose(file_ptr);
            close(sockfd);
            return -5;
        }
        fwrite(buffer, mode == 0 ? 1 : 2, bytes_received, file_ptr);
    }

    fclose(file_ptr);
    close(sockfd);
    return 0;
}
