EVP_MD* get_md(const char* algo) {
#ifndef OPENSSL_NO_MD2
    if (strcmp(algo, "MD2") == 0)
        return EVP_md2();
#endif

#ifndef OPENSSL_NO_MD4
    if (strcmp(algo, "MD4") == 0)
        return EVP_md4();
#endif

#ifndef OPENSSL_NO_MD5
    if (strcmp(algo, "MD5") == 0)
        return EVP_md5();
#endif

#ifndef OPENSSL_NO_SHA
    if (strcmp(algo, "SHA") == 0 || strcmp(algo, "SHA1") == 0)
        return EVP_sha();
#elif defined(OPENSSL_1_1_0) || defined(OPENSSL_1_1_1) || defined(OPENSSL_3_0_0)
    if (strcmp(algo, "SHA1") == 0)
        return EVP_sha1();
#endif

#ifndef OPENSSL_NO_DSS
    if (strcmp(algo, "DSS") == 0 || strcmp(algo, "DSS1") == 0)
        return EVP_dss();
#elif defined(OPENSSL_1_1_0) || defined(OPENSSL_1_1_1) || defined(OPENSSL_3_0_0)
    if (strcmp(algo, "DSS1") == 0)
        return EVP_sha();
#endif

#ifndef OPENSSL_NO_ECDSA
    if (strcmp(algo, "ECDSA") == 0)
        return EVP_ecdsa();
#endif

#ifndef OPENSSL_NO_SHA256
    if (strcmp(algo, "SHA256") == 0)
        return EVP_sha256();
#endif

