void display_message(char* message) {
    int line_length = 80; // adjustable line length
    char* p = message;

    while (*p != '\0') {
        if (strlen(p) > line_length) {
            printf("\n");
            p++;
            continue;
        }

        fwrite(p, sizeof(char), line_length, stdout);
        p += line_length;
        fputc('\n', stdout);
        fflush(stdout);

        while (*p != '\0') {
            if (fgetc(stdin) == '\r' || fgetc(stdin) == '\n') {
                break;
            }
            printf("%c", *p++);
        }
    }
}

