Allocation* allocate(int TOTAL_ALLOCS, int MIN_ALLOC_SIZE, int MAX_ALLOC_SIZE) {
    Allocation* allocations = (Allocation*)malloc(TOTAL_ALLOCS * sizeof(Allocation));
    if (!allocations) return NULL; // Error allocating memory for structures

    srand(time(NULL)); // Initialize random number generator
    int total_size = 0;
    int num_allocs = 0;

    for (int i = 0; i < TOTAL_ALLOCS; i++) {
        int alloc_size = rand() % (MAX_ALLOC_SIZE - MIN_ALLOC_SIZE + 1) + MIN_ALLOC_SIZE;
        void* data = malloc(alloc_size * sizeof(char));
        if (!data) return NULL; // Error allocating memory for block

        allocations[i].data = data;
        allocations[i].size = alloc_size;
        total_size += alloc_size;
        num_allocs++;
    }

    printf("Allocated %d structures, with a total size of %d bytes.\n", num_allocs, total_size);

    return allocations;
}

