int copy_memory_device(int device_id, void* src, void* dst, uint32_t len) {
    int ret;
    rte_ioat_pool_t* pool = rte_ioat_pool_create(device_id);
    if (!pool) {
        printf("Failed to create IOAT pool\n");
        return -1;
    }
    uint8_t* src_buf = (uint8_t*)rte_malloc(pool, len, 0);
    uint8_t* dst_buf = (uint8_t*)rte_malloc(pool, len, 0);
    if (!src_buf || !dst_buf) {
        printf("Failed to allocate memory buffers\n");
        rte_free(src_buf);
        rte_free(dst_buf);
        return -1;
    }
    for (int i = 0; i < len; i++) {
        src_buf[i] = rand() % 256;
    }
    ret = rte_ioat_enqueue_copy(device_id, src_buf, dst_buf, len);
    if (ret) {
        printf("Failed to enqueue copy operation: %d\n", ret);
        rte_free(src_buf);
        rte_free(dst_buf);
        return -1;
    }
    rte_free(src_buf);
    rte_free(dst_buf);
    return 0;
}
