#include <stdint.h>
#include <stdlib.h>

uint8_t* aes_encrypt_block_ctr(uint8_t* test_vector, uint8_t* key_schedule, size_t test_vector_length) {
    int i;
    uint32_t nonce = 0; // Initialize nonce to zero
    uint8_t block[16]; // Define a block

    for (i = 0; i < test_vector_length; i += 16) {
        // Copy current 128 bits of the test vector into the block
        memcpy(block, &test_vector[i], 16);

        // Initialize the key counter to zero
        uint32_t key_counter = nonce;

        // Perform AES encryption on the block
        for (i = 0; i < 16; i++) {
            uint8_t* key_block = (uint8_t*)&key_schedule[key_counter % 4 * 16];
            uint32_t result;
            aes_encrypt_keyblock(&result, &key_block);
            block[i] ^= (uint8_t)result;

            // Increment the key counter
            key_counter++;
        }

        // Store the encrypted block back into the test vector
        memcpy(&test_vector[i], block, 16);

        // Increment nonce
        nonce++;
    }

    return test_vector;
}
