char* generateUUID() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Create a buffer to hold the UUID string
    char* uuid = (char*)malloc(36 * sizeof(char));

    // Set the first character as uppercase '4'
    uuid[0] = '4';

    // Generate the hexadecimal part of the UUID
    for(int i = 1; i < 34; i++) {
        uint8_t randomByte;
        // Generate a random byte using a cryptographically secure pseudorandom number generator
        randomByte = (uint8_t)rand() % 256;

        // Convert the byte to hexadecimal and store it in the buffer
        sprintf(&uuid[i], "%02x", randomByte);
    }

    // Terminate the UUID string with a NULL character
    uuid[34] = '\0';

    return uuid;
}

