#define MAX_WORD_LENGTH 100
#define MAX_LINE_LENGTH 1024
#define MAX_PAIRS 1000

typedef struct {
    char words[2][MAX_WORD_LENGTH];
} Pair;

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        return -1;
    }

    Pair pairs[MAX_PAIRS];
    int pair_count = 0;
    char line[MAX_LINE_LENGTH];

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *token = strtok(line, " ");
        for (int i = 0; i < 2; i++) {
            if (strlen(token) > 0) {
                strcpy(pairs[pair_count].words[i], token);
                token = strtok(NULL, " ");
            }
        }

        if (pair_count >= 1 && strcmp(pairs[pair_count].words[0], pairs[pair_count - 1].words[1]) == 0) {
            pair_count--;
        } else {
            pair_count++;
        }
    }

    for (int i = 0; i < pair_count; i++) {
        printf("%s %s\n", pairs[i].words[0], pairs[i].words[1]);
    }

    fclose(file);
    return 0;
}
