```java
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.nio.ByteBuffer;

public class HashFunction {
    public static byte[] sha256(Object... blocks) throws Exception {
        Mac mac = Mac.getInstance("SHA-256");
        Key k = new SecretKeySpec(new byte[0], "AES");
        mac.init(k);
        for (Object block : blocks) {
            byte[] b = ((byte[]) block);
            mac.update(b);
        }
        return mac.doFinal();
    }

    public static byte[] sha1(Object... blocks) throws Exception {
        Mac mac = Mac.getInstance("SHA-1");
        Key k = new SecretKeySpec(new byte[0], "AES");
        mac.init(k);
        for (Object block : blocks) {
            byte[] b = ((byte[]) block);
            mac.update(b);
        }
        return mac.doFinal();
    }

    public static byte[] md5(Object... blocks) throws Exception {
        Mac mac = Mac.getInstance("MD5");
        Key k = new SecretKeySpec(new byte[0], "AES");
        mac.init(k);
        for (Object block : blocks) {
            byte[] b = ((byte[]) block);
            mac.update(b);
        }
        return mac.doFinal();
    }
}
