#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    JSON_NULL = 0,
    JSON_BOOL,
    JSON_INT,
    JSON_DOUBLE,
} json_type;

json_type parse_json_value(const char* str, size_t len) {
    if (len == 0 || !str)
        return JSON_NULL;

    int sign = 1;
    long long ll_val = 0;
    double dbl_val = 0.0;
    size_t i = 0;

    if (strncasecmp(str, "true", len) == 0 || strncasecmp(str, "false", len) == 0)
        return JSON_BOOL;

    for (; i < len; i++) {
        if (!isdigit(str[i]) && str[i] != '.') {
            break;
        }
    }

    if (i > 0) {
        if (str[i - 1] == 'L' || str[i - 1] == 'l') {
            for (; i < len; i++) {
                if (!isdigit(str[i])) {
                    break;
                }
            }
            sign = -1;
            ll_val = atoll(&str[0]);
            return JSON_INT;
        } else {
            for (; i < len; i++) {
                if (!isdigit(str[i]) && str[i] != '.') {
                    break;
                }
            }
            char* end = NULL;
            dbl_val = strtod(&str[0], &end);
            if (*end == '\0') {
                return JSON_DOUBLE;
            }
        }
    }

    return JSON_NULL;
}
