int read_path_table(struct iso9660_volume_descriptor *vd) {
    int path_table_length = le32toh(vd->volume_size);
    int path_table_offset = le32toh(vd->path_table_offset);

    if (sysmalloc((size_t *) &vd->path_table, path_table_length, 1) != 0)
        return -1;

    FILE *iso_file = fopen("/dev/your_iso_image", "rb");
    fseek(iso_file, le32toh(vd->address), SEEK_SET);
    fread(&vd->path_table, 1, path_table_length, iso_file);

    fclose(iso_file);

    int record_count = (path_table_length + 3) / 4;
    return record_count;
}

