def set_key(key):
    key = key.encode('utf-8')
    key_hash = [0] * 256
    for i in range(0, len(key)):
        key_hash[key[i]] += 1
    return key_hash


def generate_initialization_vector():
    iv = [random.randint(0, 255) for _ in range(64)]
    return bytes(iv)


def ecb_encrypt(message, key):
    encrypted_message = bytearray()
    for i in range(0, len(message), BLOCK_SIZE):
        block = message[i:i + BLOCK_SIZE]
        cipher_text = xor(block, generate_key(key, i))
        encrypted_message.extend(cipher_text)
    return bytes(encrypted_message)


def ecb_decrypt(encrypted_message, key):
    decrypted_message = bytearray()
    for i in range(0, len(encrypted_message), BLOCK_SIZE):
        block = encrypted_message[i:i + BLOCK_SIZE]
        plain_text = xor(block, generate_key(key, i))
        decrypted_message.extend(plain_text)
    return bytes(decrypted_message)


def cbc_encrypt(message, key, iv):
    encrypted_message = bytearray()
    for i in range(0, len(message), BLOCK_SIZE):
        block = message[i:i + BLOCK_SIZE]
        if i == 0:
            cipher_text = xor(block, iv)
        else:
            previous_block = encrypted_message[i - BLOCK_SIZE:i]
            cipher_text = xor(block, previous_block)
        encrypted_message.extend(cipher_text)
    return bytes(encrypted_message)


def cbc_decrypt(encrypted_message, key, iv):
    decrypted_message = bytearray()
    for i in range(0, len(encrypted_message), BLOCK_SIZE):
        block = encrypted_message[i:i + BLOCK_SIZE]
        if i == 0:
            plain_text = xor(block, iv)
        else:
            previous_block = encrypted_message[:i]
            plain_text = xor(block, previous_block[-BLOCK_SIZE:])
        decrypted_message.extend(plain_text)
    return bytes(decrypted_message)


def cfb64_encrypt(message, key, iv):
    encrypted_message = bytearray()
    ciphertext = bytearray()
    for i in range(0, len(message)):
        if i % 8 == 0:
            block = iv[i % 8:]
            ciphertext.extend(block)
        plain_text = message[i:i + 1]
        cipher_text = xor(plain_text, ciphertext[-64:-64+1])
        encrypted_message.append(cipher_text[0])
        ciphertext += cipher_text
    return bytes(encrypted_message)


def cfb64_decrypt(encrypted_message, key, iv):
    decrypted_message = bytearray()
    ciphertext = bytearray(encrypted_message[:64])
    for i in range(0, len(encrypted_message), 8):
        block = encrypted_message[i:i + 8]
        if i % 8 == 0:
            plain_text = xor(block, ciphertext)
            decrypted_message.extend(plain_text)
            ciphertext = block
        else:
            plain_text = xor(block, ciphertext[-64:-64+1])
            decrypted_message.append(plain_text[0])
            ciphertext += plain_text
    return bytes(decrypted_message)


def generate_key(key_hash, index):
    key = [0] * 256
    for i in range(index, len(key), BLOCK_SIZE):
        block = bytes((i.bit_length() // 8) % 256)
        for j in range(0, len(block)):
            if block[j]:
                for k in range(i, min(i + BLOCK_SIZE, len(key))):
                    key[k] = (key[k] * 256 + block[j]) % 256
    return bytes(key)


def xor(block1, block2):
    result = bytearray()
    for i in range(len(block1)):
        result.append(block1[i] ^ block2[i])
    return bytes(result)
