#include <stdio.h>
#include <stdlib.h>
#include <time.h>

unsigned char* compress_data(char* file_path) {
    // Open the input file
    FILE *file = fopen(file_path, "rb");
    if (!file) return NULL;

    // Read the entire file into memory
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    unsigned char* buffer = (unsigned char*)malloc(file_size + 1);
    fread(buffer, 1, file_size, file);
    fclose(file);

    // Initialize the random number generator
    srand(time(NULL));

    // Calculate the density of the data
    int density = (rand() % 100) + 1;

    // Allocate memory for the compressed data
    size_t compressed_size = file_size / density;
    unsigned char* compressed_buffer = (unsigned char*)malloc(compressed_size);

    // Compress the data using bitwise operations and random numbers
    int byte_index = 0, bit_index = 0;
    for (int i = 0; i < file_size; i++) {
        if ((rand() % 2) && (i % density == 0)) {
            compressed_buffer[byte_index] |= ((buffer[i] & 0x01) << bit_index);
            bit_index++;
            if (bit_index == 8) {
                byte_index++;
                bit_index = 0;
            }
        } else {
            compressed_buffer[byte_index++] = buffer[i];
        }
    }

    // Return the compressed data
    return compressed_buffer;
}
