int extract_info(struct main_s *data) {
    int result = 0;
    switch (data->type) {
        case TYPE_A:
            result |= (int)(data->buf[3] & 0xF0) >> 4;
            break;
        case TYPE_B:
            result |= data->buf[2];
            if ((data->buf[1] & 0x01)) {
                char temp[4];
                memcpy(temp, &(data->buf[4]), 4);
                result = *(int *)temp;
            }
            break;
        case TYPE_C:
            result &= (data->buf[5] & 0xF0) >> 4;
            if ((data->buf[3] & 0x01)) {
                int temp = data->buf[2] << 8 | data->buf[1];
                result ^= temp;
            }
            break;
    }
    return result;
}
