char *find_block_driver(const char *filename, const char *prefix) {
    DIR *dir;
    struct dirent *entry;
    char *driver = NULL;

    dir = opendir("/dev");
    if (dir == NULL)
        return driver;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        if (strncmp(entry->d_name, prefix, strlen(prefix)) == 0) {
            size_t len = strlen(prefix);
            char *block_driver = entry->d_name + len;
            driver = strdup(block_driver);
            break;
        }
    }

    closedir(dir);

    return driver;
}
