```
int exponential_backoff_with_jitter(mqtt_context* ctx) {
    static int base_retry = 1000; // Initial retry in milliseconds
    static int max_retries = 16; // Maximum number of retries
    static int max_timeout = 30000; // Maximum timeout in milliseconds

    int retries = 0;
    int current_timeout = base_retry;

    while (retries < max_retries) {
        // Simulate a connection attempt with the current timeout
        if (!mqtt_connect(ctx, current_timeout)) {
            break;
        }

        // If the connection is successful, return OK
        return 1;
    }

    // If all retries fail, return an error
    return -1;

    int jitter = (rand() % 500) + 250; // Random jitter between 250-750 milliseconds

    current_timeout += jitter;
    if (current_timeout > max_timeout) {
        current_timeout = max_timeout;
    }

    base_retry *= 2; // Double the initial retry time for the next attempt
    return exponential_backoff_with_jitter(ctx);
}
