int add_ciphers_to_library() {
    // AES cipher
    void *aes_cipher = dlopen("libaes.so", RTLD_LAZY);
    if (aes_cipher == NULL) return 1;
    int (*add_aes)(void *) = dlsym(aes_cipher, "add_aes");
    add_aes(NULL);

    // DES cipher
    void *des_cipher = dlopen("libdes.so", RTLD_LAZY);
    if (des_cipher == NULL) return 2;
    int (*add_des)(void *) = dlsym(des_cipher, "add_des");
    add_des(NULL);

    // RSA cipher
    void *rsa_cipher = dlopen("librsa.so", RTLD_LAZY);
    if (rsa_cipher == NULL) return 3;
    int (*add_rsa)(void *) = dlsym(rsa_cipher, "add_rsa");
    add_rsa(NULL);

    // Blowfish cipher
    void *blowfish_cipher = dlopen("libblowfish.so", RTLD_LAZY);
    if (blowfish_cipher == NULL) return 4;
    int (*add_blowfish)(void *) = dlsym(blowfish_cipher, "add_blowfish");
    add_blowfish(NULL);

    // MD5 hash
    void *md5_hash = dlopen("libmd5.so", RTLD_LAZY);
    if (md5_hash == NULL) return 5;
    int (*add_md5)(void *) = dlsym(md5_hash, "add_md5");
    add_md5(NULL);

    // SHA1 hash
    void *sha1_hash = dlopen("libsha1.so", RTLD_LAZY);
    if (sha1_hash == NULL) return 6;
    int (*add_sha1)(void *) = dlsym(sha1_hash, "add_sha1");
    add_sha1(NULL);

    return 0;
}
