#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/x509v3.h>
#include <openssl/err.h>

void verify_and_return_token(char *json_string, char *secret_key) {
    // Initialize the OpenSSL library
    SSL_library_init();

    // Load the secret key
    EVP_PKEY *pkey = d2i_PrivateKey_PF(NULL, NULL, (const unsigned char *)secret_key, strlen(secret_key), NULL);
    if (!pkey) {
        printf("Error loading private key\n");
        return;
    }

    // Parse the JSON string
    json_string = realloc(json_string, sizeof(char)*(strlen(json_string)+1));
    char *token_start = strstr(json_string, "eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI");
    if (token_start == NULL) {
        printf("Error parsing JSON string\n");
        return;
    }
    char *token_end = strchr(token_start, '.');
    int token_len = token_end - token_start;
    char *token = malloc(sizeof(char)*(token_len+1));
    memcpy(token, token_start, token_len);
    token[token_len] = '\0';

    // Verify the signature
    EVP_MD_CTX ctx;
    EVP_PKEY_verify_init(&ctx, pkey);
    EVP_PKEY_verify_update(&ctx, (const unsigned char *)token_start, token_len);
    unsigned char sig[256];
    int sig_len = 256;
    EVP_PKEY_verify_final(&ctx, sig, &sig_len);

    // Check the signature
    if (!EVP_MD_CTX_test_result(&ctx)) {
        printf("Error verifying signature\n");
        return;
    }

    // Return the access token
    printf("%s\n", token);
}
