#include <des.h>

void des_ecb_encrypt(unsigned char key[3], unsigned char plaintext[], unsigned char result[8]) {
    DES_cblock k;
    for (int i = 0; i < 3; ++i) {
        k[i] = key[i];
    }

    DES_key_schedule ks;
    DES_set_key_checked(&k, &ks);

    int block_num = 0;
    while (strlen((char *)plaintext) >= 8) {
        char temp[9] = {0};
        memcpy(temp, plaintext, 8);
        temp[8] = '\0';

        DES_ecb_encrypt((DES_cblock *)&temp, &ks);

        for (int i = 0; i < 8; ++i) {
            result[i*3 + block_num] = temp[i];
        }

        plaintext += 8;
        block_num = (block_num+1)%3;
    }

    char temp[9] = {0};
    memcpy(temp, plaintext, strlen((char *)plaintext));
    temp[strlen((char *)plaintext)] = '\0';

    DES_ecb_encrypt((DES_cblock *)&temp, &ks);

    for (int i = 0; i < strlen((char *)plaintext); ++i) {
        result[i*3 + block_num] = temp[i];
    }
}
