```c
#include <stdint.h>

#define MD4_BLOCK_SIZE 64
#define MD4_DIGEST_SIZE 16

void md4_transform(uint32_t *state, const uint8_t *block) {
    uint32_t a = state[0];
    uint32_t b = state[1];
    uint32_t c = state[2];
    uint32_t d = state[3];

    uint32_t AA = (a >> 2 | a << 30);
    uint32_t BB = ((b & 0xffffffff) >> 10 | (b & 0x3ff) << 22);
    uint32_t CC = (c >> 15 | c << 17);
    uint32_t DD = d;

    AA += (block[3] & 0xff) + (block[2] & 0xff00) + (block[1] & 0xff0000) + (block[0] & 0xff000000);
    BB += (block[7] & 0xff) + (block[6] & 0xff00) + (block[5] & 0xff0000) + (block[4] & 0xff000000);

    c = d = b = a;
    a += (BB >> 10 | BB << 12) + CC + DD + AA;

    state[0] = (a >> 2 | a << 30);
    state[1] = b;
    state[2] = c;
    state[3] = d;
}

void md4_update(uint32_t *state, const uint8_t *message, size_t length) {
    while (length >= MD4_BLOCK_SIZE) {
        md4_transform(state, message);
        message += MD4_BLOCK_SIZE;
        length -= MD4_BLOCK_SIZE;
    }

    if (length > 0) {
        size_t remaining = length;
        uint8_t *block = (uint8_t *)message;

        while (remaining >= 64) {
            md4_transform(state, block);
            block += MD4_BLOCK_SIZE;
            remaining -= MD4_BLOCK_SIZE;
        }

        // Pad the message with zeros and append a single '1' bit
        *(uint32_t *)(block + remaining - 8) = 0x80000000;

        // Calculate the length of the message in bits, padding as needed
        size_t len_bits = (length * 8) | (remaining * 8);

        *(uint32_t *)(block + remaining - 4) = len_bits;
        *(uint32_t *)(block + remaining - 8) += (len_bits >> 28);
        *(uint32_t *)(block + length) = block[3];

        md4_transform(state, block);
    }
}

void md4_finalize(uint32_t *state, uint8_t *digest) {
    state[0] = (state[0] >> 3 | state[0] << 29);
    state[1] = (state[1] >> 10 | state[1] << 22);
    state[2] = (state[2] >> 15 | state[2] << 17);

    uint8_t *block = (uint8_t *)state;

    for (int i = 0; i < MD4_DIGEST_SIZE; ++i) {
        digest[i] = (block[i] & 0xff);
        block++;
    }
}

void md4(const uint8_t *message, size_t length, uint8_t *digest) {
    uint32_t state[4];

    // Initialize the state
    for (int i = 0; i < 4; ++i) {
        state[i] = 0x67452301;
    }

    md4_update(state, message, length);
    md4_finalize(state, digest);
}
