#include <openssl/ripemd.h>
#include <openssl/sha.h>

uint8_t* crypto_hash(const uint8_t* buffer, size_t length, const char* algo) {
    if (strcmp(algo, "MD2") == 0) {
        MD2_CTX ctx;
        MD2_Init(&ctx);
        MD2_Update(&ctx, buffer, length);
        uint8_t* result = (uint8_t*)malloc(MD2_DIGEST_SIZE);
        MD2_Final(result, &ctx);
        return result;
    } else if (strcmp(algo, "MD4") == 0) {
        MD4_CTX ctx;
        MD4_Init(&ctx);
        MD4_Update(&ctx, buffer, length);
        uint8_t* result = (uint8_t*)malloc(MD4_DIGEST_SIZE);
        MD4_Final(result, &ctx);
        return result;
    } else if (strcmp(algo, "MD5") == 0) {
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, buffer, length);
        uint8_t* result = (uint8_t*)malloc(MD5_DIGEST_SIZE);
        MD5_Final(result, &ctx);
        return result;
    } else if (strcmp(algo, "SHA1") == 0) {
        SHA_CTX ctx;
        SHA_Init(&ctx);
        SHA_Update(&ctx, buffer, length);
        uint8_t* result = (uint8_t*)malloc(SHA_DIGEST_LENGTH);
        SHA_Final(result, &ctx);
        return result;
    } else if (strcmp(algo, "SHA256") == 0) {
        EVP_MD_CTX ctx;
        EVP_DigestInit_ex(&ctx, EVP_sha256(), NULL);
        EVP_DigestUpdate(&ctx, buffer, length);
        uint8_t* result = (uint8_t*)malloc(EVP_MAX_DIGEST_SIZE);
        EVP_DigestFinal_ex(&ctx, result, NULL);
        return result;
    } else {
        return NULL; // unsupported algorithm
    }
}
