EVP_CIPHER_CTX* get_aes_cbc_cipher(int key_length) {
    EVP_CIPHER_CTX* cipher = NULL;
    switch (key_length) {
        case 16: // 128 bits
            cipher = EVP_des_ede_cfb1(); // equivalent to AES-128 CBC
            break;
        case 24: // 192 bits
            cipher = EVP_des_ede3_cfb1(); // equivalent to AES-192 CBC
            break;
        case 32: // 256 bits
            cipher = EVP_aes_256_cbc();
            break;
        default:
            cipher = NULL; // unsupported key length
    }
    return cipher;
}

