#include <iostream>
#include <cmath>

struct OctreeNode {
    // Node type: internal node (1) or leaf node (0)
    int type;
    // Center of the current octant
    float* center;
    // Size of the current octant
    float* size;
    // Children nodes
    struct OctreeNode** children;
    // Data associated with this node
    float* data;
};

OctreeNode* initOctree(int featureSize, int numLeafNodes, int dataCapacity) {
    // Calculate the number of levels in the octree
    int numLevels = (int)log2(numLeafNodes);
    OctreeNode* root = new OctreeNode();
    root->type = 1; // Start with an internal node
    root->center = new float[3];
    root->size = new float[3];
    root->children = nullptr;
    root->data = nullptr;

    // Initialize the root's center and size
    for (int i = 0; i < 3; ++i) {
        root->center[i] = 0.0f;
        root->size[i] = featureSize;
    }

    // Recursively construct the octree
    for (int i = 0; i < numLevels; ++i) {
        // Calculate the capacity of this level
        int capacity = pow(2, i);
        // Check if we need to increase the capacity
        if (capacity < numLeafNodes) {
            // Increase the capacity and allocate memory for children
            capacity *= 2;
            root->children = new OctreeNode*[8];
            for (int j = 0; j < 8; ++j) {
                root->children[j] = nullptr;
            }
        } else {
            break;
        }

        // Update the size and center of this node
        for (int j = 0; j < 3; ++j) {
            root->size[j] /= 2.0f;
            root->center[j] += featureSize / 2.0f;
        }
    }

    return root;
}
