```cpp
void findBestCombination(int target, pair<int, bool> values[], int n) {
    int bestSum = 0;
    int bestCount = INT_MAX;
    int currentSum = 0;
    int currentCount = 0;
    vector<pair<int, bool>> selectedValues;

    for (int i = 0; i < n; i++) {
        if (!values[i].second) { // Value not yet selected
            if (currentSum + values[i].first <= target && currentCount < bestCount) {
                currentSum += values[i].first;
                currentCount++;
                selectedValues.push_back(values[i]);
            }
            else if (currentSum >= target) {
                if (currentCount < bestCount || (currentCount == bestCount && currentSum > bestSum)) {
                    bestSum = currentSum;
                    bestCount = currentCount;
                    for (int j = 0; j < n; j++) {
                        if (find(selectedValues.begin(), selectedValues.end(), values[j]) != selectedValues.end()) {
                            values[j].second = true;
                        }
                    }
                }
                currentSum = 0;
                currentCount = 0;
                selectedValues.clear();
            }
        }
    }

    // If the best combination was found within the array, return it
    if (bestCount < INT_MAX) {
        for (int i = 0; i < n; i++) {
            if (find(selectedValues.begin(), selectedValues.end(), values[i]) != selectedValues.end()) {
                values[i].second = true;
            }
        }
    }
}
