struct config {
    char *protocol;
    char **commands;
    int num_commands;
};

char *execute_config(struct config *config) {
    FILE *fp = NULL;
    char *output = NULL;

    if (strcmp(config->protocol, "Telnet") == 0) {
        // Prompt for password
        printf("Enter Telnet password: ");
        char password[64];
        fgets(password, sizeof(password), stdin);
        password[strcspn(password, "\n")] = '\0';

        // Execute commands using Telnet protocol
        fp = popen("telnet localhost 23", "w");
        for (int i = 0; i < config->num_commands; i++) {
            fprintf(fp, "%s\n", config->commands[i]);
        }
        pclose(fp);
    } else if (strcmp(config->protocol, "SSH") == 0) {
        // Execute commands using SSH protocol
        fp = popen("ssh localhost -t 'command1\ncommand2\n...'\n", "w");
    }

    if (fp != NULL) {
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), fp) != NULL) {
            output = realloc(output, strlen(output) + strlen(buffer));
            strcat(output, buffer);
        }
        pclose(fp);
    } else {
        // Handle error
    }

    return output;
}
