void testSetIndexedPropertiesToExternalArrayData(v8::Isolate* isolate) {
  // Allocate memory for the external data
  int size = 5;
  double* externalData = new double[size];
  for (int i = 0; i < size; ++i) {
    externalData[i] = static_cast<double>(i);
  }

  // Create a V8 Object
  v8::Local<v8::Object> obj = v8::Object::New(isolate);

  // Set the indexed properties to the external data using v8::Object::SetIndexedPropertiesToExternalArrayData
  v8::Local<v8::Value> array = v8::Array::New(isolate, size);
  for (int i = 0; i < size; ++i) {
    array->Set(i, v8::Number::New(isolate, externalData[i]));
  }
  obj->SetIndexedPropertiesToExternalArrayData(array);

  // Check that the object has indexed properties in external array data
  v8::Local<v8::Value> property = obj->Get(v8::Integer::New(isolate, 0));
  if (!property->IsNumber()) {
    return;
  }

  double value = property->As<v8::Number>()->GetValue();
  if (value != static_cast<double>(0)) {
    return;
  }

  // Check that the external data is correct
  for (int i = 0; i < size; ++i) {
    property = obj->Get(v8::Integer::New(isolate, i));
    if (!property->IsNumber()) {
      return;
    }
    value = property->As<v8::Number>()->GetValue();
    if (value != static_cast<double>(i)) {
      return;
    }
  }

  // Check that the data type is correct
  for (int i = 0; i < size; ++i) {
    property = obj->Get(v8::Integer::New(isolate, i));
    if (!property->IsNumber()) {
      return;
    }
  }

  // Check that the length is correct
  v8::Local<v8::Value> length = obj->Get(v8::String::NewFromUtf8(isolate, "length"));
  if (!length->IsInteger()) {
    return;
  }
  int len = length->As<v8::Integer>()->GetValue();
  if (len != size) {
    return;
  }

  // Free the external data
  delete[] externalData;

  return;
}

