std::vector<int> getEntitiesOnLayer(int dbId, int layerId, const std::string& criterion) {
    // Assuming a custom database class called Database
    auto db = Database::getInstance();

    if (!db->isLayerPresent(dbId, layerId)) {
        throw std::runtime_error("Layer not found");
    }

