#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/ec.h>
#include <openssl/hmac.h>
#include <string.h>

void *ecies_encrypt(const uint8_t *plaintext, size_t plaintext_len, const uint8_t *key,
                     size_t key_len) {
    EVP_PKEY *ec_key = NULL;
    EC_KEY *eckey = NULL;
    ECDSA_SIG *sig = NULL;
    unsigned char encrypted[plaintext_len];
    unsigned char shared_secret[EVP_MAX_MD_SIZE];
    unsigned char hash_value[EVP_MAX_MD_SIZE];
    size_t shared_secret_len, hash_value_len;

    // Generate EC private key
    if (!(eckey = EC_KEY_new_by_curve_name(NID_secp160r2))) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }

    // Load the public key from the provided encrypted key
    if (!EC_key_set_public_key_form(eckey, key, 16)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey);
        return NULL;
    }

    // Generate a shared secret using ECDH
    if (!ECDH_compute_key(shared_secret, &shared_secret_len, eckey, EC_KEY_new_by_curve_name(NID_secp160r2), key, 16)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); EC_KEY_free(EC_KEY_new_by_curve_name(NID_secp160r2));
        return NULL;
    }

    // Derive a shared secret using HMAC
    if (!HMAC( EVP_sha256(), key, 16, shared_secret, shared_secret_len, hash_value, &hash_value_len)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); free(shared_secret);
        return NULL;
    }

    // Encrypt the plaintext using AES-128-CBC
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char encrypted_block[AES_BLOCK_SIZE];
    int outlen;

    if (!AES_new_iv(iv)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); free(shared_secret); free(hash_value);
        return NULL;
    }

    // Create an EVP_CIPHER_CTX
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Set the encryption direction (encrypt)
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, 16)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); free(shared_secret); free(hash_value);
        return NULL;
    }

    // Set the IV and add the plaintext to the encryption context
    if (!EVP_EncryptUpdate(ctx, encrypted, &outlen, (const uint8_t *)plaintext, plaintext_len)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); free(shared_secret); free(hash_value);
        return NULL;
    }

    // Finalize the encryption
    if (!EVP_EncryptFinal_ex(ctx, encrypted + outlen, &outlen)) {
        ERR_error_fp(stderr, NULL);
        EC_KEY_free(eckey); free(shared_secret); free(hash_value);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Free allocated memory
    EC_KEY_free(eckey); free(shared_secret); free(hash_value);

    return encrypted;
}
