```c++
char** loadMap(const std::string& mapStr) {
    size_t rowDelim = ',';
    size_t tileSize = 1; // Assuming single-byte tiles
    int rows = 0, cols = 0;

    for (size_t i = 0; i < mapStr.size(); ++i) {
        if (mapStr[i] == '\n') {
            ++rows;
            if (i > 0 && mapStr[i - 1] != rowDelim) {
                // No delimiter found at end of previous line
                return nullptr;
            }
        } else if (mapStr[i] == rowDelim) {
            ++cols;
        } else {
            ++tileSize; // Assuming multi-byte tiles
        }
    }

    if (rows * cols != mapStr.size() - rows) {
        // Incomplete or invalid input string
        return nullptr;
    }

    char** result = new char*[rows];
    for (int i = 0; i < rows; ++i) {
        result[i] = new char[cols * tileSize];
    }

    size_t idx = 0;
    for (size_t i = 0; i <= mapStr.size(); ++i) {
        if (i == mapStr.size() || mapStr[i] == '\n') {
            size_t rowStart = i - (mapStr[i - 1] != rowDelim);
            size_t rowEnd = i;
            for (size_t j = rowStart; j < rowEnd; ++j) {
                if (mapStr[j] == rowDelim) {
                    ++j;
                    break;
                }
                for (int k = 0; k < tileSize; ++k) {
                    if (idx + k >= cols * tileSize) {
                        return nullptr; // Not enough space in the buffer
                    }
                    result[i / (tileSize == 1 ? 1 : rowDelim)][j - rowStart] = mapStr[j];
                }
            }
            ++idx;
        }
    }

    return result;
}

