#include <map>
#include <string>

class Page {
public:
    std::string id;
    void* data;

    Page(const std::string& _id) : id(_id), data(nullptr) {}
};

class PagePool {
private:
    std::map<std::string, Page*> pages;

public:
    Page* createPage(const std::string& id) {
        if (pages.find(id) != pages.end()) {
            return nullptr; // Page already exists
        }

        Page* page = new Page(id);
        pages[id] = page;
        return page;
    }

    Page* retrievePage(const std::string& id) {
        auto it = pages.find(id);
        if (it == pages.end()) {
            return nullptr; // Page does not exist
        }
        return it->second;
    }

    void deletePage(const std::string& id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            delete it->second;
            pages.erase(it);
        }
    }
};

