            vp8Decoder->setTemporalLayers(encoderSettings.getTemporalLayers());
            vp8Decoder->setDenoising(encoderSettings.getDenoising());
            vp8Decoder->setErrorConcealment(encoderSettings.getErrorConcealment());
        }
    }

    return decoder;
}
