struct AdjListNode {
    int v;
    struct AdjListNode* next;
};

std::vector<AdjListNode*> createAdjList(std::pair<int, int> range, std::vector<std::pair<int, int>>& edges) {
    std::vector<AdjListNode*> adjList(range.second + 1);
    for (int i = 0; i <= range.second; ++i)
        adjList[i] = nullptr;

    for (const auto& edge : edges) {
        int u = edge.first;
        int v = edge.second;

        AdjListNode* newNode = new AdjListNode();
        newNode->v = v;
        newNode->next = adjList[u];
        adjList[u] = newNode;
    }

    return adjList;
}
