char *drawPaths(LineSeg *paths1, LineSeg *paths2, int numSegs1, int numSegs2, char fillType) {
    double x, y;
    int i, j;

    printf("Drawing paths...\n");

    // Draw the first path
    for (i = 0; i < numSegs1; i++) {
        printf("(%.2f, %.2f) -- (%.2f, %.2f)", paths1[i].x1, paths1[i].y1, paths1[i].x2, paths1[i].y2);
    }
    printf("\n");

    // Check if the path can be simplified
    int isSimplifiable = 0;
    for (i = 0; i < numSegs1 - 1; i++) {
        if ((paths1[i].x2 - paths1[i + 1].x1) * (paths1[i].y2 - paths1[i + 1].y1) <
            sqrt(pow(paths1[i].x2 - paths1[i + 1].x1, 2) + pow(paths1[i].y2 - paths1[i + 1].y1, 2)) * 0.00001) {
            isSimplifiable = 1;
            break;
        }
    }

    printf("Path simplification possible: %s\n", isSimplifiable ? "yes" : "no");

    // Draw the second path
    for (j = 0; j < numSegs2; j++) {
        printf("(%.2f, %.2f) -- (%.2f, %.2f)", paths2[j].x1, paths2[j].y1, paths2[j].x2, paths2[j].y2);
    }
    printf("\n");

    return "Path drawing completed.\0";
}
