int estimateStorage(double threshold, int numAngles) {
    // Calculate the estimated storage in bytes
    int estimatedBytes = (int)(threshold * 1000.0 * 4.0 * numAngles);

    // Convert estimated storage from bytes to appropriate unit of measurement
    const char* units[] = {"B", "KB", "MB", "GB", "TB"};
    int i;
    for(i = 0; (estimatedBytes / (1 << i)) >= 1024; ++i);

    // Round the estimated storage to the nearest power of 2
    int estimatedStorage = (int)(pow(1024.0, i));

    return estimatedStorage;
}

