void renderCurve(GLfloat* controlPoints, int numControlPoints, GLfloat lineWidth, GLfloat red, GLfloat green, GLfloat blue) {
    glBegin(GL_LINE_STRIP);
    for (int i = 0; i < numControlPoints; i++) {
        glColor3f(red, green, blue);
        glVertex3fv(&controlPoints[i * 3]);
    }
    glEnd();

    glBegin(GL_LINE_STRIP);
    if (numControlPoints > 1) {
        GLfloat* prevPoint = &controlPoints[0];
        for (int i = 1; i < numControlPoints; i++) {
            glColor3f(red, green, blue);
            glVertex3fv(&controlPoints[i * 3]);
            glBegin(GL_LINES);
            glVertex3fv(prevPoint);
            glVertex3fv(&controlPoints[i * 3]);
            glEnd();
            prevPoint = &controlPoints[i * 3];
        }
    }

    glColor3f(red, green, blue);
    glBegin(GL_LINE_STRIP);
    glVertex3fv(controlPoints + (numControlPoints - 1) * 3);
    for (int i = numControlPoints - 2; i >= 0; i--) {
        glBegin(GL_LINES);
        glVertex3fv(&controlPoints[i * 3]);
        glVertex3fv(controlPoints + (numControlPoints - 1) * 3);
        glEnd();
        prevPoint = &controlPoints[i * 3];
    }

    glLineWidth(lineWidth);
}

