int main() {
    FILE *fp;
    float **arr;
    int i, j;

    fp = fopen("binary_file.bin", "rb");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    // Read dimensions from the file
    unsigned short dims[2];
    fread(dims, sizeof(unsigned short), 2, fp);
    int rows = dims[0];
    int cols = dims[1];

    arr = (float **)malloc(rows * sizeof(float *));
    for (i = 0; i < rows; i++) {
        arr[i] = (float *)malloc(cols * sizeof(float));
    }

    // Read values from the file
    for (i = 0; i < rows; i++) {
        for (j = 0; j < cols; j++) {
            fread(&arr[i][j], sizeof(float), 1, fp);
        }
    }

    printf("Array dimensions: %d x %d\n", rows, cols);

    // Free memory
    for (i = 0; i < rows; i++) {
        free(arr[i]);
    }
    free(arr);

    fclose(fp);
    return 0;
}
