std::vector<char> encryptWideString(wchar_t* wideStr) {
    int len = wcslen(wideStr);
    std::vector<char> encryptedData(len * 2);

    for (int i = 0; i < len; i++) {
        wchar_t c = wideStr[i];
        char bytes[4];
        memcpy(bytes, &c, sizeof(c));
        char* p = bytes;
        while (p < bytes + 4) {
            *p++ = static_cast<char>(static_cast<unsigned int>(*p) ^ 0x12);
        }
        char* destP = encryptedData.data() + i * 2;
        memcpy(destP, bytes, sizeof(c));
    }

    return encryptedData;
}

