#include <cuda_runtime.h>
#include <curand.h>
#include <cufft.h>

int main() {
    int N = 1024;
    int M = 1024;

    // Allocate host memory
    float *h_data = (float *)malloc(N * M * sizeof(float));
    if (!h_data) {
        printf("Host memory allocation failed\n");
        return -1;
    }

    // Initialize host memory with random values
    curandGenerateRandomDouble(h_data, N * M);

    // Allocate device memory
    float *d_data;
    cudaMalloc((void **)&d_data, N * M * sizeof(float));
    if (cudaGetLastError() != cudaSuccess) {
        printf("Device memory allocation failed\n");
        free(h_data);
        return -1;
    }

    // Copy host data to device
    cudaMemcpy(d_data, h_data, N * M * sizeof(float), cudaMemcpyHostToDevice);

    // Perform FFT
    cufftComplex *h_plan = new cufftComplex[N / 2];
    cufftComplex *d_plan;

    cufftPlan2d(h_plan, N, M, CUFFT_C2C);
    cudaMalloc((void **)&d_plan, sizeof(cufftComplex) * (N + M));

    cufftExecC2C(h_plan, d_data, d_plan, CUFFT_FORWARD);

    // Read FFT output from device
    float *h_output = (float *)malloc(N * M * sizeof(float));
    cudaMemcpy(h_output, d_plan, N * M * sizeof(float), cudaMemcpyDeviceToHost);

    // Deallocate host and device memory
    free(h_data);
    free(h_output);
    cudaFree(d_data);
    cudaFree(d_plan);

    return 0;
}
