int splitUnicodeString(char *unicodeStr, char ***result, int **len) {
    int count = 0;
    int lenCount = 0;
    char *str = (char *)uprv_malloc(strlen(unicodeStr) + 1);
    strcpy(str, unicodeStr);

    for (int i = 0; i < strlen(str); i++) {
        if (isCanonSegmentStarter((wuint16)(str[i])) == TRUE) {
            count++;
            lenCount++;
            if (*result != NULL) {
                free(*result[count - 1]);
            }
            *result = (char **)realloc(*result, sizeof(char *) * (count + 1));
            (*result)[count] = (char *)uprv_malloc(i - lenCount + 2);
            strcpy((*result)[count], str);
            lenCount = i;
        }
    }

    if (len != NULL) {
        *len = (int *)malloc(sizeof(int) * count);
        for (int i = 0; i < count; i++) {
            (*len)[i] = strlen((*result)[i]);
        }
    }

    return count;
}
