int parseText(char *text) {
    char *paragraphs = NULL;
    int paragraphCount = 0;
    int currentLength = 0;
    int totalLength = 0;

    for (char *p = text; *p != '\0'; p++) {
        if (*p == '\n' && *(p - 1) != '\r') {
            paragraphs = realloc(paragraphs, (totalLength + 2) * sizeof(char));
            paragraphs[totalLength] = '\n';
            paragraphs[totalLength + 1] = '\0';
            totalLength += 2;
            paragraphCount++;
        } else {
            if (currentLength > 0) {
                paragraphs = realloc(paragraphs, (totalLength + currentLength + 2) * sizeof(char));
                strncpy(&paragraphs[totalLength], text, currentLength);
                totalLength += currentLength;
                currentLength = 0;
            }
        }

        p++;
    }

    if (currentLength > 0) {
        paragraphs = realloc(paragraphs, (totalLength + currentLength + 2) * sizeof(char));
        strncpy(&paragraphs[totalLength], text, currentLength);
        totalLength += currentLength;
        paragraphCount++;
    }

    paragraphs = realloc(paragraphs, (totalLength + 1) * sizeof(char));
    paragraphs[totalLength] = '\0';

    return paragraphCount;
}

