void* reverse_args(int count, ...) {
    va_list args;
    va_start(args, count);
    void** reversed = (void**)malloc((count + 1) * sizeof(void*));
    for (int i = count; i >= 0; --i) {
        switch (i % 2) {
            case 0:
                *(reversed + i) = va_arg(args, int);
                break;
            case 1:
                *(reversed + i) = va_arg(args, char*);
                break;
        }
    }
    va_end(args);
    return reversed;
}

