void setupTearDownResources(PredFuncMode mode, int blockSize) {
    int *predictionReferences = new int[blockSize*blockSize];
    int *data = new int[blockSize*blockSize];

    if (mode == INTRA_PRED_FUNC_MODE_1) {
        // Set up prediction modes and references for mode 1
        for (int i = 0; i < blockSize; i++) {
            for (int j = 0; j < blockSize; j++) {
                predictionReferences[i*blockSize + j] = data[i*blockSize + j];
            }
        }
    } else if (mode == INTRA_PRED_FUNC_MODE_2) {
        // Set up prediction modes and references for mode 2
        for (int i = 0; i < blockSize; i++) {
            for (int j = 0; j < blockSize; j++) {
                if (i == 0 || j == 0) {
                    predictionReferences[i*blockSize + j] = data[i*blockSize + j];
                } else {
                    predictionReferences[i*blockSize + j] = predictionReferences[(i-1)*blockSize + j-1];
                }
            }
        }
    }

    // Tear down resources
    delete[] predictionReferences;
    delete[] data;

    system("clear");  // Clear the system state
}

