char* strip_whitespace(const char* str) {
    if (!str)
        return NULL;

    size_t len = strlen(str);
    char* new_str = (char*)malloc((len + 1)*sizeof(char));
    if (!new_str)
        return NULL;

    char* p = new_str, *q = str;
    while (*q) {
        if (*q == ' ' || *q == '\t' || *q == '\n' || *q == '\v') {
            q++;
            continue;
        }
        *p++ = *q++;
    }
    *p = '\0';

    return new_str;
}

