    for (int i = 0; i < n; ++i) {
        std::cin >> nodes[i];
    }
    for (int i = 0; i < n; ++i) {
        int left = c[i*2+1];
        int right = c[i*2+2];
        if (left >= 0) {
            nodes[left] = nodes[i];
            nodes[right] = nodes[i];
        }
    }
    return nodes;
}`

