void generateDungeon(int x1, int y1, int x2, int y2, int *doorFlag) {
    if ((x2 - x1 == 0) || (y2 - y1 == 0)) {
        return;
    }

    int midX = (x1 + x2) / 2;
    int midY = (y1 + y2) / 2;

    // Randomly decide which wall to split
    if ((rand() % 2) == 0) {
        generateDungeon(x1, y1, midX, y2, doorFlag);
        for (int i = midX; i < x2; i++) {
            for (int j = y1; j <= y2; j++) {
                // Mark the wall as 'door'
                *doorFlag = 1;
            }
        }
    } else {
        generateDungeon(x1, y1, x2, midY, doorFlag);
        for (int i = x1; i < x2; i++) {
            for (int j = midY; j <= y2; j++) {
                // Mark the wall as 'door'
                *doorFlag = 1;
            }
        }
    }

    generateDungeon(x1, y1, midX, midY, doorFlag);
    generateDungeon(midX, y1, x2, midY, doorFlag);
    generateDungeon(x1, midY, midX, y2, doorFlag);
    generateDungeon(midX, midY, x2, y2, doorFlag);
}

