TypeHandle GetFunctionPointerType(TypeInfo* typeInfo, bool exact) {
    TypeHandle typeHandles = nullptr;
    size_t count = 0;

    if (exact) {
        count = typeInfo->paramCount + 1; // include return type
    } else {
        count = typeInfo->paramCount; // do not include return type
    }

    typeHandles = new TypeHandle[count];

    if (!typeHandles) {
        return TypeHandle();
    }

    size_t bytesRead;
    TypeHandle* pTypeHandles = (TypeHandle*)malloc(count * sizeof(TypeHandle));

    if (ReadLoadedTypeHandles(pTypeHandles, &bytesRead, count) != S_OK) {
        free(typeHandles);
        typeHandles = nullptr;
        return TypeHandle();
    }

    for (size_t i = 0; i < count; ++i) {
        typeHandles[i] = pTypeHandles[i];
    }

    free(pTypeHandles);

    if (exact) {
        typeHandles[0] = typeInfo->returnType;
    }

    return typeHandles[0]; // return type handle
}

