void checkTensorData(string valueString, Tensor& tensor) {
    vector<string> values = split(valueString, ",");
    for (int i = 0; i < values.size(); i++) {
        string value = values[i];
        switch(tensor.getDataType()) {
            case Tensor::FLOAT:
                if (!isFloatValue(value)) {
                    cout << "Invalid float value: " << value << endl;
                    return;
                }
                break;
            case Tensor::INT:
                if (!isIntValue(value)) {
                    cout << "Invalid int value: " << value << endl;
                    return;
                }
                break;
            case Tensor::STRING:
                if (value != tensor.getStringValue()) {
                    cout << "Mismatched string value: expected '" << tensor.getStringValue() << "', got '" << value << "'" << endl;
                    return;
                }
                break;
        }
    }
}
