public static byte[] generatePPMImage(PageDocument pageDocument, int pageNumber, int displayWidth, int displayHeight) {
    BufferedImage image = pageDocument.getPage(pageNumber).getBufferedImage();
    int width = Math.min(image.getWidth(), displayWidth);
    int height = Math.min(image.getHeight(), displayHeight);
    BufferedImage scaledImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
