#include <openssl/pbkdf2.h>
#include <openssl/err.h>

int derive_key(char *password, char *salt, int iteration_count) {
    EVP_PBE_METHOD *pbem;
    PBKDF2_CTX pbctx;
    unsigned char *key = NULL;
    unsigned char *iv = NULL;

    if ((pbem = EVP.pbkdf2_init()) == NULL)
        return 0;

    if (!PBKDF2.pbkdf2_init_ex(&pbctx, pbem, (const unsigned char *)salt, strlen(salt), password, strlen(password), iteration_count, 32, &key, &iv)) {
        OPENSSL_free(key);
        OPENSSL_free(iv);
        EVP.pbkdf2_free(pbem);
        return 0;
    }

    OPENSSL_free(key);
    OPENSSL_free(iv);
    EVP.pbkdf2_free(pbem);

    return 1;
}
