void saveData(const std::vector<int>& data, const std::string& filename) {
    // XML format
    pugi::xml_document doc;
    pugi::xml_node root = doc.child("data");
    for (int value : data) {
        pugi::xml_node node = root.append_child("value");
        node.append_child().text(std::to_string(value));
    }
    std::ofstream file(filename + ".xml");
    if (!file) {
        std::cerr << "Error opening XML file: " << filename << ".xml" << std::endl;
        return;
    }
    doc.save(file);
    std::cout << "Saved data to " << filename << ".xml in XML format." << std::endl;

    // Binary format
    std::ofstream binaryFile(filename + ".bin", std::ios::binary);
    if (!binaryFile) {
        std::cerr << "Error opening binary file: " << filename << ".bin" << std::endl;
        return;
    }
    for (int value : data) {
        binaryFile.write(reinterpret_cast<const char*>(&value), sizeof(int));
    }
    std::cout << "Saved data to " << filename << ".bin in binary format." << std::endl;

    // COLLADA Physics 1.4.1 format
    domphysics::Physics physics;
    for (int value : data) {
        domgeometry::Geometry geometry;
        geometry.appendChild(new domboundcompute::BoundCompute(value));
        physics.appendChild(&geometry);
    }
    std::ofstream colladaFile(filename + ".dae");
    if (!colladaFile) {
        std::cerr << "Error opening COLLADA file: " << filename << ".dae" << std::endl;
        return;
    }
    physics.save(colladaFile);
    std::cout << "Saved data to " << filename << ".dae in COLLADA Physics 1.4.1 format." << std::endl;
}
