#include <chrono>
#include <vector>
#include <random>

std::pair<double, double> generateRandomImage(int width, int height) {
    std::vector<int> image(width * height);

    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < width * height; i++) {
        image[i] = rand() % 256;
    }
    auto end = std::chrono::high_resolution_clock::now();
    double directIndexingTime = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < width * height; i++) {
        image[i % width] = rand() % 256;
    }
    end = std::chrono::high_resolution_clock::now();
    double boundaryClampingTime = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < width * height; i++) {
        image[i / width] = rand() % 256;
    }
    end = std::chrono::high_resolution_clock::now();
    double scalarAccessTime = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    return {directIndexingTime, boundaryClampingTime};
}
