void verticalFlipPixelArray(unsigned char*** arr, int format) {
    int rows = *(int*)(&((*arr)[0][0]));
    int cols = *(int*)(&((*arr)[0][1]));
    int bytesPerPixel = (format == 1) ? 1 : 3;
    int pixelsPerRow = cols * bytesPerPixel;

    unsigned char* tempArr = (unsigned char*)malloc(rows * pixelsPerRow);

    for(int i = 0; i < rows; i++) {
        memcpy((char*)tempArr + (rows - i - 1) * pixelsPerRow, &((*arr)[i][0]), pixelsPerRow);
    }

    for(int i = 0; i < rows; i++) {
        memcpy(&((*arr)[i][0]), tempArr + i * pixelsPerRow, pixelsPerRow);
    }

    free(tempArr);
}
