#include <iostream>
#include <random>
#include <cmath>
#include <vector>

double matrixProjection(int numSamples, int tableSize, int dimension) {
    std::mt19937 gen;
    std::normal_distribution<double> dist(0.0, 1.0);

    // Create a random matrix
    std::vector<std::vector<double>> matrix(tableSize, std::vector<double>(dimension));
    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < dimension; ++j) {
            matrix[i][j] = dist(gen);
        }
    }

    // Create a random vector
    std::vector<double> vector(dimension);
    for (int j = 0; j < dimension; ++j) {
        vector[j] = dist(gen);
    }

    // Perform the matrix projection operation
    std::vector<double> projectedVector(tableSize, 0.0);
    for (int i = 0; i < tableSize; ++i) {
        double dotProduct = 0.0;
        for (int j = 0; j < dimension; ++j) {
            dotProduct += matrix[i][j] * vector[j];
        }
        projectedVector[i] = dotProduct;
    }

    // Calculate the reference result
    std::vector<double> referenceProjectedVector(tableSize, 0.0);
    for (int i = 0; i < tableSize; ++i) {
        double referenceDotProduct = 0.0;
        for (int j = 0; j < dimension; ++j) {
            referenceDotProduct += matrix[i][j] * vector[j];
        }
        referenceProjectedVector[i] = referenceDotProduct;
    }

    // Print the log message
    std::cout << "Matrix Projection: numSamples=" << numSamples
              << ", tableSize=" << tableSize
              << ", dimension=" << dimension
              << ", projectedVector=" << projectedVector[0];
    for (int i = 1; i < tableSize; ++i) {
        std::cout << "," << projectedVector[i];
    }
    std::cout << std::endl;
    for (int i = 0; i < tableSize; ++i) {
        if (i > 0) {
            std::cout << ", ";
        }
        std::cout << referenceProjectedVector[i];
    }
    std::cout << std::endl;

    // Compare the results
    bool isMatch = true;
    for (int i = 0; i < tableSize; ++i) {
        if (std::abs(projectedVector[i] - referenceProjectedVector[i]) > 1e-6) {
            isMatch = false;
            break;
        }
    }

    return isMatch ? 0.0 : -1.0;
}

