char* format_string(const char* filepath, int line_num, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);

    int len = vsnprintf(NULL, 0, fmt, args);
    va_end(args);

    if(len < 0) return NULL;

    char* str = (char*)malloc((len + 1) * sizeof(char));
    if(str == NULL) return NULL; // Handle allocation failure

    va_start(args, fmt);
    vsnprintf(str, len + 1, fmt, args);
    va_end(args);

    return str;
}

