#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <deque>
#include <map>
#include <string>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

using namespace std;

const int PORT = 8080;
const int MAX_CONNECTIONS = 10;

class MessageQueue {
public:
    void push(string message) {
        unique_lock<mutex> lock(mutex_);
        queue_.push(message);
        cv_.notify_one();
    }

    string pop() {
        unique_lock<mutex> lock(mutex_);
        while (queue_.empty()) {
            cv_.wait(lock);
        }
        string message = queue_.front();
        queue_.pop();
        return message;
    }

private:
    mutex mutex_;
    condition_variable cv_;
    queue<string> queue_;
};

class WorkerThread {
public:
    void operator()(int socket) {
        while (true) {
            string message = MessageQueue::getInstance().pop();
            send(socket, message.c_str(), message.size(), 0);
            char buffer[1024];
            int bytesRead = recv(socket, buffer, 1024, 0);
            if (bytesRead == 0 || bytesRead == -1) break;
            string incomingMessage(buffer, bytesRead);
            MessageQueue::getInstance().push(incomingMessage);
        }
    }

private:
    static MessageQueue& getInstance() {
        static MessageQueue instance;
        return instance;
    }
};

map<int, thread> workers;

void acceptConnections(int serverSocket) {
    int clientSocket = -1;
    struct sockaddr_in clientAddress;
    socklen_t clientLength = sizeof(clientAddress);
    while (true) {
        clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddress, &clientLength);
        if (clientSocket == -1) break;
        workers[clientSocket] = thread(WorkerThread()(clientSocket));
    }
}

int main() {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(PORT);
    bind(serverSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress));
    listen(serverSocket, MAX_CONNECTIONS);

    thread acceptThread(acceptConnections, serverSocket);

    acceptThread.join();

    return 0;
}
