char* calculate_DISCID(cdio_CD_ROM *cd) {
    cdio_track_t* track;
    int64_t sum = 0;

    for (track = cd->get_tracks(); track; track = track->next) {
        sum += track->lba;
    }

    uint32_t result = (sum / 0xFF);
    result >>= 24;

    char buf[9];
    sprintf(buf, "%08x", result);

    printf("DISCID: %s\n", buf);

    return strdup(buf);
}

