double optimizeModularity(int** graph, int numNodes, double epsilon) {
    double modularity = 0.0;
    for (int pass = 0; pass < MAX_PASSES && modularity <= LAST_IMPROVEMENT; pass++) {
        bool improved = false;
        for (int node = 0; node < numNodes; node++) {
            int bestNeighbor = -1;
            double bestDiff = 0.0;
            for (int neighbor = 0; neighbor < numNodes; neighbor++) {
                if (graph[node][neighbor] && neighbor != node) {
                    double diff = calculateModularityDiff(graph, node, neighbor);
                    if (diff > bestDiff) {
                        bestNeighbor = neighbor;
                        bestDiff = diff;
                    }
                }
            }
            if (bestNeighbor >= 0) {
                swapNodes(graph, node, bestNeighbor);
                modularity += bestDiff;
                improved = true;
            }
        }
        if (!improved) {
            break;
        }
    }
    return modularity;
}

