```c
#include <setjmp.h>
#include "jpeglib.h"

jpeg_decompress_ptr jptr;
JSAMPIMAGE *image;

int decompress_jpg(char* buffer, int width, int height) {
    JDecompressor cinfo;
    JDIMENSION w = (JDIMENSION)width;
    JDIMENSION h = (JDIMENSION)height;

    // Initialize the JPEG decompression state
    if (!jinit_decompress(&cinfo)) return -1;
    if (!cinfo.create_dc(cinfo.comp_info[0], 1)) return -1;

    // Set the output dimensions and colorspace information
    cinfo.output_width = w;
    cinfo.output_height = h;
    cinfo.out_colorspace = JCS_RGB;

    // Initialize the JPEG decompression state for the specified buffer
    jptr = (jpeg_decompress_ptr) &cinfo;
    image = (JSAMPIMAGE *)malloc(sizeof(JSAMPARRAY));
    *image = (JSAMPROW *)malloc((h+7)/8 * sizeof(JSAMPLE));

    if (!jstart_decompress(jptr)) return -1;

    // Initialize the JPEG decompression state for processing
    jpeg_start_decompress(jptr);

    // Allocate memory for the pixel array
    unsigned char* pixels = (unsigned char*)malloc(width * height * 3);
    unsigned int num_bytes_per_pixel = 3;
    unsigned int line_size = width * num_bytes_per_pixel;

    while (jptr->output_scanline < h) {
        // Read a scanline from the JPEG buffer
        JSAMPIMAGE *buf = jptr->temp_buffer;
        JDIMENSION row = jptr->output_scanline;
        JDIMENSION linesize = line_size;
        unsigned char* p = pixels + (row*w*num_bytes_per_pixel);

        // Copy the pixel data to the output array
        for(int i=0; i<linesize; i+=3) {
            *p++ = buf[0];  // Red
            *p++ = buf[1];  // Green
            *p++ = buf[2];  // Blue
        }

        jpeg_read_scanlines(jptr, &buf, 1);
    }

    // Free the temporary buffer and decompression state
    free(image);
    jptr->temp_buffer = NULL;

    return pixels;
}

