std::vector<std::vector<uint8_t>> loadDescriptors(const std::vector<std::string>& filePaths, bool includeAlpha) {
    int totalDescriptors = 0;
    for (const auto& filePath : filePaths) {
        // Load descriptors from the current file
        // For simplicity, assume this is done using a custom function 'loadFile'
        const auto& fileDescriptors = loadFile(filePath);

        // Add the number of descriptors in the current file to the total count
        totalDescriptors += fileDescriptors.size();
    }

    std::vector<std::vector<uint8_t>> descriptorsMatrix(totalDescriptors, std::vector<uint8_t>(4)); // Assuming 3 dimensions by default

    int descriptorIndex = 0;
    for (const auto& filePath : filePaths) {
        // Load descriptors from the current file
        const auto& fileDescriptors = loadFile(filePath);

        for (const auto& descriptor : fileDescriptors) {
            // Store each descriptor in the matrix, converting to uint8_t if necessary
            std::copy(descriptor.begin(), descriptor.end(), descriptorsMatrix[descriptorIndex].begin());

            if (includeAlpha) {
                // Add alpha values as additional dimensions (assuming 2D)
                descriptorsMatrix[descriptorIndex].push_back(0); // X
                descriptorsMatrix[descriptorIndex].push_back(0); // Y
            }

            descriptorIndex++;
        }
    }

    return descriptorsMatrix;
