```c++
map<int, int> countingSort(vector<int>& nums) {
    map<int, int> freq;
    int max = *max_element(nums.begin(), nums.end());
    int min = *min_element(nums.begin(), nums.end());

    vector<int> count(max - min + 1, 0);

    for (int num : nums) {
        count[num - min]++;
    }

    for (int i = 0; i < count.size(); i++) {
        freq[i + min] = count[i];
    }

    return freq;
}
