int countConnectedComponents(char **edges) {
    int numNodes = 0;
    for (int i = 0; edges[i]; i++) {
        char *edge = strtok(edges[i], " ");
        int node1 = atoi(edge);
        edge = strtok(NULL, " ");
        int node2 = atoi(edge);
        if (node1 > numNodes) numNodes = node1;
        if (node2 > numNodes) numNodes = node2;
    }
    int **graph = (int **)malloc((numNodes + 1) * sizeof(int *));
    for (int i = 0; i <= numNodes; i++) {
        graph[i] = (int *)malloc((numNodes + 1) * sizeof(int));
        for (int j = 0; j <= numNodes; j++)
            graph[i][j] = 0;
    }
    numNodes++;
    for (int i = 0; edges[i]; i++) {
        char *edge = strtok(edges[i], " ");
        int node1 = atoi(edge);
        edge = strtok(NULL, " ");
        int node2 = atoi(edge);
        graph[node1][node2] = 1;
        graph[node2][node1] = 1;
    }
    int connectedComponents = 0;
    for (int i = 0; i < numNodes; i++) {
        if (graph[i][i] == 0) {
            DFS(graph, i);
            connectedComponents++;
        }
    }
    for (int i = 0; i <= numNodes; i++)
        free((void *)graph[i]);
    free((void *)graph);
    return connectedComponents;
}

void DFS(int **graph, int node) {
    graph[node][node] = 1;
    for (int i = 0; i < graph->numNodes; i++) {
        if (graph[node][i] == 1 && !graph[i][i]) {
            DFS(graph, i);
        }
    }
}
