void appendCIMValueToString(CIMValue& value, std::string& str) {
    if (value.isNull()) {
        str += "null";
    } else if (value.isArray()) {
        str += "[";
        for (int i = 0; i < value.size(); ++i) {
            CIMValue v = value.get(i);
            appendCIMValueToString(v, str);
            if (i < value.size() - 1) {
