std::string ipToString(HostAddress* address) {
    std::string result = "";

    uint16_t temp1 = ntohs(address->getIpv4());
    uint32_t temp2 = ntohl(address->getIpv6());

    if (temp1 != 0 || temp2 != 0) {
        if (address->isIPv4()) {
            char buffer[5];
            sprintf(buffer, "%d.%d.%d.%d", 
                    (temp1 >> 8) & 0xFF, 
                    (temp1 >> 0) & 0xFF,
                    (temp1 >> 16) & 0xFF, 
                    (temp1 >> 24) & 0xFF);
            result = std::string(buffer);
        } else if (address->isIPv6()) {
            char buffer[45];
            sprintf(buffer, "%02x%02x:%02x%02x:%02x%02x:%02x%02x:%02x%02x:%02x%02x",
                    (temp2 >> 40) & 0xFF, 
                    (temp2 >> 36) & 0xFF,
                    (temp2 >> 32) & 0xFF, 
                    (temp2 >> 28) & 0xFF,
                    (temp2 >> 24) & 0xFF, 
                    (temp2 >> 20) & 0xFF,
                    (temp2 >> 16) & 0xFF, 
                    (temp2 >> 12) & 0xFF,
                    (temp2 >> 8) & 0xFF, 
                    (temp2 >> 4) & 0xFF,
                    temp2 & 0xFF);
            result = std::string(buffer);
        }
    } else {
        result = "0.0.0.0";
    }

    return result;
}

