void applyPlasmaEffect(unsigned char *image, int width, int height, double roughness, const double *colormap) {
    int center_x = width / 2;
    int center_y = height / 2;

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            double dx = x - center_x;
            double dy = y - center_y;

            if (dx * dx + dy * dy <= roughness * roughness) {
                // Calculate new color values
                double r, g, b;
                if ((x / 2 < width / 4 && y / 2 < height / 4) || 
                    (width - x > width / 4 && y / 2 < height / 4)) {
                    center_x = width / 4;
                    center_y = height / 4;
                } else if ((x / 2 >= width / 4 && y / 2 < height / 4) || 
                           (width - x > width / 4 && y / 2 < height / 4)) {
                    center_x = width * 3 / 4;
                    center_y = height / 4;
                } else if ((x / 2 < width / 4 && y / 2 >= height / 4) || 
                           (width - x > width / 4 && y / 2 >= height / 4)) {
                    center_x = width / 4;
                    center_y = height * 3 / 4;
                } else {
                    center_x = width * 3 / 4;
                    center_y = height * 3 / 4;
                }

                r = colormap[0] + (rand() / (double) RAND_MAX) * (colormap[1] - colormap[0]);
                g = colormap[2] + (rand() / (double) RAND_MAX) * (colormap[3] - colormap[2]);
                b = colormap[4] + (rand() / (double) RAND_MAX) * (colormap[5] - colormap[4]);

                // Set new color values
                image[(y * width * 3) + (x * 3)] = (unsigned char)r;
                image[(y * width * 3) + (x * 3) + 1] = (unsigned char)g;
                image[(y * width * 3) + (x * 3) + 2] = (unsigned char)b;
            }
        }
    }
}

