#include <iostream>
#include <string>
#include <cstdlib>

#include <lcb_instance.h>
#include <lcb_uri.h>
#include <lcb_config.h>

using namespace std;

int main(int argc, char** argv) {
    string server = argv[1];
    string username = argv[2];
    string password = argv[3];
    string bucketName = argv[4];

    lcb_INSTANCE_t instance;
    lcb_create(&instance);
    lcb_set_opt(instance, LCB_OPT_USE_VB, 0);
    lcb_connect(instance, server.c_str(), atoi(argv[5]), 11210);

    if (lcb_wait_for_connect(instance) != LCB_SUCCESS) {
        cerr << "Failed to connect: " << lcb_strerror(lcb_get_last_error(instance)) << endl;
        return 1;
    }

    lcb_BUCKET_CREATE_t bucketCreate;
    lcb_create_bucket(&bucketCreate, instance);
    bucketCreate.vcb_name = (char*)bucketName.c_str();
    if (lcb_bucket_create(instance, &bucketCreate) != LCB_SUCCESS) {
        cerr << "Failed to create bucket: " << lcb_strerror(lcb_get_last_error(instance)) << endl;
        return 1;
    }

    string query = argc > 5 ? argv[6] : "SELECT * FROM `default` WHERE `mykey`='myvalue'";

    lcb_QUERY_t queryStruct;
    lcb_create_query(&queryStruct, instance);
    queryStruct.query.set_key(0, (char*)("mykey").c_str());
    queryStruct.query.nkeys = 1;

    if (lcb_query(instance, &queryStruct) != LCB_SUCCESS) {
        cerr << "Failed to execute query: " << lcb_strerror(lcb_get_last_error(instance)) << endl;
        return 1;
    }

    while (true) {
        lcb_RESPHDRU_t response;
        lcb_respond(instance, NULL, &response);
        if (response.type == LCB_RES_TYPE_QUERY_FINAL) {
            break;
        }
    }

    lcb_wait_for_response(instance);

    lcb_query_destroy(&queryStruct);

    lcb_close(instance);
    lcb_destroy(instance);

    return 0;
}

