```cpp
int extractTokens(const std::string& buffer, const std::string& delimiter, const std::string& specialValue, std::vector<std::string>& tokens) {
    size_t pos = 0;
    int count = 0;
    while ((pos = buffer.find(delimiter, pos)) != std::string::npos) {
        if (buffer.substr(pos - specialValue.size(), specialValue.size()) == specialValue) {
            pos += specialValue.size();
            continue;
        }
        size_t tokenStart = pos;
        size_t tokenEnd = buffer.find(delimiter, pos + 1);
        tokens.push_back(buffer.substr(tokenStart, tokenEnd - tokenStart));
        ++count;
        pos = tokenEnd;
    }
    if (pos < buffer.size()) {
        tokens.push_back(buffer.substr(pos));
        ++count;
    }
    return count;
}

