```c++
void executeKernel(cl_context context, cl_kernel kernel, size_t numElements, float* inputHost, float* outputHost) {
    // Allocate memory on device
    cl_mem inputDev = clCreateMemObject(context, CL_MEM_READ_ONLY, sizeof(float)*numElements);
    cl_mem outputDev = clCreateMemObject(context, CL_MEM_WRITE_ONLY, sizeof(float)*numElements);
    cl_mem tempDev = clCreateMemObject(context, CL_MEM_READ_WRITE, sizeof(float)*numElements);

    // Copy data from host memory to device memory
    clEnqueueWriteBuffer(context, inputDev, true, 0, numElements*sizeof(float), inputHost, nullptr, nullptr);
    clEnqueueWriteBuffer(context, outputDev, true, 0, numElements*sizeof(float), outputHost, nullptr, nullptr);

    // Set kernel arguments
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &inputDev);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &outputDev);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &tempDev);

    // Create command queue and execute kernel
    cl_command_queue queue = clCreateCommandQueue(context, nullptr);
    size_t globalWorkSize[1] = {numElements};
    clEnqueueNDRangeKernel(queue, kernel, 1, nullptr, globalWorkSize, nullptr);
    clFinish(queue);

    // Copy data from device memory back to host memory
    clEnqueueReadBuffer(context, outputDev, true, 0, numElements*sizeof(float), outputHost, nullptr, nullptr);

    // Release resources
    clReleaseMemObject(inputDev);
    clReleaseMemObject(outputDev);
    clReleaseMemObject(tempDev);
    clReleaseCommandQueue(queue);
}
