void sendPackets(double packetNumber) {
    static double maxPacketRate = 1000; // assume packets per second
    static double rttSum = 0;
    static double lostPackets = 0;
    static bool monitoringStarted = false;
    static auto startMonitoring = std::chrono::high_resolution_clock::now();
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_real_distribution<double> durDist(1.7, 2.2);

    if (packetNumber >= maxPacketRate * 1.7) {
        if (!monitoringStarted) {
            // start monitoring
            std::cout << "Monitoring started." << std::endl;
            rttSum = 0;
            lostPackets = 0;
        }
    } else if (packetNumber > 0 && monitoringStarted) {
        // stop monitoring
        std::chrono::duration<double> monitoringDuration = std::chrono::high_resolution_clock::now() - startMonitoring;
        double rtt = monitoringDuration.count();
        double packetLossRate = lostPackets / maxPacketRate;
        std::cout << "RTT: " << rtt << " seconds" << std::endl;
        std::cout << "Packet loss rate: " << packetLossRate << std::endl;
        monitoringStarted = false;
    }
}
