std::vector<std::string> generateRandomStrings(const std::vector<std::string>& baseStrings, size_t length) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, baseStrings.size() - 1);

    std::vector<std::string> result;

    for (size_t i = 0; i < length; ++i) {
        std::string str;
        size_t numBaseStrings = 1 + gen() % 5; // adjust the number of base strings to include
        for (size_t j = 0; j < numBaseStrings; ++j) {
            str += baseStrings[dis(gen)];
        }
        result.push_back(str);
    }

    return result;
}
