#include <vector>
#include <random>
#include <algorithm>

int closestSum(const std::vector<int>& nums, int target) {
    if (nums.empty()) {
        return 0;
    }

    std::vector<int> selected;
    int sum = 0;
    bool reachedTarget = false;

    while (sum < target && !reachedTarget) {
        int randomIndex = rand() % nums.size();
        int randomNum = nums[randomIndex];
        if (sum + randomNum <= target) {
            sum += randomNum;
            selected.push_back(randomNum);
        }
    }

    if (sum >= target) {
        reachedTarget = true;
    } else {
        for (int i : nums) {
            if (i > 0 && sum + i > target) {
                int closestDiff = abs(sum - target);
                for (int j : selected) {
                    if (abs(i - target) < closestDiff) {
                        closestDiff = abs(i - target);
                        break;
                    }
                }
                if (closestDiff == abs(i - target)) {
                    sum -= *std::min_element(selected.begin(), selected.end());
                    selected.erase(std::remove(selected.begin(), selected.end(), *std::min_element(selected.begin(), selected.end())), selected.end());
                    sum += i;
                    reachedTarget = true;
                }
            }
        }
    }

    return sum;
}

