    struct stat sb;
    if(stat(path, &sb) == -1) {
        printf("Error: File not found\n");
        return NULL;
    }

    FILE* file = fopen(path, "rb");
    if(file == NULL) {
        printf("Error: Could not open file\n");
        return NULL;
    }

    char magic[4];
    fread(magic, 1, 4, file);
    if(!strcmp((char*)magic, "RIFF")) {
        // Check the format of the sound file
        uint32_t size;
        fread(&size, sizeof(uint32_t), 1, file);
        fseek(file, 8, SEEK_SET);
        uint16_t fmtSize;
        fread(&fmtSize, sizeof(uint16_t), 1, file);
        if(fmtSize != 16) {
            printf("Error: Invalid sound format\n");
            fclose(file);
            return NULL;
        }

        // Read the rest of the file
        char* data = malloc(size - 8 - fmtSize);
        fread(data, 1, size - 8 - fmtSize, file);
        fclose(file);
        return data;
    } else {
        printf("Error: Not a valid sound file\n");
        fclose(file);
        return NULL;
    }
}
