#include <string.h>
#include <openssl/hmac.h>
#include <openssl/err.h>
#include <base64.h>

char* hmac_sha1(const char* message, const char* secret_key) {
    unsigned char* signature = NULL;
    int signature_len = 0;

    HMAC_CTX ctx;
    HMAC_Init(&ctx, secret_key, strlen(secret_key), EVP_md5());
    HMAC_Update(&ctx, (const unsigned char*)message, strlen(message));
    HMAC_Final(&ctx, &signature);
    signature_len = HMAC_Size(&ctx);

    char* base64_signature = malloc((signature_len * 4 + 1) * sizeof(char));
    base64_encode(signature, signature_len, base64_signature);

    free(signature);
    HMAC_cleanup(&ctx);

    return base64_signature;
}

