std::string kdf2(const std::string& password, const std::string& master_key, size_t output_length) {
    #include <hashes/sha1.hpp> // Boost.Crypto
    #include <digest/finalize.hpp> // Boost.Crypto

    using namespace boost::crypto;
    using namespace boost;

    SHA1 sha1;
    Hash<SHA1>::object hash = sha1;

    std::string result;

    for (size_t i = 0; i <= output_length / 64; ++i) {
        std::string block = password + master_key + std::to_string(i);
        SHA1::digest d = finalize(sha1.checksum(block.data(), block.size()));
        std::string key_part(d.begin(), d.end());
        result += key_part;
    }

    return result.substr(0, output_length);
}

BOOST_PYTHON_MODULE(kdf2)
{
    using namespace boost::python;

    def("kdf2", kdf2);
}
