int main() {
    // Calculate the cache line size
    int cacheLineSize = sysconf(_SC_PAGE_SIZE);

    int* ptr;
    int blockSize = 32;

    for(int i=0; i<blockSize; i++) {
        void* mem = aligned_malloc(blockSize, (i+1)*cacheLineSize);
        if(mem != NULL) {
            printf("Block size: %d bytes, Alignment: %d bytes\n", blockSize, (i+1)*cacheLineSize);
            // Check if the memory is properly aligned
            if(((long long)mem)%((i+1)*cacheLineSize) == 0) {
                printf("Memory is properly aligned.\n");
            } else {
                printf("Memory is not properly aligned.\n");
            }
            free(mem);
        } else {
            printf("Memory allocation failed.\n");
        }
    }

    return 0;
}

void* aligned_malloc(size_t size, size_t alignment) {
    int alignmentMask = (int)(alignment - 1);

    void* result = malloc(size + ((size + alignment - 1) & alignmentMask));
    if(result != NULL) {
        *((char*)result + size) = '\0';
    }

    return result;
}
