```c++
int findBestCombination(std::vector<std::pair<int, bool>>& pairs, int target) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    int total = 0;
    for (int i = 0; i < pairs.size(); ++i) {
        if (!pairs[i].second && dis(gen) == 1) {
            total += pairs[i].first;
            for (int j = i; j < pairs.size(); ++j) {
                pairs[j].second = true;
            }
        } else {
            break;
        }
    }

    int bestTotal = 0;
    int bestIndex = -1;
    for (int i = 0, totalCurr = 0; i < pairs.size() || totalCurr <= target; ++i) {
        if (i < pairs.size() && !pairs[i].second) {
            totalCurr += pairs[i].first;
            for (int j = i; j < pairs.size(); ++j) {
                pairs[j].second = true;
            }
        } else {
            if (totalCurr > bestTotal && totalCurr <= target) {
                bestTotal = totalCurr;
                bestIndex = i;
            }
            totalCurr -= pairs[i-1].first;
            for (int j = i; j < pairs.size(); ++j) {
                pairs[j].second = false;
            }
        }
    }

    if (bestIndex == -1 || bestTotal > target) {
        return -1;
    } else {
        int resultTotal = 0;
        for (int i = 0, totalCurr = 0; i < pairs.size() || totalCurr <= target; ++i) {
            if (i < pairs.size() && !pairs[i].second) {
                totalCurr += pairs[i].first;
                for (int j = i; j < pairs.size(); ++j) {
                    pairs[j].second = true;
                }
            } else {
                if (totalCurr > bestTotal && totalCurr <= target) {
                    resultTotal = totalCurr;
                    break;
                }
                totalCurr -= pairs[i-1].first;
                for (int j = i; j < pairs.size(); ++j) {
                    pairs[j].second = false;
                }
            }
        }

        std::vector<int> bestCombination;
        int totalCurr2 = 0;
        for (int i = 0, j = bestIndex; i < pairs.size() || totalCurr2 <= target; ++i, ++j) {
            if (i < pairs.size() && !pairs[j].second) {
                totalCurr2 += pairs[j].first;
                bestCombination.push_back(pairs[j].first);
                for (int k = j; k < pairs.size(); ++k) {
                    pairs[k].second = true;
                }
            } else {
                if (totalCurr2 > resultTotal && totalCurr2 <= target) {
                    break;
                }
                totalCurr2 -= pairs[i-1].first;
                for (int k = i; k < pairs.size(); ++k) {
                    pairs[k].second = false;
                }
            }
        }

        return bestCombination.size();
    }
}

```cpp
#include <iostream>
#include <cmath>
#include <cstdlib>

int** convolution(int** img, int** filter, float bias, int kernel_size, int stride) {
    int rows = sizeof(img)/sizeof(img[0]);
    int cols = sizeof(img[0])/sizeof(img[0][0]);
    int filter_rows = sizeof(filter)/sizeof(filter[0]);
    int filter_cols = sizeof(filter[0])/sizeof(filter[0][0]);

    // Create output image with the same dimensions as input
    int** out_img = new int*[rows];
    for(int i = 0; i < rows; i++) {
        out_img[i] = new int[cols];
    }

    // Perform convolution operation
    for(int i = 0; i < rows-kernel_size+1; i++) {
        for(int j = 0; j < cols-filter_cols+1; j++) {
            float sum = 0;
            for(int k = 0; k < kernel_size; k++) {
                for(int l = 0; l < filter_cols; l++) {
                    sum += (img[i+k][j+l] * filter[k][l]);
                }
            }
            out_img[i][j] = static_cast<int>(sum + bias);
        }
    }

    // Perform max pooling operation
    int new_rows = rows / stride;
    int new_cols = cols / stride;
    int** pool_img = new int*[new_rows];
    for(int i = 0; i < new_rows; i++) {
        pool_img[i] = new int[new_cols];
    }
    for(int i = 0; i < new_rows; i++) {
        for(int j = 0; j < new_cols; j++) {
            float max_val = out_img[i*stride][j*stride];
            for(int k = 0; k < kernel_size; k++) {
                for(int l = 0; l < filter_cols; l++) {
                    if(out_img[i*stride+k][j*stride+l] > max_val) {
                        max_val = out_img[i*stride+k][j*stride+l];
                    }
                }
            }
            pool_img[i][j] = static_cast<int>(max_val);
        }
    }

    // Clean up
    for(int i = 0; i < rows; i++) {
        delete[] out_img[i];
    }
    delete[] out_img;
    for(int i = 0; i < new_rows; i++) {
        delete[] pool_img[i];
    }
    delete[] pool_img;

    return pool_img;
}

