```c
void extract_tokens(char* str, char** tokens) {
    int i = 0;
    bool in_quote = false;

    for (int j = 0; j < strlen(str); j++) {
        char c = str[j];

        if (!in_quote && (isspace(c) || c == '-' || isdigit(c))) {
            while ((j + 1 < strlen(str)) && (str[j + 1] == ' ' || str[j + 1] == '\t')) j++;
            tokens[i++] = &str[j];
            while ((j + 1 < strlen(str)) && (c != ' ' && c != '\t') && (!in_quote || c == '"')) {
                if (c == '"') in_quote = !in_quote;
                j++;
            }
        } else if (!in_quote && (c == '"' || c == '\'')) {
            in_quote = true;
            while ((j + 1 < strlen(str)) && str[j + 1] != ' ' && str[j + 1] != '\t' && str[j + 1] != c) j++;
            if (str[j + 1] == c) j++; // skip the quote
        }
    }
    tokens[i] = NULL;
}
