int match_strings(const char *s1, const char *s2) {
    int result = 0;
    stack<char> fold_stack;

    for (; *s1 && *s2; s1++, s2++) {
        if (isupper(*s1)) {
            fold_stack.push(islower(*s1));
        } else if (!isalpha(*s1) || islower(*s1)) {
            if (!fold_stack.empty() && tolower(*s1) == fold_stack.top()) {
                result++;
                fold_stack.pop();
            }
        } else {
            if (tolower(*s1) != tolower(*s2)) {
                break;
            } else {
                result++;
            }
        }
    }

    return result;
}
