```cpp
struct Option {
    std::string name;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& optionsStr) {
    std::vector<Option> options;
    size_t pos = 0, commaPos = 0;

    while ((commaPos = optionsStr.find(',', pos)) != std::string::npos) {
        if (commaPos - pos < 2) { // Not a valid option
            return {};
        }

        Option opt;
        size_t keyEnd = optionsStr.find('=', pos);
        if (keyEnd == std::string::npos || commaPos > keyEnd) { // Key not found or malformed
            return {};

        } else {
            opt.name = optionsStr.substr(pos, keyEnd - pos);
        }

        opt.value = optionsStr.substr(keyEnd + 1, commaPos - (keyEnd + 1));
        options.push_back(opt);

        pos = commaPos + 1;
    }

    if (pos < optionsStr.size()) { // Last option not parsed
        Option opt;
        size_t keyEnd = optionsStr.find('=', pos);
        if (keyEnd == std::string::npos) { // Malformed last option
            return {};

        } else {
            opt.name = optionsStr.substr(pos, keyEnd - pos);
            opt.value = optionsStr.substr(keyEnd + 1);
            options.push_back(opt);
        }
    }

    return options;
}
