#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<std::vector<std::string>> studentRecords;

    std::string line;
    while (std::getline(std::cin, line)) {
        size_t spacePos = 0;
        std::vector<std::string> record;

        while ((spacePos = line.find(" ")) != std::string::npos) {
            record.push_back(line.substr(0, spacePos));
            line.erase(0, spacePos + 1);
        }

        if (!line.empty()) {
            record.push_back(line);
        }

        studentRecords.push_back(record);
    }

    for (const auto& record : studentRecords) {
        std::cout << "Name: " << record[1] << ", Student ID: " << record[0] << "\n";
    }
}

