#include <vector>
#include <cstdlib>

void percolationStep(std::vector<int>& sites, double probability, int timeStep) {
    int siteIndex = rand() % sites.size();

    if (sites[siteIndex] == 0 && (double)rand() / RAND_MAX <= probability) {
        for (int i = 0; i < sites.size(); i++) {
            if (i > siteIndex) {
                sites[i]++;
            }
        }
    } else if (sites[siteIndex] > 0) {
        for (int i = 0; i < sites.size(); i++) {
            if (i > timeStep && sites[i] > 0) {
                sites[i]--;
            }
        }
    }
}
