#include <string>
#include <vector>
#include <boost/lexical_cast.hpp>
#include <boost/url.hpp>

std::vector<std::string> extractUrlComponents(const std::string& url) {
    boost::url parsed_url(url);

    if (parsed_url.scheme().empty()) return {};

    std::vector<std::string> components = { 
        parsed_url.scheme(),  // protocol
        parsed_url.host(),   // host
        boost::lexical_cast<std::string>(parsed_url.port()).empty() ? "" : parsed_url.port().to_string()
    };

    return components;
}
