int initOpenGLApp(char* title, int majorVersion, int minorVersion, unsigned char red, unsigned char green, unsigned char blue, float depth) {
    // Initialize the OpenGL context
    glewExperimental = GL_TRUE;
    if (glewInit() != GLEW_OK) {
        std::cerr << "Failed to initialize OpenGL" << std::endl;
