int loadRobotFromFile(const std::string& fileName, std::vector<Robot>& robotCollection) {
    int index = -1;
    size_t found = fileName.find('.');
    if (found != std::string::npos) {
        std::string robotId = fileName.substr(0, found);
        Robot newRobot(robotId);
        std::ifstream file(fileName);
        if (file.is_open()) {
            file >> newRobot;
            robotCollection.push_back(newRobot);
            index = robotCollection.size() - 1;
            file.close();
        } else {
            // File could not be opened
        }
    } else {
        // No extension found in the file name
    }
    return index;
}

