SkDashPathEffect* createDashPathEffect(SkScalar* intervals, int count, SkScalar phase, bool scaleToFit) {
    SkDashPathEffect* dash = (SkDashPathEffect*) sk_malloc_throw(sizeof(SkDashPathEffect));
    if (!dash) return NULL;

    dash->fIntervals = intervals;
    dash->fCount = count;

    SkScalar totalLength = 0;
    for (int i = 0; i < count; ++i) {
        totalLength += intervals[i];
    }
    dash->fIntervalLength = totalLength;

    return dash;
}

