int run_command_background(char *command) {
    pid_t pid = fork();
    if (pid < 0) {
        return 0;
    } else if (pid == 0) {
        dup2(STDOUT_FILENO, STDOUT_FILENO);
        dup2(STDERR_FILENO, STDERR_FILENO);
        execlp(command, command, NULL);
        return 1; // unreachable
    }
    int status;
    wait(&status);
    return WIFEXITED(status);
}

int pop_iovcs(void *handle, size_t n, ...) {
    va_list ap;
    va_start(ap, n);
    int count = n / 2;
    iovec *iovcs = alloca(count * sizeof(iovec));
    for (size_t i = 0; i < count; ++i) {
        iovcs[i].iov_base = va_arg(ap, void *);
        iovcs[i].iov_len = va_arg(ap, size_t);
    }
    va_end(ap);
    return count;
}

