```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LENGTH 20

typedef struct {
    int day;
    int month;
    int year;
} Date;

int haab_days(int year) {
    if (year % 4 == 0)
        return 365;
    else
        return 366;
}

int days_between_dates(Date d1, Date d2) {
    int days = 0;
    for (int i = d1.year; i < d2.year; i++) {
        days += haab_days(i);
    }
    if (d1.month > d2.month || (d1.month == d2.month && d1.day >= d2.day)) {
        return -1;
    } else {
        for (int j = d1.day; j < d2.day; j++) {
            days++;
        }
        return days;
    }
}

int main() {
    Date dates[100];
    int i = 0;
    while (1) {
        char line[MAX_LENGTH];
        if (!fgets(line, MAX_LENGTH, stdin)) break;
        char *token = strtok(line, ".");
        dates[i].day = atoi(token);
        token = strtok(NULL, " ");
        dates[i].month = atoi(token);
        token = strtok(NULL, "\n");
        dates[i++].year = atoi(token);
    }
    for (int j = 1; j < i; j++) {
        printf("%d\n", days_between_dates(dates[j-1], dates[j]));
    }
    return 0;
}

