#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

struct datos {
    char CURP[11];
    char celular[12];
    char partido[6];
};

int main() {
    int sockfd, connfd;
    struct sockaddr_in servaddr, cliaddr;
    struct datos datos_envio;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("socket creation failed\n");
        exit(1);
    }

    // Set server address
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        printf("connection failed\n");
        exit(1);
    }

    // Create data packet
    strcpy(datos_envio.CURP, "12345678901");
    strcpy(datos_envio.celular, "3130000000");
    strcpy(datos_envio.partido, "PRD");

    // Send data packet
    if (send(sockfd, &datos_envio, sizeof(struct datos), 0) < 0) {
        printf("send failed\n");
        exit(1);
    }

    // Receive response
    char buffer[100];
    int bytes_recv = recv(sockfd, buffer, sizeof(buffer), 0);

    if (bytes_recv < 0) {
        printf("recv failed\n");
        exit(1);
    }

    // Print response
    printf("Response: %s\n", buffer);

    // Close sockets
    close(sockfd);

    return 0;
}
