TorConn conn;

void setupHiddenService(const char* private_key) {
    tor_set_conf("VirtualSocksListenAddress", "127.0.0.1:9050");
    tor_set_conf("VirtualSocksPort", "9050");
    tor_set_conf("ControlPort", "9051");

    if (tor_control_authenticate()) {
        printf("Authentication failed.\n");
        return;
    }

    char onion_address[256];
    int ret = tor_add_onion(private_key, onion_address, 256);
    if (ret < 0) {
        printf("Failed to create onion address: %d\n", ret);
        return;
    }

    conn = tor_connect(onion_address);

    if (!conn) {
        printf("Failed to connect to the hidden service.\n");
    }
}
