```c++
#include <iostream>
#include <string>
#include <iomanip>
#include <openssl/sha.h>
#include <openssl/hmac.h>

std::string hmacSha256(const std::string& message, const std::string& secret) {
    unsigned char key[secret.size()];
    for (int i = 0; i < secret.size(); ++i)
        key[i] = static_cast<unsigned char>(secret[i]);

    unsigned char* msg = reinterpret_cast<unsigned char*>(message.c_str());
    int msg_len = message.size();

    unsigned char hmac[EVP_MAX_DIGEST_SIZE];
    size_t hmac_len;

    HmacSHA256_CTX ctx;
    HMAC_CTX_init(&ctx);
    HMAC_Init_ex(&ctx, key, secret.size(), EVP_sha256(), NULL);
    HMAC_Update(&ctx, msg, msg_len);
    HMAC_Final(&ctx, hmac, &hmac_len);

    std::string result;
    for (int i = 0; i < hmac_len; ++i) {
        char buffer[3];
        sprintf(buffer, "%02x", hmac[i]);
        result.append(buffer);
    }

    HMAC_CTX_cleanup(&ctx);

    return result;
}

