float** computeDifferences(int width, int height)
{
    float** arr = new float*[width];
    for (int i = 0; i < width; i++) {
        arr[i] = new float[height];
    }

    // Initialize array with values
    for (int i = 0; i < width; i++) {
        for (int j = 0; j < height; j++) {
            arr[i][j] = (float)(i + j);
        }
    }

    // Compute differences in all directions
    for (int i = 1; i < width - 1; i++) {
        for (int j = 1; j < height - 1; j++) {
            arr[i][j] -= (arr[i-1][j] + arr[i+1][j] + arr[i][j-1] + arr[i][j+1] +
                           arr[i-1][j-1] + arr[i-1][j+1] + arr[i+1][j-1] + arr[i+1][j+1]);
        }
    }

    return arr;
}
