#include <iostream>
#include <fstream>
#include <vector>

using namespace std;

struct DataPoint {
    double x, y;
};

double calculateLinearRegression(const vector<DataPoint>& data) {
    int n = data.size();
    double sumX = 0.0, sumY = 0.0, sumXY = 0.0, sumXSq = 0.0;

    for (const auto& point : data) {
        sumX += point.x;
        sumY += point.y;
        sumXY += point.x * point.y;
        sumXSq += point.x * point.x;
    }

    double m = (n * sumXY - sumX * sumY) / (n * sumXSq - pow(sumX, 2));
    double b = (sumY - m * sumX) / n;

    return b;
}

int main() {
    ifstream file("data.txt");
    vector<DataPoint> data;

    if (!file) {
        cout << "Error opening file.\n";
        return -1;
    }

    DataPoint point;
    while (file >> point.x >> point.y) {
        data.push_back(point);
    }

    double result = calculateLinearRegression(data);

    cout << "Number of data points: " << data.size() << endl;
    cout << "Result of linear regression: " << result << endl;

    return 0;
}

