            MyClass(int i) : val(i) {}
            ~MyClass() { ++count; }
        private:
            int val;
            static int count;
    };

    auto_ptr<MyClass> p(new MyClass(5));

    p.reset();
    assert(!p.get());

    p = auto_ptr<MyClass>(new MyClass(10));
    assert(p.get());

    delete p.release();
    assert(!p.get());

    assert(MyClass::count == 2);
}

