Mesh deepCopy(const Mesh& mesh) {
    Mesh copiedMesh;

    copiedMesh.vertices = new Vertex*[mesh.vertices.size()];
    for (int i = 0; i < mesh.vertices.size(); i++) {
        copiedMesh.vertices[i] = new Vertex(*mesh.vertices[i]);
    }

    copiedMesh.indices = new int[mesh.indices.size()];
    std::copy(mesh.indices.begin(), mesh.indices.end(), copiedMesh.indices);

    return copiedMesh;
}

