```cpp
#include <cuda_runtime.h>
#include <cublas_v2.h>

void sparseMatrixToEigen(CUdeviceptr d_A, int* A_size, int*** result_eigenvalue,
                          int** result_eigenvector, int* result_eigen_num) {
    // Define the interval of eigenvalues
    double low = 0.0;
    double high = 10000.0;

    // Calculate the number of non-zero elements in the matrix
    int count = 0;
    for (int i = 0; i < *A_size; i++) {
        for (int j = 0; j < *A_size; j++) {
            if (A[i][j] != 0) {
                count++;
            }
        }
    }

    // Calculate the eigenvectors and eigenvalues using CUDA
    int* d_eigenvalue;
    int** d_eigenvector;

    cudaMalloc((void**)&d_eigenvalue, sizeof(double) * count);
    cudaMalloc((void**)&d_eigenvector, sizeof(int*) * count);

    cudaMemcpy(d_eigenvalue, &low, sizeof(double), cudaMemcpyHostToDevice);
    cudaMemcpy(d_eigenvalue + 1, &high, sizeof(double), cudaMemcpyHostToDevice);

    cublasSsyevd(CUBLAS_REAL_N, CUBLAS_FILL_MODE_UPPER, d_A,
                 *A_size, *A_size, (void*)d_eigenvalue, (void**)d_eigenvector, count);

    // Copy the data from the device to the host
    cudaMemcpy(result_eigenvalue, d_eigenvalue, sizeof(double) * count, cudaMemcpyDeviceToHost);
    for (int i = 0; i < count; i++) {
        cudaMemcpy(&result_eigenvector[i][0], &d_eigenvector[i][0],
                   sizeof(int) * (*A_size), cudaMemcpyDeviceToHost);
    }

    // Release memory
    cudaFree(d_eigenvalue);
    for (int i = 0; i < count; i++) {
        cudaFree(&d_eigenvector[i]);
    }
    cudaFreeArray(CUDA_ARRAY_OF_STRUCTS, sizeof(int));
}
