```c
#include <openssl/err.h>
#include <openssl/kdf.h>

int derive_key(const char *password, const char *salt, int rounds, int method) {
    EVP_PBE_CTX *ctx;
    unsigned char *key = NULL, *iv = NULL;
    unsigned long key_len = 0, iv_len = 0;
    int ret;

    if ((ret = EVP_PBE_CTX_new()) != 1) return 0; // error

    ctx = EVP_PBE_CTX_set_method(ctx, method); // select the algorithm
    if (!ctx) return 0; // error

    if ((ret = EVP_PBE_CTX_set_key_length(ctx, 32)) != 1) return 0; // error
    if ((ret = EVP_PBE_CTX_set_iv_length(ctx, 16)) != 1) return 0; // error

    if ((ret = EVP_PBE_CTX_init(ctx, password, strlen(password), salt, strlen(salt))) != 1) return 0; // error

    ret = EVP_PBE_CTX_do_pbe(ctx, &key, &key_len, &iv, &iv_len);

    EVP_PBE_CTX_free(ctx); // free the context

    if (ret <= 0 || !key || !iv) return 0; // failure
    if (key_len != 32 || iv_len != 16) return 0; // wrong key or IV length

    free(key);
    free(iv);

    return 1;
}

