std::string convertToAnsi(const std::wstring& wstr) {
    const int BUF_SIZE = 1024;
    char* buff = new char[BUF_SIZE];
    size_t len = 0;

    for (const wchar_t* wptr = wstr.c_str(); *wptr; ++wptr) {
        size_t bytes = wcstombs(buff + len, wptr, BUF_SIZE - len);
        if (bytes == (size_t)-1) break;
        len += bytes;
    }

    std::string ansiStr(buff, len);
    delete[] buff;

    return ansiStr;
}

