#include <openssl/err.h>
#include <openssl/pbkdf2.h>

int derive_key(char *password, char *salt) {
    unsigned char key[32];
    unsigned char derivedKey[32];
    int iterations = 1000;
    int derivations = 1;

    if (!PKCS5_PBKDF2(password, strlen(password), salt, strlen(salt), iterations, derivations, key)) {
        ERR_error_fp(stderr, NULL);
        return 0;
    }

    // Perform the same derivation process to get a derivedKey
    if (!PKCS5_PBKDF2(password, strlen(password), salt, strlen(salt), iterations, derivations, derivedKey)) {
        ERR_error_fp(stderr, NULL);
        return 0;
    }

    for (int i = 0; i < sizeof(key); i++) {
        if (key[i] != derivedKey[i]) {
            return 0;
        }
    }

    return 1;
}
