char* read_child_stdout(pid_t pid){
    char buffer[1024];
    size_t len = 0;
    int status;
    FILE* stream = fopen("/proc/self/fd/" + (pid)., "r");
    if(stream == NULL || (fseek(stream, 0L, SEEK_END) != 0)){
        return NULL;
    }
    size_t size = ftell(stream);
    rewind(stream);
    if(size > sizeof(buffer)-1){
        buffer[size-1] = '\0';
        char* output = malloc(size+1);
        fread(output, 1, size, stream);
        fclose(stream);
        return output;
    }else{
        fread(buffer, 1, size, stream);
        fclose(stream);
        buffer[size-1] = '\0';
        return strdup(buffer);
    }
}

