float* compute_normals(float* points, int num_points) {
    float* p0 = &points[0];
    float* p1;
    float* normals = alloca(num_points * sizeof(float));
    for (int i = 0; i < num_points - 1; i++) {
        p1 = &points[i + 1];
        float dx = p1[0] - p0[0];
        float dy = p1[1] - p0[1];
        float length = sqrt(dx * dx + dy * dy);
        normals[i*2] = dx / length;
        normals[i*2+1] = dy / length;
        p0 = p1;
    }
    return normals;
}

