#include <wchar.h>

wchar_t* read_file(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return NULL; // error opening file

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    wchar_t *buffer = (wchar_t *)malloc((length + 1) * sizeof(wchar_t));
    if (!buffer) return NULL; // error allocating memory

    size_t bytesRead = fread(buffer, 2, length/2, file);
    buffer[length] = L'\0'; // null-terminate the string
    fclose(file);

    if (bytesRead < length/2) {
        free(buffer); // not all bytes were read, so free and return NULL
        return NULL;
    }

    return buffer;
}

