char *receiveReply(int sock) {
    char buffer[1024];
    int bytesRead = recv(sock, buffer, 1023, 0);
    if (bytesRead == -1) {
        return NULL;
    }

    char *message = malloc(bytesRead + 1);
    memcpy(message, buffer, bytesRead);
    message[bytesRead] = '\0';

    char *userID = strstr(message, "User ID: ");
    if (!userID) {
        free(message);
        return NULL;
    }

    int userIdLength = strlen(userID) - 10; // assume "User ID: " is 10 characters long
    char *userIdStr = malloc(userIdLength + 1);
    memcpy(userIdStr, userID + 10, userIdLength);
    userIdStr[userIdLength] = '\0';

    int replyLen = bytesRead + strlen("Reply from server: ") + userIdLength + 2;
    char *reply = malloc(replyLen);
    strcpy(reply, message);
    strcat(reply, "Reply from server: ");
    strcat(reply, userIdStr);
    strcat(reply, "\n");

    free(message);
    free(userIdStr);

    send(sock, reply, replyLen - 1, 0);

    return reply;
}

