int** bfs(int **adj_matrix, int num_nodes, int start_node) {
    int *visited = (int*)malloc(num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) visited[i] = 0;

    int **queue = (int**)malloc(1 * sizeof(int*));
    *(queue) = (int*)malloc(num_nodes * sizeof(int));

    int queue_size = 0;
    int front = 0, rear = 0;
    visited[start_node] = 1;
    int *path = NULL;

    while (1) {
        if (front > rear) break;

        for (int i = front; i <= rear; i++) {
            int node = queue[i][0];
            for (int j = 1; j < num_nodes; j++) {
                if (adj_matrix[node][j] && !visited[j]) {
                    visited[j] = 1;
                    *(queue + (++rear)) = (int*)malloc(num_nodes * sizeof(int));
                    *(queue[rear]) = (int){j};
                }
            }
        }

        front = rear + 1;
    }

    for (int i = 0; i < num_nodes; i++) {
        if (!visited[i] && adj_matrix[start_node][i]) {
            path = (int*)malloc(num_nodes * sizeof(int));
            int j = start_node;
            int k = i;
            while (k) {
                path[++] = k;
                for (int l = 0; l < num_nodes; l++) if (adj_matrix[k][l] && visited[l]) k = l;
            }
            break;
        }
    }

    free(visited);
    int **temp = queue;
    queue = *queue;
    *temp = NULL;
    while (rear--) {
        int *temp2 = *(queue + rear);
        *(queue + rear) = temp;
        temp = temp2;
    }
    free(temp);

    return path;
}
