int estimateStorage(double threshold, int numSequences) {
    const double byteToKB = 1024;
    const double byteToMB = 1024 * byteToKB;
    const double byteToGB = 1024 * byteToMB;
    const double byteToTB = 1024 * byteToGB;

    double storagePerSequence = log2(numSequences) + threshold; // in bytes

    int estimatedStorage = static_cast<int>(storagePerSequence);

    if (estimatedStorage >= byteToTB) {
        printf("Estimated maximum storage required: %.2f TB\n", (double)estimatedStorage / byteToTB);
    } else if (estimatedStorage >= byteToGB) {
        printf("Estimated maximum storage required: %.2f GB\n", (double)estimatedStorage / byteToGB);
    } else if (estimatedStorage >= byteToMB) {
        printf("Estimated maximum storage required: %.2f MB\n", (double)estimatedStorage / byteToMB);
    } else if (estimatedStorage >= byteToKB) {
        printf("Estimated maximum storage required: %.2f KB\n", (double)estimatedStorage / byteToKB);
    } else {
        printf("Estimated maximum storage required: %d bytes\n", estimatedStorage);
    }

    return estimatedStorage;
}

