#include <vector>
#include <flann.hpp>

int knnSearch(const std::vector<std::pair<float, float>>& points, const std::vector<std::pair<float, float>>& queryPoint, float radius) {
    flann::Matrix<float> indexedPoints;
    for (const auto& point : points) {
        indexedPoints.resize(indexedPoints.rows + 1);
        indexedPoints.row(indexedPoints.rows - 1).setConstant(0);
        indexedPoints.row(indexedPoints.rows - 1)(0) = point.first;
        indexedPoints.row(indexedPoints.rows - 1)(1) = point.second;
    }

    flann::SearchParams searchParams;
    searchParams cores = 4; // adjust this based on your system's available CPU cores
    searchParams.useIndexedLshSearch = false;

    int neighborsFound = 0;
    for (const auto& queryPointPair : queryPoint) {
        indexedPoints.resize(indexedPoints.rows + 1);
        indexedPoints.row(indexedPoints.rows).setConstant(0);
        indexedPoints.row(indexedPoints.rows)(0) = queryPointPair.first;
        indexedPoints.row(indexedPoints.rows)(1) = queryPointPair.second;

        flann::Matrix<float> results;
        int kNNResult = flann::kdtreeSingleIndexSearch<flann::L2>(indexedPoints, &results, searchParams);
        for (int i = 0; i < kNNResult; ++i) {
            if ((results.row(i)(1) - queryPointPair.second) * (results.row(i)(1) - queryPointPair.second) + 
                (results.row(i)(0) - queryPointPair.first) * (results.row(i)(0) - queryPointPair.first) <= radius * radius)
                ++neighborsFound;
        }
    }

    return neighborsFound;
}

