```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TrieNode {
    char c;
    int count;
    struct TrieNode* children[26];
} TrieNode;

TrieNode* create_node(char c) {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    node->c = c;
    for(int i = 0; i < 26; i++) {
        node->children[i] = NULL;
    }
    return node;
}

void insert_string(TrieNode** root, char* str) {
    TrieNode* current = *root;
    for(char c : str) {
        int index = c - 'a';
        if(current->children[index] == NULL) {
            current->children[index] = create_node(c);
        }
        current = current->children[index];
    }
}

void count_chars(TrieNode* root, int* counts) {
    for(int i = 0; i < 26; i++) {
        if(root->children[i] != NULL) {
            counts[i]++;
            TrieNode* node = root->children[i];
            while(node != NULL) {
                counts[node->c - 'a']++;
                node = node->children[0];
            }
        }
    }
}

int* count_chars_in_string(char* str) {
    int len = strlen(str);
    TrieNode* root = create_node('\0');
    insert_string(&root, str);

    int* counts = (int*)malloc(sizeof(int) * 26);
    for(int i = 0; i < 26; i++) {
        counts[i] = 0;
    }

    count_chars(root, counts);

    return counts;
}
