int* reduceList(int* entries, int entriesCount) {
    int i = 0;
    int j = 0;
    int* result = NULL;

    for (i = 0; i < entriesCount; i++) {
        bool found = false;
        for (j = 0; j < i; j++) {
            if (entries[i] == result[j]) {
                found = true;
                break;
            }
        }
        if (!found) {
            if (result == NULL) {
                int* temp = malloc((++j) * sizeof(int));
                result = temp;
            } else {
                int* temp = realloc(result, (j + 1) * sizeof(int));
                result = temp;
            }
            result[j - 1] = entries[i];
        }
    }

    int uniqueEntriesCount = i;

    return result;
}
