```c
int ways(int n, int k, int dp[][k+1]) {
    if (n == 0) return 1;
    if (dp[n][k] != -1) return dp[n][k];
    int res = 0;
    for (int i = 0; i <= k; i++) {
        res += ways(n-1, i, dp);
    }
    dp[n][k] = res;
    return res;
}

int chooseLetters(int n, int m) {
    int dp[n+1][m+1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            dp[i][j] = -1;
        }
    }
    return ways(n, m, dp);
}

