void renderImage(Camera& camera, ViewModel& viewmodel, int width, int height, std::vector<std::thread>& threads, Color** image) {
    int numThreads = threads.size();
    int threadSize = height / numThreads;

    for (int i = 0; i < numThreads; i++) {
        int startRow = i * threadSize;
        int endRow = (i == numThreads - 1) ? height : (i + 1) * threadSize;

        threads[i] = std::thread([&, i, startRow, endRow]() {
            for (int j = 0; j < width; j++) {
                Color pixelColor;
                camera.GetPixelColor(viewmodel, j, startRow, pixelColor);
                image[i][j] = pixelColor;
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

