    if (len < 0 || len >= sizeof(buffer)) return -1;
    for (int i = 0; i < n; i++) {
        len += snprintf(&buffer[len], sizeof(buffer) - len, "%d", integers[i]);
        if (len < 0 || len >= sizeof(buffer)) return -1;
        if (i < n-1) {
            len += snprintf(&buffer[len], sizeof(buffer) - len, " ");
            if (len < 0 || len >= sizeof(buffer)) return -1;
        }
    }
    buffer[len] = '\0';
    return 0;
}

