    // Ask user for new name
    printf("Enter new file name: ");
    scanf("%255s", newFileName);

    while (1) {
        fp = fopen(newFileName, "r");
        if (fp != NULL) {
            printf("File already exists. Try another name.\n");
            printf("Enter new file name: ");
            scanf("%255s", newFileName);
        } else {
            fclose(fp);
            rename(originalName, newFileName);
            return 0;
        }
    }

    return -1;
}

