#include <vector>
#include <random>

std::vector<std::vector<float>> createRandomInputData(int batch_size, int input_dim, int seq_len, float density = 0.5f) {
    std::vector<std::vector<float>> data(batch_size);

    if(seq_len > 0) { // sequence data
        for(auto& row : data) {
            row.resize(seq_len);
            for(int i = 0; i < seq_len; ++i) {
                row[i] = static_cast<float>(std::rand()) / RAND_MAX;
            }
        }
    } else if(density > 0.f) { // sparse
        std::random_device rd;
        std::mt19937 gen(rd());
        std::bernoulli_distribution d(density);

        for(auto& row : data) {
            row.resize(input_dim);
            for(int i = 0; i < input_dim; ++i) {
                if(d(gen)) {
                    row[i] = static_cast<float>(std::rand()) / RAND_MAX;
                } else {
                    row[i] = 0.f;
                }
            }
        }
    } else { // dense
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<float> distribution;

        for(auto& row : data) {
            row.resize(input_dim);
            for(int i = 0; i < input_dim; ++i) {
                row[i] = distribution(gen);
            }
        }
    }

    return data;
}
