#include <stdio.h>
#include <stdlib.h>
#include <float.h>

void topicModeling(int wp_rows, int wp_cols, double *wp, int dp_rows, int dp_cols, double *dp, int *probs, int *sumdp, int *ztot) {
    probs = (int *)malloc(wp_rows * sizeof(int));
    sumdp = (int *)malloc(wp_rows * sizeof(int));
    ztot = (int *)malloc(dp_rows * sizeof(int));

    for(int i = 0; i < wp_rows; i++) {
        double total = 0.0;
        for(int j = 0; j < dp_cols; j++) {
            probs[i] += (wp[i][j] * dp[j][i]);
            total += wp[i][j];
        }
        sumdp[i] = total;
    }

    for(int i = 0; i < dp_rows; i++) {
        int ztot_tmp = 0;
        for(int j = 0; j < wp_rows; j++) {
            ztot[i] += probs[j] * (wp[j][i]);
            ztot_tmp += (int)wp[j][i];
        }
        ztot[i] = ztot_tmp;
    }
}

