#include <vector>

std::vector<std::vector<double>> addBorder(const std::vector<std::vector<double>>& arr, double val) {
    int rows = arr.size();
    int cols = arr[0].size();

    // Create new 2D array with extra row and column for border values
    std::vector<std::vector<double>> result(rows + 2, std::vector<double>(cols + 2));

    // Fill in the border values
    for (int i = 0; i <= rows; ++i) {
        for (int j = 0; j <= cols; ++j) {
            if (i > 0 && j > 0) {
                result[i][j] = arr[i - 1][j - 1] + val;
            } else {
                result[i][j] = val;
            }
        }
    }

    return result;
}

