int parseBinaryFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return -1; // error opening file
    }

    int numBlocks;
    fread(&numBlocks, sizeof(int), 1, file);

    int *blockIndices;
    blockIndices = malloc(numBlocks * sizeof(int));
    if (!blockIndices) {
        fclose(file);
        return -2; // error allocating memory for block indices
    }

    for (int i = 0; i < numBlocks; i++) {
        fread(&blockIndices[i], sizeof(int), 1, file);
    }

    fclose(file);

    return numBlocks;
}

