```cpp
void addBlit(int width, int height, int x, int y, float* pixels, int* alpha) {
    for (int row = 0; row < height; row++) {
        int top = y + row;
        if (top >= 0 && top < height) {
            for (int col = 0; col < width; col++) {
                int left = x + col;
                if (left >= 0 && left < width) {
                    float value = 0.0f;
                    float weightSum = 0.0f;
                    int runStartCol = left, runEndCol = left;
                    for (int runCol = left; runCol <= left + 1; runCol++) {
                        if (runCol >= 0 && runCol < width) {
                            float oldPixelValue = pixels[width * top + col];
                            float newPixelValue = pixels[width * top + runCol] * alpha[width * top + runCol] / 255.0f;
                            float blendValue = (oldPixelValue * (1 - newPixelValue) + newPixelValue * oldPixelValue) / (1 - newPixelValue);
                            value += blendValue;
                            weightSum += (1 - newPixelValue);
                        } else {
                            break;
                        }
                    }
                    if (weightSum > 0.5f) {
                        for (int col2 = runStartCol; col2 <= runEndCol; col2++) {
                            pixels[width * top + col2] *= 1 - alpha[width * top + col2] / 255.0f;
                        }
                    } else {
                        float blendValue = value / weightSum;
                        for (int col2 = runStartCol; col2 <= runEndCol; col2++) {
                            pixels[width * width * top + col2] += (blendValue - pixels[width * width * top + col2]) * alpha[width * top + col2] / 255.0f;
                        }
                    }
                } else {
                    break;
                }
            }
        } else {
            break;
        }
    }
}
