template <typename T>
std::variant<T>& operator=(T&& RHS) {
    if (holds_alternative<T>(this->index())) {
        std::get<T>(*this) = RHS;
        return *this;
    } else {
        throw std::bad_variant_access("Assignment to non-existent type");
    }
}

template <typename T>
std::variant<T>& operator=(std::unique_ptr<T>&& RHS) {
    if (holds_alternative<std::unique_ptr<T>>(this->index())) {
        std::get<std::unique_ptr<T>>(*this) = RHS;
        return *this;
    } else {
        throw std::bad_variant_access("Assignment to non-existent type");
    }
}
