#include <vector>
#include "DisjointSetUnion.h"

bool areConnected(const std::vector<int>& vec1, const std::vector<int>& vec2) {
    DisjointSetUnion dsu;
    for (int num : vec1) {
        dsu.makeSet(num);
    }

    for (int i = 0; i < vec2.size(); ++i) {
        int root = findRoot(dsu, vec2[i]);
        for (int j = i + 1; j < vec2.size(); ++j) {
            if (vec2[j] == root) continue;
            int otherRoot = findRoot(dsu, vec2[j]);
            if (root != otherRoot) return false;
        }
    }

    return true;
}

int findRoot(DisjointSetUnion& dsu, int num) {
    while (num != dsu.parent(num)) {
        num = dsu.parent(num);
    }
    return num;
}
