    strcat(full_path, "/");
    strcat(full_path, driver_sub_tree);
    strcat(full_path, "/");
    strcat(full_path, file_name);

    FILE* file = fopen(full_path, "rb");
    if (file == NULL) {
        free(full_path);
        return 0;
    }

    fclose(file);
    free(full_path);
    return 1;
}
