#include <vector>
#include <chrono>

template <typename LinearSolverInterface>
std::vector<double> solveLinearSystem(const std::vector<std::vector<double>>& matrix, const std::vector<double>& rightHandSides) {
    auto start = std::chrono::high_resolution_clock::now();

    // Scale the matrix
    int scale = 0;
    for (int i = 0; i < matrix.size(); ++i) {
        double sum = 0.0;
        for (int j = 0; j < matrix[i].size(); ++j) {
            sum += matrix[i][j];
        }
        if (scale == 0 || std::abs(sum) > std::abs(scale)) {
            scale = sum;
        }
    }

    // Scale the matrix
    for (int i = 0; i < matrix.size(); ++i) {
        for (int j = 0; j < matrix[i].size(); ++j) {
            matrix[i][j] /= scale;
        }
    }

    auto stop = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(stop - start);
    // Print the time taken for scaling the matrix
    std::cout << "Time taken to scale the matrix: " << duration.count() << " microseconds" << std::endl;

    // Solve the system of linear equations using the given linear solver interface
    return LinearSolverInterface()(matrix, rightHandSides);
}
