#include <map>
#include <vector>
#include <algorithm>

std::vector<std::pair<int, int>> sortOutputCounts(const std::map<std::string, int>& stats, const std::vector<int>& counts) {
    std::vector<std::pair<int, int>> outputCounts;
    for (int i = 0; i < counts.size(); ++i) {
        outputCounts.emplace_back(i, counts[i]);
    }

    std::sort(outputCounts.begin(), outputCounts.end(), [&stats](const auto& a, const auto& b) {
        return stats.find(std::to_string(a.second)) == stats.end() ? a > b
            : (stats.find(std::to_string(b.second)) == stats.end()) || (a.second >= b.second);
    });

    return outputCounts;
}

