        if(text[i] >= 'a' && text[i] <= 'z') {
            text[i] = (text[i] - 'a' + key[(text[i]-'a')%key_len]) % 26 + 'a';
        } else if(text[i] >= 'A' && text[i] <= 'Z') {
            text[i] = (text[i] - 'A' + key[(text[i]-'A')%key_len]) % 26 + 'A';
        }
    }

    printf("%s\n", text);

    return 0;
