public static Dictionary<string, string> ParseXml(string xmlString)
{
    var readerSettings = new XmlReaderSettings();
    readerSettings.IgnoreCase = true;
    readerSettings.IgnoreWhitespace = true;
    readerSettings.CloseInput = true;

    using (var reader = XmlReader.Create(new StringReader(xmlString), readerSettings))
    {
        var result = new Dictionary<string, string>();

        while (reader.Read())
        {
            if (reader.NodeType == XmlNodeType.Element && reader.Name == "parameter")
            {
                reader.Read();
                if (reader.NodeType == XmlNodeType.Text)
                {
                    result.Add(reader.GetAttribute("name"), reader.Value);
                }
            }
        }

        return result;
    }
}

