public static Tuple<bool, List<int>> TestSorting(int min, int max)
{
    Random rand = new Random();
    int randomCount = rand.Next(1, 100);
    List<int> originalList = new List<int>();
    for (int i = 0; i < randomCount; i++)
    {
        originalList.Add(rand.Next(min, max));
    }
    List<int> shuffledList = new List<int>(originalList);
    Shuffle(shuffledList, rand);
    List<int> sortedList = new List<int>(shuffledList);
    sortedList.Sort((x, y) => CustomSorter(x, y));
    bool isEqual = AreEqual(originalList, sortedList);
    return new Tuple<bool, List<int>>(isEqual, sortedList);
}

public static void Shuffle<T>(List<T> list, Random rng)
{
    for (int i = list.Count - 1; i > 0; i--)
    {
        int j = rng.Next(i + 1);
        T temp = list[i];
        list[i] = list[j];
        list[j] = temp;
    }
}

public static int CustomSorter(int x, int y)
{
    // implement your custom sorting logic here
    return x.CompareTo(y);
}

public static bool AreEqual(List<int> originalList, List<int> sortedList)
{
    return originalList.SequenceEqual(sortedList);
}

