public static bool ValidateXmlAgainstXsd(string xmlString, string xsdFile)
{
    XmlReaderSettings settings = new XmlReaderSettings();
    settings.ValidationType = ValidationType.Schema;
    XmlSchemaSet schemaSet = new XmlSchemaSet();
    schemaSet.Add(None, xsdFile);
    settings.Schemas = schemaSet;

    using (XmlReader reader = XmlReader.Create(new StringReader(xmlString), settings))
    {
        while (reader.Read())
        {
            if (reader.MoveToFirstChild())
            {
                bool valid = false;
                do
                {
                    if (reader.Name == "ValidationError")
                    {
                        Console.WriteLine("Validation error: {0}", reader.GetAttribute("message"));
                        return false;
                    }
                    else
                    {
                        valid = true;
                    }
                } while (reader.MoveToNextAttribute() || reader.Read());
                reader.MoveToParent();
            }
        }
    }
    return true;
}

