public static void TestRandomDatagrams()
{
    for (int i = 0; i < 10; i++)
    {
        int size1 = new Random().Next(1, 100);
        byte[] datagram1 = GenerateRandomDatagram(size1);

        int size2 = new Random().Next(1, 100);
        byte[] datagram2 = GenerateRandomDatagram(size2);

        if (datagram1.Length == datagram2.Length)
        {
            for (int j = 0; j < datagram1.Length; j++)
            {
                if (datagram1[j] != datagram2[j])
                {
                    Console.WriteLine("Datagrams are not equal");
                    return;
                }
            }
        }
        else
        {
            Console.WriteLine("Datagrams have different lengths, they are not equal");
            return;
        }

        int hash1 = BitConverter.ToInt32(datagram1.Take(4).ToArray(), 0);
        int hash2 = BitConverter.ToInt32(datagram2.Take(4).ToArray(), 0);

        if (hash1 == hash2)
        {
            Console.WriteLine("Datagrams have the same hash code, they are equal");
        }
        else
        {
            Console.WriteLine("Datagrams do not have the same hash code, they are not equal");
        }
    }
}

