public static T[,] CreateRandomMatrix<T>(int rows, int cols, Random random = null) where T : new()
{
    if (random == null)
        random = new Random();

    var matrix = new T[rows, cols];

    for (int i = 0; i < rows; i++)
    {
        for (int j = 0; j < cols; j++)
        {
            matrix[i, j] = (T)(object)random.NextDouble() * (new T().MaxValue - new T().MinValue) + new T().MinValue;
        }
    }

    return matrix;
}

