public static void GenerateTree(int x, int y, int z, int maxTrunkLength)
{
    Random rand = new Random();
    int trunkLength = rand.Next(5, maxTrunkLength);
    for (int i = 0; i < trunkLength; i++)
    {
        if (!IsColliding(x, y, z + i))
        {
            Console.WriteLine($"Placing block at ({x}, {y}, {z + i})");
        }
        else
        {
            break;
        }
    }
    for (int i = 0; i < trunkLength / 2; i++)
    {
        int branchDirection = rand.Next(1, 4);
        switch (branchDirection)
        {
            case 1:
                int newX = x + rand.Next(-1, 2);
                int newZ = z + trunkLength - i - 1;
                while (!IsColliding(newX, y, newZ))
                {
                    if (!IsColliding(newX, y, newZ - 1) && !IsColliding(newX, y, newZ + 1))
                    {
                        Console.WriteLine($"Placing branch at ({newX}, {y}, {newZ})");
                        break;
                    }
                    newX += rand.Next(-1, 2);
                }
                break;
            case 2:
                int newY = y + rand.Next(-1, 2);
                int newZ = z + trunkLength - i - 1;
                while (!IsColliding(x, newY, newZ))
                {
                    if (!IsColliding(x, newY, newZ - 1) && !IsColliding(x, newY, newZ + 1))
                    {
                        Console.WriteLine($"Placing branch at ({x}, {newY}, {newZ})");
                        break;
                    }
                    newY += rand.Next(-1, 2);
                }
                break;
            case 3:
                int newX = x + rand.Next(-1, 2);
                int newY = y + rand.Next(-1, 2);
                newZ = z + trunkLength - i - 1;
                while (!IsColliding(newX, newY, newZ))
                {
                    if (!IsColliding(newX, newY, newZ - 1) && !IsColliding(newX, newY, newZ + 1))
                    {
                        Console.WriteLine($"Placing branch at ({newX}, {newY}, {newZ})");
                        break;
                    }
                    newX += rand.Next(-1, 2);
                    newY += rand.Next(-1, 2);
                }
                break;
            case 4:
                int newX = x + rand.Next(-1, 2);
                newZ = z + trunkLength - i - 1;
                while (!IsColliding(newX, y, newZ))
                {
                    if (!IsColliding(newX, y, newZ - 1) && !IsColliding(newX, y, newZ + 1))
                    {
                        Console.WriteLine($"Placing branch at ({newX}, {y}, {newZ})");
                        break;
                    }
                    newX += rand.Next(-1, 2);
                }
                break;
        }
    }
}

