using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptBase64(string base64String, string key, string iv)
{
    byte[] encryptedBytes = Convert.FromBase64String(base64String);
    using (TripleDESCryptoServiceProvider cryptoProvider = new TripleDESCryptoServiceProvider())
    {
        cryptoProvider.Key = Convert.FromBase64String(key);
        cryptoProvider.IV = Convert.FromBase64String(iv);

        using (MemoryStream ms = new MemoryStream(encryptedBytes))
        {
            using (CryptoStream cs = new CryptoStream(ms, cryptoProvider.CreateDecryptor(), CryptoStreamMode.Write))
            {
                byte[] decryptedBytes = new byte[encryptedBytes.Length];
                cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
    }
}

