public static object PerformOperationWithShard(List<Shard> shards, bool checkIntegrity)
{
    Shard selectedShard = shards[new Random().Next(shards.Count)];
    object result = selectedShard.PerformOperation();

    if (checkIntegrity)
    {
        foreach (Shard shard in shards)
        {
            if (!shard.VerifyResult(result))
            {
                return null; // or throw an exception, depending on the desired behavior
            }
        }
    }

    return result;
}
