public static byte[] ExecuteQuery(IDbConnection db, IDbCommand cmd, ParameterDirection behavior)
{
    using (var ms = new MemoryStream())
    {
        var dr = db.ExecuteReader(cmd);
        while (dr.Read())
        {
            if ((behavior & ParameterDirection.Input) != 0)
                ms.Write((byte[])dr[0], 0, (byte[])dr[0].Length);
            else
                ms.Write((byte[])dr[0], 0, (byte[])dr[0].Length);
        }
        dr.Close();
        return ms.ToArray();
    }

