public static void AddInsertStatementToBatch(Dictionary<string, byte[]> payloads, Cluster cluster)
{
    using (var session = cluster.Connect("mykeyspace"))
    {
        var batch = new BatchStatement();
        var insert = new SimpleStatement("INSERT INTO mytable (column1, column2) VALUES (?, ?)", 0, 1);
        batch.Add(insert);

        foreach (var (key, value) in payloads)
        {
            batch.SetOutgoingValue(key, value);
        }

        session.Execute(batch);

        var result = session.Execute(insert);
        var incomingPayloads = new Dictionary<string, byte[]>();

        foreach (var row in result)
        {
            foreach (var column in row.Columns)
            {
                if (!incomingPayloads.ContainsKey(column.Name))
                    incomingPayloads[column.Name] = null;
                incomingPayloads[column.Name] = row.GetByte(column);
            }
        }

        Assert.NotEqual(null, incomingPayloads);
        Assert.Equal(payloads.Count, incomingPayloads.Count);

        foreach (var (key, value) in payloads)
        {
            Assert.Equal(value, incomingPayloads[key]);
        }
    }
}

