public static SqlCommand CreateSqlCommand(string storedProcedureName, DataTable dataTable)
{
    SqlCommand sqlCmd = new SqlCommand(storedProcedureName, Conn);
    foreach (DataRow row in dataTable.Rows)
    {
        foreach (DataColumn column in dataTable.Columns)
        {
            if (!row[column].Equals DBNull.Value)
            {
                SqlParameter param = new SqlParameter("@p_" + column.ColumnName, SqlDbType.NVarChar);
                param.Value = row[column];
                sqlCmd.Parameters.Add(param);
            }
        }
    }
    return sqlCmd;
}

