public static void StartProcess(ProcessStartInfo startInfo)
{
    using var process = Process.Start(startInfo);
    File.WriteAllText("process_id.txt", process.Id.ToString());

    if (!Directory.Exists("tracking"))
    {
        throw new InvalidOperationException("Tracking folder does not exist");
    }

    using var sentinelProcess = Process.Start(new ProcessStartInfo
    {
        FileName = "sentinel.exe",
        WorkingDirectory = Directory.GetCurrentDirectory(),
        RedirectStandardInput = true,
        RedirectStandardOutput = true,
        UseShellExecute = false
    });

    int timeout = 3000; // 3 seconds
    sentinelProcess.WaitForExit(timeout);

    if (!File.Exists("process_id.txt"))
    {
        File.Delete("process_id.txt");
    }

    sentinelProcess.Exit();
}
