public static Font CreateFontFromXml(Device device, string fontName)
{
    Assembly assembly = typeof(Font).GetAssembly();
    Stream stream = assembly.GetManifestResourceStream("Your_Assembly_Name." + fontName + ".xml");
    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.Load(stream);
    XmlElement fontNode = xmlDoc.DocumentElement.SelectSingleNode("/font") as XmlElement;
    int fontSize = int.Parse(fontNode["size"].InnerText);
    float fontWidth = float.Parse(fontNode["width"].InnerText);
    float fontHeight = float.Parse(fontNode["height"].InnerText);
    return new Font(device, fontName, fontSize, fontWidth, fontHeight);
}
