public static void RotateTransform(Transform transform, IntersectionType type)
{
    float angle = 0f;
    if (type == IntersectionType.Left || type == IntersectionType.Right)
        angle = MathF.PI / 2f;
    else
        angle = -MathF.PI / 2f;

    Quaternion rotation = Quaternion.Euler(0f, angle, 0f);
    transform.rotation = rotation * transform.rotation;
}

public enum IntersectionType { Top, Bottom, Left, Right }

