using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptDES(string encryptedMessage, string key)
{
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    des.Key = ASCIIEncoding.ASCII.GetBytes(key.PadRight(8, Convert.ToChar(0)));
    des.IV = ASCIIEncoding.ASCII.GetBytes(new char[8]);

    MemoryStream ms = new MemoryStream(System.Text.Encoding.ASCII.GetBytes(encryptedMessage));
    CryptoStream cs = new CryptoStream(ms, des.CreateDecryptor());
    byte[] decryptedBytes = new byte[System.Convert.ToInt32(cs.Length)];
    cs.Read(decryptedBytes, 0, decryptedBytes.Length);
    return Encoding.UTF8.GetString(decryptedBytes);
}

```csharp
public Matrix<LabPixel> GenerateRandomMatrix(int rows, int columns)
{
    LabPixel[] data = new LabPixel[rows * columns];
    Random random = new Random();
    for (int i = 0; i < data.Length; i++)
    {
        data[i] = new LabPixel(random.Next(0, 256), random.Next(0, 256), random.Next(0, 256));
    }
    IntPtr ptr = Marshal.AllocHGlobal(data.Length * sizeof(LabPixel));
    Marshal.StructureToPtr(data[0], new IntPtr(ptr), true);
    for (int i = 1; i < data.Length; i++)
    {
        Marshal.StructureToPtr(data[i], new IntPtr((ptr.ToInt32() + i * sizeof(LabPixel))), false);
    }
    Matrix<LabPixel> matrix = new Matrix<LabPixel>(rows, columns);
    Marshal.Copy(ptr, matrix.Data, 0, data.Length * sizeof(LabPixel));
    Marshal.FreeHGlobal(ptr);
    return matrix;
}
