public ActionResult ProcessRequest(HttpRequestBase request)
{
    string cacheKey = $"{request.Method}{request.Url}";
    object cachedData;

    if (cache.TryGetValue(cacheKey, out cachedData))
    {
        return new CacheContentResult(cachedData);
    }

    switch (request.Method)
    {
        case "GET":
            // Process GET request and store data in cache
            cachedData = ProcessGetRequest(request);
            break;
        case "POST":
            // Process POST request and store data in cache
            cachedData = ProcessPostRequest(request);
            break;
        default:
            return new HttpNotFoundResult();
    }

    cache.Add(cacheKey, cachedData, TimeSpan.FromDays(1));
    return new CacheContentResult(cachedData);
}

private object ProcessGetRequest(HttpRequestBase request)
