private void ShuffleListView(ListView listView)
{
    Random rng = new Random();
    int n = listView.Items.Count;
    for (int i = n - 1; i > 0; i--)
    {
        int j = rng.Next(i + 1);
        ListViewItem temp = listView.Items[i];
        listView.Items[i] = listView.Items[j];
        listView.Items[j] = temp;
    }
    listView.Refresh();
}
