```csharp
public static void ConnectTanks(object[,] grid)
{
    Random random = new Random();
    for (int i = 0; i < grid.GetLength(0); i++)
    {
        for (int j = 0; j < grid.GetLength(1); j++)
        {
            if (grid[i, j] is Tank tank && !tank.IsSink)
            {
                bool hasOutput = false;
                while (!hasOutput)
                {
                    int direction = random.Next(4);
                    switch (direction)
                    {
                        case 0: // up
                            if (i > 0 && grid[i - 1, j] is Tank)
                            {
                                tank.OutputDirection = OutputDirection.Up;
                                ((Tank)grid[i - 1, j]).InputDirections |= InputDirection.Down;
                                hasOutput = true;
                            }
                            break;
                        case 1: // right
                            if (j < grid.GetLength(1) - 1 && grid[i, j + 1] is Tank)
                            {
                                tank.OutputDirection = OutputDirection.Right;
                                ((Tank)grid[i, j + 1]).InputDirections |= InputDirection.Left;
                                hasOutput = true;
                            }
                            break;
                        case 2: // down
                            if (i < grid.GetLength(0) - 1 && grid[i + 1, j] is Tank)
                            {
                                tank.OutputDirection = OutputDirection.Down;
                                ((Tank)grid[i + 1, j]).InputDirections |= InputDirection.Up;
                                hasOutput = true;
                            }
                            break;
                        case 3: // left
                            if (j > 0 && grid[i, j - 1] is Tank)
                            {
                                tank.OutputDirection = OutputDirection.Left;
                                ((Tank)grid[i, j - 1]).InputDirections |= InputDirection.Right;
                                hasOutput = true;
                            }
                            break;
                    }
                }
            }
        }
    }
}

