public class ProducerConsumer
{
    private readonly object _lock = new();
    private int _sequenceNumber;
    private Random _random;

    public Observation Produce(int argument)
    {
        lock (_lock)
        {
            int sequenceNumber = Interlocked.Increment(ref _sequenceNumber);
            Thread.Sleep(_random.Next(0, 100));
            return new Observation(sequenceNumber, Thread.CurrentThread.ManagedThreadId, 1.0); 
        }
    }

    public class Observation
    {
        public int SequenceNumber { get; set; }
        public int ProducerThreadId { get; set; }
        public double Latency { get; set; }

        public Observation(int sequenceNumber, int producerThreadId, double latency)
        {
            SequenceNumber = sequenceNumber;
            ProducerThreadId = producerThreadId;
            Latency = latency;
        }
    }
}

