public void CreateViews(List<object> list, XmlDocument xmlDocument)
{
    XmlNodeList views = xmlDocument.SelectNodes("views/view");
    string viewType = list.GetType().BaseType.Name;

    foreach (XmlNode view in views)
    {
        if (view["type"].InnerText == viewType)
        {
            View newView = new View
            {
                Name = view["name"].InnerText,
                Type = viewType,
                FieldsToDisplay = new List<string>()
            };

            XmlNode fieldsNode = view.SelectSingleNode("fields/field");
            while (fieldsNode != null)
            {
                newView.FieldsToDisplay.Add(fieldsNode.InnerText);
                fieldsNode = fieldsNode.NextSibling;
            }

            list.DefaultView = newView;
            int rowLimit = Convert.ToInt32(view["rowlimit"].InnerText);
            list.RowLimit = rowLimit;
        }
    }
}

public class View
{
    public string Name { get; set; }
    public string Type { get; set; }
    public List<string> FieldsToDisplay { get; set; }
}
