using System;
using System.Data.SqlClient;

public static void DeleteTrackableItem(string itemCode, int groupId)
{
    try
    {
        using (SqlConnection connection = new SqlConnection("Server=myserver;Database=mydatabase;User Id=myuser;Password=mypassword"))
        {
            connection.Open();

            SqlCommand command = new SqlCommand();
            command.Connection = connection;

            // Delete associated data
            command.CommandText = "DELETE FROM AssociatedData WHERE ItemCode = @itemCode AND GroupId = @groupId";
            command.Parameters.AddWithValue("@itemCode", itemCode);
            command.Parameters.AddWithValue("@groupId", groupId);
            command.ExecuteNonQuery();

            // Delete trackable item
            command.CommandText = "DELETE FROM TrackableItems WHERE Code = @itemCode";
            command.Parameters.AddWithValue("@itemCode", itemCode);
            command.ExecuteNonQuery();
        }
    }
    catch (SqlException ex)
    {
        Console.WriteLine("Error deleting trackable item: " + ex.Message);
    }
}
```
This function takes two parameters, `itemCode` and `groupId`, which are used to construct the SQL queries. It uses a `using` statement to ensure that the database connection is properly closed and disposed of, even if an exception occurs.

The function first attempts to delete the associated data for the trackable item using a `DELETE` query with a `WHERE` clause that matches the `itemCode` and `groupId`. Then it deletes the trackable item itself using another `DELETE` query with a `WHERE` clause that matches the `itemCode`.

If an exception occurs during execution (e.g., due to a database error or invalid input), the function catches the `SqlException` and logs an error message to the console.

