```csharp
public string GetStartupFilePath(Project project)
{
    if (project.StartupFile != null)
        return project.StartupFile;

    int port = GenerateRandomAvailablePort();
    while (!IsPortAvailable(port))
    {
        port = GenerateRandomAvailablePort();
    }

    string startupFile = Path.GetFileNameWithoutExtension(project.StartupFile);
    string startupFilePath = Path.Combine(Path.GetDirectoryName(project.StartupFile), $"{startupFile}:{port}");
    return startupFilePath;
}

private int GenerateRandomAvailablePort()
{
    Random random = new Random();
    return random.Next(1200, 60001);
}

private bool IsPortAvailable(int port)
{
    IPGlobalProperties ipProps = Dns.GetIpGlobalInfo();
    foreach (IPAddress ip in ipProps.GetAllAddressEntries())
    {
        IPEndPoint endPoint = new IPEndPoint(ip, port);
        if (!ipProps.IsTcpConnectionInState(endPoint, State.Listen) &&
            !ipProps.IsTcpConnectionInState(endPoint, State.Bound))
        {
            return true;
        }
    }
    return false;
}
