public static string DecryptString(string cipherText, string key)
{
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    des.Key = ASCIIEncoding.ASCII.GetBytes(key);
    des.Mode = CipherMode.ECB;
    des.Padding = PaddingMode.PKCS7;

    MemoryStream ms = new MemoryStream(Convert.FromBase64String(cipherText));
    CryptoStream cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read);

    byte[] decryptedBytes = new byte[cs.Length];
    cs.Read(decryptedBytes, 0, decryptedBytes.Length);
    cs.FlushFinalBlock();

    return ASCIIEncoding.ASCII.GetString(decryptedBytes).TrimEnd(new char[] { Convert.ToChar(des.Padding) });
}

