public void CreateViews(WebObject webObject, string url, string xmlFilePath)
{
    if (string.IsNullOrEmpty(url) || string.IsNullOrEmpty(xmlFilePath))
    {
        throw new ArgumentNullException("URL and XML file path cannot be null or empty");
    }

    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.Load(xmlFilePath);

    XmlNodeList viewsNode = xmlDoc.SelectNodes("//views/view");

    foreach (XmlNode viewNode in viewsNode)
    {
        string viewType = viewNode["type"].InnerText;
        string viewUrl = viewNode["url"].InnerText;

        // Create the view based on the type
        Type viewTypeType = Type.GetType(viewType);
        webObject.Views.Add((viewTypeType == typeof(IView)) ? (IView)Activator.CreateInstance(viewTypeType) : null);

        // Add the URL to the view
        ((IView)webObject.Views[webObject.Views.Count - 1]).Url = viewUrl;
    }
}

