public static async Task StartProcessAndReadOutputAsync(string processName, string arguments)
{
    using (var process = new Process())
    {
        process.StartInfo.FileName = processName;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardInput = true;
        process.StartInfo.RedirectStandardOutput = true;

        process.OutputDataReceived += (sender, data) => Console.WriteLine(data.Data);
        process.Exited += (sender, e) => process.Dispose();

        using (var output = new MemoryStream())
        {
            process.StandardOutput.BaseStream = output;
            process.Start();
            process.BeginOutputReadLine();

            var input = Console.OpenStandardInput();
            using (var writer = new StreamWriter(input))
            {
                while (true)
                {
                    writer.WriteLine("Manager command");
                    await Task.Delay(1000);
                }
            }
