using System;
using System.Security.Cryptography;
using System.Text;

public static string GenerateToken(string password, string domain, int port, string url)
{
    byte[] hashBytes = SHA1.Create().ComputeHash(Encoding.ASCII.GetBytes(password));
    string token = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

    HttpWebRequest request = (HttpWebRequest)WebRequest.Create("http://" + domain + ":" + port + url);
    request.Method = "POST";
    request.ContentType = "application/x-www-form-urlencoded";
    byte[] data = Encoding.ASCII.GetBytes("token=" + token);
    request.ContentLength = data.Length;
    using (Stream stream = request.GetRequestStream())
    {
        stream.Write(data, 0, data.Length);
    }

    return token;
}
