public static IDataReader ExecuteReader(string connectionString, CommandType commandType, string commandText, params SqlParameter[] commandParameters)
{
    using (DbConnection connection = DbFactory.CreateConnection())
    {
        try
        {
            connection.Open();
            DbCommand command = connection.CreateCommand(commandText, commandType);
            foreach (SqlParameter param in commandParameters)
                command.Parameters.Add(param);
            IDataReader reader = command.ExecuteReader();
            return reader;
        }
        catch (Exception ex)
        {
            connection.Close();
            throw new Exception("Error executing SQL command", ex);
        }
    }
