XDocument UpdateConfigFile(string filePath, string existingSectionName, string newSectionName)
{
    var doc = XDocument.Load(filePath);
    var existingSection = doc.Descendants().Where(x => (string)x.Attribute("name") == existingSectionName).FirstOrDefault();

    if (existingSection != null)
    {
        var newNode = new XElement("section", new XAttribute("name", newSectionName));
        var parentElement = (XElement)existingSection;
        parentElement.AddAfterSelf(newNode);

        doc.Save(filePath);
        return doc;
    }
    else
    {
        throw new Exception($"The section '{existingSectionName}' was not found in the config file.");
    }
}

