public static byte[] DecryptAescbcpadding(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
{
    using (var aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = iv;

        using (var decryptor = aes.CreateDecryptor())
        {
            using (var ms = new MemoryStream(ciphertext))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var plaintext = new byte[ciphertext.Length];
                    int read = cs.Read(plaintext, 0, plaintext.Length);
                    if (read != plaintext.Length)
                    {
                        // pad the remaining bytes
                        var remainder = new byte[ciphertext.Length - read];
                        cs.Read(remainder, 0, remainder.Length);
                        plaintext = CombineArrays(plaintext, remainder);
                    }
                    return plaintext;
                }
            }
        }
    }

    static byte[] CombineArrays(byte[] a, byte[] b)
    {
        var result = new byte[a.Length + b.Length];
        a.CopyTo(result, 0);
        b.CopyTo(result, a.Length);
        return result;
    }
