public static XDocument GenerateXml(Type type)
{
    XDocument doc = new XDocument();
    XElement root = new XElement(type.Name);
    doc.Add(root);

    foreach (PropertyInfo property in type.GetProperties())
    {
        XmlizedClassAttribute xmlizedAttr = property.GetCustomAttribute<XmlizedClassAttribute>();
        if (xmlizedAttr != null)
        {
            XElement element = new XElement(xmlizedAttr.ElementName);
            root.Add(element);

            foreach (FieldInfo field in property.GetFields())
            {
                XmlizedSqlstringIDClassAttribute sqlIdAttr = field.GetCustomAttribute<XmlizedSqlstringIDClassAttribute>();
                if (sqlIdAttr != null)
                {
                    XElement subElement = new XElement(sqlIdAttr.ElementName);
                    element.Add(subElement);

                    subElement.Value = field.GetValue(null).ToString();
                }
            }
        }
    }

    return doc;
}

