using System;
using System.IO;
using System.Text.RegularExpressions;
using System.Collections.Generic;

public List<TravelItem> ExtractGeocacheCoordinates(string resourceName)
{
    var travelItems = new List<TravelItem>();

    using (var stream = typeof(Program).Assembly.GetManifestResourceStream(resourceName))
    {
        if (stream == null) throw new Exception($"Resource '{resourceName}' not found");

        using (var reader = new StreamReader(stream))
        {
            string html = reader.ReadToEnd();
            var regex = new Regex(@"<td\s+class=""coordinates"">([^<>]+)</td>");
            MatchCollection matches = regex.Matches(html);

            foreach (Match match in matches)
            {
                double latitude, longitude;
                if (double.TryParse(match.Groups[1].Value.Split(',')[0], out latitude) &&
                    double.TryParse(match.Groups[1].Value.Split(',')[1], out longitude))
                {
                    travelItems.Add(new TravelItem(latitude, longitude, DateTime.Now));
                }
            }
        }
    }

    return travelItems;
}

public class TravelItem
{
    public double Latitude { get; set; }
    public double Longitude { get; set; }
    public DateTime DateLogged { get; set; }

    public TravelItem(double latitude, double longitude, DateTime dateLogged)
    {
        Latitude = latitude;
        Longitude = longitude;
        DateLogged = dateLogged;
    }
}
