using System;
using System.Security.Cryptography;
using System.Text;

public static string EncryptDES(string plainText)
{
    byte[] inputByteArray = ASCIIEncoding.GetBytes(plainText);
    byte[] outputByteArray = null;
    using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
    {
        des.Key = ASCIIEncoding.GetBytes("MySecretKey");
        des.Mode = CipherMode.ECB;
        des.Padding = PaddingMode.PKCS7;
        using (MemoryStream ms = new MemoryStream(inputByteArray))
        {
            CryptoStream cs = new CryptoStream(ms, des.CreateEncryptor(), CryptoStreamMode.Write);
            cs.Write(inputByteArray, 0, inputByteArray.Length);
            cs.FlushFinalBlock();
            outputByteArray = ms.ToArray();
        }
    }
    return Convert.ToBase64String(outputByteArray);
}

