public async Task<int> GetNextStreamVersionAsync(int streamId, int count, int currentVersion)
{
    using var connection = new SqlConnection("Data Source=<your_data_source>;Initial Catalog=<your_catalog_name>;User ID=<your_user_id>;Password=<your_password>;"); 
    await connection.OpenAsync();

    using var command = new SqlCommand("SELECT TOP 1 [Version] FROM [YourTable] WHERE [StreamId] = @streamId AND [Version] > @currentVersion ORDER BY [Version]", connection);
    command.Parameters.AddWithValue("@streamId", streamId);
    command.Parameters.AddWithValue("@currentVersion", currentVersion);

    using var reader = await command.ExecuteReaderAsync();

    if (await reader.ReadAsync())
    {
        return (int)reader["Version"] + count;
    }

    return -1;
}
