    @name NVARCHAR(50),
    @evilnessFactor INT,
    @connection DBConnection READONLY,
    @transaction DBTransaction READONLY
AS
BEGIN
    DECLARE @villainID INT;

    SET @connection.BeginTransaction();

    BEGIN TRY
        INSERT INTO Villains (Name, EvilnessFactor)
        VALUES (@name, @evilnessFactor);

        SET @villainID = SCOPE_IDENTITY();

        SET @transaction.CommitTransaction();

        PRINT 'Villain inserted successfully!';

        RETURN @villainID;
    END TRY
    BEGIN CATCH
        SET @connection.RollbackTransaction();
        PRINT 'Error inserting villain.';
        THROW;
    END CATCH;
END;

