public int CountNodesAndUpdateXml(string filePath, string xpathQuery)
{
    XmlDocument document = new XmlDocument();
    document.Load(filePath);
    XmlNodeList nodesBefore = document.SelectNodes(xpathQuery);

    int nodesBeforeCount = nodesBefore == null ? 0 : nodesBefore.Count;

    XmlElement newNode = document.CreateElement("newNode");
    document.DocumentElement.AppendChild(newNode);

    XmlNodeList nodesAfter = document.SelectNodes(xpathQuery);

    int nodesAfterCount = nodesAfter == null ? 0 : nodesAfter.Count;

    Assert.AreEqual(nodesBeforeCount, nodesAfterCount);
    return nodesBeforeCount;
}

