public bool ValidateXml(string xmlDocument, string schema)
{
    XmlDocument doc = new XmlDocument();
    doc.LoadXml(xmlDocument);
    XmlSchema schemaDoc = new XmlDocument().LoadXml(schema);
    XmlSchemaSet schemaSet = new XmlSchemaSet();
    schemaSet.Add(schemaDoc);
    XmlReaderSettings settings = new XmlReaderSettings();
    settings.ValidationType = ValidationType.Schema;
    settings.Schemas.Add(schemaSet);
    using (XmlReader reader = XmlReader.Create(new StringReader(xmlDocument), settings))
    {
        while (reader.Read())
        {
            if (reader.AttributeCount > 0)
            {
                reader.MoveToAttribute(0);
                string prefix = reader.GetAttribute("prefix");
                if (!string.IsNullOrEmpty(prefix))
                    return false;
            }
        }
    }
    return true;
}

