public SqlCommand CreateSqlCommand(string connectionString, bool useStoredProcedure, List<SqlParameter> parameters)
{
    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        connection.Open();

        string commandText;
        if (useStoredProcedure)
        {
            commandText = parameters[0].ParameterName;
        }
        else
        {
            commandText = string.Join(" ", parameters.Select(p => "@" + p.ParameterName).ToArray());
        }

        SqlCommand cmd = new SqlCommand(commandText, connection);

        foreach (SqlParameter param in parameters)
        {
            cmd.Parameters.AddWithValue(param.ParameterName, param.Value);
            cmd.Parameters[param.ParameterName].DbType = param.DbType;
        }

        return cmd;
    }
}
