public class CustomUserValidator : UserValidator<User>
{
    public override async Task<IdentityResult> ValidateAsync(ApplicationUserManager UserManager, ApplicationUser user)
    {
        IdentityResult result = await base.ValidateAsync(UserManager, user);

        if (!result.Succeeded)
            return result;

        if (string.IsNullOrWhiteSpace(user.UserName))
        {
            result.Errors.Add("Username cannot be null or whitespace.");
            return result;
        }

        // Add your custom validation logic here
        // For example:
        if (user.UserName.Length < 6 || user.UserName.Length > 20)
        {
            result.Errors.Add("Username must be between 6 and 20 characters long.");
            return result;
        }

        return await base.ValidateAsync(UserManager, user);
    }
}

public class CustomPasswordValidator : PasswordValidator
{
    public override async Task<IdentityResult> ValidateAsync(string password)
    {
        IdentityResult result = await base.ValidateAsync(password);

        if (!result.Succeeded)
            return result;

        // Add your custom validation logic here
        // For example:
        if (password.Length < 8 || !Regex.IsMatch(password, @"[0-9]+"))
        {
            result.Errors.Add("Password must be at least 8 characters long and contain at least one number.");
            return result;
        }

        return await base.ValidateAsync(password);
    }
}

