    SET @service = N'MyService';
    CREATE SERVICE [MyService] ON QUEUES [MyQueue];
END;

IF NOT EXISTS (SELECT 1 FROM sys.service_queue_permissions WHERE service = @service AND queue = 'MyQueue' AND permission = 'SUBSCRIBE')
