    XmlDocument doc = new XmlDocument();
    doc.Load(filePath);

    XmlNode configNode = doc.SelectSingleNode("/configuration");
    if (configNode != null)
    {
        foreach (XmlNode setting in configNode.ChildNodes)
        {
            if (setting.Name == "setting")
            {
                string key = setting.Attributes["key"].Value;
                string value = setting.InnerText;
                settings.Add(string.Format("{0}:{1}", key, value));
            }
        }
    }

    return settings;
}

