public void UpdateTrackableDatabase(Trackable t)
{
    using (var dbConnection = new MySqlConnection(Configuration.ConnectionString))
    {
        dbConnection.Open();

        var updateQuery = "UPDATE trackables SET HopCount=@HopCount, InCacheCount=@InCacheCount, DiscoverCount=@DiscoverCount WHERE Id=@Id";
        var parameters = new Dictionary<string, MySqlParameter>
        {
            {"@HopCount", new MySqlParameter("@HopCount", t.HopCount)},
            {"@InCacheCount", new MySqlParameter("@InCacheCount", t.InCacheCount)},
            {"@DiscoverCount", new MySqlParameter("@DiscoverCount", t.DiscoverCount)},
            {"@Id", new MySqlParameter("@Id", t.Id)}
        };

        var deleteQuery = "DELETE FROM logs WHERE TrackableId=@Id";
        parameters.Add("@Id", new MySqlParameter("@Id", t.Id));

        using (var command = new MySqlCommand(updateQuery, dbConnection))
        {
            foreach (var parameter in parameters.Values)
            {
                command.Parameters.Add(parameter);
            }
            command.ExecuteNonQuery();
        }

        using (var logDeleteCommand = new MySqlCommand(deleteQuery, dbConnection))
        {
            logDeleteCommand.Parameters.Add(parameters["@Id"]);
            logDeleteCommand.ExecuteNonQuery();
        }
    }
}
