using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public class Resource
{
    public byte[] Bytes { get; set; }
    public string MimeType { get; set; }
    public string Md5Hash { get; set; }
}

public List<Resource> ComputeMd5Hashes(List<(byte[], string)> resources)
{
    var result = new List<Resource>();

    foreach (var (resourceBytes, mimeType) in resources)
    {
        using var md5 = MD5.Create();
        var hashBytes = md5.ComputeHash(resourceBytes);

        var resource = new Resource
        {
            Bytes = resourceBytes,
            MimeType = mimeType,
            Md5Hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower()
        };

        result.Add(resource);
    }

    return result;
}

