using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptDES(string hexData)
{
    try
    {
        // Convert hexadecimal to byte array
        byte[] data = Convert.FromHexString(hexData);

        // Create a DES decryptor
        DESCryptoServiceProvider desCrypto = new DESCryptoServiceProvider();
        desCrypto.Key = ASCIIEncoding.ASCII.GetBytes("MySecretKey"); // fixed key

        // Decrypt the data
        using (MemoryStream ms = new MemoryStream(data))
        {
            CryptoStream cs = new CryptoStream(ms, desCrypto.CreateDecryptor());
            byte[] decryptedData = new byte[cs.Length];
            cs.Read(decryptedData, 0, decryptedData.Length);

            return Encoding.ASCII.GetString(decryptedData);
        }
    }
    catch (Exception ex)
    {
        throw new InvalidOperationException("Invalid hexadecimal representation of a DES-encrypted message", ex);
    }
}

