public void RedirectToUrl(string email, int personId)
{
    try
    {
        // create request object
        var request = new RequestObject(email, personId);

        // retrieve URL from web service
        var response = WebService.GetRequestResponse(request);
        if (response.IsSuccessStatusCode)
        {
            // redirect to retrieved URL
            Uri url = new Uri(response.Content.ReadAsStringAsync().Result);
            System.Diagnostics.Process.Start(new Process { StartInfo = { FileName = url.AbsoluteUri } });
        }
    }
    catch (Exception ex)
    {
        // log any errors that occur during the process
        LoggingService.LogError(ex.Message, "RedirectToUrl");
    }
}
