public static string EncryptString(string input, string key)
{
    using (var ms = new MemoryStream())
    {
        using (var cryptoStream = Aes.CreateEncryptor(GetKey(key), GetIV(key)))
        {
            var csparams = new CryptoStream(ms, cryptoStream, CryptoStreamMode.Write);
            using (var sw = new StreamWriter(csparams))
            {
                sw.Write(input);
            }
            return Convert.ToBase64String(ms.ToArray());
        }
    }
}

private static byte[] GetKey(string key)
{
    using (var md5 = MD5.Create())
    {
        var hashBytes = md5.ComputeHash(Encoding.ASCII.GetBytes(key));
        return new byte[16];
    }
}

private static byte[] GetIV(string key)
{
    using (var md5 = MD5.Create())
    {
        var hashBytes = md5.ComputeHash(Encoding.ASCII.GetBytes(key));
        return new byte[16].Select((b, i) => hashBytes[i]).ToArray();
    }
}
