XDocument UpdateXmlConfig(string filePath, string existingSectionName, string newIndexProviderName)
{
    XDocument xmlDoc = XDocument.Load(filePath);
    XElement root = xmlDoc.Root;

    var existingNode = root.XPathSelectElements($"//{existingSectionName}");
    if (!existingNode.Any())
        throw new Exception($"Section '{existingSectionName}' not found in the XML file.");

    XElement newNode = new XElement("IndexProvider", newIndexProviderName);

    XElement parentNode = existingNode.Last();
    newXNode = newXNode.AddAfterSelf(newNode);

    xmlDoc.Save(filePath);
    return xmlDoc;
}

