using iTextSharp.text.pdf;
using iTextSharp.text.pdf.parser;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: pdf_to_text input.pdf output.pdf");
            return;
        }

        string inputFile = args[0];
        string outputFile = args[1];

        using (PdfReader reader = new PdfReader(inputFile))
        {
            using (PdfWriter writer = new PdfWriter(outputFile))
            {
                Document document = new Document();
                PdfContentByte cb;

                for (int i = 1; i <= reader.GetNumberPages(); i++)
                {
                    document.Open();

                    cb = writer.DirectContent;
                    cb.BeginText();
                    cb.ShowTextAligned(cb, PdfContentByte.ALIGN_LEFT, reader.GetPageContent(i), 0, 70f, true);
                    cb.EndText();
                    document.Close();
                }
            }
        }

        Process.Start(outputFile);
    }
}
