using System;
using System.Xml.XPath;

public static string UpdateXmlFile(string filePath, string removeXPath, string insertAfterXPath)
{
    XPathDocument doc = new XPathDocument(filePath);
    XPathNavigator nav = doc.CreateNavigator();
    XPathExpression exprRemove = nav.Compile(removeXPath);
    XPathExpression exprInsertAfter = nav.Compile(insertAfterXPath);

    XPathNodeIterator iterRemove = nav.Select(exprRemove);
    XPathNodeIterator iterInsertAfter = nav.Select(exprInsertAfter);

    if (iterRemove.MoveNext())
    {
        XPathNodeIterator iterParent = iterRemove.Current.GetParent();
        XPathNodeIterator iterCurrent = iterParent.Clone().MoveToFirstChild();

        while (true)
        {
            XPathNodeIterator iterChild = iterCurrent.Clone().MoveToFirstChild();

            while (iterChild.MoveToFirstChild())
            {
                if (exprRemove.Compile().Evaluate(iterChild) as XmlNode != null)
                {
                    iterParent.DeleteChild(iterChild);
                }
                else
                {
                    iterCurrent = iterChild;
                }
            }

            if (!iterParent.MoveToNext())
            {
                break;
            }
            else
            {
                iterCurrent = nav.Select(exprInsertAfter).MoveToFirstChild();
            }
        }
    }

    StringWriter writer = new StringWriter();
    XmlTextWriter xmlWriter = new XmlTextWriter(writer);
    doc.CreateNavigator().WriteContent(xmlWriter);
    return writer.ToString();
}

