using System;
using System.Xml.Linq;

public static string UpdateXmlFile(string filePath, string existingElementXPath, XNode newElement, string insertAfterElementXPath)
{
    XDocument doc = XDocument.Load(filePath);
    XElement root = doc.Root.Element(existingElementXPath.Split('/').Last());
    root.Add(newElement);

    foreach (XElement element in doc.Descendants())
    {
        if ((element as XElement).Name.LocalName == insertAfterElementXPath.Split('/').Last() && element.Parent != null)
        {
            element.AddAfterSelf(newElement);
            break;
        }
    }

    return doc.Declaration + doc.ToString();
}

