using System;
using System.Security.Cryptography;
using System.Text;

public static string DecryptString(string cipherText, byte[] key)
{
    DESCryptoServiceProvider des = new DESCryptoServiceProvider();
    des.Key = key;
    des.Mode = CipherMode.ECB; // Electronic Codebook Book mode
    des.Padding = PaddingMode.PKCS7; // PKCS #7 padding

    MemoryStream ms = new MemoryStream(Convert.FromBase64String(cipherText));
    CryptoStream cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read);
    byte[] decryptedBytes = new byte[ms.Length];
    int readBytes = cs.Read(decryptedBytes, 0, decryptedBytes.Length);

    return Encoding.UTF8.GetString(decryptedBytes, 0, readBytes);
}

