public XDocument GenerateXmlObject(XObject obj)
{
    var doc = new XDocument();
    foreach (var prop in obj.GetType().GetProperties())
    {
        var attribute = Attribute.GetCustomAttribute(prop, typeof(XmlizedPropertyAttribute));
        if (attribute != null)
        {
            var nodeName = attribute.Path;
            var nodeValue = string.Empty;
            if (prop.PropertyType.GenericTypeOf() == typeof(IExportToXmlable))
            {
                var exportable = prop.GetValue(obj);
                nodeValue = ((IExportToXmlable)exportable).ExportToXml();
            }
            else
            {
                nodeValue = prop.GetValue(obj)?.ToString();
            }
            var node = new XElement(nodeName, nodeValue);
            doc.Add(node);
        }
    }
    return doc;
}

