public class HashAlgorithmWrapper
{
    public string Name { get; }
    public System.Security.Cryptography.HashAlgorithm Algorithm { get; }

    public HashAlgorithmWrapper(string name, System.Security.Cryptography.HashAlgorithm algorithm)
    {
        Name = name;
        Algorithm = algorithm;
    }

    public byte[] CalculateHash(string input)
    {
        using (var ms = new MemoryStream())
        {
            var cryptoStream = new CryptoStream(ms, Algorithm);
            var writer = new StreamWriter(cryptoStream);
            writer.Write(input);
            writer.Flush();
            cryptoStream.Flush();
            return ms.ToArray();
        }
    }

    public static HashAlgorithmWrapper CreateMd5()
    {
        using (var md5 = System.Security.Cryptography.MD5.Create())
        {
            return new HashAlgorithmWrapper("MD5", md5);
        }
    }

    public static HashAlgorithmWrapper CreateSha1()
    {
        using (var sha1 = System.Security.Cryptography.SHA1.Create())
        {
            return new HashAlgorithmWrapper("SHA1", sha1);
        }
    }

    public static HashAlgorithmWrapper CreateSha256()
    {
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
            return new HashAlgorithmWrapper("SHA256", sha256);
        }
    }

    public static HashAlgorithmWrapper CreateSha512()
    {
        using (var sha512 = System.Security.Cryptography.SHA512.Create())
        {
            return new HashAlgorithmWrapper("SHA512", sha512);
        }
    }
}

