    {
        var parent = config.Descendants().FirstOrDefault(e => e.XPathSelectElements(insertionXPath).Any());

        if (parent != null)
        {
            parent.AddAfterSelf(newSection);
        }
        else
        {
            config.Root.Add(newSection);
