public static T ReadLastObjectFromFile<T>(string filePath) where T : MarshalByRefObject
{
    T lastObject = default(T);
    using (FileStream fs = new FileStream(filePath, FileMode.Open))
    {
        BinaryFormatter formatter = new BinaryFormatter();
        Stream stream = new MemoryStream();
        fs.CopyTo(stream);
        stream.Position = 0;
        T obj;
        while ((obj = (T)formatter.Deserialize(stream)) != null)
        {
            lastObject = obj;
        }
    }
    return lastObject;
}

