public static void LoadAndSaveSettings(string directoryPath)
{
    XmlDocument configXml = new XmlDocument();
    configXml.Load(directoryPath + "\\config.xml");

    XmlNode systemSettingsNode = configXml.SelectSingleNode("//systemSettings");
    if (systemSettingsNode != null)
    {
        // Display current settings to user
        Console.WriteLine("Current settings:");
        foreach (XmlNode setting in systemSettingsNode.ChildNodes)
        {
            Console.WriteLine(setting.Name + ": " + setting.InnerText);
        }

        // Allow user to update custom settings
        string[] options = { "update", "cancel" };
        Console.Write("Enter a setting to update (or 'q' to quit): ");
        string input = Console.ReadLine();
        while (!options.Contains(input))
        {
            Console.WriteLine("Invalid option. Please try again.");
            Console.Write("Enter a setting to update (or 'q' to quit): ");
            input = Console.ReadLine();
        }
        if (input == "update")
        {
            // Get user's updated settings
            foreach (XmlNode setting in systemSettingsNode.ChildNodes)
            {
                Console.Write(setting.Name + ": ");
                string value = Console.ReadLine();
                setting.InnerText = value;
            }

            // Save changes to config file
            configXml.Save(directoryPath + "\\config.xml");
        }
    }
}

