using System;
using System.IO;
using System.Security.Cryptography;

public static void TestSymmetricEncryption(Algorithm algorithm, byte[] key, string message)
{
    using (Aes aes = Aes.Create())
    {
        aes.Key = key;
        aes.BlockSize = 128; // Assuming AES-128
        aes.Mode = CipherMode.ECB;
        aes.Padding = PaddingMode.Zeros;

        ICryptoTransform encryptor = aes.CreateEncryptor();
        ICryptoTransform decryptor = aes.CreateDecryptor();

        byte[] plaintextBytes = Encoding.UTF8.GetBytes(message);
        byte[] encryptedBytes = Encrypt(encryptor, plaintextBytes);

        // Check that the key size and block size are correct
        if (aes.Key.Length * 8 != algorithm.KeySize && aes.BlockSize / 8 != algorithm.BlockSize)
            throw new Exception("Incorrect key or block size");

        // Check that the effective key size is correct
        if (aes.Key.Length * 8 > algorithm.EffectiveKeySize)
            throw new Exception("Effective key size too large");

        byte[] decryptedBytes = Decrypt(decryptor, encryptedBytes);

        // Check that the encryption and decryption operations are inverse
        for (int i = 0; i < plaintextBytes.Length; i++)
        {
            if (plaintextBytes[i] != decryptedBytes[i])
                throw new Exception("Encryption and decryption not inverse");
        }

        // Check that the original message is the same as the encrypted message
        byte[] originalBytes = Encrypt(encryptor, plaintextBytes);
        for (int i = 0; i < originalBytes.Length; i++)
        {
            if (originalBytes[i] != encryptedBytes[i])
                throw new Exception("Original and encrypted messages not equal");
        }
    }
}

private static byte[] Encrypt(ICryptoTransform transform, byte[] data)
{
    using (MemoryStream ms = new MemoryStream())
    {
        using (CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Write))
        {
            cs.Write(data, 0, data.Length);
        }
        return ms.ToArray();
    }
}

private static byte[] Decrypt(ICryptoTransform transform, byte[] data)
{
    using (MemoryStream ms = new MemoryStream())
    {
        using (CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Write))
        {
            cs.Write(data, 0, data.Length);
        }
        return ms.ToArray();
    }
}

public enum Algorithm
{
    AES_128_CBC,
    AES_192_CBC,
    AES_256_CBC,
}
