public static double[] mutateValue(Random rng, double value, double stdDevFactor) {
    double mutatedValue = value + (rng.nextGaussian() * stdDevFactor);
    List<Double> discreteValues = new ArrayList<>();
    for (double i = Math.max(0, value - 2 * stdDevFactor); i <= Math.min(value + 2 * stdDevFactor, 10.0); i += 0.1) {
        discreteValues.add(i);
    }
    return new double[]{mutatedValue, discreteValues.get(0), discreteValues.get(discreteValues.size() - 1)};
}

