```java
public static Object getRandomValue(Class<?> clazz, int... options) {
    Random random = new Random();
    Object result = null;
    switch (clazz.getName()) {
        case "int":
            result = options[random.nextInt(options.length)];
            break;
        case "double":
            double min = Double.MIN_VALUE;
            double max = Double.MAX_VALUE;
            if (options.length > 0) {
                min = (double) options[0];
            }
            if (options.length > 1) {
                max = (double) options[1];
            }
            result = random.nextDouble() * (max - min) + min;
            break;
        case "boolean":
            result = options[random.nextInt(options.length)] == Boolean.TRUE;
            break;
        default:
            throw new UnsupportedOperationException("Unsupported type: " + clazz.getName());
    }
    return result;
}

