import java.security.SecureRandom;
import java.util.Random;

public class PasswordGenerator {
    public static String generatePassword(int length) {
        final String lowercase = "abcdefghijklmnopqrstuvwxyz";
        final String uppercase = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        final String digits = "0123456789";
        final String specialChars = "!@#$%^&*()_+~`-={}|[]:;\"'<,.";

        Random random = new SecureRandom();

        StringBuilder password = new StringBuilder(length);

        for (int i = 0; i < length / 4; i++) {
            password.append(lowercase.charAt(random.nextInt(26)));
            password.append(uppercase.charAt(random.nextInt(26)));
            password.append(digits.charAt(random.nextInt(10)));
            password.append(specialChars.charAt(random.nextInt(16)));
        }

        for (int i = password.length(); i < length; i++) {
            password.append(lowercase.charAt(random.nextInt(26)));
        }

        return password.toString();
    }
}

```java
public static <T> T getRandomValue(Random rng, Class<T> clazz) {
    if (clazz.equals(byte.class)) {
        return (T) Byte.valueOf((byte) rng.nextInt());
    } else if (clazz.equals(short.class)) {
        return (T) Short.valueOf((short) rng.nextInt());
    } else if (clazz.equals(int.class)) {
        return (T) Integer.valueOf(rng.nextInt());
    } else if (clazz.equals(long.class)) {
        return (T) Long.valueOf(rng.nextLong());
    } else if (clazz.equals(float.class)) {
        return (T) Float.valueOf(rng.nextFloat());
    } else if (clazz.equals(double.class)) {
        return (T) Double.valueOf(rng.nextDouble());
    } else if (clazz.equals(char.class)) {
        return (T) Character.valueOf((char) rng.nextInt(65536));
    } else if (clazz.equals(String.class)) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rng.nextInt(10); i++) {
            sb.append((char) rng.nextInt(65536));
        }
        return (T) sb.toString();
    } else if (clazz.getSimpleName().equals("DecimalType")) { // assuming DecimalType is a custom class
        Random r = new Random();
        int sign = r.nextBoolean() ? 1 : -1;
        long num = Math.abs(rng.nextLong());
        BigDecimal dec = new BigDecimal(num).multiply(new BigDecimal(sign));
        return (T) dec;
    } else {
        throw new RuntimeException("Unsupported type");
    }
}

