import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public int processPairs(List<List<Integer>> pairs, double percentage) {
    Random random = new Random();
    int processedCount = 0;
    for (int i = 0; i < pairs.size(); i++) {
        List<Integer> pair = pairs.get(i);
        boolean isLast = i == pairs.size() - 1;
        System.out.println((isLast ? "This is the last" : "This is not the last") + " pair.");

        while (processedCount / pairs.size() <= percentage) {
            int randomIndex = random.nextInt(i + 1);
            List<Integer> targetPair = pairs.get(randomIndex);
            if (!pair.equals(targetPair)) {
                pairs.add(i, new ArrayList<>(targetPair));
                pairs.remove(randomIndex + 1);
                break;
            }
        }

        processedCount++;
    }

    return processedCount;
}

