    int numFields = rand.nextInt(9 - 1) + 1;
    Object[] fields = new Object[numFields];
    boolean ascend = rand.nextBoolean();

    for (int i = 0; i < numFields; i++) {
        int typeIndex = rand.nextInt(types.length);
        if (!allowNulls && rand.nextBoolean()) {
            fields[i] = null;
