public List<InetAddress> createInetSocketAddressList(List<String> hostsAndPorts, String username, String password, int serverID, boolean createEnrichmentConnection, String driverLocation, String driverName, int connectionTimeout) {
    List<InetSocketAddress> inetSocketAddresses = new ArrayList<>();
    for(String hostPort : hostsAndPorts) {
        String[] parts = hostPort.split(":");
        if(parts.length != 2) {
            throw new ArrayIndexOutOfBoundsException("Invalid input format: " + hostPort);
        }
        try {
            int port = Integer.parseInt(parts[1]);
            InetSocketAddress inetSocketAddress = new InetSocketAddress(parts[0], port);
            inetSocketAddresses.add(inetSocketAddress);
        } catch(NumberFormatException e) {
            throw new ArrayIndexOutOfBoundsException("Invalid port number: " + parts[1]);
        }
    }
    return inetSocketAddresses;
}

