public File generateRandomBinaryFile(int length, FileSystem fs, Path folder, String fileName) throws IOException {
    File file = new File(folder.resolve(fileName).toString());
    FileOutputStream fos = fs.createOutputStream(file);
    RandomAccessFile raf = new RandomAccessFile(fos, "rw");

    for (int i = 0; i < length; i++) {
        boolean isSingleByte = Math.random() < 0.5;
        byte[] bytesToWrite = new byte[1];

        if (isSingleByte) {
            bytesToWrite[0] = (byte) Math.floor(Math.random() * 256);
        } else {
            Random r = new Random();
            for (int j = 0; j < 8; j++) {
                bytesToWrite[0] |= (byte) ((r.nextInt(2) << j));
            }
        }

        raf.write(bytesToWrite);
    }

    raf.close();

    return file;
}

