import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import java.security.spec.KeySpec;
import java.security.spec.PBKDF2KeySpec;

public class AESCipher {
    public static byte[] encrypt(byte[] password, byte[] salt, byte[] data) throws Exception {
        // Generate key using PBKDF2WithHmacSHA1 algorithm
        KeySpec spec = new PBKDF2KeySpec(password, salt, 65536, 128);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();

        // Generate IV for AES/CBC/NoPadding cipher
        IvParameterSpec iv = new IvParameterSpec(new byte[16]);

        // Initialize AES/CBC/NoPadding cipher for encryption
        Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, new javax.crypto.spec.SecretKeySpec(keyBytes, "AES"), iv);

        // Encrypt data using AES/CBC/NoPadding cipher
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(byte[] password, byte[] salt, byte[] encryptedData) throws Exception {
        // Generate key using PBKDF2WithHmacSHA1 algorithm
        KeySpec spec = new PBKDF2KeySpec(password, salt, 65536, 128);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();

        // Generate IV for AES/CBC/NoPadding cipher
        IvParameterSpec iv = new IvParameterSpec(new byte[16]);

        // Initialize AES/CBC/NoPadding cipher for decryption
        Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, new javax.crypto.spec.SecretKeySpec(keyBytes, "AES"), iv);

        // Decrypt data using AES/CBC/NoPadding cipher
        return cipher.doFinal(encryptedData);
    }
}

