public void manageThemeCaching() {
    Bitmap bitmap = getBitmapFromCache();
    if (bitmap != null && !bitmap.isRecycled()) {
        bitmap.recycle();
        bitmap = null;
    }

    String defaultDir = getDefaultDirectory();
    if (defaultDir == null) {
        defaultDir = "/path/to/default/directory";
    }

    File cacheRoot = new File(defaultDir);
    if (!cacheRoot.exists() && !cacheRoot.mkdirs()) {
        Log.e("ThemeCache", "Failed to create cache root directory");
        return;
    }

    File themeFile = new File(cacheRoot, "theme.png");
    Bitmap parsedBitmap = null;
    try (InputStream is = new FileInputStream(themeFile)) {
        parsedBitmap = BitmapFactory.decodeStream(is);
    } catch (IOException e) {
        Log.e("ThemeCache", "Failed to parse theme PNG file");
    }

    if (parsedBitmap != null && !parsedBitmap.isRecycled()) {
        parsedBitmap.recycle();
        parsedBitmap = null;
    }
}
