```java
public SortedBinaryDocValues loadAndCompare(Random random, LeafReaderContext context, IndexFieldData field1, IndexFieldData field2, Preprocessor preprocessor) {
    byte[] data1 = field1.loadBytes();
    byte[] data2 = field2.loadBytes();

    int len = data1.length;
    byte[] data = new byte[len * 2];
    System.arraycopy(data1, 0, data, 0, len);
    System.arraycopy(data2, 0, data, len, len);

    Arrays.sort(data);

    int resultLen = binarySearch(random, context, preprocessor, data);
    return new SortedBinaryDocValues(data, resultLen);
}

private int binarySearch(Random random, LeafReaderContext context, Preprocessor preprocessor, byte[] data) {
    int low = 0;
    int high = data.length - 1;

    while (low <= high) {
        int mid = low + ((high - low) >>> 1);

        byte val = data[mid];
        if (preprocessor.apply(val)) {
            // found the value, return the length
            return mid;
        } else if (!preprocessor.apply(data[0])) {
            // not found, move the low pointer
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return low;
}
