class GraphVertex {
    int id;
    List<GraphVertex> neighbors = new ArrayList<>();

    public GraphVertex(int id) {
        this.id = id;
    }
}

public class Main {
    private static AtomicLong numVertices = new AtomicLong();
    private static AtomicLong numEdges = new AtomicLong();
    private static AtomicLong completedThreads = new AtomicLong();

    public static void main(String[] args) throws InterruptedException {
        List<GraphVertex> graph = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            graph.add(new GraphVertex(i));
        }

        for (int i = 0; i < 9; i++) {
            int fromId = i;
            int toId = i + 1;
            graph.get(fromId).neighbors.add(graph.get(toId));
            numEdges.incrementAndGet();
        }

        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < graph.size(); i++) {
            Thread thread = new GraphTraversalThread(graph, i);
            thread.start();
            threads.add(thread);
        }

        for (Thread thread : threads) {
            thread.join();
        }

        System.out.println("Number of vertices: " + numVertices.get());
        System.out.println("Number of edges: " + numEdges.get());
        System.out.println("Completed threads: " + completedThreads.get());
    }
}

class GraphTraversalThread extends Thread {
    private List<GraphVertex> graph;
    private int startVertexId;

    public GraphTraversalThread(List<GraphVertex> graph, int startVertexId) {
        this.graph = graph;
        this.startVertexId = startVertexId;
    }

    @Override
    public void run() {
        for (int i = startVertexId; i < graph.size(); i++) {
            numVertices.incrementAndGet();
            System.out.println("Thread " + Thread.currentThread().getId() + " is visiting vertex " + graph.get(i).id);

            for (GraphVertex neighbor : graph.get(i).neighbors) {
                if (!neighbor.equals(graph.get(i))) {
                    numEdges.incrementAndGet();
                }
            }

        }

        completedThreads.incrementAndGet();
    }
}
