public static <K> Map<K, Double> normalizeWeights(List<Map.Entry<K, Double>> weightedItems, Function<Map.Entry<K, Double>, Double> weightComputer) {
    double totalWeight = 0;
    for (Map.Entry<K, Double> entry : weightedItems) {
        totalWeight += entry.getValue();
    }
    Map<K, Double> normalizedWeights = new HashMap<>();
    for (Map.Entry<K, Double> entry : weightedItems) {
        double weight = entry.getValue() / totalWeight;
        double normalizedWeight = weight * weightComputer.apply(entry);
        normalizedWeights.put(entry.getKey(), normalizedWeight);
    }
    return normalizedWeights;

