import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import org.xml.sax.Attributes;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

public class XmlSaxParser {

    public static void parse(String filename) {
        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();

            saxParser.setErrorHandler(new MyErrorHandler());

            InputSource inputSource = new InputSource(filename);
            saxParser.parse(inputSource, new MyDefaultHandler());
        } catch (Exception e) {
            System.out.println("Error parsing XML: " + e.getMessage());
        }
    }

    static class MyErrorHandler implements org.xml.sax.ErrorHandler {

        public void error(SAXParseException ex) throws SAXException {
            System.out.println("Warning: " + ex.getMessage());
        }

        public void fatalError(SAXParseException ex) throws SAXException {
            System.out.println("Fatal Error: " + ex.getMessage());
        }

        public void warning(SAXParseException ex) throws SAXException {
            System.out.println("Warning: " + ex.getMessage());
        }
    }

    static class MyDefaultHandler extends org.xml.sax.helpers.DefaultHandler {

        @Override
        public void startElement(String uri, String localName, String qname,
                Attributes atts) {
            System.out.println("Start Element: " + qname);
        }

        @Override
        public void endElement(String uri, String localName, String qname) {
            System.out.println("End Element: " + qname);
        }
    }

    static class SAXParseException extends Exception {

        public SAXParseException(String message) {
            super(message);
        }
    }
}

