    float viewportWidth = viewport.width();
    float viewportHeight = viewport.height();
    float viewportAspect = viewportWidth / viewportHeight;

    // Calculate the aspect ratio of the drawable
    float drawableWidth = drawable.width();
    float drawableHeight = drawable.height();
    float drawableAspect = drawableWidth / drawableHeight;

    // Determine the maximum possible crop rectangle based on the aspect ratios
    if (Math.abs(viewportAspect - drawableAspect) < 0.01f) {
        float maxLength = Math.min(drawableWidth, drawableHeight);
        RectF maxCrop = new RectF(0, 0, maxLength, maxLength);

        // Randomly scale the crop rectangle by a factor between minScale and maxScale
        float scale = (float) Math.random() * (maxScale - minScale) + minScale;
        maxCrop.inset(-maxLength * (1 - scale), -maxLength * (1 - scale));

        // Randomly offset the crop rectangle within the drawable bounds
        maxCrop.offset((float) Math.random() * (drawableWidth - maxLength),
                (float) Math.random() * (drawableHeight - maxLength));
    } else if (Math.abs(viewportAspect - 1.0f) < 0.01f && Math.abs(drawableAspect - 1.0f) > 10.0f) {
