public void connectToRemoteAddress(String host, int port) throws IOException {
    try (JavaChannel channel = JavaChannel.open()) {
        InetSocketAddress address = new InetSocketAddress(host, port);
        channel.bind(null, address);

        while (!channel.isOpen()) {
            channel.configureBlocking(true);
            channel.connect();
        }

        while (channel.isConnected() || channel.isConnecting()) {
            if (channel.isConnecting()) {
                System.out.println("Connection in progress...");
            }
            else if (channel.isConnected()) {
                System.out.println("Connected to " + host + ":" + port);
            }
            Thread.sleep(5000); // wait for 5 seconds
        }

        channel.configureBlocking(false);
    } catch (IOException e) {
        throw e;
    }
}
