import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.security.SecurityScheme;

public void configureOpenAPISecurity(OpenAPI openAPI, String realmPath) {
    SecurityScheme oidcSecurityScheme = new SecurityScheme();
    oidcSecurityScheme.setName("oidc");
    oidcSecurityScheme.setDescription("OIDC security scheme");
    oidcSecurityScheme.setFlows(new Flow().authorizationCode());
    oidcSecurityScheme.setScopes(new ArrayList<String>());
    openAPI.addSecurityItem(new OpenAPI.SecurityScheme(oidcSecurityScheme));

    SecurityScheme oauth2SecurityScheme = new SecurityScheme();
    oauth2SecurityScheme.setName("oauth2");
    oauth2SecurityScheme.setDescription("OAuth 2.0 security scheme");
    Flow flow = new Flow().authorizationCode()
            .withNoncompliantScopes(new ArrayList<String>());
    oauth2SecurityScheme.setFlows(flow);
    openAPI.addSecurityItem(new OpenAPI.SecurityScheme(oauth2SecurityScheme));
}
