public void assertGeographicPointDataEquality(Set<GeographicPoint> set1, Set<GeographicPoint> set2, double distanceTolerance) {
    for (GeographicPoint point1 : set1) {
        GeographicPoint point2 = findMatchingPoint(set2, point1, distanceTolerance);
        if (point2 == null) {
            throw new AssertionError("No matching point found");
        }

        int size1 = getUniqueValues(point1).size();
        int size2 = getUniqueValues(point2).size();
        if (size1 != size2) {
            throw new AssertionError("Size of values not equal");
        }

        List<Double> uniqueValues1 = new ArrayList<>(getUniqueValues(point1));
        List<Double> uniqueValues2 = new ArrayList<>(getUniqueValues(point2));
        Collections.sort(uniqueValues1);
        Collections.sort(uniqueValues2);

        if (!uniqueValues1.equals(uniqueValues2)) {
            throw new AssertionError("Values not in increasing order");
        }
    }
}

private GeographicPoint findMatchingPoint(Set<GeographicPoint> set, GeographicPoint point, double distanceTolerance) {
    for (GeographicPoint p : set) {
        if (isPointsEqual(point, p, distanceTolerance)) {
            return p;
        }
    }
    return null;
}

