import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class Main {
    public static void main(String[] args) {
        Gson gson = new GsonBuilder().create();
        List<JsonEvent> events = new ArrayList<>();
        Random random = new Random();

        for (int i = 0; i < 10; i++) {
            JsonEvent event = new JsonEvent(i, random.nextGaussian());
            events.add(event);
        }

        JsonArray jsonArray = new JsonArray();
        for (JsonEvent event : events) {
            JsonObject jsonObject = new JsonObject();
            jsonObject.addProperty("header", event.getHeader());
            jsonObject.addProperty("body", String.valueOf(event.getBody()));
            jsonArray.add(jsonObject);
        }

        System.out.println(gson.toJson(jsonArray));
    }
}

class JsonEvent {
    private int header;
    private double body;

    public JsonEvent(int header, double body) {
        this.header = header;
        this.body = body;
    }

    public int getHeader() {
        return header;
    }

    public double getBody() {
        return body;
    }
}

