public boolean createAndManageToken(String username, String password, String tokenId) {
    DelegationTokenManagerService dtms = new DelegationTokenManagerService();
    try {
        // Create token for the given user
        Token token = dtms.createToken(username, password);

        if (token == null) {
            return false;
        }

        // Verify the created token
        if (!dtms.verify(tokenId)) {
            return false;
        }

        // Renew the token
        Token renewedToken = dtms.renew(tokenId);
        if (renewedToken == null) {
            return false;
        }

        // Cancel the token
        boolean canceled = dtms.cancel(renewedToken);
        return canceled;
    } catch (Exception e) {
        return false;
    }
}

