public static String getWeatherData(String location) {
    try {
        URL url = new URL("http://api.openweathermap.org/data/2.5/weather?q=" + location + "&units=metric");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();

        if(responseCode == 200) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder weatherData = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                weatherData.append(inputLine);
            }
            in.close();
            return weatherData.toString();
        } else {
            throw new IOException("Error code: " + responseCode);
        }
    } catch (MalformedURLException e) {
        return "Invalid URL";
    } catch (IOException e) {
        return "Error reading from API";
    }
}

