public static Text getKerberosDelegationToken(String url, int port) {
    Text token = null;
    try {
        // Create a GSSAPI context
        GSSManager gssManager = GSSManager.getInstance();
        GSSContext gssContext = gssManager.createContext(null);

        // Acquire a delegation token
        GSSCredential credential = gssManager.createCredential(GSSCredential.DEFAULT);
        GSSName name = new UnameGSSName(System.getProperty("user.name"));
        boolean delegated = false;
        if (gssContext.isDelegated(name, credential)) {
            delegated = true;
            token = gssManager.getDelegationToken(credential);
        }

    } catch (InterruptedException e) {
        // Handle interrupt
    } catch (GSSException e) {
        // Handle GSS errors
    } finally {
        return new Text(token != null ? "true" : "false");
    }
}

