import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.net.InetSocketAddress;
import java.nio.channels.ServerSocketChannel;
import java.util.Scanner;

public class NioServer {

    public static void main(String[] args) throws IOException {
        ServerSocketChannel server = ServerSocketChannel.open();
        InetSocketAddress address = new InetSocketAddress("localhost", 12345);
        server.bind(address);
        System.out.println("Server is running...");

        Scanner scanner = new Scanner(System.in);

        while (true) {
            try {
                server.accept();
                System.out.println("Connection accepted");

                BufferedReader in = new BufferedReader(new InputStreamReader(server.socket().getInputStream()));
                PrintWriter out = new PrintWriter(server.socket().getOutputStream(), true);

                while (true) {
                    String line;
                    if ((line = scanner.nextLine()) != null) {
                        out.println(line);
                    }

                    String clientLine = in.readLine();
                    System.out.println("Client says: " + clientLine);

                    if (clientLine.equalsIgnoreCase("quit")) {
                        break;
                    }
                }

                server.close();
            } catch (IOException e) {
                System.out.println("Error: " + e.getMessage());
            }
        }

        scanner.close();
    }
}

