import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.Base64;

public class AESEncryption {
    public static void main(String[] args) throws Exception {
        // Generate an AES encryption key
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256); // 256-bit key
        SecretKey skey = kg.generateKey();
        byte[] secretBytes = skey.getEncoded();

        // Generate a random initialization vector (IV)
        SecureRandom sr = new SecureRandom();
        byte[] ivBytes = new byte[16];
        sr.nextBytes(ivBytes);
        IvParameterSpec iv = new IvParameterSpec(ivBytes);

        // Encrypt the input message
        String inputMessage = "This is an example message";
        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, skey, iv);

        byte[] encryptedBytes = cipher.doFinal(inputMessage.getBytes());
        System.out.println("Encrypted message in hexadecimal format: "
                + Base64.getEncoder().encodeToString(encryptedBytes));
    }
}
