import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public String getDateInterval(String dateRange) {
    String[] dates = dateRange.split("/");
    long startDateLong = Long.parseLong(dates[0]);
    long endDateLong = Long.parseLong(dates[1]);
    long interval = (endDateLong - startDateLong);

    if (interval < 0) {
        return "Invalid Date Range";
    }

    MessageDigest md;
    try {
        md = MessageDigest.getInstance("SHA-256");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }

    String hash = bytesToHex(md.digest(dateRange.getBytes()));
    if (interval > 0) {
        return "start/" + (startDateLong + interval);
    } else {
        return hash;
    }
}

public static String bytesToHex(byte[] bytes) {
    StringBuilder builder = new StringBuilder();
    for (byte b : bytes) {
        builder.append(String.format("%02x", b));
    }
    return builder.toString();
}
