public static byte[] serializeKijiDataRequest(KijiDataRequest request) throws IOException {
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    ObjectOutputStream oos = new ObjectOutputStream(bos);
    oos.writeObject(request);
    oos.flush();
    byte[] serializedRequest = bos.toByteArray();

    ByteArrayInputStream bis = new ByteArrayInputStream(serializedRequest);
    ObjectInputStream ois = new ObjectInputStream(bis);

    KijiDataRequest deserializedRequest = (KijiDataRequest) ois.readObject();

    // Compare the original request with the deserialized request
    if (!request.equals(deserializedRequest)) {
        throw new IOException("Serialization failed");
    }

    return serializedRequest;
}

