import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public byte[] concatenateHashes(byte[] data) {
    try {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        MessageDigest md2 = MessageDigest.getInstance("MD2");

        byte[] md5Hash = md5.digest(data);
        byte[] md2Hash = md2.digest(data);

        byte[] combinedHash = new byte[md5Hash.length + md2Hash.length];
        System.arraycopy(md5Hash, 0, combinedHash, 0, md5Hash.length);
        System.arraycopy(md2Hash, 0, combinedHash, md5Hash.length, md2Hash.length);

        return combinedHash;
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

