public URI downloadFile(String urlStr) throws IOException {
    URL url = new URL(urlStr);
    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    conn.setRequestMethod("GET");
    conn.setConnectTimeout(5000); // 5 seconds
    conn.setReadTimeout(10000); // 10 seconds

    int responseCode = conn.getResponseCode();

    if (responseCode >= 200 && responseCode < 300) {
        InputStream inputStream = conn.getInputStream();
        FileOutputStream fileOutputStream = null;
        File file = new File("path", "to", "your", "file.txt"); // adjust the path
        try {
            fileOutputStream = new FileOutputStream(file);
            IOUtils.copy(inputStream, fileOutputStream);
            return Uri.fromFile(file); // adjust the import statement
        } catch (IOException e) {
            throw new IOException("Failed to download file: " + e.getMessage());
        } finally {
            if (fileOutputStream != null) {
                fileOutputStream.close();
            }
        }
    } else {
        return null;
    }
}

