public void updateAndDrawBallAndPaddles(int ballX, int ballY, int paddle1X, int paddle2X, boolean isModified) {
    Graphics g = getGraphics();
    Font font = new Font("Arial", Font.BOLD, 16);
    FontMetrics fm = g.getFontMetrics(font);

    // Update position of the ball
    int centerX = Math.min(Math.max(ballX, 0), getWidth());
    int centerY = Math.min(Math.max(ballY, 0), getHeight());

    // Update positions of paddles
    int paddle1CenterX = Math.min(Math.max(paddle1X, 0), getWidth());
    int paddle2CenterX = Math.min(Math.max(paddle2X, 0), getWidth());

    // Draw text indicating who created and modified the game
    g.setFont(font);
    String creditsText = "Created by John Doe\nModified by Jane Smith";
    int creditWidth = fm.stringWidth(creditsText);
    int x = (getWidth() - creditWidth) / 2;
    int y = getHeight() - fm.getAscent() * 2;

    // Draw ball and paddles
    g.setColor(Color.WHITE);
    g.fillOval(centerX - 5, centerY - 5, 10, 10); // draw ball
    g.fillRect(paddle1CenterX - 20, 0, 40, getHeight()); // draw paddle 1
    g.fillRect(paddle2CenterX - 20, 0, 40, getHeight()); // draw paddle 2

    // Draw credits text
    g.setColor(Color.BLACK);
    g.drawString(creditsText, x, y);

    repaint();
