import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.server.NIOServerQuorumPeer;
import org.apache.zookeeper.server.ServerCnxnFactory;

public class ZooKeeperServer {
    public static void main(String[] args) throws Exception {
        int portStart = 2181;
        int portEnd = 2190;

        for (int port = portStart; port <= portEnd; port++) {
            try {
                ServerCnxnFactory factory = new NIOServerQuorumPeer.Main(new InetSocketAddress(port));
                ZooKeeper zk = new ZooKeeper("", 30000, null);
                zk/serverCnxnFactory = factory;
                zk.start();

                // Set tick time and session timeouts
                zk.setTickTime(2000);
                zk.setSessionTimeout(60000);

            } catch (Exception e) {
                if (!(e instanceof BindException)) {
                    throw e;
                }
            }
        }
    }
