import io.netty.handler.logging.LoggingHandler;
import org.apache.mina.core.service.IoService;
import org.apache.mina.core.service.IoServiceConfig;
import org.apache.mina.transport.socket.nio.NioSocketConnector;
import org.apache.mina.transport.socket.nio.NioSocketSession;
import org.apache.mina.transport.socket.SocketSessionConfig;

public IoSession setupConnection(String uri) {
    NioSocketConnector connector = new NioSocketConnector();
    connector.setHandler(new LoggingHandler());

    try {
        connector.setServiceConfig(new IoServiceConfig() {
            public void configure(IoService ioService) {
                ioService.setWorkerCount(2);
            }
        });

        SocketSessionConfig config = new SocketSessionConfig();
        config.setSoTimeout(10000); // 10 seconds
        config.setReuseAddress(true);
        config.setPerformancePreferences(1, 2, 3);

        NioSocketSession session = (NioSocketSession) connector.connect(new InetSocketAddress(uri)).get();
        session.getConfig().setSoKeepAlive(true);
        session.getConfig().setTcpNoDelay(true);
        return session;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

