import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;

class TransitionProbability {
    String fromState;
    Map<String, Double> toStates = new HashMap<>();

    public TransitionProbability(String fromState) {
        this.fromState = fromState;
    }
}

public class PartOfSpeechTagging {
    static Map<String, TransitionProbability> transitionProbabilities = new HashMap<>();
    static Map<String, Map<String, Double>> emissionProbabilities = new HashMap<>();
    static Map<String, Double> initialProbabilities = new HashMap<>();

    public static void main(String[] args) throws IOException {
        readModel("hmm.txt");
        String text = "This is a sample text for part-of-speech tagging.";
        Map<String, String> taggedText = tagText(text);
        printTaggedText(taggedText);
    }

    private static void readModel(String filename) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(filename));
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("TransitionProbabilities")) {
                reader.readLine(); // Skip the next line
                String[] transitionProbabilityLine = reader.readLine().split(",");
                TransitionProbability transitionProbability = new TransitionProbability(transitionProbabilityLine[0]);
                for (int i = 1; i < transitionProbabilityLine.length; i++) {
                    String[] splitLine = transitionProbabilityLine[i].trim().split(":");
                    transitionProbability.toStates.put(splitLine[0], Double.parseDouble(splitLine[1]));
                }
                transitionProbabilities.put(transitionProbability.fromState, transitionProbability);
            } else if (line.startsWith("EmissionProbabilities")) {
                reader.readLine(); // Skip the next line
                String[] emissionProbabilityLines = new String[20]; // Assuming 20 tags
                for (int i = 0; i < emissionProbabilityLines.length; i++) {
                    emissionProbabilityLines[i] = reader.readLine();
                }
                for (String emissionProbabilityLine : emissionProbabilityLines) {
                    String[] splitLine = emissionProbabilityLine.trim().split(":");
                    Map<String, Double> tagProbabilities = new HashMap<>();
                    for (int j = 1; j < splitLine.length; j++) {
                        String[] splitTagProbability = splitLine[j].trim().split(",");
                        tagProbabilities.put(splitTagProbability[0], Double.parseDouble(splitTagProbability[1]));
                    }
                    emissionProbabilities.put(emissionProbabilityLines[0].trim(), tagProbabilities);
                }
            } else if (line.startsWith("InitialProbabilities")) {
                reader.readLine(); // Skip the next line
                String[] initialProbabilityLine = reader.readLine().split(",");
                for (int i = 1; i < initialProbabilityLine.length; i++) {
                    initialProbabilities.put(initialProbabilityLine[i].trim(), Double.parseDouble(initialProbabilityLine[0]));
                }
            }
        }
    }

    private static Map<String, String> tagText(String text) {
        Map<String, String> taggedText = new HashMap<>();
        String previousTag = "";
        for (String word : text.split(" ")) {
            double maxProbability = 0;
            String bestTag = null;
            for (Map.Entry<String, Map<String, Double>> emissionProbabilityEntry : emissionProbabilities.entrySet()) {
                String tag = emissionProbabilityEntry.getKey();
                if (!taggedText.containsKey(word)) {
                    taggedText.put(word, "");
                }
                double probability = initialProbabilities.getOrDefault(tag, 0.0);
                for (Map.Entry<String, TransitionProbability> transitionProbabilityEntry : transitionProbabilities.entrySet()) {
                    if (transitionProbabilityEntry.getValue().fromState.equals(previousTag) && emissionProbabilityEntry.getKey().equals(tag)) {
                        probability *= transitionProbabilityEntry.getValue().toStates.getOrDefault(word, 1.0);
                    }
                }
                if (probability > maxProbability) {
                    maxProbability = probability;
                    bestTag = tag;
                }
            }
            taggedText.put(word, bestTag);
            previousTag = bestTag;
        }
        return taggedText;
    }

    private static void printTaggedText(Map<String, String> taggedText) {
        for (Map.Entry<String, String> entry : taggedText.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}

