import canal.connector CanalConnector;
import canal.connector.query.QueryResult;

public class CanalConsumer {

    public static void main(String[] args) {
        String canalAddress = "localhost:11933";
        int batchSize = 1000;
        int maxAttempts = 3;
        String topic = "";

        CanalConnector connector = new CanalConnector(canalAddress);

        try {
            // Connect to the Canal server
            if (!connector.connect()) {
                System.out.println("Failed to connect to Canal server");
                return;
            }

            // Subscribe to an empty topic
            connector.subscribe(topic);
            QueryResult queryResult = connector.query();

            // Roll back the database to a point in time before receiving messages
            int lastOffset = queryResult.getLastOffset();
            connector.rollback(lastOffset);

            // Receive messages in batches
            while (true) {
                try {
                    List<Message> messages = connector.receive(batchSize);
                    // Process the received messages
                    for (Message message : messages) {
                        System.out.println(message);
                    }
                } catch (Exception e) {
                    if (maxAttempts > 0 && e instanceof ExceptionWithRetries) {
                        // If an exception occurs, roll back and try again
                        connector.rollback();
                        maxAttempts--;
                    } else {
                        // Print the error message and exit
                        System.out.println("Error: " + e.getMessage());
                        return;
                    }
                }

                // Check if there are no more messages available
                if (connector.isEmpty()) {
                    break;
                }
            }
        } finally {
            // Disconnect from the Canal server when done
            connector.disconnect();
        }
    }
}
