public static Socket createSecureSocket(String hostname, int port) throws IOException {
    TrustManager[] trustAllCerts = new TrustManager[]{new TrustAllCertificateManager()};
    SSLContext context = SSLContext.getInstance("TLS");
    context.init(null, trustAllCerts, null);
    SSLSocketFactory sslSockFac = context.getSocketFactory();
