    public static List<String> getMacAddresses() throws IOException {
        List<String> macAddresses = new ArrayList<>();
        Process process = Runtime.getRuntime().exec("netsh interface ip show config all");

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains("IPv4 Address") || line.contains("IPv6 Address")) {
                    String[] parts = line.split("\\s+");
                    for (String part : parts) {
                        if (part.startsWith("MAC")) {
                            macAddresses.add(part.substring(3));
                        }
                    }
                }
            }
        }

        return macAddresses;
    }
