public class DictionaryDownloader {
    public static void main(String[] args) throws IOException {
        String url = "https://raw.githubusercontent.com/firstdraft/defaultdict/master/defaultdict.txt";
        File tempFile = File.createTempFile("temp", ".txt");
        File existingDictFile = new File("existing_dict_file.txt");

        try (BufferedInputStream bis = new BufferedInputStream(new URL(url).openStream())) {
            try (BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(tempFile))) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = bis.read(buffer)) != -1) {
                    bos.write(buffer, 0, bytesRead);
                }
            }
        }

        try (BufferedReader br = new BufferedReader(new FileReader(tempFile))) {
            File newTextFile = new File("new_dict_file.txt");
            try (PrintWriter pw = new PrintWriter(newTextFile)) {
                String line;
                while ((line = br.readLine()) != null) {
                    pw.println(line);
                }
            }

            // Replace existing dictionary file with the downloaded contents
            Files.deleteIfExists(existingDictFile.toPath());
            Files.move(tempFile.toPath(), existingDictFile.toPath());
        } catch (IOException e) {
            System.err.format("IOException: %s%n", e);
        }
    }
}
