public HttpResponse postRequest(String endpoint, String requestBody, String token) {
    HttpClient client = new DefaultHttpClient();
    HttpPost request = new HttpPost(endpoint);

    if (requestBody != null && !requestBody.isEmpty()) {
        StringEntity entity = new StringEntity(requestBody, "UTF-8");
        entity.setContentEncoding("gzip"); // set gzip encoding
        request.setEntity(entity);
    }

    request.addHeader("Authorization", "Bearer " + token); // add token header

    if (rateLimiter(maxRate)) { // check if rate limiter should be applied
        client = applyRateLimiter(client, maxRate);
    }

    HttpResponse response = client.execute(request);
    return response;
}

private HttpClient applyRateLimiter(HttpClient client, int maxRate) {
    // implement your rate limiter logic here
    // for example:
