import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static void generateMD5Hash(String filePath) throws Exception {
    File file = new File(filePath);
    if (!file.isFile()) {
        System.out.println("Error: The provided path is not a valid file.");
        return;
    }

    MessageDigest md = MessageDigest.getInstance("MD5");
    FileInputStream fis = new FileInputStream(file);
    byte[] buffer = new byte[1024];
    int nRead;

    while ((nRead = fis.read(buffer)) != -1) {
        md.update(buffer, 0, nRead);
    }

    fis.close();

    byte[] digest = md.digest();

    FileOutputStream fos = new FileOutputStream(filePath.replace(".", ".md5"));
    for (int i = 0; i < digest.length; i++) {
        fos.write(String.format("%02x", digest[i]).getBytes());
    }
    fos.close();
}

