public static Object invokeRemoteMethod(String serverAddress, String methodName, Object[] params) throws IOException {
    Socket socket = new Socket(serverAddress, 8000);
    ObjectOutputStream output = new ObjectOutputStream(socket.getOutputStream());
    ObjectInputStream input = new ObjectInputStream(socket.getInputStream());

    Request request = new Request(methodName, params);

    output.writeObject(request);
    output.flush();

    Response response = (Response) input.readObject();
    input.close();
    output.close();
    socket.close();

    return response.getResult();
}

class Request implements Serializable {
    private String methodName;
    private Object[] params;

    public Request(String methodName, Object[] params) {
        this.methodName = methodName;
        this.params = params;
    }

    // getters and setters
}

class Response implements Serializable {
    private Object result;

    public Response(Object result) {
        this.result = result;
    }

    // getter for the result
}
