public String generateETag(Change change) {
    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
        // Handle exception if needed
    }

    StringBuilder etag = new StringBuilder();
    etag.append(change.getLastUpdated());
    etag.append(change.getRowVersion());
    etag.append(change.getAccountID());

    for (Revision revision : change.getProject().getRevisions()) {
        etag.append(revision.getRevisionID());
    }

    byte[] hashBytes;
    try {
        md.update(etag.toString().getBytes("UTF-8"));
        hashBytes = md.digest();
    } catch (UnsupportedEncodingException e) {
        // Handle exception if needed
    }

    String result = "";
    for (int i = 0; i < hashBytes.length; i++) {
        result += Integer.toHexString((hashBytes[i] & 0xFF));
    }
    return result;
}

