import java.io.IOException;
import java.net.Socket;

public void connectAndSendMessage(String host, int port, byte[] messageBuffer) throws IOException {
    Socket socket = new Socket(host, port);

    // Enable keepalive on the socket
    socket.setKeepAlive(true);

    try (socket.getOutputStream()) {
        while (true) {
            // Send the message buffer to the host
            socket.getOutputStream().write(messageBuffer);

            // Flush requests are handled here
            socket.getOutputStream().flush();
        }
    }
}
