public static Socket createSocket(String host, int port, boolean useSSL) throws IOException {
    Socket socket;
    if (useSSL) {
        SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLContext.getDefault().getSocketFactory();
        socket = (SSLSocket) sslSocketFactory.createSocket(host, String.valueOf(port));
        ((SSLSocket) socket).setSoTimeout(10000); // set read timeout to 10 seconds
    } else {
        socket = new Socket(host, port);
        socket.setSoTimeout(10000); // set read timeout to 10 seconds
    }
    socket.setSoLinger(true, 3000); // initialize with a linger time of 3 seconds
    return socket;
}

