public DatagramConnector setupDatagramConnection(String connectionURI) {
    if (transferExchange) {
        throw new IllegalArgumentException("Transfer exchange is set to true");
    }

    DatagramConnector connector = new DatagramConnector();

    InetSocketAddress address = new InetSocketAddress(InetAddress.getByName(connectionURI), 8080);
    connector.setSocketAddress(address);

    try {
        connector.setChannel(DatagramChannel.open());
    } catch (IOException e) {
        // handle exception
    }

    connector.setProcessorCount(Runtime.getRuntime().availableProcessors());

    ExecutorService executor = Executors.newFixedThreadPool(5);
    connector.setExecutor(executor);

    return connector;
}

