import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public String compressAndHash(String filePath, int compressionLevel) {
    try (InputStream is = new FileInputStream(filePath);
         OutputStream os = new FileOutputStream("compressed_" + filePath);
         LZOCompressor compressor = new LZOCompressor(compressionLevel)) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = is.read(buffer)) != -1) {
            byte[] compressedData = compressor.compress(buffer, 0, bytesRead);
            os.write(compressedData);
        }
    }

    try (InputStream is = new FileInputStream("compressed_" + filePath)) {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        int bytesRead;
        byte[] buffer = new byte[1024];
        while ((bytesRead = is.read(buffer)) != -1) {
            md5.update(buffer, 0, bytesRead);
        }
        return bytesToHex(md5.digest());
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

private String bytesToHex(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
        sb.append(String.format("%02x", b));
    }
    return sb.toString();
}

