import java.io.FileReader;
import java.io.IOException;
import javax.crypto.Mac;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.SecretKeySpec;

public String getFileMD5Checksum(String filePath) throws IOException {
    Mac mac = null;
    try {
        FileReader fileReader = new FileReader(filePath);
        byte[] buffer = new byte[1024];
        int bytesRead;
        StringBuilder sb = new StringBuilder();
        mac = SecretKeyFactory.getInstance("HmacMD5").generateSecret(new SecretKeySpec("MD5".getBytes(), "HmacMD5"));
        MessageDigest md = MessageDigest.getInstance("MD5");
        while ((bytesRead = fileReader.read(buffer)) != -1) {
            md.update(buffer, 0, bytesRead);
        }
        fileReader.close();
        byte[] checksumBytes = md.digest();
        for (int i = 0; i < checksumBytes.length; i++) {
            sb.append(Integer.toHexString(0xFF & checksumBytes[i]));
        }
    } catch (IOException e) {
        throw e;
    } finally {
        try {
            if (mac != null) {
                mac.reset();
            }
        } catch (Exception ignored) {}
    }
    return sb.toString();
}
