import java.io.*;
import java.lang.reflect.Method;
import java.net.*;

public void handleSocket(Socket socket) throws IOException {
    BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
    PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

    String line;
    line = in.readLine();
    Object[] args = null;

    try {
        Class<?> clazz = Class.forName(line.split(" ")[0]);
        Method method = clazz.getMethod(line.split(" ")[1], (Class[])null);
        if (args != null) {
            method.invoke(null, args);
        } else {
            method.invoke(null);
        }
    } catch (ClassNotFoundException e) {
        out.println("Error: Class not found");
    } catch (NoSuchMethodException e) {
        out.println("Error: Method not found");
    } catch (IllegalAccessException e) {
        out.println("Error: Illegal access to method");
    } catch (InvocationTargetException e) {
        out.println("Error: Error calling method");
    }

    if (args != null) {
        out.println(method.invoke(null, args));
    } else {
        out.println(method.invoke(null));
    }
}
