public Socket connectToServer(String serverName, int port) throws IOException {
    // Initialize the Kerberos configuration
    System.setProperty("javax.security.auth.useSubjectCredsOnly", "true");

    // Get a socket factory that supports Kerberos
    SocketFactory sf = (SocketFactory) ServiceLocator.create(SocketFactory.class);

    // Establish a connection to the server using Kerberos authentication
    Socket s = sf.createSocket(serverName, port);

    // Set the connection timeout and ping interval
    s.setSoTimeout(10000); // 10 seconds
    s.setSoPingInterval(5000); // 5 seconds

    return s;
}
