public boolean executeProcess(String command, List<String> args) {
    try {
        Process process = Runtime.getRuntime().exec(command, null);
        logExecutionDetails("Started process: " + command, process);

        WatchdogThread thread = new WatchdogThread(process);
        thread.start();

        return true;
