class WatchdogThread extends Thread {
    private Process process;

    public WatchdogThread(Process process) {
        this.process = process;
    }

    @Override
    public void run() {
        try {
            int status = process.waitFor();
            logExecutionDetails("Process ended with status: " + status, process);
        } catch (InterruptedException e) {
            logError("Watchdog thread interrupted", e);
        }
    }
}
