import java.io.*;
import java.util.Random;

public class Main {

    public static void main(String[] args) throws IOException {
        Random random = new Random();
        Person person = new Person(random.nextInt(), random.nextBoolean());

        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutput oo = null;
        long startTime = System.nanoTime();

        for (int i = 0; i < 500; i++) {
            try {
                oo = new ObjectOutputStream(bos);
                oo.writeObject(person);
            } catch (NotSerializableException e) {
                // Handle the exception
            }

            bos.reset();
        }

        long endTime = System.nanoTime();
        long timeTaken = (endTime - startTime) / 1000000;
        byte[] serializedData = bos.toByteArray();

        System.out.println("Time taken: " + timeTaken + " milliseconds");
        System.out.println("Serialized data size: " + serializedData.length);

        // Deserialization
        ByteArrayInputStream bis = new ByteArrayInputStream(serializedData);
        ObjectInput ii = null;

        startTime = System.nanoTime();
        for (int i = 0; i < 500; i++) {
            try {
                ii = new ObjectInputStream(bis);
                person = (Person) ii.readObject();
            } catch (ClassNotFoundException e) {
                // Handle the exception
            }

            bis.reset();
        }

        endTime = System.nanoTime();
        timeTaken = (endTime - startTime) / 1000000;
        System.out.println("Deserialization time taken: " + timeTaken + " milliseconds");
    }
}

