import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;

public byte[] encryptAES(byte[] input, String key) throws Exception {
    // Create an instance of AES/CBC/PKCS5Padding cipher
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5PADDING");

    // Set the encryption mode and key
    IvParameterSpec iv = new IvParameterSpec(new byte[16]);
    cipher.init(Cipher.ENCRYPT_MODE, generateKey(key), iv);

    // Encrypt the data
    byte[] encryptedBytes = cipher.doFinal(input);

    // Return the encrypted data along with the IV as a single byte array
    byte[] result = new byte[encryptedBytes.length + 16];
    System.arraycopy(encryptedBytes, 0, result, 0, encryptedBytes.length);
    System.arraycopy(iv.getIV(), 0, result, encryptedBytes.length, iv.getIV().length);

    return result;
}

private Key generateKey(String key) throws Exception {
    // Implement your key generation logic here
    // For simplicity, this method just returns a generated key for demonstration purposes
    SecureRandom random = new SecureRandom();
    byte[] keyBytes = new byte[16];
    random.nextBytes(keyBytes);
    return new SecretKeySpec(keyBytes, "AES");
}

