```java
public int getHash(String str, String hashFunction) {
    if (hashFunction.equals("MD5")) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            return -1;
        }
        byte[] bytes = str.getBytes();
        int[] ints = new int[4];
        for (int i = 0; i < 16; i += 4) {
            long l = 0;
            for (int j = 0; j < 4; j++) {
                l = (l << 8) | ((bytes[i + j] & 0xFF));
            }
            ints[i / 4] = (int) (l % Integer.MAX_VALUE);
        }
        int hashValue = 0;
        for (int i : ints) {
            hashValue += i;
        }
        return hashValue;

    } else if (hashFunction.equals("SHA")) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("SHA");
        } catch (NoSuchAlgorithmException e) {
            return -1;
        }
        byte[] bytes = str.getBytes();
        byte[] hashBytes = md.digest(bytes);
        int hashValue = 0;
        for (byte b : hashBytes) {
            hashValue += b & 0xFF;
        }
        return hashValue;

    } else if (hashFunction.equals("FNV")) {
        long hashValue = 2166136261L;
        char[] chars = str.toCharArray();
        for (char c : chars) {
            hashValue = (hashValue ^ ((long) c)) * 16777219L;
        }
        return (int) (hashValue % Integer.MAX_VALUE);

    } else {
        return -1;
    }
}

