public WalkMap readFile(String filePath) {
    WalkMap walkMap;
    String fileExtension = filePath.substring(filePath.lastIndexOf('.') + 1);

    try (FileInputStream fis = new FileInputStream(filePath)) {
        if (fileExtension.equals("objv")) {
            byte[] content = new byte[fis.available()];
            fis.read(content);
            walkMap = new ViewMap(new ByteArrayInputStream(content));
        } else if (fileExtension.equals("objp")) {
            walkMap = new PathsMap(fis);
        } else if (fileExtension.equals("jrd3m")) {
            ObjectInputStream ois = new ObjectInputStream(fis);
            walkMap = (WalkMap) ois.readObject();
        } else {
            throw new Exception("Invalid file extension");
        }
    } catch (FileNotFoundException e) {
        throw new Exception("File not found: " + filePath);
    } catch (IOException | ClassNotFoundException e) {
        throw new Exception("Failed to read file: " + filePath);
    }

    return walkMap;
}

