import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import org.xml.sax.Attributes;
import org.xml.sax.helpers.DefaultHandler;

import java.io.File;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        FrequencyHandler frequencyHandler = new FrequencyHandler();
        SAXParser saxParser = SAXParserFactory.newInstance().newSAXParser();

        File folder = new File("path_to_your_xml_files");
        for (File file : Objects.requireNonNull(folder.listFiles())) {
            if (file.getName().endsWith(".xml")) {
                saxParser.parse(file.getAbsolutePath(), frequencyHandler);
            }
        }

        Map<String, Integer> prefixFrequencyMap = frequencyHandler.getPrefixFrequencyMap();
        for (Map.Entry<String, Integer> entry : prefixFrequencyMap.entrySet()) {
            System.out.println("Prefix: " + entry.getKey() + ", Frequency: " + entry.getValue());
        }
    }
}

class FrequencyHandler extends DefaultHandler {

    private Map<String, Integer> prefixFrequencyMap;

    public FrequencyHandler() {
        this.prefixFrequencyMap = new HashMap<>();
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attributes) {
        if (localName.equals("prefix")) {
            String prefix = attributes.getValue("value");
            if (!this.prefixFrequencyMap.containsKey(prefix)) {
                this.prefixFrequencyMap.put(prefix, 1);
            } else {
                int frequency = this.prefixFrequencyMap.get(prefix);
                this.prefixFrequencyMap.put(prefix, frequency + 1);
            }
        }
    }

    public Map<String, Integer> getPrefixFrequencyMap() {
        return this.prefixFrequencyMap;
    }
}

