import java.io.UnsupportedEncodingException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Map;

public int generateHashCode(Map<String, String> paths, String moduleName, boolean createSymlinks, boolean createHeaderMap) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        StringBuilder sb = new StringBuilder();

        if (moduleName != null && !moduleName.isEmpty()) {
            sb.append(moduleName);
        }

        if (createSymlinks) {
            sb.append("symlink");
        } else {
            sb.append("nolink");
        }

        if (createHeaderMap) {
            sb.append("headermap");
        } else {
            sb.append("noheadermap");
        }

        for (Map.Entry<String, String> entry : paths.entrySet()) {
            sb.append(entry.getKey());
            sb.append(entry.getValue());
        }

        byte[] hashBytes = md.digest(sb.toString().getBytes("UTF-8"));
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }

        return Integer.parseInt(hexString.toString(), 16);

    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException(e);
    }
}

