public static boolean assertCoordinates(String input, double xExpected, double yExpected) {
    String[] coordinates = input.split(",");
    if (coordinates.length != 2) {
        return false;
    }
    try {
        double x = Double.parseDouble(coordinates[0].trim());
        double y = Double.parseDouble(coordinates[1].trim());
        return Math.abs(x - xExpected) < 0.00001 && Math.abs(y - yExpected) < 0.00001;
