public Object deserializeAndReset(Object obj) throws IOException {
    ObjectOutputStream oos = null;
    ObjectInputStream ois = null;
    try {
        oos = new ObjectOutputStream(new ByteArrayOutputStream());
        oos.writeObject(obj);
        oos.reset();
        byte[] bytes = ((ByteArrayOutputStream) oos).toString().getBytes();
        ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
        ois = new ObjectInputStream(bais);
        return ois.readObject();
    } catch (IOException e) {
        throw e;
    } finally {
        try {
            if (oos != null) {
                oos.close();
            }
            if (ois != null) {
                ois.close();
            }
        } catch (IOException e) {
            // ignore
        }
    }
}

