public int executeCommand(InputStream input, OutputStream output, Optional<Long> timeout) {
    try (Process process = Runtime.getRuntime().exec(input == null ? new String[0] : new String[]{"-"}, input != null && output != null, input, output)) {
        if(timeout.isPresent()) {
            process.waitFor(timeout.get(), TimeUnit.MILLISECONDS);
        } else {
            process.waitFor();
        }
    } catch (IOException | InterruptedException e) {
        throw new RuntimeException("Failed to execute command", e);
    }
    return process.exitValue();
