import java.io.*;
import java.util.*;

public NFA createAndSerializeNFA(int windowLength) {
    // Create new NFA
    NFA nfa = new NFA();

    // Set the number of states in the NFA
    nfa.setNumStates(windowLength + 1);

    // Create a set to store all the states
    HashSet stateSet = new HashSet();

    // Add all the states to the set
    for (int i = 0; i <= windowLength; i++) {
        stateSet.add(new State(i));
    }

    // Set the start state and end state
    nfa.setStartState((State) stateSet.iterator().next());
    nfa.setEndState((State) stateSet.iterator().next());

    // Serialize the NFA
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    ObjectOutputStream oos;
    try {
        oos = new ObjectOutputStream(bos);
        oos.writeObject(nfa);
        oos.close();

        // Deserialize the NFA
        ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
        ObjectInputStream ois;
        try {
            ois = new ObjectInputStream(bis);
            NFA deserializedNFA = (NFA) ois.readObject();

            // Compare the original and deserialized NFAs for equality
            if (!nfa.equals(deserializedNFA)) {
                return null;
            }
        } catch (ClassNotFoundException e) {
            return null;
        }
    } catch (IOException e) {
        return null;
    }

    return nfa;
}
