public boolean testIsJavaLetter() {
    Character.isJavaLetter('a'); // letter
    assertTrue(Character.isJavaLetter('a'));

    Character.isJavaLetter('9'); // digit
    assertFalse(Character.isJavaLetter('9'));

    Character.isJavaLetter('&'); // currency symbol
    assertTrue(Character.isJavaLetter('&'));

    Character.isJavaLetter('_'); // connecting character
    assertTrue(Character.isJavaLetter('_'));

    Character.isJavaLetter('\uFEFF'); // ignored control (zero-width joiner)
    assertTrue(Character.isJavaLetter('\uFEFF'));

    Character.isJavaLetter('!'); // punctuation
    assertFalse(Character.isJavaLetter('!'));

    return true;
}

