import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import java.nio.ByteBuffer;
import java.security.KeyException;
import java.util.Base64;

public String encrypt(String text, CompanyService companyService) {
    SecretKey secretKey = companyService.getSecretKey();
    byte[] ivBytes = companyService.getInitializationVector();

    Cipher cipher;
    try {
        cipher = Cipher.getInstance("Blowfish/CFB/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ByteBuffer.wrap(ivBytes));
    } catch (Exception e) {
        throw new RuntimeException("Encryption failed", e);
    }

    byte[] textBytes = text.getBytes();
    byte[] encryptedBytes;
    try {
        encryptedBytes = cipher.doFinal(textBytes);
    } catch (Exception e) {
        throw new RuntimeException("Encryption failed", e);
    }

    return Base64.getEncoder().encodeToString(encryptedBytes);
}

