public static String encryptMessage(String message, String encodingScheme, boolean toUpper) {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = message.getBytes(encodingScheme);
        if (toUpper) {
            bytes = bytes.map(b -> (byte) (b & 0xFF)).toArray(new byte[0]);
        }
        String encryptedMessage = bytesToHexString(md.digest(bytes));
        return encryptedMessage;
    } catch (Exception e) {
        return null;
    }
}

public static String bytesToHexString(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
        sb.append(String.format("%02X", b));
    }
    return sb.toString();
}
