import javax.crypto.*;
import java.security.*;
import java.util.Base64;

public String encrypt(String key, String target) throws Exception {
    // Convert input strings to byte arrays
    byte[] keyBytes = key.getBytes("UTF-8");
    byte[] targetBytes = target.getBytes("UTF-8");

    // Create a secret key from the given key
    SecretKey secretKey = new SecretKeySpec(keyBytes, "AES");

    // Create an initialization vector (IV)
    IvParameterSpec ivParamSpec = new IvParameterSpec(new byte[16]);

    // Create a cipher object for AES encryption with CBC mode and PKCS5 padding
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5PADDING");

    // Initialize the cipher for encryption
    cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParamSpec);

    // Perform the encryption operation
    byte[] encryptedBytes = cipher.doFinal(targetBytes);

    // Encode the resulting ciphertext into a string using Base64
    return Base64.getEncoder().encodeToString(encryptedBytes);
}

