import java.io.FileInputStream;
import java.io.IOException;
import javax.xml.hash.MD5MessageDigest;

public String calculateMD5Hash(String filePath) throws IOException {
    FileInputStream fileInputStream = new FileInputStream(filePath);
    MD5MessageDigest md5Hasher = MD5MessageDigest.getInstance();
    byte[] fileBytes = new byte[fileInputStream.available()];
    fileInputStream.read(fileBytes);
    return String.format("%032x", md5Hasher.digest(fileBytes));
}

