import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import java.io.IOException;

public class SaxExample {
    public static void main(String[] args) throws SAXException, IOException {
        // Create a new instance of the XMLReader
        SAXParserFactory factory = SAXParserFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        XMLReader reader = factory.newSAXParser().getXMLReader();

        SaxHandler handler = new SaxHandler();
        reader.parse(new File("input.xml"), handler);
    }
}

class SaxHandler extends DefaultHandler {
    public void startElement(String uri, String localName, String qname, Attributes atts) throws SAXException {
        System.out.println("Start Element: " + qname);
    }

    public void endElement(String uri, String localName, String qname) throws SAXException {
        System.out.println("End Element: " + qname);
    }

    public void error(SAXParseException e) throws SAXException {
        System.out.println("Error at line " + e.getLineNumber() + ": " + e.getMessage());
    }
}

class SAXParseException extends Exception {
    private int lineNumber;
    private String message;

    public SAXParseException(int lineNumber, String message) {
        this.lineNumber = lineNumber;
        this.message = message;
    }

    public int getLineNumber() {
        return lineNumber;
    }

    public String getMessage() {
        return message;
    }
}

