private static String formatHex(BigInteger bi) {
    StringBuilder sb = new StringBuilder();
    String hex = bi.toString(16);
    for (int i = 0; i < 32 - hex.length(); i++) {
        sb.append('0');
    }
    sb.append(hex);
    return sb.toString();
}

