import org.apache.http.*;
import org.apache.http.auth.AuthSchemes;
import org.apache.http.auth.CredentialsProvider;
import org.apache.http.auth.MacAuthScheme;
import org.apache.http.auth.UsernamePasswordCredentials;
import org.apache.http.client.CredentialsProvider;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.config.Registry;
import org.apache.http.config.RegistryBuilder;
import org.apache.http.conn.socket.PlainSocketFactory;
import org.apache.http.conn.ssl.SSLConnectionSocketFactory;
import org.apache.http.impl.client.BasicCredentialsProvider;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClientBuilder;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.protocol.HttpContext;
import org.apache.http.util.EntityUtils;

public class Main {
    public static void main(String[] args) throws IOException {
        Registry<SocketFactory> socketFactoryRegistry = RegistryBuilder.get()
                .register("http", PlainSocketFactory.getSocketFactory())
                .register("https", SSLConnectionSocketFactory.getSocketFactory())
                .build();

        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        UsernamePasswordCredentials credentials = new UsernamePasswordCredentials("username", "password");
        credentialsProvider.setCredentials(new AuthSchemes BASIC, credentials);

        RequestConfig requestConfig = RequestConfig.custom()
                .setProxy(new HttpHost("proxy.host", 8080))
                .build();

        CloseableHttpClient httpClient = HttpClients.custom()
                .setDefaultRequestConfig(requestConfig)
                .setDefaultCredentialsProvider(credentialsProvider)
                .setSSLHostnameVerifier(NoopHostnameVerifier.INSTANCE)
                .setSocketFactoryRegistry(socketFactoryRegistry)
                .build();

        HttpGet get = new HttpGet("http://example.com");
        CloseableHttpResponse response = httpClient.execute(get);

        String responseBody = EntityUtils.toString(response.getEntity());
        System.out.println(responseBody);

        response.close();
        httpClient.close();
    }
}

