import javax.xml.namespace.NamespaceContext;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;

public boolean modifyProperty(String groupName, String propertyName, String newValue) {
    try {
        // Create a new XPath object
        XPath xPath = XPathFactory.newInstance().newXPath();

        // Compile the XPath expression to get the property group node
        XPathExpression expr = xPath.compile("//" + groupName);
        Object result = expr.evaluate(null);

        if (result != null) {
            // Get the property node within the group node
            Node propertyNode = (Node) result;

            // Compile the XPath expression to set the new value of the property
            expr = xPath.compile(propertyName);
            NodeList childNodes = (NodeList) expr.evaluate(propertyNode, XPathConstants.NODESET);

            if (!childNodes.isEmpty()) {
                // Set the new value of the property
                Node childNode = childNodes.item(0);
                childNode.setTextContent(newValue);
                return true;
            }
        }

    } catch (Exception e) {
        // Handle exceptions
    }

    return false;
}

