import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashFunction {
    private Map<String, MessageDigest> algorithms = new HashMap<>();

    public String getHash(String input, String algorithm) throws NoSuchAlgorithmException {
        if (!algorithms.containsKey(algorithm)) {
            algorithms.put(algorithm, MessageDigest.getInstance(algorithm));
        }
        MessageDigest md = algorithms.get(algorithm);
        md.update(input.getBytes());
        byte[] hashBytes = md.digest();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hashBytes.length; i++) {
            String hex = Integer.toHexString(0xff & hashBytes[i]);
            if (hex.length() == 1) {
                sb.append('0');
            }
            sb.append(hex);
        }
        return sb.toString();
    }

    public static void main(String[] args) throws NoSuchAlgorithmException {
        HashFunction hf = new HashFunction();
        String input = "Hello, World!";
        System.out.println("MD5: " + hf.getHash(input, "MD5"));
        System.out.println("SHA-1: " + hf.getHash(input, "SHA-1"));
        System.out.println("SHA-256: " + hf.getHash(input, "SHA-256"));
        System.out.println("SHA-384: " + hf.getHash(input, "SHA-384"));
        System.out.println("SHA-512: " + hf.getHash(input, "SHA-512"));
    }
}

