public void registerUser(String username, String password) {
    if (username == null || username.isEmpty() || password == null || password.isEmpty()) {
        log.warning("Username and/or password is empty");
        HttpSession session = ((HttpServlet)request).getSession();
        session.setAttribute("error", "Username and/or password is empty");
        return;
    }

    // hash the password using MD5 algorithm
    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] bytes = password.getBytes("UTF-8");
    byte[] hashedBytes = md.digest(bytes);
    String hashedPassword = byteArrayToHexString(hashedBytes);

    // register the user in the database
    // this code assumes you have a connection to your database and a method to insert data
    Connection conn = Database.getConnection();
    PreparedStatement ps = conn.prepareStatement("INSERT INTO users (username, password) VALUES (?, ?)");
    ps.setString(1, username);
    ps.setString(2, hashedPassword);
    ps.executeUpdate();

    ps.close();
    conn.close();
}

private String byteArrayToHexString(byte[] array) {
    StringBuilder sb = new StringBuilder();
    for (byte b : array) {
        sb.append(Integer.toHexString((b & 0xFF) | 0x100).substring(1));
    }
    return sb.toString();
}
