import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.security.KeyFactory;
import java.security.spec.PKCS8EncodedKeySpec;
import java.util.Base64;

public String encrypt(String input, String secretKey) throws Exception {
    Key key = new SecretKeySpec(secretKey.getBytes(), "AES");
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
    byte[] encryptedBytes = null;
    try {
        cipher.init(Cipher.ENCRYPT_MODE, key);
        PKCS8EncodedKeySpec encodedKeySpec = (PKCS8EncodedKeySpec) KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(secretKey.getBytes()));
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(encodedKeySpec.getEncoded(), "AES"));
        byte[] inputBytes = input.getBytes();
        encryptedBytes = cipher.doFinal(inputBytes);
    } finally {
        if (cipher != null) cipher.reset();
    }
    return Base64.getEncoder().encodeToString(encryptedBytes);
}
