import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.List;

public String mergeSegments(List<List<LocalDateTime>> segments) {
    LocalDateTime start = null;
    LocalDateTime end = null;

    for (List<LocalDateTime> segment : segments) {
        LocalDateTime segStart = segment.get(0);
        LocalDateTime segEnd = segment.get(segment.size() - 1);

        if (start == null || start.isBefore(segStart)) {
            start = segStart;
        }
        if (end == null || end.isBefore(segEnd)) {
            end = segEnd;
        }
    }

    return start.atZone(ZoneId.systemDefault()).toLocalDateTime().toString() + "-" +
           end.atZone(ZoneId.systemDefault()).toLocalDateTime().toString();
}

