public long generateNodeId() {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = md.digest(InetAddress.getLocalHost().getHostAddress().getBytes());
        long nodeId = 0;
        for (int i = 3; i < 11; i++) {
            nodeId |= ((long)bytes[i] & 0xFF) << (i * 8);
        }
        return nodeId & 0xFFFFFFFFFFFF0000L;
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
