public static byte[] generateAESKeyAndCipher(int keySize, int paddingScheme) throws Exception {
    KeyGenerator kg = KeyGenerator.getInstance("AES");
    kg.init(new SecureRandom());
    SecretKey secretKey = kg.generateKey();

    Cipher cipher = Cipher.getInstance("AES/" + getPaddingSchemeToString(paddingScheme));
    cipher.init(Cipher.ENCRYPT_MODE, secretKey);

    return new byte[] {secretKey.getEncoded()};
}

private static String getPaddingSchemeToString(int paddingScheme) {
    switch (paddingScheme) {
        case Cipher.PKCS7:
            return "PKCS7";
        case Cipher.ISO_10126:
            return "ISO_10126";
        default:
            throw new Exception("Invalid Padding Scheme");
    }
}

