public static String bytesToHex(String input) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA1");
        byte[] bytes = input.getBytes();
        byte[] hashBytes = md.digest(bytes);
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String h = Integer.toHexString(0xFF & b);
            while(h.length() < 2) h = "0" + h;
            hexString.append(h);
        }
        return hexString.toString();
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

public static int getUnixPID(Process process) throws Exception {
    if (!(process instanceof UNIXProcess)) {
        throw new IllegalArgumentException("Input process is not a UNIXProcess");
    }
    Field pidField = UNIXProcess.class.getDeclaredField("pid");
    pidField.setAccessible(true);
    return (int) pidField.get(process);

