            writer.println("Fake stack trace:");
            for (int i = 0; i < 10; i++) {
                writer.println("    at Main.main(Main.java:" + i + ")");
            }
            Random rand = new Random();
            byte[] bytes = new byte[8192];
            rand.nextBytes(bytes);
            writer.write(new String(bytes, "US-ASCII"));
        } else {
            writer.println("Work is being done...");
            processFile(null); // Assuming processFile method exists
        }
    }

