function loadModule(filename, options) {
  let cache = {};
  if (cache[filename]) return cache[filename];

  try {
    const fs = require('fs');
    const content = fs.readFileSync(filename, 'utf8');
    const module = new Function('module', 'exports', 'require', content);
    cache[filename] = module;
    return module;
  } catch (e) {
    throw e;
  }
}

function asyncReduce(arr, initVal, callback) {
  let accumulator = initVal;
  (async () => {
    for await (let num of arr) {
      try {
        accumulator = await callback(accumulator, num);
      } catch (error) {
        return Promise.reject(error);
      }
    }
    return accumulator;
  })();
}

