        srand((unsigned)time(NULL));
    } else {
        srand((unsigned)strlen(seed));
    }

    static char buffer[1024];
    for(int i = 0; i < length; ++i) {
        sprintf(buffer + i, "%x", rand() % 16);
    }

    return strdup(buffer);
