function generateCss(filePath, stylusFiles, outputDir) {
  const Stylus = require('stylus');
  const fs = require('fs');

  function compileStylus(file) {
    return new Promise((resolve, reject) => {
      const stylusInstance = new Stylus();
      stylusInstance.renderFile(file, (err, css) => {
        if (err) {
          reject(err);
        } else {
          resolve(css.toString());
        }
      });
    });
  }

  function concatenateAndSave(files) {
    return files.reduce((acc, file) => acc + file, '');
  }

  function saveCssToDestination(cssContent, outputDir, filePath) {
    fs.writeFile(`${outputDir}/${filePath}.css`, cssContent, (err) => {
      if (err) {
        console.error(err);
      } else {
        console.log(`CSS file saved to ${outputDir}/${filePath}.css`);
      }
    });
  }

  Promise.all(stylusFiles.map(compileStylus)).then((files) => {
    const concatenatedCss = concatenateAndSave(files);
    saveCssToDestination(concatenatedCss, outputDir, filePath);
  }).catch((err) => console.error(err));
}

