function validateDirectoryTree(fs, dirPath, options) {
  let isValid = true;
  let createDir = options.createDir || false;

  function validate(dirPath) {
    fs.readdir(dirPath, (err, files) => {
      if (err) return;
      files.forEach((file) => {
        const filePath = path.join(dirPath, file);
        fs.stat(filePath, (err, stats) => {
          if (err) {
            if (!createDir) isValid = false;
            else {
              createDir(filePath.substring(0, filePath.lastIndexOf('/')));
              validate(filePath);
            }
          } else if (stats.isDirectory()) {
            validate(filePath);
          }
        });
      });
    });
  }

  validate(dirPath);

  return isValid;

