function calculateLength(buffer, repeat, options) {
  const { groupSeparator, radixPoint } = options;
  let len = buffer.length * repeat;

  if (groupSeparator && radixPoint) {
    // Remove the last separator and point
    while (len > 0 && len % parseInt(radixPoint, 10) !== 0) {
      if (!isNaN(buffer[len - 1])) {
        len -= 1;
      } else {
        break;
      }
    }
  }

  const offset = buffer.length * repeat;

  return [len, offset];
}

