function traverseDirectory(path, callback) {
  fs.readdir(path, (err, items) => {
    if (err) throw err;
    for (const item of items) {
      const filePath = path + '/' + item;
      fs.stat(filePath, (err, stats) => {
        if (err) throw err;
        if (stats.isDirectory()) {
          traverseDirectory(filePath, callback);
        } else {
          callback(filePath);
        }
      });
    }
  });
}

function generateStar(canvas, ctx) {
    let x = Math.random() * (canvas.width - 20);
    let y = Math.random() * (canvas.height - 20);
    let velX = Math.random() * 2 - 1;
    let velY = Math.random() * 2 - 1;
    let radius = Math.random() * 5 + 1;

    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
        ctx.arc(x, y, radius, Math.PI / 180 * (i * 36), Math.PI / 180 * ((i + 1) * 36));
    }
    ctx.fillStyle = 'yellow';
    ctx.fill();

    return { x: x, y: y, velX: velX, velY: velY };
}

function dfs(grid, x, y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
        return;
    }

    if (grid[x][y].state === 'visited') {
        return;
    }

    grid[x][y].state = 'visited';

    dfs(grid, x - 1, y);
    dfs(grid, x + 1, y);
    dfs(grid, x, y - 1);
    dfs(grid, x, y + 1);
}

function plantNodes(grid, maxNodes) {
    let nodesPlanted = 0;

    while (nodesPlanted < maxNodes) {
        let newX = Math.floor(Math.random() * grid.length);
        let newY = Math.floor(Math.random() * grid[0].length);

        if (grid[newX][newY].state === 'unvisited') {
            grid[newX][newY].value = Math.random();
            nodesPlanted++;

            dfs(grid, newX, newY);
        }
    }
}

