  const encryptedMessage = CryptoJS.enc.Utf8.parse(message);
  const encryptionKey = generateUniqueId(16);
  const iv = generateUniqueId(12);
  const encryptedData = AES.encrypt(encryptedMessage, encryptionKey, iv);
  const connection = new WebSocket('ws://localhost:8080');
  connection.send(JSON.stringify({
    uniqueId,
    message: encryptedData.toString(),
  }));
}

