function validateAndCreateFiles(directoryPath, options) {
  const { files = [], directories = [] } = options;
  try {
    for (const file of files) {
      if (!fs.existsSync(`${directoryPath}/${file}`)) {
        fs.writeFileSync(`${directoryPath}/${file}`, '');
      }
    }
    for (const dir of directories) {
      if (!fs.existsSync(`${directoryPath}/${dir}`)) {
        fs.mkdirSync(`${directoryPath}/${dir}`);
      }
    }
  } catch (error) {
    throw error;
  }
}

