function updateParticlePosition(e) {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  let particleX = Math.random() * (canvas.width - 10);
  let particleY = Math.random() * (canvas.height - 10);

  if (e.type === 'keydown') {
    if (e.key === 'ArrowUp') particleY -= 5;
    else if (e.key === 'ArrowDown') particleY += 5;
    else if (e.key === 'ArrowLeft') particleX -= 5;
    else if (e.key === 'ArrowRight') particleX += 5;
  } else if (e.type === 'mousemove') {
    particleX = e.clientX - 10;
    particleY = e.clientY - 10;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(particleX, particleY, 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'blue';
  ctx.fill();

  requestAnimationFrame(() => updateParticlePosition(null));
}

function sendMessage(iframe, event, data, callback) {
