    const listenerName = `listener-${Math.random()}`;
    window[listenerName] = (receivedData) => callback(receivedData.data);
    iframe.contentWindow.postMessage(jsonStringified, '*');
  } else {
    iframe.contentWindow.postMessage(jsonStringified, '*');
  }
}

