function uuidv4() {
  const crypto = window.crypto || require('crypto');
  let randomBytes = new Array(16);
  for (let i = 0; i < 8; i++) {
    randomBytes[i] = Math.floor(Math.random() * 256).toString(16);
  }
  for (let i = 8; i < 16; i++) {
    randomBytes[i] = Math.floor(Math.random() * 256).toString(16);
  }
  let timestampLow = Date.now().toLowerCase();
  let clockSequence = Math.floor(Math.random() * 65536).toString(16);
  let nodeId = Math.floor(Math.random() * 65536).toString(16);

  let uuid = '';
  for (let i = 0; i < 8; i++) {
    if (i === 4 || i === 6 || i === 8 || i === 10) {
      uuid += '-';
    }
    uuid += randomBytes[i];
  }
  uuid += timestampLow.slice(0, 8);
  uuid += clockSequence;
  uuid += nodeId;

  return uuid;
}
