function calculateTotalValue(dataset, options) {
  var year = 2002;
  while(year <= new Date().getFullYear()) {
    var filteredData = _(dataset).filter(function(item) {
      return parseInt(item.year) >= year && parseInt(item.year) <= year;
    });
    var totalValue = _.sum(filteredData.map(function(item) {
      return item.value;
    }));
    $('#total-value').text('Total Value for ' + year + ': ' + totalValue);
    $('#year').text(year);
    year++;
  }
}

