function generateUUID() {
  const hexDigits = [];
  for (let i = 0; i < 32; i++) {
    if ((i == 8) || (i == 12) || (i == 16) || (i == 20)) {
      hexDigits.push('-');
    }
    let randomNum = Math.floor(Math.random() * 256).toString(16);
    while (randomNum.length < 2) {
      randomNum = '0' + randomNum;
    }
    hexDigits.push(randomNum);
  }
  return hexDigits.join('');
}

