import re
def escape_unescape(s, replacements, mode):
    pattern = re.compile(r'([%s])' % '|'.join(re.escape(replacements.keys())))
    if mode == 'escape':
        return pattern.sub(lambda m: '%' + str(len(replacements)) + '0' + str(ord(m.group(1))) , s)
    elif mode == 'unescape':
        return ''.join(replacement if ord(c) - 48 < len(replacements) else c for c, replacement in zip(s, [s[i:i+3] for i in range(0, len(s), 3)]))
