function loadWaveform(url, callback) {
  const xhr = new XMLHttpRequest();
  xhr.open('GET', url, true);
  xhr.responseType = 'text';
  xhr.onload = function() {
    if (xhr.status === 200) {
      const data = JSON.parse(xhr.responseText);
      const realData = new Float32Array(data.samples.length);
      const imagData = new Float32Array(data.samples.length);
      for (let i = 0; i < data.samples.length; i++) {
        realData[i] = data.samples[i].real;
        imagData[i] = data.samples[i].imag;
      }
      callback(realData, imagData);
    } else {
      console.error('Error loading waveform:', xhr.statusText);
    }
  };
  xhr.send();
}

