function makeRequest(url, data, method = 'GET', callback) {
  let options = {
    method: method,
    headers: {'Content-Type': 'application/json'}
  };

  if (method === 'POST') {
    if (!data.secretPhrase) {
      options.method = 'GET';
    } else {
      if (data.account.errorCode === 5) {
        callback({errorCode: 5, message: 'Account error'});
      }
    }
  }

  if (options.method === 'GET') {
    let randomParam = Math.random().toString();
    url += `?random=${randomParam}`;
  }

  fetch(url, options)
    .then(response => response.json())
    .then(data => {
      return data;
    })
