const memo = new Map();

function evaluateFunctions(functions) {
  const results = [];

  functions.forEach((func) => {
    try {
      const result = func(...func.args);
      results.push({ function: func, result });
      memo.set(func.toString(), result);
    } catch (error) {
      console.error(`Error evaluating ${func.name}:`, error);
      results.push({ function: func, result: null });
    }
  });

  return results;
}

