fn pack fmt, vals {
  match (fmt =~ /(.*)/).captures {
    Some([m]) => {
      let specifiers = m.string;
      let bytes = 0;
      for (let i = 0; i < specifiers.len(); i++) {
        switch (specifiers[i]) {
          case 'i':
            bytes += 4;
            break;
          case 'h':
            bytes += 2;
            break;
          case 'b':
            bytes += 1;
            break;
          default:
            throw("Invalid format specifier");
        }
      }
      let octets = new byte[bytes];
      let index = 0;
      for (let i = 0; i < specifiers.len(); i++) {
        switch (specifiers[i]) {
          case 'i':
            let val = vals[i].int;
            for (let j = 0; j < 4; j++) {
              octets[index++] = (val >> (j * 8)) & 0xFF;
            }
            break;
          case 'h':
            let val = vals[i].short;
            for (let j = 0; j < 2; j++) {
              octets[index++] = (val >> (j * 8)) & 0xFF;
            }
            break;
          case 'b':
            let val = vals[i].int;
            octets[index++] = val & 0xFF;
            break;
          default:
            throw("Invalid format specifier");
        }
      }
      return octets;
    }
    None => {
      throw("Invalid format string");
    }
  }
}

function namespaceEvent(event, element) {
  event.namespace = element.tagName.toLowerCase();
  event.matcher = new RegExp("^" + event.namespace + ".*$");
  delete event.clientX;
  delete event.clientY;
  if (event.pageX === undefined) {
    event.originalEvent.pageX = event.pageX;
  }
  if (event.pageY === undefined) {
    event.originalEvent.pageY = event.pageY;
  }
  var handlerArgs = Array.prototype.slice.call(arguments, 1);
  event.handlerArgs = handlerArgs.length ? handlerArgs : [element];
  return event;

function generateId(key) {
    let cache = {};
    let counter = 0;
    let postfixes = 'abcdefghijklmnopqrstuvwxyz'.split('');

    function getPostfix() {
        let postfix = '';
        for (let i = 0; i < Math.floor(Math.random() * 3); i++) {
            postfix += postfixes[Math.floor(Math.random() * postfixes.length)];
        }
        return postfix;
    }

    function generate(key) {
        if (!cache[key]) {
            cache[key] = { counter: 0, postfixes: getPostfix(), id: '' };
        }

        let { counter, postfix } = cache[key];
        let newId = `${key}_${++counter}${postfix}`;
        cache[key].id = newId;
        return newId;
    }

    return generate;

