function updateNavigationMenu() {
  const menuItems = document.querySelectorAll('.menu-item');
  const currentUrl = window.location.pathname;

  menuItems.forEach((menuItem) => {
    menuItem.classList.remove('active');
  });

  menuItems.forEach((menuItem) => {
    const parentMenuItems = Array.prototype.slice.call(menuItem.parentNode.children);

    for (let i = 0; i < parentMenuItems.length; i++) {
      if (parentMenuItems[i].href.includes(currentUrl)) {
        while (i >= 0) {
          parentMenuItems[i].classList.add('active');
          i--;
        }
        return;
      } else if (currentUrl.includes(parentMenuItems[i].href)) {
        parentMenuItems[i].classList.add('active');
        return;
      }
    }
  });
}

