function executeIfVisible(element, callback) {
  if (element.offsetParent) {
    callback();
    if (element.tagName === 'IFRAME') {
      element.src = `${element.src}?api=true`;
      let frame = element.contentWindow;
      frame.postMessage('muteVolume', '*');
      element.width = '';
      element.height = '';
      [element.width, element.height] = [getComputedStyle(element).width, getComputedStyle(element).height].map(c => c.replace('px', ''));
      if (element.tagName === 'IFRAME') {
        let loadEvent = () => console.log('Frame loaded');
        element.addEventListener('load', loadEvent);
        setTimeout(() => {
          element.removeEventListener('load', loadEvent);
        }, 1000);
      }
    }
  }
}

function parseSelector(selector) {
  const combinators = {
    '': 'descendant',
    '+': 'adjacent sibling',
    '>': 'child',
    '~': 'sibling',
    '=': 'attribute equal to',
    '^=': 'attribute starts with',
    '$=': 'attribute ends with',
    '*=': 'attribute contains'
  };

  const selectorParts = selector.trim().split(/\s+|[{}()>~]/);
  let result = {
    type: 'simple',
    value: ''
  };
  let currentSelector = result;

  for (let part of selectorParts) {
    if (!part || part === '') continue;
    if (combinators[part]) {
      currentSelector.type = combinators[part];
      currentSelector.value = '';
    } else if (part.startsWith('[')) {
      currentSelector.type = 'attribute';
      currentSelector.value = part.substring(1, part.length - 1);
    } else {
      currentSelector.type = 'simple';
      currentSelector.value = part;
    }
  }

  return result;
}

function parseJsonString(str) {
  var regex = /^[{}(),:\[\]""';\s0-9a-zA-Z\u00A0-\uD7FF\uD83C-\uD87D\uD8B0-\uD93F]+$/;
  if (!regex.test(str)) {
    throw new Error("Invalid JSON string");
  }
  try {
    return Function('"use strict";return ' + str)(); // JSON.parse(str);
  } catch (e) {
    throw e;
  }
}

