function bench(b) {
  return function() {
    b.tic();
    let start = performance.now();
    for (let i = 0; i < arguments.length; i++) {
      this[i] = arguments[i];
    }
    let result = this[arguments.length - 1].apply(this, Array(arguments.length - 1).fill().map(() => arguments[0]));
    let end = performance.now();
    if (!b.ok(result)) {
      b.end("Benchmark failed: " + JSON.stringify(result));
    } else {
      console.log(`Average time taken for ${arguments.length} iterations: ${(end - start) / arguments.length}ms`);
      b.toc();
    }
  };
}

