function generateStar() {
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    function Star(x, y, vx, vy, radius) {
        this.x = x;
        this.y = y;
        this.vx = vx;
        this.vy = vy;
        this.radius = radius;
    }

    return new Star(
        Math.random() * (canvas.width - 10),
        Math.random() * (canvas.height - 10),
        Math.random() * 2,
        Math.random() * 2,
        Math.floor(Math.random() * 5) + 1
    );

    ctx.beginPath();
    star = generateStar();
    ctx.arc(star.x, star.y, star.radius, 0, 2 * Math.PI);
    ctx.fillStyle = 'white';
    ctx.fill();
}

function generateSessionID(secretKey, length) {
    let randomBytes = crypto.randomBytes(Math.ceil(length / 2));
    let sessionId = '';
    for (let i = 0; i < length; i++) {
        if (i % 2 === 0) {
            sessionId += secretKey.charCodeAt(i % secretKey.length);
        } else {
            sessionId += randomBytes.readInt8(i - Math.floor(length / 2));
        }
    }
    return sessionId.toString('hex').substr(0, length);

