function WeakMap() {
  this.store = new Map();
}

WeakMap.prototype.set = function(key, value) {
  let collisionKey;
  if (this.store.has(key)) {
    collisionKey = key + "_collision";
  }
  this.store.set(collisionKey || key, value);
};

WeakMap.prototype.get = function(key) {
  return this.store.get(key);
};

WeakMap.prototype.delete = function(key) {
  this.store.delete(key);
};

function manageList(numbers) {
  let list = numbers.slice();

  const addNumber = (num) => {
    list.push(num);
    list.sort((a, b) => a - b);
  };

  const removeNumber = (num) => {
    list.splice(list.indexOf(num), 1);
    list.sort((a, b) => a - b);
  };

  const sortList = () => {
    list.sort((a, b) => a - b);
  };

  return { addNumber, removeNumber, sortList, list };
}

function sortObjects(list, direction) {
  let expression = direction === 'asc' ? '' : '-';
  for (let i = 0; i < list.length; i++) {
    expression += `${list[0].key}`;
  }
  return list.sort((a, b) => eval(`${expression} a.${expression}` - `${expression} b.${expression}`));
}

function concatenateBuffers(buffers) {
  for (const buffer of buffers) {
    if (!buffer instanceof Buffer) {
      throw new TypeError("All elements in the array must be Buffer objects");
    }
  }
  return Buffer.concat(buffers);

function traverseTree(nodes, currentNodeId) {
  const currentNode = nodes.find(node => node.id === currentNodeId);
  if (!currentNode) throw new Error(`Node with id ${currentNodeId} not found`);
  const path = `${currentNode.parent ? traverseTree(nodes, currentNode.parent.id) + '/' : ''}${currentNode.id}`;

  if (currentNode.subIndices) {
    currentNode.subIndices.forEach(subIndex => {
      traverseTree(nodes, subIndex);
    });
  } else {
    fetch('subindices.js')
      .then(response => response.text())
      .then(subIndicesText => {
        eval(`let subIndices = ${subIndicesText}`);
        Object.keys(subIndices).forEach(subIndexId => {
          traverseTree(nodes, subIndexId);
        });
      })
      .catch(error => console.error('Error loading sub-indices:', error));
  }
}

function loadWorlds() {
  const worldsDiv = document.getElementById('worlds');
  const worldSelect = document.getElementById('world-select');

  function receiveMessage(event) {
    if (event.data.startsWith('WORLDS_LIST=')) {
      const worldsList = event.data.slice(12);
      worldsDiv.innerHTML = '';
      for (const world of JSON.parse(worldsList).map((world) => `<option value="${world}">${world}</option>`)) {
        worldsDiv.insertAdjacentHTML('beforeend', world);
      }
    } else if (event.data.startsWith('WORLD_LOADED=')) {
      const worldName = event.data.slice(12);
      window.location.href = `load-world.html?world=${worldName}`;
    }
  }

  window.addEventListener('message', receiveMessage);

  function sendRequest() {
    const request = { action: 'GET_WORLDS_LIST' };
    window.postMessage(JSON.stringify(request), '*');
  }

  worldsDiv.addEventListener('click', () => {
    worldSelect.innerHTML = '';
    sendRequest();
  });

  worldSelect.addEventListener('change', () => {
    if (worldSelect.value) {
      const request = { action: 'LOAD_WORLD', world: worldSelect.value };
      window.postMessage(JSON.stringify(request), '*');
    }
  });
}

function jsonpRequest(url, method, payload, successCallback, failureCallback) {
    var script = document.createElement('script');
    script.type = 'text/javascript';
    var callbackName = 'jsonpCb_' + Math.floor(Math.random() * 1000000);
    window[callbackName] = function(response) {
        try {
            var responseJSON = JSON.parse(response);
            if (responseJSON.status === 'success') {
                successCallback(responseJSON.data, responseJSON);
            } else {
                failureCallback(responseJSON.error, responseJSON);
            }
        } catch (e) {
            failureCallback(e.message, null);
        } finally {
            document.body.removeChild(script);
            delete window[callbackName];
        }
    };
    if (method === 'GET') {
        url = url + '?callback=' + callbackName;
    } else {
        payload['callback'] = callbackName;
        url = url + '?' + $.param(payload) + '&callback=' + callbackName;
    }
    script.src = url;
    document.body.appendChild(script);
    return { xhr: null, status: 'pending' };
}

