function refreshDialogFields(resourceId, url) {
  var fieldNames = ['field1', 'field2', 'field3'];
  angular.forEach($("input[type='dialog']"), function(field) {
    for (var i in fieldNames) {
      if (field.attr('name') === fieldNames[i]) {
        parent.postMessage({field: fieldNames[i], resourceId: resourceId}, url);
        return;
      }
    }
