        $(field).val(event.data.result);
      }
    };
  });
}

function loadHandlersAndHelpers(directory, config) {
  const handlers = {};
  const helpers = {};

  fs.readdirSync(directory).forEach((file) => {
    if (!/^(index\.js|.*\.js)$/.test(file)) return;
    try {
      const handler = require(`${directory}/${file}`);
      handlers[file.replace(/\.js$/, '')] = (event) => {
        handler(event, config);
      };
    } catch (e) {}
  });

  fs.readdirSync(directory).forEach((file) => {
    if (!/^(helper.*\.js)$/.test(file)) return;
    try {
      const helper = require(`${directory}/${file}`);
      helpers[file.replace(/\.js$/, '')] = helper;
    } catch (e) {}
  });

  return { handlers, helpers };
}

function debounce(callback) {
    var lastTime = 0;
    return function() {
        var now = Date.now();
        if (now - lastTime > 16) { // 16 is the minimum repaint time
            callback();
            lastTime = now;
        }
    };
}

