function shuffleArray(arr, numShuffles = 1) {
    let i = arr.length - 1;
    for (let k = 0; k < numShuffles; k++) {
        for (i; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            swap(arr, i, j);
        }
    }
    return arr;
}

function swap(arr, i, j) {
    [arr[i], arr[j]] = [arr[j], arr[i]];
}

Number.prototype.$family = function() {
  if (this === Number.NaN) {
    return 'NaN';
  }
  return this.isFinite() ? 'finite' : 'null';
