function map(fn, arr) {
  let result = [];
  for (let i = 0; i < arr.length; i++) {
    let elem = arr[i];
    let mapped = fn(elem);
    if (mapped !== null && mapped !== undefined) {
      result.push(mapped);
    } else if (Array.isArray(elem)) {
      for (let j = 0; j < mapped.length; j++) {
        let subMapped = fn(mapped[j]);
        if (subMapped !== null && subMapped !== undefined) {
          result.push(subMapped);
        }
      }
    }
  }
  return result;

