function reloadCommand(client, commandName) {
  const oldCommand = client.commands.get(commandName);
  if (oldCommand) client.commands.delete(commandName);

  try {
    delete require.cache[require.resolve(`./commands/${commandName}`)];
    const newCommand = require(`../commands/${commandName}`);
    Object.keys(newCommand.aliases).forEach((alias) => {
      oldCommand ? oldCommand.aliases.delete(alias) : null;
      client.commands_aliases.set(`${commandName}_${alias}`, true);
    });
  } catch (error) {
    console.error(`Error reloading command ${commandName}:`, error);
  }

  client.commands.set(commandName, newCommand);
}

function createLodashShortcuts() {
  const originalMethods = {
    isArray: Array.isArray,
    isBoolean: Boolean.prototype.constructor === Boolean,
    isDate: Date.prototype.constructor === Date,
    isError: Error.prototype.constructor === Error,
    isEmpty: Object.create(null),
    isEqual: (a, b) => a === b,
    isFinite: Number.isFinite,
    isNaN: Number.isNaN,
    isNumber: Number.prototype.constructor === Number,
    isObject: Object.prototype.constructor === Object,
    isPlainObject: Object.getPrototypeOf(Object.prototype) === null,
    isRegExp: RegExp.prototype.constructor === RegExp,
    isString: String.prototype.constructor === String,
    isSymbol: Symbol.prototype.constructor === Symbol,
  };

  const constructors = {
    Array: [Array],
    Boolean: [Boolean],
    Date: [Date],
    Error: [Error],
    Function: [Function],
    Number: [Number],
    Object: [Object, Map, Set],
    RegExp: [RegExp],
    String: [String],
    Symbol: [Symbol],
  };

  return function (fn) {
    if (!originalMethods[fn.name]) return fn;

    const lookup = constructors[[fn.prototype].constructor];
    const originalMethod = originalMethods[fn.name];

    return function (...args) {
      if (!lookup.includes(fn.prototype.constructor)) return originalMethod.apply(null, args);
      return fn.apply(null, args);
    };
  };
}

