void printDependencies(Node root, List<String> names, int maxLines) {
    int lines = 0;
    printDependenciesHelper(root, names, 0, maxLines, lines);
}

void printDependenciesHelper(Node node, List<String> names, int depth, int maxLines, int& lines) {
    if (node == null || lines >= maxLines) return;
    for (int i = 0; i < depth; i++) System.out.print("  ");
    if (lines < maxLines) {
        for (String name : names) {
            Node depNode = node.getDep(name);
            if (depNode != null) {
                System.out.println(depNode.getName());
                lines++;
            }
        }
    } else {
        System.out.println("... and " + (maxLines - lines) + " more dependencies.");
    }
    for (Node child : node.getChildren()) {
        printDependenciesHelper(child, names, depth + 1, maxLines, lines);
    }
}

function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function simulateLiveStream() {
  let existingKeys = [];
  const maxKeys = 100;
  let deletedKeys = [];

  function generateKey() {
    let key = Math.floor(Math.random() * (maxKeys + 1));
    while (existingKeys.includes(key) || deletedKeys.includes(key)) {
      key = Math.floor(Math.random() * (maxKeys + 1));
    }
    return key;
  }

  function deleteRandomKey() {
    if (existingKeys.length > 0) {
      let index = Math.floor(Math.random() * existingKeys.length);
      deletedKeys.push(existingKeys.splice(index, 1)[0]);
    }
  }

  setImmediate(() => {
    for (let i = 0; i < maxKeys; i++) {
      existingKeys.push(generateKey());
    }
    setInterval(() => {
      deleteRandomKey();
    }, 1000);
  });
}

