function createGetterSetter(obj) {
  for (const key in obj) {
    const propertyName = key.replace(/_/g, '');
    if (/^set|get/.test(propertyName)) {
      continue;
    }
    if (!/^[a-zA-Z_]+$/.test(propertyName)) {
      return function() {};
    }
    const existingGetter = obj[propertyName];
    if (typeof existingGetter === 'function') {
      return function(value) {
        if (arguments.length > 0) {
          return existingGetter.call(obj, value);
        } else {
          return existingGetter.call(obj);
        }
      };
    }
    obj[propertyName] = function(value) {
      if (arguments.length > 0) {
        this[propertyName] = value;
      } else {
        return this[propertyName];
      }
    };
  }
}

