const fs = require('fs');
const childProcess = require('child_process');

function copyFolder(src, dest) {
  if (!fs.existsSync(dest)) {
    fs.mkdirSync(dest);
  }
  fs.readdirSync(src).forEach(file => {
    const srcPath = `${src}/${file}`;
    const destPath = `${dest}/${file}`;
    if (fs.statSync(srcPath).isDirectory()) {
      copyFolder(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  });
}

function codesignFile(file, identity) {
  try {
    childProcess.exec(`codesign -s ${identity} --force --verbose ${file}`);
  } catch (err) {
    console.error(err);
  }
}

function buildPackage(packageName) {
  try {
    childProcess.exec(`xcodebuild -target ${packageName} -sdk macosx -configuration Release`);
  } catch (err) {
    console.error(err);
  }
}

module.exports = function(options) {
  const { sourceFolder, destinationFolder, identity } = options;

  copyFolder(sourceFolder, destinationFolder);

  fs.readdirSync(destinationFolder).forEach(file => {
    if (fs.statSync(`${destinationFolder}/${file}`).isFile()) {
      codesignFile(`${destinationFolder}/${file}`, identity);
    }
  });

  buildPackage('YourPackage');
};

function processString(input, regexes) {
  let result = input;
  for (let i = 0; i < regexes.length; i++) {
    const regex = new RegExp(regexes[i].regex);
    if (regex.test(result)) {
      if (typeof regexes[i].handler === 'string') {
        eval('with(console) { log(' + regexes[i].handler + ') }');
      } else {
        regexes[i].handler(result);
      }
      result = regex.replace(input, '');
    }
  }
  return result;
}

