const zlib = require('zlib');
const base64 = require('base64-js');

function decodeAndExtractFingerprint(encodedData, callback) {
  const dataBuffer = base64.toByteArray(encodedData);
  zlib.inflate(dataBuffer, (err, buffer) => {
    if (err) {
      callback(err);
      return;
    }
    const asciiHexCodes = buffer.toString('ascii');
    const codeFragments = [];
    let timeOffset = 0;
    for (let i = 0; i < asciiHexCodes.length; i++) {
      if (asciiHexCodes[i] === ' ') {
        codeFragments.push({ start: timeOffset, end: timeOffset });
        timeOffset += 1;
      } else {
        const fragStart = parseInt(asciiHexCodes.substring(i, i + 2), 16);
        const fragEnd = parseInt(asciiHexCodes.substring(i + 2, i + 4), 16);
        codeFragments.push({ start: timeOffset, end: fragStart });
        timeOffset += fragStart;
        codeFragments.push({ start: fragStart, end: fragEnd });
        timeOffset += fragEnd - fragStart;
      }
    }
    callback(null, { codeFragments, timeOffsets: [] }); // timeOffsets is not used in this example
  });
}
```
This function first decodes the base64-encoded string using `base64-js`. Then it decompresses the resulting binary buffer using `zlib.inflate`. The decompressed data is then converted to an ASCII string.

The ASCII string is then processed to extract code fragments and time offsets. Each code fragment is a pair of hexadecimal values, with the first value being the start of the fragment and the second value being the end. Time offsets are simply incremented by one for each whitespace character in the ASCII string.

Finally, the function calls the callback function with a fingerprint object containing the list of code fragments and time offsets as its properties.

