function compileFragment(c, rlo, rhi, ram) {
  // Create a new function to hold the compiled code
  let func = null;

  // Check if the code contains any labels (e.g. "start:", "end:")
  const labels = c.match(/(\w+):/g);
  if (labels && labels.length > 0) {
    // If there are labels, create a new function for each label
    labels.forEach((label) => {
      const labelName = label.replace(':', '');
      func = {
        [labelName]: null,
      };
      c = c.replace(new RegExp(label + ':', 'g'), `func.${labelName}.`);
    });
  }

  // Compile the code using eval()
  try {
    func = new Function(c, rlo, rhi);
  } catch (e) {
    console.error(`Error compiling fragment: ${e}`);
  }

  return func;
}
