function CustomArray(data, offset) {
  this.data = data;
  this.offset = offset || 0;

  Object.defineProperty(this, 'size', {
    get: function() { return this.data.length; },
    enumerable: true
  });

  Object.defineProperty(this, 'dimension', {
    get: function() { return 1; }, // For simplicity, assume all arrays are one-dimensional
    enumerable: true
  });

  Object.defineProperty(this, 'get', {
    value: function(index) {
      if (index < 0 || index >= this.size) throw new RangeError('Index out of bounds');
      return this.data[index + this.offset];
    },
    enumerable: true
  });

  Object.defineProperty(this, 'set', {
    value: function(index, value) {
      if (index < 0 || index >= this.size) throw new RangeError('Index out of bounds');
      this.data[index + this.offset] = value;
    },
    enumerable: true
  };
}

