function createCodeExecutor(code) {
  return (s, k) => {
    return new Promise((resolve, reject) => {
      try {
        const result = eval.call(s, code);
        if (result && typeof result.then === 'function') {
          result.then((value) => resolve(value)).catch((error) => reject(error));
        } else {
          resolve(result);
        }
      } catch (error) {
        reject(error);
      }
    });
  };
}
