function validateProps(props, componentName) {
  const warned = [];

  function getWarning(type, propsKey, message) {
    if (!warned.includes(type)) {
      warned.push(type);
      warning(false, `Invalid prop %s=%s on %s. It seems you may be setting ` +
        'default props upon initialization! This is not recommended because ` +
        'the value of this prop will be frozen. To avoid this, set the default props when rendering this component `%s` instead.`, type,
        JSON.stringify(propsKey, null, 2), componentName);
    }
  }

  function warnForBooleanProp(type) {
    getWarning(type, "dangerouslySetInnerHTML", "Dangerously allowing JSX in a `dangerouslySetInnerHTML` property.");
    getWarning(type, "props", "Setting a prop with the same name as a JSX element.");
  }

  if (process.env.NODE_ENV !== 'production') {
    const treeWalker = require('react-dom/factory').treeWalker;
    const eventPluginsRegistry = require('react-dom/events');

    walkComponentTree(componentName, props);

    function walkComponentTree(name, props) {
      treeWalker.walker((currentNode, ancestorList) => {
        if (currentNode.type === componentName && currentNode.props) {
          for (const prop in currentNode.props) {
            switch (prop) {
              case 'dangerouslySetInnerHTML':
                warnForBooleanProp('dangerouslySetInnerHTML');
                break;
              default:
                walkComponentProps(name, prop);
                break;
            }
          }
        }
      });
    }

    function walkComponentProps(componentName, propName) {
      if (!props[propName]) {
        return;
      }

      switch (propName) {
        case 'dangerouslySetInnerHTML':
          warnForBooleanProp('dangerouslySetInnerHTML');
          break;
        default:
          for (const key in props[propName]) {
            if (typeof props[propName][key] === 'object') {
              walkComponentProps(componentName, key);
            }
          }
      }
    }
  }

  return null;
}

