function parseAction(buffer, offset) {
  const typeOffset = offset + 4;
  const lengthBytes = buffer.slice(offset + 8, offset + 10);
  if (lengthBytes.length !== 2) return { error: "Invalid length field", code: "ERR_LENGTH_FORMAT" };
  const length = parseInt(lengthBytes.toString("hex"), 16);
  if (!isFinite(length)) return { error: "Invalid length value", code: "ERR_LENGTH_VALUE" };
  if (buffer.readUInt32BE(typeOffset) !== 0x1234) return { error: "Unknown action type", code: "ERR_ACTION_TYPE" };
  return { action: buffer.slice(offset, offset + length), length };
}
