function collectStreamData(stream, callback) {
  const data = [];
  let paused = false;
  let resumed = false;

  stream.on('data', (chunk) => {
    if (!paused) {
      data.push(chunk);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    resumed = true;
  });

  stream.on('end', () => {
    if (callback) callback(data.join(''));
  });

  return {
    pause: () => {
      if (!paused && !resumed) {
        stream.pause();
        paused = true;
      }
    },
    resume: () => {
      if (paused && !resumed) {
        stream.resume();
        paused = false;
        resumed = true;
      }
    }
  };
}

