#include <iostream>
#include <vector>
#include <cstdint>

std::vector<uint8_t> concatenateBuffers(const std::vector<std::vector<uint8_t>>& buffers) {
    size_t totalSize = 0;
    for (const auto& buffer : buffers) {
        totalSize += buffer.size();
    }

    if (totalSize > std::numeric_limits<size_t>::max() / sizeof(uint8_t)) {
        throw std::runtime_error("Total buffer size exceeds maximum allowed");
    }

    std::vector<uint8_t> result;
    result.reserve(totalSize);

    for (const auto& buffer : buffers) {
        result.insert(result.end(), buffer.begin(), buffer.end());
    }

    return result;
}
