function createFunction(buffer, depthBuffer, offset, depth, color1, color2, material) {
    const func = new Function('buffer', 'depthBuffer', 'offset', 'depth', 'color1', 'color2', 'material',
        `
            let resultBuffer = buffer;
            let resultDepthBuffer = depthBuffer;

            for (let i = 0; i < offset.length; i++) {
                const x = offset[i][0];
                const y = offset[i][1];

                resultBuffer[y * buffer.length + x] *= material;

                if (depth > 0) {
                    resultDepthBuffer[y * depthBuffer.length + x] += material / depth;
                }

                if (color1 !== color2) {
                    resultBuffer[y * buffer.length + x] = Math.min(Math.max(resultBuffer[y * buffer.length + x], color1), color2);
                }
            }

            return [resultBuffer, resultDepthBuffer];
        `);

    return func;
}

