    window.scrollTo({ top: 0 });
  } else if (hash.match(/^#(\w+)$/) && document.getElementById(hash.replace('#', ''))) {
    const element = document.getElementById(hash.replace('#', ''));
    window.scrollTo({ left: 0, top: element.offsetTop });
  } else if (hash.match(/^#(.*?)$/) && document.querySelector(`[name="${hash.replace('#', '')"}`)) {
    window.scrollTo({ top: 0 });
  }
