function makeDraggableResizable(element) {
  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let startWidth = element.offsetWidth;
  let startHeight = element.offsetHeight;

  function handleMouseDown(event) {
    if (event.target === element || event.target.parentNode === element) {
      isDragging = true;
      startX = event.clientX;
      startY = event.clientY;
    }
  }

  function handleMouseMove(event) {
    if (isDragging) {
      let newX = event.clientX;
      let newY = event.clientY;

      element.style.left = `${newX}px`;
      element.style.top = `${newY}px`;

      isDragging = false;
    }
  }

  function handleMouseUp() {
    isDragging = false;
  }

  function handleResizeMouseDown(event) {
    if (event.target === element.querySelector('.resize-handle')) {
      let direction = event.target.classList.contains('left') ? 'left' : 'right';
      let initialWidth = element.offsetWidth;

      document.addEventListener('mousemove', handleMouseMoveResize);
      document.addEventListener('mouseup', handleMouseUpResize);

      function handleMouseMoveResize(event) {
        let newWidth = initialWidth + (event.clientX - startX);
        element.style.width = `${newWidth}px`;

        if (direction === 'left') {
          element.style.right = `calc(${element.offsetWidth - newWidth}px)`;
        } else {
          element.style.left = `calc(${element.offsetLeft} + ${newWidth}px)`;
        }
      }

      function handleMouseUpResize() {
        document.removeEventListener('mousemove', handleMouseMoveResize);
        document.removeEventListener('mouseup', handleMouseUpResize);
      }
    }
  }

  function handleAlignmentMouseDown(event) {
    if (event.target === element.querySelector('.alignment-handle')) {
      let direction = event.target.classList.contains('left') ? 'left' : 'right';
      let initialWidth = element.offsetWidth;

      document.addEventListener('mousemove', handleMouseMoveAlignment);
      document.addEventListener('mouseup', handleMouseUpAlignment);

      function handleMouseMoveAlignment(event) {
        let newLeft = event.clientX;
        if (direction === 'left') {
          element.style.left = `${newLeft}px`;
        } else {
          element.style.right = `calc(${element.offsetWidth - newLeft}px)`;
        }
      }

      function handleMouseUpAlignment() {
        document.removeEventListener('mousemove', handleMouseMoveAlignment);
        document.removeEventListener('mouseup', handleMouseUpAlignment);
      }
    }
  }

  element.addEventListener('mousedown', handleMouseDown);
  element.querySelector('.resize-handle').addEventListener('mousedown', handleResizeMouseDown);
  element.querySelectorAll('.alignment-handle').forEach(handle => handle.addEventListener('mousedown', handleAlignmentMouseDown));
}

