function validateProps(props, expectedTypes) {
  const propCache = {};

  for (const prop in props) {
    if (!expectedTypes.hasOwnProperty(prop)) {
      console.warn(`Unknown prop '${prop}'`);
      continue;
    }

    if (propCache[prop] === expectedTypes[prop]) {
      continue;
    }

    if (!Object.prototype.hasOwnProperty.call(props, prop) || typeof props[prop] !== expectedTypes[prop].name) {
      console.error(`Invalid type for prop '${prop}': expected ${expectedTypes[prop].name}, got ${typeof props[prop]} (typeof ${JSON.stringify(props[prop])})`);
    }

    propCache[prop] = expectedTypes[prop];
  }
}

