function normalizeURL(url) {
    const components = url.split("/");
    let stack = [];

    for (const component of components) {
        if (component === "") continue;
        if (component === ".") continue;
        if (component === "..") {
            if (stack.length > 0) stack.pop();
            continue;
        }
        stack.push(component);
    }

    return `/` + stack.join("/");
}

