function readI2CBuf(i2c, addr, reg, cb) {
  if (typeof cb === 'function') {
    i2c.readBuffer(addr, reg, (err, buf) => {
      if (err) return cb(err);
      return cb(null, buf);
    });
  } else {
    return new Promise((resolve, reject) => {
      i2c.readBuffer(addr, reg, (err, buf) => {
        if (err) reject(err);
        resolve(buf);
      });
    });
  }
}

