function decodeBuffer(buffer) {
  let result = '';
  for (let i = 0; i < buffer.length; i++) {
    let charCode;
    let charDone = false;
    while (!charDone && i < buffer.length) {
      if (buffer[i] & 128) {
        charCode = (buffer[i] - 256);
        charDone = true;
      } else {
        charCode = buffer[i];
        i++;
        if (i >= buffer.length || !(buffer[i] & 128)) throw new Error('Incomplete character');
        charCode = (charCode << 7) + (buffer[i] - 128);
      }
      result += String.fromCharCode(charCode);
    }
  }
  return result;
}

function analyzeComponent(component) {
  if (!React.isValidElement(component)) return "Not a valid React element";

  let type = component.type;
