  if (type === 'div' || type === 'p') {
    if (props.includes('children')) return "Content component with children";
    else if (props.includes('dangerouslySetInnerHTML')) return "HTML content component";
    else return "Plain text content component";
  } else if (React.isValidElementType(type)) {
    return "Custom content component with custom type: " + type.name;
  } else {
    return "Non-content component: " + type.name;
  }
}

function parseTokens(tokens) {
  const patterns = [
    /foo/, // matches "foo"
    /bar/i, // matches "bar" (case-insensitive)
    /^baz/, // matches "baz" at the start of the string
    /qux$/, // matches "qux" at the end of the string
  ];
  const results = [];

  for (let token of tokens) {
    for (const pattern of patterns) {
      if (pattern.test(token)) {
        results.push(token);
        break;
      }
    }
  }

  return results;

