function copyBytes(chunks, numBytes) {
  let buffer = Buffer.allocUnsafe(Math.ceil(numBytes / 4));
  let offset = 0;
  for (let chunk of chunks) {
    let bytesRemaining = numBytes;
    for (let i = 0; i < chunk.length && bytesRemaining > 0; i++) {
      let start = Math.min(i, numBytes);
      let end = Math.min(start + 4, i + chunk.length);
      buffer.copy(chunk.subarray(i - start, end - start), offset, start, end - start);
      offset += end - start;
      bytesRemaining -= end - start;
    }
  }
  return buffer.slice(0, numBytes);
}

