function bufferToString(buffer) {
  let output = '';
  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];
    if ((byte >= 0x80 && byte <= 0xbf) || (byte >= 0xe0 && byte <= 0xef) || (byte >= 0xf0 && byte <= 0xf4)) {
      output += String.fromCharCode(buffer[i] & ~0xc0 | (buffer[i + 1] >> 6) << 5);
      i++;
    } else if ((byte & 0xe0) == 0xc0) {
      let firstByte = buffer[i];
      let secondByte = buffer[i + 1];
      output += String.fromCharCode((firstByte & 0x1f) << 6 | (secondByte >> 2));
      i++;
    } else if ((byte & 0xf0) == 0xe0) {
      let firstByte = buffer[i];
      let secondByte = buffer[i + 1];
      let thirdByte = buffer[i + 2];
      output += String.fromCharCode(((firstByte & 0x0f) << 12 | (secondByte >> 4)) << 6 | (thirdByte >> 2));
      i += 2;
    } else {
      output += String.fromCharCode(byte);
    }
  }
  return output;
}

