function modifyFile(src_filename, dest_filename, arch) {
  const fs = require('fs');
  const dpkgDeb = require('dpkg-deb');

  if (!fs.existsSync(src_filename)) {
    console.log(`Error: ${src_filename} does not exist`);
    return;
  }

  let fileContent = fs.readFileSync(src_filename, 'utf8').toString();

  fileContent = fileContent.replace('{{version}}', arch);
  fileContent = fileContent.replace('{{arch}}', arch);

  fs.writeFileSync(dest_filename, fileContent, 'utf8');

  if (dpkgDeb) {
    const deb32Name = `${dest_filename}.linux32.deb`;
    const deb64Name = `${dest_filename}.linux64.deb`;

    dpkgDeb.createPackage({
      name: dest_filename,
      version: arch,
      architecture: arch === 'x86_64' ? 'amd64' : 'i386',
      contents: [fileContent],
    }, (err, package1) => {
      if (err) {
        console.log(`Error creating ${dest_filename}.deb: ${err}`);
      } else {
        fs.writeFileSync(deb32Name, package1.data);
        fs.writeFileSync(`${deb64Name}`, package1.data.replace(/i386/, 'amd64'));
      }
    });

    dpkgDeb.createPackage({
      name: `${dest_filename}`,
      version: arch,
      architecture: arch === 'x86_64' ? 'amd64' : 'i386',
      contents: [fileContent],
    }, (err, package2) => {
      if (err) {
        console.log(`Error creating ${dest_filename}.deb: ${err}`);
      } else {
        fs.writeFileSync(deb32Name, package2.data);
        fs.writeFileSync(`${deb64Name}`, package2.data.replace(/i386/, 'amd64'));
      }
    });
  } else {
    console.log('dpkg-deb is not installed');
  }
}

