function parseMetaEvents(stream) {
  let result = [];

  while (stream.length > 0) {
    let eventByte = stream.readUInt8(0);
    stream.shift(1);

    switch (eventByte & 0xF0) {
      case 0x00: // timeSignature
        if (stream.length < 4) throw new Error("Invalid data length");
        let numerator = stream.readUInt8(0);
        let denominator = stream.readUInt8(1);
        let metronome = stream.readUInt8(2);
        let thirtyseconds = stream.readUInt16LE(3);
        result.push({
          subtype: 'timeSignature',
          numerator,
          denominator,
          metronome,
          thirtyseconds
        });
        break;
      case 0x40: // keySignature
        if (stream.length < 3) throw new Error("Invalid data length");
        let key = stream.readUInt8(0);
        let scale = stream.readUInt8(1);
        result.push({
          subtype: 'keySignature',
          key,
          scale
        });
        break;
      case 0x50: // sequencerSpecific
        if (stream.length < 2) throw new Error("Invalid data length");
        let dataSize = stream.readUInt8(0);
        let data = stream.slice(1, 1 + dataSize).toArray('hex');
        result.push({
          subtype: 'sequencerSpecific',
          data
        });
        break;
      default:
        result.push({ subtype: 'unknown', data: stream.toString('hex') });
    }
  }

  return result;
}
