void* copyBuffer(size_t n, void** list) {
    size_t total = 0;
    void* result = Buffer.allocUnsafe(n);
    for (; *list; list++) {
        size_t chunkSize = ((Buffer*)(*list))->length();
        if (total + chunkSize > n) {
            break;
        }
        uint8_t* src = ((Buffer*)(*list))->data();
        uint8_t* dst = (uint8_t*)result + total;
        memcpy(dst, src, chunkSize);
        total += chunkSize;
    }
    return result;

