def get_methods_to_mock(declarations):
    def is_applicable(method):
        if method.name.startswith('_') or not method.is_abstract and not method.is_interface_method:
            return False
        for annotation in method.annotations:
            if annotation.name == 'NotMockable':
                return False
        return True

    methods = []
    for declaration in declarations:
        for method in getattr(declaration, 'methods', []):
            if is_applicable(method):
                methods.append(method)
    return methods

