function determine_mime_type($file_path) {
    $mime_type = null;
    $log_messages = array();

    if (php_uname('s') == 'Linux' || php_uname('s') == 'Darwin') { // Unix-based system
        if (function_exists('finfo_open')) {
            $finfo = finfo_open(FILEINFO_MIME_TYPE);
            $mime_type = finfo_file($finfo, $file_path);
            finfo_close($finfo);
            $log_messages[] = 'File info: ' . $mime_type;
        } else {
            $log_messages[] = 'Fileinfo extension not available.';
        }
    } elseif (php_uname('s') == 'Windows') { // Windows-based system
        $log_messages[] = 'System is Windows, MIME type detection unavailable.';
    } else {
        $log_messages[] = 'Unknown system, cannot determine MIME type.';
    }

    return array('mime_type' => $mime_type, 'log_messages' => $log_messages);
}

