private static string GenerateEncryptionKey(string mode, string key)
{
    int hash = 0;
    foreach (char c in key) { hash ^= (int)c; }
    foreach (char c in mode) { hash ^= (int)c * 31; }
    return ((hash >> 5) | (hash << 27)).ToString("X");
}

