function cacheTaskContent($task, $content = null, $isDownload = false) {
    if (!defined('CACHE_DIR')) {
        throw new Exception('CACHE_DIR is not defined');
    }

    $taskUrl = $task['url'];
    $hash = md5($taskUrl);
    $cachePath = CACHE_DIR . '/' . $hash;

    if ($isDownload) {
        $cachePath .= '/download-' . $hash;
    }

    if (file_exists($cachePath)) {
        return array('path' => $cachePath, 'content' => file_get_contents($cachePath));
    } else {
        if (!$content) {
            throw new Exception('No content provided for caching');
        }
        file_put_contents($cachePath, $content);
        return array('path' => $cachePath, 'content' => $content);
    }
}

