function encrypt_aes_ctr($inputString, $key) {
    if (!extension_loaded('mcrypt')) {
        throw new Exception("MCrypt extension not loaded");
    }
    if (empty($key)) {
        throw new Exception("Key is empty");
    }

    $iv = mcrypt_create_iv(mcrypt_get_block_size(MCRYPT_RIJNDAEL_256), MCRYPT_MODE_CBC);
    $ctrMode = Mcrypt::createIV(mcrypt_get_block_size(MCRYPT_RIJNDAEL_256));
    $encryptedString = mcrypt_encrypt(MCRYPT_RIJNDAEL_256, $key, $inputString, $ctrMode, $iv);
    return base64_encode($iv . $encryptedString);
}
