        $text_height = 12; // assume font size is 12
        $x_position -= $padding;
        $y_position -= floor(($height - $text_height) / 2);
    }

    imagettftext($image, $direction == "horizontal" ? 8 : 12, 0, $x_position, $y_position, $black_color, 'arial.ttf', $text);

    return $image;
}

