function generateBoundary($hashFunction = 'md5') {
    $boundary = '';
    for ($i = 0; $i < 36; $i++) {
        if ($i % 4 == 0) {
            $boundary .= '-';
        }
        $boundary .= chr(ord('a') + (mt_rand(0, 25)));
    }
    $hash = hash($hashFunction, $boundary);
    return substr($hash, 0, 16) . '-' . substr($hash, 16, 16) . '-' . substr($hash, 32, 16) . '-';
}

function getNextChunk($chunkSize, $boundary) {
    $nextChunk = '';
    for ($i = 0; $i < $chunkSize; $i++) {
        if (rand(1, 2) == 1) {
            $nextChunk .= '--';
        } else {
            $nextChunk .= '-'.chr(ord('a') + rand(0, 25));
        }
    }
    return $boundary . $nextChunk . "\r\n";
}
