function ldapQuery($filter, $baseDn) {
    // Sanitize user input
    $filter = filter_var($filter, FILTER_SANITIZE_STRING);
    $baseDn = filter_var($baseDn, FILTER_SANITIZE_STRING);

    // Set up connection to LDAP server
    $ldapServer = 'localhost';
    $ldapPort = 389;
    $ldapUsername = 'your_username';
    $ldapPassword = 'your_password';

    // Connect to LDAP server
    $ldapConnection = ldap_connect($ldapServer, $ldapPort);

    if (!$ldapConnection) {
        return "Failed to connect to LDAP server";
    }

    // Bind to LDAP server
    $bindResult = ldap_bind($ldapConnection, $ldapUsername, $ldapPassword);

    if (!$bindResult) {
        return "Failed to bind to LDAP server";
    }

    // Construct LDAP query
    $ldapFilter = '(&(uid=' . $filter . '))';
    $ldapQuery = '(&' . $ldapFilter . ')';

    // Execute LDAP query and retrieve results
    $result = ldap_search($ldapConnection, $baseDn, $ldapQuery);

    if (!$result) {
        return "Failed to execute LDAP query";
    }

    // Convert LDAP result to array
    $entries = ldap_get_entries($ldapConnection, $result);
    $users = array();

    for ($i = 0; $i < $entries['count'][0]; $i++) {
        if (isset($entries[$i]['uid'])) {
            $users[] = $entries[$i]['uid'];
        }
    }

    // Free LDAP resources
    ldap_free_result($result);
    ldap_close($ldapConnection);

    return $users;
}

