function execute_query($query) {
    $mysqli = new mysqli('localhost', 'username', 'password', 'database');
    if ($mysqli->connect_error) {
        die('Connect Error: ' . $mysqli->connect_error);
    }
    $query_parts = explode(' ', $query);
    $table_name = $query_parts[3];
    if (strtok($query, 'UPDATE ') === 'UPDATE') {
        $values = array();
        foreach (explode(', ', substr($query, 9)) as $column) {
            list($value) = explode('=', trim($column));
            $values[$value] = $mysqli->real_escape_string($_POST[$value]);
        }
        $query = "UPDATE $table_name SET " . implode(", ", array_map(function ($k) use (&$values) { return "$k = '$values[$k]'"; }, array_keys($values))) . ";";
    } elseif (strtok($query, 'INSERT ') === 'INSERT') {
        $values = array();
        foreach (explode(', ', substr($query, 8)) as $column) {
            list($value) = explode(' INTO ', trim($column));
            $values[] = $mysqli->real_escape_string($value);
        }
        $query = "INSERT INTO $table_name VALUES (" . implode(", ", array_map(function ($v) { return "'$v'"; }, $values)) . ");";
    } else {
        die('Invalid query');
    }
    if (! $mysqli->query($query)) {
        die('Query Error: ' . $mysqli->error);
