function addConversationFromfile($entity, $botDir) {
    $conversations = new Conversation($botDir);
    if ($conversations->hasMemoryFile()) {
        $conversations->loadMemory();
    }
    $conversationFile = $conversations->loadConversationFile($entity);
    return $conversations->mergeConversations($conversations->getCurrent(), $conversationFile);
}

class Conversation {
    private $botDir;
    private $memory;

    public function __construct($botDir) {
        $this->botDir = $botDir;
    }

    public function hasMemoryFile() {
        return file_exists($this->botDir . '/memory.txt');
    }

    public function loadMemory() {
        $this->memory = unserialize(file_get_contents($this->botDir . '/memory.txt'));
    }

    public function getCurrent() {
        return empty($this->memory) ? array() : $this->memory;
    }

    public function mergeConversations($current, $conversationFile) {
        $conversations = unserialize(file_get_contents($this->botDir . '/' . $conversationFile));
        if (!empty($conversations)) {
            $current[] = $conversations;
        }
        return $current;
    }

    public function loadConversationFile($entity) {
        $files = scandir($this->botDir);
        foreach ($files as $file) {
            if (strpos($file, $entity . '.txt') !== false) {
                return $file;
            }
        }
        return null;
    }
}

