function updatePassword($user_id, $new_password, $confirm_password, $return_url) {
  $db = mysqli_connect("localhost", "username", "password", "database");
  if (!$db) {
    die('Error connecting to database: ' . mysql_error());
  }

  // Validate new password and confirmation
  if ($new_password != $confirm_password) {
    header('Location: /error');
    exit;
  }

  // Encrypt the new password
  $new_password = md5($new_password);

  // Update user's password in database
  $query = "UPDATE users SET password='$new_password' WHERE id=$user_id";
  mysqli_query($db, $query);
  if (mysqli_errno($db)) {
    header('Location: /error');
    exit;
  }

  // Reset force password reset flag
  $query = "UPDATE users SET force_password_reset=0 WHERE id=$user_id";
  mysqli_query($db, $query);
  if (mysqli_errno($db)) {
    header('Location: /error');
    exit;
  }

  // Redirect to success message or specified return URL
  header('Location: ' . $return_url);
  exit;
}
