CREATE OR REPLACE FUNCTION limit_query(p_query IN VARCHAR2, p_limit IN NUMBER, p_offset IN NUMBER DEFAULT 0)
RETURN SYS_REFCURSOR AS
l_sql_query VARCHAR2(4000);
BEGIN
  l_sql_query := 'SELECT ' || p_query || ' FROM DUAL';
  IF p_limit > 0 THEN
    l_sql_query := 'ALTER SESSION SET NLS_DATE_FORMAT=''YYYY-MM-DD HH24:MI:SS''; SELECT * FROM (' || l_sql_query || ') WHERE ROWNUM <= :1 OFFSET :2 ORDER BY NULL' USING p_limit, p_offset;
  ELSE
    l_sql_query := 'ALTER SESSION SET NLS_DATE_FORMAT=''YYYY-MM-DD HH24:MI:SS''; SELECT * FROM (' || l_sql_query || ') ORDER BY NULL';
  END IF;
  RETURN SYS_REFCURSOR(l_sql_query);
END limit_query;

