public function hashWhereClause($where, $value) {
  if (!is_null($value)) {
    $paramName = hash('sha1', $value);
    $this->whereClauses[] = sprintf('%s==:%s', $where, $paramName);
    $this->$paramName = $value;
  } else {
    $this->whereClauses[] = $where;
  }
  return $this;
}

