import hashlib
from functools import lru_cache

@lru_cache(maxsize=None)
def generate_url(name: str, params: list, absolute: bool) -> str:
    context = {'absolute': absolute}
    key = f"{name}{'-'.join(map(str, params))}{hashlib.sha256(str(context).encode()).hexdigest()}"
    if not (url := cache.get(key)):
        url = f"/{name}/" + '/'.join(f"{k}={v}" for k, v in zip(['param1', 'param2'], params))
        if absolute:
            url = "https://" + url
        cache.set(key, url)
    return url

function getSettings($userId, $tableName) {
    $settings = array();
    $query = "SELECT * FROM `user_settings` WHERE `user_id` = '$userId' AND `table_name` = '$tableName'";
    $result = mysql_query($query);
    while ($row = mysql_fetch_assoc($result)) {
        foreach ($row as $key => $value) {
            if (strlen($key) > 4 && substr($key, -4) == '_bool') {
                $settings[$key] = $value;
            }
        }
    }
    return $settings;
}

