function optimizeFulltextIndex($indexDir) {
    if (debug_mode()) {
        echo "Checking for invalid entries in fulltext index...\n";
    }
    system("find $indexDir -type d | while read dir; do ft_stat --errors-only "$dir"; done", $return);

    if ($return != 0) {
        if (debug_mode()) {
            echo "Optimizing fulltext index...\n";
        }
        system("sudo find $indexDir -type d | while read dir; do ft_optimize "$dir"; done", $return);
    }
}

