function generateQuiz($username, $quizTitle, $questions) {
  // Generate unique identifier for quiz
  $uniqueId = uniqid();

  // Connect to database
  $db = new mysqli('localhost', 'username', 'password', 'database');

  // Check connection
  if ($db->connect_error) {
    die("Connection failed: " . $db->connect_error);
  }

  // Create query to store user input and quiz information in database
  $query = "INSERT INTO quizzes (user, title, uniqueId) VALUES ('$username', '$quizTitle', '$uniqueId')";
  if ($db->query($query)) {
    // Loop through questions and store answers in database
    foreach ($questions as $question => $answer) {
      $query = "INSERT INTO quizAnswers (quizId, question, answer) VALUES ((SELECT id FROM quizzes WHERE uniqueId='$uniqueId'), '$question', '$answer')";
      if (!$db->query($query)) {
        die("Error inserting answers: " . $db->error);
      }
    }

    // Set cookie to remember user's progress
    setcookie('quizProgress', json_encode(['quizId' => $uniqueId, 'answers' => $questions]));
  } else {
    die("Error inserting quiz: " . $db->error);
  }

  // Close database connection
  $db->close();
}

