function ssh_exec($host, $username, $password) {
    $ssh = ssh2_connect($host, 22);
    if (!ssh2_auth_password($ssh, $username, $password)) {
        return false;
    }
    $stream = ssh2_exec($ssh, 'pwd');
    stream_set_blocking($stream);
    $result = '';
    while ($chunk = fread($stream, 5120)) {
        $result .= $chunk;
    }
    fclose($stream);
    return $result;
}

