function initMemcached($config) {
    $memcached = new Memcached();
    if (!isset($config['save_path'])) {
        error_log('Error: save path not configured');
    }
    $sanitizedSavePath = str_replace(array('\\', '/'), '', $config['save_path']);
    $memcached->setOption(Memcached::OPT_COMPRESSION, true);
    $memcached->setOption(Memcached::OPT_BINARY_PROTOCOL, true);
    $memcached->setOption(Memcached::OPT_NO_DELAY_TIMEOUT, 0);
    if (isset($config['ip_match']) && $config['ip_match']) {
        $memcached->setOption(Memcached::OPT_COMPRESS_DATA, false);
        $memcached->setOption(Memcached::OPT_REMOVE_OPTIONAL_FEATURES, true);
        foreach ($memcached->getServers() as $server) {
            $server->setRemoteAddressPrefix(function($addr) {
                return 'remote_addr_' . bin2hex($addr) . '_';
            });
        }
    }
    return $memcached;
}
