function processPostRequest() {
    if ($_SERVER['REQUEST_METHOD'] == 'POST') {
        $db = mysqli_connect('localhost', 'username', 'password', 'database');
        if (!$db) {
            echo "Error connecting to database";
            exit;
        }

        // Sanitize input data
        $sanitized_data = array();
        foreach ($_POST as $key => $value) {
            $sanitized_data[$key] = mysqli_real_escape_string($db, $value);
        }

        // Insert data into table
        $query = "INSERT INTO table_name (column1, column2, ...) VALUES ('" . implode("', '", $sanitized_data) . "')";
        if (!mysqli_query($db, $query)) {
            echo "Error inserting data";
            exit;
        }

        // Log user's IP address and browser information
        $ip_address = $_SERVER['REMOTE_ADDR'];
        $browser_info = array('user_agent' => $_SERVER['HTTP_USER_AGENT'], 'accept_language' => $_SERVER['HTTP_ACCEPT_LANGUAGE']);

        // Insert log data into table
        $log_query = "INSERT INTO logs (ip_address, browser_info) VALUES ('$ip_address', '" . json_encode($browser_info) . "')";
        if (!mysqli_query($db, $log_query)) {
            echo "Error logging user's information";
            exit;
        }

        // Return success message
        echo "Data successfully inserted!";
    } else {
        echo "Invalid request method";
    }
}

