function validateFormData() {
  $isValid = true;
  $maxFileSize = 1024 * 1024; // 1MB
  $allowedExtensions = array('jpg', 'jpeg', 'png', 'gif');

  if(empty($_POST)) {
    $isValid = false;
  }

  foreach ($_FILES as $file) {
    if($file['error'] > 0) {
      $isValid = false;
    }
    elseif($file['size'] > $maxFileSize) {
      $isValid = false;
    }
    elseif(!in_array(strtolower(substr(strrchr($file['name'], '.'), 1)), $allowedExtensions)) {
      $isValid = false;
    }
  }

  return $isValid;
}

