function executeShellCommand($command, $logFile, $outputModifiers = []) {
    $output = shell_exec($command);
    $logData = "Command: $command\nOutput: $output\n";

    if (file_put_contents($logFile, $logData, FILE_APPEND)) {
        // Output modifiers
        foreach ($outputModifiers as $modifier => $value) {
            switch ($modifier) {
                case 'trim':
                    $output = trim($output);
                    break;
                case 'stripTags':
                    $output = strip_tags($output);
                    break;
                case 'lowercase':
                    $output = strtolower($output);
                    break;
                case 'uppercase':
                    $output = strtoupper($output);
                    break;
            }
        }
    } else {
        // Error logging
        error_log("Error writing to log file: $logFile");
    }

    return $output;
}

