function process_login($db) {
  if (isset($_POST['submit'])) {
    $email = $_POST['email'];
    $password = $_POST['password'];

    // Validate password
    if (!preg_match('/^[a-zA-Z0-9]+$/', $password)) {
      header('Location: login.php?error=Invalid%20password');
      exit;
    }

    // Check if user exists in database
    $query = "SELECT * FROM users WHERE email = '$email'";
    $result = $db->query($query);
    $user = $result->fetch_assoc();

    if ($user) {
      // User exists, check password
      if (password_verify($password, $user['password'])) {
        // Valid login, create session and redirect to welcome page
        session_start();
        $_SESSION['user'] = $user;
        header('Location: welcome.php');
        exit;
      } else {
        // Invalid password, display error message
        header('Location: login.php?error=Invalid%20password');
        exit;
      }
    } else {
      // User does not exist, create new user and redirect to login page
      $new_user = array(
        'email' => $email,
        'password' => password_hash($password, PASSWORD_DEFAULT)
      );
      $db->query("INSERT INTO users SET email = '$email', password = '$password'");
      header('Location: login.php?message=New%20account%20created');
      exit;
    }
  }
}

