function deleteContentElement($databaseConnection, $idToDelete) {
    // Get all content elements
    $query = "SELECT id, position FROM content_elements";
    $result = mysqli_query($databaseConnection, $query);

    // Store current positions in an array for future reference
    $currentPositions = array();
    while ($row = mysqli_fetch_assoc($result)) {
        $currentPositions[$row['id']] = $row['position'];
    }
    mysqli_free_result($result);

    // Update position of all elements greater than the one to be deleted
    $query = "UPDATE content_elements SET position = (SELECT position FROM content_elements WHERE id = ?) + 1 WHERE id > ?";
    foreach ($currentPositions as $id => $position) {
        if ($id > $idToDelete) {
            mysqli_prepare($databaseConnection, $query);
            mysqli_stmt_bind_param($databaseConnection, 'ii', $idToDelete, $id);
            mysqli_stmt_execute($databaseConnection);
        }
    }

    // Delete the content element
    $query = "DELETE FROM content_elements WHERE id = ?";
    mysqli_prepare($databaseConnection, $query);
    mysqli_stmt_bind_param($databaseConnection, 'i', $idToDelete);
    mysqli_stmt_execute($databaseConnection);

    return;
}

