function add_user_input($username, $password, $verification_code) {
  // Database connection
  $db = mysqli_connect("localhost", "user", "pass", "database");

  // Validate input
  if (!isset($username) || !isset($password)) {
    return "Error: Missing required fields";
  }
  if (strlen($username) < 3 || strlen($username) > 20) {
    return "Error: Username must be between 3 and 20 characters";
  }
  if (strlen($password) < 8 || strlen($password) > 32) {
    return "Error: Password must be between 8 and 32 characters";
  }
  if ($verification_code != "my_secret_verification_code") {
    return "Error: Invalid verification code";
  }

  // Add input to database
  $query = "INSERT INTO users (username, password) VALUES ('$username', '$password')";
  mysqli_query($db, $query);
  return "Success: User added!";
}
