function createInteractiveMap(locations) {
  const map = new google.maps.Map(document.getElementById('map'), {
    center: { lat: 37.09024, lng: -95.71289 },
    zoom: 4
  });

  const markerOptions = {
    icon: 'https://maps.google.com/mapfiles/kml/polygons_regular_13.png',
    labelOrigin: new google.maps.Point(0, -10)
  };

  let categories = {};
  locations.forEach(location => {
    if (!categories[location.category]) {
      categories[location.category] = [];
    }
    categories[location.category].push({
      lat: location.lat,
      lng: location.lng
    });
  });

  const categoryMenu = document.getElementById('category-menu');
  Object.keys(categories).forEach(category => {
    const option = document.createElement('option');
    option.text = category;
    option.value = category;
    categoryMenu.appendChild(option);
  });

  let selectedCategory;

  categoryMenu.addEventListener('change', () => {
    selectedCategory = categoryMenu.options[categoryMenu.selectedIndex].value;
    map.clear();
    categories[selectedCategory].forEach(location => {
      const marker = new google.maps.Marker({
        position: location,
        map: map,
        ...markerOptions
      });
    });
  });

  categories['default'].forEach(location => {
    const marker = new google.maps.Marker({
      position: location,
      map: map,
      ...markerOptions
    });
  });
}

