        throw new RuntimeException("All parameters are required");
    }

    String nonceStr = UUID.randomUUID().toString();

    // calculate the digital signature
    String digitalSignature = digitalSign(appid, mch_id, spbill_create_ip, sign, trade_type, notify_url, openid);

    StringBuilder xmlStringBuilder = new StringBuilder("<xml><appid>" + appid + "</appid><mch_id>" + mch_id + "</mch_id><spbill_create_ip>" + spbill_create_ip + "</spbill_create_ip><nonce_str>" + nonceStr + "</nonce_str><sign>" + sign + "</sign><trade_type>" + trade_type + "</trade_type><notify_url>" + notify_url + "</notify_url><openid>" + openid + "</openid><digital_signature>" + digitalSignature + "</digital_signature></xml>");

    return xmlStringBuilder.toString();
}
