function pingback($url) {
    $ip = gethostbyaddr(gethostbyname(parse_url($url, PHP_URL_HOST)));
    $userAgent = 'Pingback/1.0';
    $pinged = false;

    if(file_get_contents($url . '/pingback')) {
        $response = json_decode(file_get_contents($url . '/pingbacks.json'), true);
        foreach($response as $item) {
            if($item['url'] == $url && $item['ip'] == $ip && $item['userAgent'] == $userAgent) {
                $pinged = true;
                break;
            }
        }
    } else {
        return 'Remote URL does not exist or is not pingback-enabled.';
    }

    if($pinged) {
        return 'Pingback already exists for this URL and IP.';
    }

    sleep(1);
    $ch = curl_init($url . '/pingbacks.json');
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_USERAGENT, $userAgent);
    $response = curl_exec($ch);
    if(curl_errno($ch)) {
        return 'cURL error: ' . curl_error($ch);
    }
    curl_close($ch);

    $data = json_decode($response, true);
    $data[] = array('url' => $url, 'ip' => $ip, 'userAgent' => $userAgent);
    file_put_contents($url . '/pingbacks.json', json_encode($data));
}

