function handleUserRequest() {
  $response = array('message' => 'error');

  if (!isset($_REQUEST['sub_action']) || !in_array($_REQUEST['sub_action'], array('create', 'update', 'delete'))) {
    return json_encode($response);
  }

  switch ($_REQUEST['sub_action']) {
    case 'create':
      $user = array();
      if (empty($_REQUEST['id'])) {
        $user['name'] = $_REQUEST['name'];
        $user['email'] = $_REQUEST['email'];
        $user['password'] = $_REQUEST['password'];

        if (!Validate($user)) {
          return json_encode($response);
        }

        Save($user);

        $response['message'] = 'success';
      } else {
        $user = Get($_REQUEST['id']);

        if (!$user) {
          return json_encode($response);
        }

        $user['name'] = $_REQUEST['name'];
        $user['email'] = $_REQUEST['email'];
        $user['password'] = $_REQUEST['password'];

        if (!Validate($user)) {
          return json_encode($response);
        }

        Save($user);

        $response['message'] = 'success';
      }
      break;
    case 'update':
      $user = array();

      if (empty($_REQUEST['id'])) {
        $response['message'] = 'error';
      } else {
        $user = Get($_REQUEST['id']);

        if (!$user) {
          $response['message'] = 'error';
        } else {
          $user['name'] = $_REQUEST['name'];
          $user['email'] = $_REQUEST['email'];
          $user['password'] = $_REQUEST['password'];

          if (!Validate($user)) {
            $response['message'] = 'error';
          } else {
            Save($user);

            $response['message'] = 'success';
          }
        }
      }
      break;
    case 'delete':
      if (empty($_REQUEST['id'])) {
        $response['message'] = 'error';
      } else {
        Delete($_REQUEST['id']);

        $response['message'] = 'success';
      }
      break;
  }

  return json_encode($response);
}

