function logExecutionInfo($logToFile = true) {
    $startMemoryUsage = memory_get_usage(true);
    $startExecutionTime = microtime(true);

    ob_start();
    include('script_to_execute.php');
    $executionOutput = ob_get_contents();
    ob_end_clean();

    $endExecutionTime = microtime(true);
    $endMemoryUsage = memory_get_usage(true);

    $logInfo = "Script execution info:\n";
    $logInfo .= "Start time: ".date("Y-m-d H:i:s", $startExecutionTime)."\n";
    $logInfo .= "End time: ".date("Y-m-d H:i:s", $endExecutionTime)."\n";
    $logInfo .= "Memory usage (start): ".round($startMemoryUsage/1024/1024, 2)." MB\n";
    $logInfo .= "Memory usage (end): ".round($endMemoryUsage/1024/1024, 2)." MB\n";
    $logInfo .= "Execution time: ".number_format($endExecutionTime - $startExecutionTime, 6)." seconds\n";
    $logInfo .= "Environment variables:\n";
    foreach ($_ENV as $key => $value) {
        $logInfo .= "$key: $value\n";
    }
    $logInfo .= "Script execution output:\n".$executionOutput;

    if($logToFile) {
        file_put_contents('script_execution.log', $logInfo);
    } else {
        echo $logInfo;
    }
}
