function generateSlug($title, $url) {
    $slug = preg_replace('/[^a-zA-Z0-9_\-]/', '', strtolower(trim($title)));
    if (empty($slug)) {
        $slug = 'Untitled';
    }
    while(file_exists($url . '/' . $slug . '.php')) {
        $slug .= '_';
    }
    return $slug;
}

function processSlug($slug, $url) {
    $errors = array();
    if (strlen($slug) > 50) {
        $errors[] = 'Slug too long. Maximum length is 50 characters.';
    }
    if (!preg_match('/^[a-zA-Z0-9_\-]+$/', $slug)) {
        $errors[] = 'Invalid slug characters. Only a-z, A-Z, numbers, and underscores are allowed.';
    }
    if ($errors) {
        header('Location: ' . $url);
        exit;
    } else {
        header('Location: ' . $url . '/' . $slug . '.php');
        exit;
    }
}
