    usort($leaseRecords, function($a, $b) use ($sortField) {
        if (isset($a->$sortField) && isset($b->$sortField)) {
            return strcasecmp($a->$sortField, $b->$sortField);
        }
        throw new Exception("'$sortField' field not found in lease records");
    });
    file_put_contents('lease_records.txt', json_encode($leaseRecords));
    exec('service ' . $serviceName . ' restart');
}

