function createAccount($username, $email, $pass) {
    require_once 'dbconfig.php';

    $stmt = $conn->prepare("SELECT * FROM users WHERE username = :username OR email = :email");
    $stmt->execute([':username' => $username, ':email' => $email]);

    if ($stmt->rowCount() > 0) {
        return "Username or email already in use";
    }

    if (strlen($pass) < 6) {
        return "Password must be at least 6 characters long";
    }

    $stmt = $conn->prepare("INSERT INTO users SET username = :username, email = :email, password = :password");
    $stmt->execute([':username' => $username, ':email' => $email, ':password' => password_hash($pass, PASSWORD_DEFAULT)]);

    if ($stmt->rowCount() === 0) {
        return "Error creating account";
    } else {
        return 'Success';
    }
}

function startNewSession() {
    $session_id = session_create_id();
    session_start();
    $token = hash('sha1', serialize($session_id));
    $_SESSION['token'] = $token;
    if (!isset($_SESSION['count'])) {
        $_SESSION['count'] = 0;
    }
    $_SESSION['count']++;
    return $session_id;
}

