function getPlacesNear($location, $page) {
    $apiKey = 'YOUR_API_KEY';
    $url = 'https://maps.googleapis.com/maps/api/place/nearbysearch/json?';
    $params = array(
        'location' => $location,
        'radius' => 1000,
        'key' => $apiKey
    );
    if ($page > 1) {
        $params['pagetoken'] = file_get_contents('https://maps.googleapis.com/maps/api/place/nearbysearch/json?'.http_build_query(array(
            'location' => $location,
            'radius' => 1000,
            'key' => $apiKey
        )));
    }
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($params));
    $response = json_decode(curl_exec($ch), true);
    if (isset($response['results'])) {
        $places = array();
        foreach ($response['results'] as $place) {
            $places[] = array(
                'name' => $place['name'],
                'vicinity' => $place['vicinity']
            );
        }
        return json_encode(array('places' => $places));
    } else {
        return json_encode(array());
    }
}
