function createMockClass($className, $interfaces = []) {
    $mockClassName = 'Mock' . ucfirst($className);
    eval('class ' . $mockClassName . ' extends ' . $className . ' { ' .
        implode("\n     ", array_map(function ($interface) use ($mockClassName) {
            return "use " . $interface . ";";
        }, $interfaces)) . '
        public function __construct() {}
        public function __get($name) {}
        public function __set($name, $value) {}
    }');

    return \Phake\MockBuilder::new($mockClassName);
}

