function handle_login($get_params, $post_params) {
  if (isset($get_params['checklogin'])) {
    if (is_authenticated()) {
      header('Location: ' . $_GET['redirect'] . (count($_GET) > 1 ? '?' . http_build_query(array_diff_key($_GET, array_flip(array('checklogin', 'redirect')))) : ''), true, 302);
      exit;
    }
  }

  if (isset($post_params['email']) && isset($post_params['password'])) {
    $user = authenticate($post_params['email'], $post_params['password']);

    if ($user) {
      $_GET['redirect'] .= '?' . http_build_query(array('checklogin' => 'true'));
      header('Location: ' . $_GET['redirect'], true, 302);
      exit;
    } else {
      return 'Invalid email or password';
    }
  }
}
