public static function updatePassword($username, $oldPassword, $newPassword) {
    require_once 'DAO.php';

    try {
        $dao = new DAO();

        // Check if the old password is correct
        $user = $dao->getUserByUsername($username);
        if (!password_verify($oldPassword, $user['password'])) {
            throw new Exception("Old password is incorrect");
        }

        // Validate the new password strength
        if (strlen($newPassword) < 8 || !preg_match('/[a-z]/', $newPassword) || !preg_match('/[A-Z]/', $newPassword) || !preg_match('/[0-9]/', $newPassword)) {
            throw new Exception("New password is too weak");
        }

        // Update the user's password
        $dao->updateUser($username, array('password' => password_hash($newPassword, PASSWORD_DEFAULT)));
    } catch (Exception $e) {
        echo 'Error: ' . $e->getMessage();
    }
}
