function get_user_id($cookie_name = 'user_id', $cookie_type = 'cookie') {
    if ($cookie_type == 'cookie') {
        if (!isset($_COOKIE[$cookie_name])) {
            $cookie_type = 'session';
        }
    } elseif ($cookie_type == 'session') {
        if (!isset($_SESSION[$cookie_name])) {
            return 1;
        }
    }

    if ($cookie_type == 'cookie') {
        return (int) $_COOKIE[$cookie_name];
    } else {
        return (int) $_SESSION[$cookie_name];
    }
}

