function db_insert($db_conn, $table_name, $column_names, $values) {
    if (!isset($values['password'])) {
        $hashed_password = null;
    } else {
        $hashed_password = password_hash($values['password'], PASSWORD_DEFAULT);
        unset($values['password']);
    }

    $columns = implode(', ', array_keys($column_names));
    $values = array_values($values);
    $quoted_values = array_map(function($value) use ($db_conn) {
        return "'" . $db_conn->real_escape_string($value) . "'";
    }, $values);
    $values_str = implode(', ', $quoted_values);

    if (isset($hashed_password)) {
        $values[$column_names['password']] = $hashed_password;
        unset($column_names['password']);
        $columns = implode(', ', array_keys($column_names));
    }

    $sql = "INSERT INTO `$table_name` (`$columns`) VALUES ($values_str)";

    if (!$stmt = $db_conn->prepare($sql)) {
        return array(false, null);
    }

    $bind_types = [];
    foreach ($values as $value) {
        $bind_types[] = '?';
    }
    $stmt->execute(array_merge($column_names, $values));
    $result = $stmt->affected_rows;
    if (!empty($hashed_password)) {
        return array(true, $db_conn->insert_id);
    } else {
        return array(true, $db_conn->insert_id);
    }
}
