function handleRequest() {
    try {
        $server = array('port' => 8080);
        set_time_limit(300);
        ignore_user_abort(true);

        if (!isset($_SERVER['REMOTE_ADDR'])) {
            throw new Exception("No client connection");
        }

        $sock = socket_accept($GLOBALS['_socket']);
        if (!$sock) {
            throw new Exception("Failed to accept connection");
        }

        $ip = socket_getpeername($sock, PHP_SOCKADDR);
        $remotePort = socket_getsockname($sock, PHP_SOCKPORT);

        socket_set_non_block($sock);

        ini_set('max_execution_time', 300);
        set_time_limit(300);

        include 'config.php';

        $data = array('message' => 'Hello from the server');
        socket_write($sock, json_encode($data), strlen(json_encode($data)));
    } catch (Exception $e) {
        error_log("Error: " . $e->getMessage());
        @socket_close($GLOBALS['_socket']);
        exit;
    }
}

