    def add_factory(cls, id, factory):
        cls.registry[id] = factory

    @classmethod
    def from_json(cls, json_string):
        import json
        data = json.loads(json_string)
        return cls.create_instance(data)

    @classmethod
    def to_json(cls, obj):
        import json
        return json.dumps(obj.__dict__)

    @classmethod
    def create_instance(cls, data):
        id = data.get('class')
        if not id:
            raise ValueError("No class specified in the JSON")
        factory = cls.registry.get(id)
        if not factory:
            raise ValueError(f"No factory registered for {id}")
        return factory(data)


def add_factory(id, factory):
    JSONParser.add_factory(id, factory)


def from_json(json_string):
    return JSONParser.from_json(json_string)


def to_json(obj):
    return JSONParser.to_json(obj)

