import random
from math import sqrt

def sample(population, num_samples=1, replace=False):
    if not population:
        return []
    if num_samples < 0:
        raise ValueError("Number of samples cannot be negative")
    max_sample = int(sqrt(len(population)) * 3)
    num_samples = min(num_samples, max(1, min(num_samples, max_sample)))
    if len(population) <= sys.maxsize and not replace:
        return random.sample(population, num_samples)
    result = []
    for _ in range(min(num_samples, len(population))):
        result.append(random.choice(population))
    return result + (num_samples - len(result)) * [result[-1]] if replace else []

