import http.server
import socketserver

class MockServer:
    def __init__(self, port):
        self.port = port
        self.server = socketserver.TCPServer(("", port), MyRequestHandler)

    def start(self):
        print(f"Mock server started on port {self.port}")
        self.server.serve_forever()

    def stop(self):
        self.server.shutdown()
        print("Mock server stopped")

class MyRequestHandler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/test":
            self.send_response(200)
            self.send_header("Content-type", "text/plain")
            self.end_headers()
            self.wfile.write(b"Test Passed!")
        else:
            super().do_GET()

def main():
    port = 8000
    server = MockServer(port)
    try:
        while True:
            command = input("Enter 'start' to start the mock server, 'stop' to stop it, or 'test' to manually test: ")
            if command == "start":
                server.start()
            elif command == "stop":
                server.stop()
                break
            elif command == "test":
                import requests
                response = requests.get(f"http://localhost:{port}/test")
                print(response.text)
    except KeyboardInterrupt:
        server.stop()

if __name__ == "__main__":
    main()

