import inspect
from scipy.stats import gumbel_r, lognorm, weibull_min, exponweib

def get_max_corr_param(distribution_name):
    if distribution_name == 'gumbel':
        dist = gumbel_r
        param_bounds = (0.5, 3)
    elif distribution_name == 'lognormal':
        dist = lognorm
        param_bounds = (0.2, 1.5)
    elif distribution_name == 'weibull':
        dist = weibull_min
        param_bounds = (0.8, 3)
    elif distribution_name == 'exponential_weibull':
        dist = exponweib
        param_bounds = (0.6, 2)

    argspec = inspect.getfullargspec(getattr(dist, 'ppf'))
    if len(argspec.args) > 1:
        param_default_location = None
        param_default_scale = None
        for arg in argspec.args[1:]:
            if arg.lower() == 'size':
                continue
            if arg.lower() != 'x':
                param_default_location = 0.0 if isinstance(getattr(dist, f'scale_{arg}'), float) and getattr(dist, f'scale_{arg}') == 0.0 else None
                param_default_scale = 1.0 if isinstance(getattr(dist, f'scale_{arg}'), float) and getattr(dist, f'scale_{arg}') == 1.0 else None

    max_corr_param = None
    max_corr_coeff = 0

    for param in [param_bounds[0], (param_bounds[0] + param_bounds[1]) / 2, param_bounds[1]]:
        dist_instance = dist(param)
        corr_coeff = dist_instance.corrcoef(eval(f'dist_instance.pp({param})'))
        if corr_coeff > max_corr_coeff:
            max_corr_coeff = corr_coeff
            max_corr_param = param

    return max_corr_param

