import numpy as np
def space_to_depth(x, block):
    b = x.shape[0]
    y = np.reshape(x, (b, x.shape[1], x.shape[2] // block, block, x.shape[3] // block, block)).transpose((0, 3, 5, 1, 4, 2))
    return np.reshape(y, (x.shape[0], x.shape[1] * (block**2), x.shape[2] // block, x.shape[3] // block))

