import re
from collections import Counter
from urllib.request import urlopen

def load_stop_words(filename):
    stop_words = set()
    with open(filename, 'r') as f:
        for line in f:
            stop_words.add(line.strip().lower())
    return stop_words

def parse_html(url):
    html = urlopen(url).read().decode('utf-8')
    words = re.findall(r'\b\w+\b', html.lower())
    return set(words)

def extract_unique_words(html, stop_words):
    unique_words = set()
    word_freq_map = Counter()
    for word in parse_html(html):
        if word not in stop_words and word.isalpha():
            unique_words.add(word)
            word_freq_map[word] += 1
    return unique_words, dict(word_freq_map)

def main(url):
    stop_words = load_stop_words('stop_words.txt')
    html = url
    unique_words, freq_map = extract_unique_words(html, stop_words)
    print("Unique words: ", unique_words)
    print("Frequency map: ", freq_map)

