import hashlib

def get_sha1_hash(file_like_object):
    sha1 = hashlib.sha1()
    chunk_size = 32768
    while True:
        chunk = file_like_object.read(chunk_size)
        if not chunk:
            break
        sha1.update(chunk.encode('utf-8'))
    return sha1.hexdigest()

