import itertools

def batch_and_cycle(batches, batch_size, num_cycles):
    for _ in range(num_cycles):
        shuffled_indices = list(itertools.permutations(range(len(batches))))
        shuffled_batches = [batches[i] for i in shuffled_indices[0]]
        batches = shuffled_batches
        batches_list = []
        temp_batch = []
        for batch in batches:
            temp_batch.append(batch)
            if len(temp_batch) == batch_size:
                batches_list.append(tuple(itertools.zip_longest(*temp_batch, fillvalue=None)))
                temp_batch = []
        if temp_batch:
            batches_list.append(tuple(itertools.zip_longest(*temp_batch, fillvalue=None)))
        for batch in batches_list:
            for item in batch:
                yield item
        if len(batches) != 0:
            raise StopIteration

