class Quantity:
    def __init__(self, amount, unit, lower_bound, upper_bound):
        self.amount = amount
        self.unit = unit
        self.lower_bound = lower_bound
        self.upper_bound = upper_bound

    @classmethod
    def from_json(cls, data):
        return cls(data['amount'], data['unit'], data['lower_bound'], data['upper_bound'])

    def to_json(self):
        return {'amount': self.amount, 'unit': self.unit, 'lower_bound': self.lower_bound, 'upper_bound': self.upper_bound}

    def __str__(self):
        return f'{self.amount} {self.unit} ({self.lower_bound}, {self.upper_bound})'

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return False
        return (self.amount == other.amount and
                self.unit == other.unit and
                self.lower_bound == other.lower_bound and
                self.upper_bound == other.upper_bound)
