CREATE FUNCTION create_and_drop_table()
RETURNS @table_info TABLE
(
    message VARCHAR(100)
)

AS
BEGIN
    DECLARE @sql NVARCHAR(MAX);
    DECLARE @table_name SYSNAME = 'my_test_table';
    DECLARE @cursor CURSOR;

    SET @cursor = CURSOR FAST_FORWARD FOR
        SELECT 'CREATE TABLE ' + QUOTENAME(@table_name) + ' (id INT, name VARCHAR(50));' AS sql_command
    FROM sys.databases
    WHERE db_id('master') = DB_ID();

    OPEN @cursor;
    FETCH NEXT FROM @cursor INTO @sql;

    EXEC (@sql);

    INSERT INTO @table_name (id, name)
    VALUES (1, 'John'), (2, 'Jane');

    SET @sql = 'SELECT * FROM ' + QUOTENAME(@table_name);
    PRINT @sql;
    EXEC (@sql);

    CLOSE @cursor;
    DEALLOCATE @cursor;

    SET @sql = 'DROP TABLE ' + QUOTENAME(@table_name);
    EXEC (@sql);

    SELECT 'Table dropped.' AS message;
END;
