def generate_musical_notes(notes):
    result = []
    current_time = 0
    for note in notes:
        x, y, time, note_type, curve= None, None, None, None, None
        if "x" in note and "y" in note:
            x, y = note["x"], note["y"]
        if "time" in note:
            current_time = note["time"]
        if "note_type" in note:
            note_type = note["note_type"]
        if "curve" in note:
            curve = note["curve"]
        if "repeat" in note:
            repeat = note["repeat"]
        for _ in range(repeat):
            result.append({
                "x": x,
                "y": y,
                "time": current_time,
                "note_type": note_type,
                "curve": curve
            })
            if curve is None or not curve:
                current_time += 1
            else:
                current_time = max(curve, current_time)
    return result

