import subprocess
import time
import re

def capture_screenshot(device_ip):
    while True:
        try:
            screenshot_command = f"adb -s {device_ip} shell screencap -p /sdcard/screenshot.png"
            subprocess.run(screenshot_command, shell=True)
            print("Screenshot captured.")
            time.sleep(1)  # Capture screenshots at an interval of 1 second
        except Exception as e:
            print(f"Error: {str(e)}")
            break

def parse_logcat(device_ip):
    logcat_command = f"adb -s {device_ip} logcat"
    output = subprocess.check_output(logcat_command, shell=True)
    logcat_data = str(output.decode("utf-8")).splitlines()
    parsed_data = []
    for line in logcat_data:
        if "W/" in line or "E/" in line:
            match = re.search(r"(\w+): (\d+) - (.*)", line)
            if match:
                timestamp = int(match.group(1))
                level = match.group(2).strip()
                message = match.group(3)
                parsed_data.append((timestamp, level, message))
    return parsed_data

def main():
    device_ip = input("Enter the IP address of the Android device: ")
    while True:
        try:
            capture_screenshot(device_ip)
            logcat_data = parse_logcat(device_ip)
            with open(f"log_{time.time()}.txt", "w") as file:
                for item in logcat_data:
                    file.write(f"{item[0]} - {item[1]}: {item[2]}\n")
        except subprocess.CalledProcessError as e:
            print(f"Error: {str(e)}")
            break
        except Exception as e:
            print(f"Error: {str(e)}")
            break

if __name__ == "__main__":
    main()
