import gzip
from Bio import GFF

def gff_to_gtf(gff_file, dialect):
    if gff_file.endswith('.gz'):
        with gzip.open(gff_file, 'rt') as f:
            gff_lines = [line.strip() for line in f]
    else:
        with open(gff_file) as f:
            gff_lines = [line.strip() for line in f]

    gtf_lines = []
    for line in gff_lines:
        if line.startswith('#'):
            gtf_lines.append(line)
        else:
            record = GFF.parse(line, dialect=dialect)
            start, end = map(int, record.location.split('-'))
            strand = '+' if record.strand == 1 else '-'
            gtf_line = f"{record.seqid}\t{dialect}\tgene\t{start}\t{end}\t.\t{strand}\t{record.score}\n"
            gtf_lines.append(gtf_line)

    return ''.join(gtf_lines)
