import os
from collections import defaultdict

def process_directory(directory_path):
    report = defaultdict(str)
    coefficient = 10.0

    for filename in os.listdir(directory_path):
        if filename.endswith(".stat"):
            with open(os.path.join(directory_path, filename), 'r') as file:
                for line in file:
                    key, value = line.strip().split(': ')
                    if key in ['Reticulations', 'Taxa', 'Increase', 'Decrease', 'Outgroup']:
                        report[key] += f'{value}\n'

    with open(os.path.join(directory_path, 'report.txt'), 'w') as file:
        for key, value in report.items():
            if key == 'Increase':
                file.write(f'Increase: {int(float(value.split('\n')[0]) * coefficient)}\n')
            elif key == 'Decrease':
                file.write(f'Decrease: {int(float(value.split('\n')[0]) * coefficient)}\n')
            else:
                file.write(f'{key}: {value}\n')

    alignment_files = [f for f in os.listdir(directory_path) if f.endswith('.aln')]
    with open(os.path.join(directory_path, 'alignments.fasta'), 'w') as file:
        for filename in alignment_files:
            with open(os.path.join(directory_path, filename), 'r') as aln_file:
                file.write(aln_file.read())
