import stats
import numpy as np
from scipy.stats import norm, lognorm, gumbel_r, weibull_min, uniform, logistic, fdist, t, pearsoniii, trimodal, laplace, levy_stable, beta

def percentile_function(distribution_name, values, q, *args, **kwargs):
    if distribution_name == 'normal':
        return norm.ppf(q)
    elif distribution_name == 'log-normal':
        return lognorm.ppf(q)
    elif distribution_name == 'gumbel':
        return gumbel_r.ppf(q)
    elif distribution_name == 'weibull':
        return weibull_min.ppf(q)
    elif distribution_name == 'uniform':
        return uniform.ppf(q)
    elif distribution_name == 'logistic':
        return logistic.ppf(q)
    elif distribution_name == 'f':
        return fdist.ppf(q, *args, **kwargs)
    elif distribution_name == 't':
        return t.ppf(q, *args, **kwargs)
    elif distribution_name == 'pearsoniii':
        return pearsoniii.ppf(q)
    elif distribution_name == 'trimodal':
        return trimodal.ppf(q)
    elif distribution_name == 'laplace':
        return laplace.ppf(q)
    elif distribution_name == 'levy_stable':
        return levy_stable.ppf(q, *args, **kwargs)
    elif distribution_name == 'beta':
        return beta.ppf(q, *args, **kwargs)
    else:
        raise ValueError(f"Distribution '{distribution_name}' not supported")
