def deprecated(old_name, new_name, version):
    def getter(self):
        warnings.warn(f"Attribute '{old_name}' is deprecated since version {version}. Use '{new_name}' instead.", DeprecationWarning)
        return getattr(self, old_name)

    def setter(self, value):
        warnings.warn(f"Setting attribute '{old_name}' is deprecated since version {version}. Use '{new_name}' instead.", DeprecationWarning)
        setattr(self, new_name, value)

    return property(getter, setter)

