CREATE FUNCTION test_lock()
RETURNS INTEGER
AS 
$$
DECLARE
    result INTEGER;
BEGIN
    CREATE TEMPORARY TABLE test_table (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL
    );

    INSERT INTO test_table (name)
    VALUES ('John'), ('Jane');

    SELECT INTO result * FROM test_table WHERE name IN ('John', 'Jane');

    BEGIN;
        SELECT pg_locks.locked_by to AS locked_by;
        FOR SHARE NOWAIT OF test_table WRITE WITH WAIT_UNTIL Exclusive ON CONCURRENTLY 'my_lock';
    EXCEPTION WHEN OTHERS THEN
        ROLLBACK;
    END;

    INSERT INTO test_table (name)
    VALUES ('Jane');

    SELECT COUNT(*) INTO result FROM test_table WHERE name IN ('John', 'Jane', 'Jane');

    RELEASE ALL LOCKS;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

