def crud_operation(db_name, table_name, operation, condition=None):
    try:
        conn = sqlite3.connect(db_name)
        c = conn.cursor()

        if operation == "create":
            columns = input("Enter columns (comma separated): ")
            values = input("Enter values (comma separated): ")
            sql = f"INSERT INTO {table_name} ({columns}) VALUES ({values})"
            c.execute(sql)
            conn.commit()
            print("Data created successfully")
        elif operation == "read":
            if condition:
                sql = f"SELECT * FROM {table_name} WHERE {condition}"
            else:
                sql = f"SELECT * FROM {table_name}"
            c.execute(sql)
            rows = c.fetchall()
            for row in rows:
                print(row)
        elif operation == "update":
            column, value = input("Enter the column and new value (comma separated): ").split(',')
            condition = f"{column} = '{value}'"
            sql = f"UPDATE {table_name} SET {column} = ? WHERE {condition}"
            c.execute(sql, (value,))
            conn.commit()
            print("Data updated successfully")
        elif operation == "delete":
            if condition:
                sql = f"DELETE FROM {table_name} WHERE {condition}"
            else:
                sql = f"DROP TABLE {table_name}"
            c.execute(sql)
            conn.commit()
            print("Data deleted successfully")
        else:
            print("Invalid operation. Please try again.")

    except Error as e:
        print(e)
    finally:
        if (conn):
            conn.close()

