def compile_template(template):
    def parse_token(tokens):
        if not tokens:
            raise ValueError("Unexpected end of template")
        token = tokens.pop(0)
        return token
    def syntax_rules():
        return {
            'n': lambda: '_n',
            '(': lambda: '(',
            ')': lambda: ')',
            ',': lambda: ',',
            ':': lambda: ':='
        }
    def compile_function(template, tokens):
        code = ''
        while tokens:
            token = parse_token(tokens)
            if token in syntax_rules():
                code += syntax_rules()[token]()
            elif token.startswith('lambda'):
                return compile_lambda(code + ')')
            else:
                raise ValueError(f"Invalid template: {token}")
    def compile_lambda(code):
        return eval('lambda ' + code, {'_n': None})
    template = template.replace('\(', '(').replace('\)', ')').split('{{')[1].split('}}')[0]
    tokens = list(template)
    try:
        return compile_function(tokens, [])
    except (ValueError, SyntaxError) as e:
        raise ValueError(str(e))
