def run_experiments(experiment_defs, input_data):
    result = {}
    for experiment_def in experiment_defs:
        if '--devmode' not in input_data:
            p = subprocess.run(['python', '-c', f"locals={str({})};exec(compile(open('{experiment_def}').read(),'{experiment_def}','exec'));"], 
                                text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            result.update(eval(p.stdout))
        else:
            dev_func_locals = eval(f"{experiment_def}.dev_func({input_data})")
            exec(f"locals={str({})};from {experiment_def} import *; locals().update(**{str(dev_func_locals)})", globals(), locals())
            result.update(locals())
    return result
