import sqlite3
from collections import defaultdict

def get_row_counts(table_names):
    conn = sqlite3.connect(':memory:')
    c = conn.cursor()

    table_schemas = defaultdict(dict)

    for table_name in table_names:
        c.execute('PRAGMA table_info(%s)' % (table_name,))
        schema = [description[1] for description in c.fetchall()]

        if not table_schemas[table_name].get('schema'):
            table_schemas[table_name]['schema'] = schema
        else:
            if schema != table_schemas[table_name]['schema']:
                raise Exception("Table has different schema")

    row_counts = {}

    for table_name in table_names:
        c.execute('SELECT COUNT(*) FROM %s' % (table_name,))
        count, = c.fetchone()

        if count == 0:
            raise Exception(f"Table {table_name} has zero rows")

        row_counts[table_name] = count

    conn.close()

    return row_counts
