import os
from shelve import open
from nltk.stem.porter import PorterStemmer

def startIndexer(path):
    inv_idx = {}
    fwrd_idx = {}
    id_to_url = {}

    stemmer = PorterStemmer()

    for filename in os.listdir(path):
        doc_id = int(filename.split('.')[0])
        url = f"{path}/{filename}"
        with open(os.path.join(path, filename), 'r') as file:
            text = file.read()
            words = text.lower().split()
            stemmed_words = [stemmer.stem(word) for word in words]
            fwrd_idx[doc_id] = stemmed_words

            for word in stemmed_words:
                if word not in inv_idx:
                    inv_idx[word] = []
                inv_idx[word].append(doc_id)

        id_to_url[doc_id] = url

    return open('index', 'n'), inv_idx, fwrd_idx, id_to_url, stemmer

def finishIndexer(index_shelf):
    index_shelf.close()
