import hashlib
import os

class UserAccount:
    def __init__(self, username):
        self.username = username
        self.password_hash = None
        self.phone_number = None
        self.emergency_contact = None
        self.salt = os.urandom(16)

    def set_password(self, password):
        salted_password = password.encode() + self.salt
        self.password_hash = hashlib.pbkdf2_hmac('sha256', salted_password, self.salt, 100000).hex()

    def verify_password(self, password):
        if self.password_hash:
            salted_password = password.encode() + self.salt
            hashed_password = hashlib.pbkdf2_hmac('sha256', salted_password, self.salt, 100000).hex()
            return self.password_hash == hashed_password
        else:
            return False

    def generate_secret_key(self):
        return os.urandom(32).hex()
