import mercurial.ui
from mercurial import nodesets, revsets
import collections

def analyze_commit_history(repo_path):
    ui = mercurial.ui.ui()
    repo = mercurial.repository.memoryrepository(ui)

    def get_branches(commit_node):
        branches = set()
        queue = [commit_node]
        while queue:
            commit = repo[nodeset.revnode(queue.pop(0))]
            for parent in commit.parents():
                if parent not in queue and parent != None:
                    queue.append(parent)
                if parent not in branches:
                    branches.add(parent)
        return len(branches)

    log_cmd = ui.popen([repo.path, 'log', '-r', 'all()', '--template', 'parents({parents})'])
    log_output = log_cmd.read().decode('utf-8')

    commit_parents = collections.defaultdict(list)
    for line in log_output.splitlines():
        if line.startswith('{'):
            parent_nodes = [node.strip() for node in line[1:-2].split(',')]
            parent_commit_node = nodeset.node(parent_nodes[-1])
            commit_node = nodeset.node(line.split('{')[0][:-1])
            commit_parents[commit_node].extend(parent_nodes)
        else:
            continue

    result = {}
    for commit_node, parents in commit_parents.items():
        if len(parents) > 1:
            result[commit_node] = get_branches(commit_node)
        else:
            result[commit_node] = 1

    return result

