import hashlib
def get_sha1_hash(filename, max_bytes=None):
    h = hashlib.sha1()
    with open(filename, 'rb') as f:
        chunk = f.read(max_bytes) if max_bytes else f.read()
        while chunk:
            h.update(chunk)
            chunk = f.read(max_bytes) if max_bytes else f.read()
    return h.hexdigest()

