class FileReader:
    def __init__(self, file_or_bucket, fail_on_missing=False):
        self.file_or_bucket = file_or_bucket
        self.fail_on_missing = fail_on_missing

    def _load(self):
        if hasattr(self.file_or_bucket, 'readlines'):
            return iter(self.file_or_bucket.readlines())
        elif 'S3' in str(type(self.file_or_bucket)):
            return iter([line.decode('utf-8').strip() for line in self.file_or_bucket.get()['Body'].iter_lines()])
        else:
            raise ValueError("Unsupported file or bucket type")

    def __iter__(self):
        try:
            return self._load()
        except AttributeError as e:
            if not self.fail_on_missing:
                print(f"Error: {e}. Loading failed. Skipping to the next iteration.")
            return iter([])

    @classmethod
    def from_json(cls, json_file_or_bucket):
        import json
        obj = cls(json.loads(json_file_or_bucket), fail_on_missing=True)
        obj._load()
        return obj

    def to_json(self):
        import json
        return json.dumps(list(self))
