CREATE FUNCTION rename_column_and_add_new(
    @tableName nvarchar(255),
    @oldColumnName nvarchar(255),
    @newColumnName nvarchar(255),
    @newColumnField nvarchar(255)
)
RETURNS TABLE
AS
RETURN
SELECT 
    c.name AS oldColumnName, 
    t.name AS tableName,
    CASE 
        WHEN NOT EXISTS (
            SELECT 1 FROM sys.columns WHERE table_id = OBJECT_ID(@tableName) AND name = @newColumnName
        ) THEN 'Added'
        ELSE 'Already exists'
    END AS operationResult
FROM 
    sys.tables t
INNER JOIN 
    sys.columns c ON t.object_id = c.object_id AND c.name = @oldColumnName
WHERE 
    t.name = @tableName;

ALTER TABLE @tableName
RENAME COLUMN @oldColumnName TO @newColumnName;

ALTER TABLE @tableName
ADD @newColumnField AS @newColumnName;
