import datetime
import platform
import os
import notify2

def send_notification(message, time_delta):
    if platform.dist().lower() == 'centos' or platform.dist().lower() == 'fedora':
        from gi.repository import Notify
    elif 'darwin' in platform.system():
        os.system('osascript -e \'Tell application "Finder" to display dialog "' + message + '" with title "Event"\'')
    else:
        if not notify2.init("Event"):
            return

    if time_delta.days > 0:
        notification_message = f"{message} (last seen {time_delta.days} days ago)"
    elif time_delta.seconds / 3600 > 0:
        notification_message = f"{message} (last seen {time_delta.seconds // 3600} hours ago)"
    else:
        notification_message = message

    if platform.dist().lower() == 'centos' or platform.dist().lower() == 'fedora':
        notify_notification = Notify.Notification.new("Event", notification_message, "Event")
        notify_notification.show()
    elif 'darwin' in platform.system():
        os.system('osascript -e \'Tell application "Finder" to display dialog "' + notification_message + '" with title "Event"\'')
    else:
        note = notify2.Notification("Event", notification_message)
        note.set_timeout(5000)  # milliseconds
        note.show()

