import os
import hashlib

def file_path(filename, parent_id=None):
    if not filename:
        raise ValueError("filename is required")
    hash = hashlib.md5(filename.encode()).hexdigest()[:3]
    dir_path = "/files/attachments"
    if parent_id:
        dir_path += f"/{parent_id}"
    dir_path += f"/{hash}/{hash}"
    return os.path.normpath(dir_path)

