from django.shortcuts import render, redirect
from django.contrib.auth.models import User

def reset_password(request):
    if request.method == 'POST':
        username = request.POST['username']
        try:
            user = User.objects.get(username=username)
            token_generator = default_token_generator.make_token(user)
            send_mail(
                subject='Password Reset',
                message=f'To reset your password, click this link: {request.build_absolute_uri(request.path)}?token={token_generator}',
                from_email='your_from_email@example.com',
                recipient_list=[user.email],
                fail_silently=False
            )
            return render(request, 'password_reset_done.html')
        except User.DoesNotExist:
            return render(request, 'password_reset_form.html', {'error': 'Invalid username'})
    else:
        return render(request, 'password_reset_form.html')

def password_reset_form(request):
    if request.method == 'POST':
        return reset_password(request)
    return render(request, 'password_reset_form.html')

