def calculate_hash(file_path, hash_function):
    try:
        with open(file_path, 'rb') as f:
            file_content = f.read()
            hash_value = int(hash_function().hexdigest(), 16)
            for chunk in iter(lambda: file_content[:65536], b''):
                file_content = chunk
                hash_value = hash_function(hash_value.to_bytes((hash_value.bit_length() + 7) // 8, 'big')).hexdigest()
    except (FileNotFoundError, OSError):
        return None
    else:
        return format(int(hash_value, 16), 'x')

