import hashlib
import getpass
import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

def hash_data(input_data, algorithm):
    if algorithm == 'sha256':
        return hashlib.sha256(input_data.encode()).hexdigest()
    elif algorithm == 'md5':
        return hashlib.md5(input_data.encode()).hexdigest()
    else:
        print("Invalid algorithm. Supported algorithms: sha256, md5.")
        return None

def derive_key(password, salt):
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
        backend=default_backend()
    )
    return base64.b64encode(kdf.derive(password.encode()))

def decrypt_data(input_data, key):
    cipher = Cipher(algorithms.AES(key), modes.ECB(), default_backend())
    decryptor = cipher.decryptor()
    decrypted_data = decryptor.update(input_data) + decryptor.finalize()
    return decrypted_data.decode()

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python program.py <input_data> <algorithm> <password>")
        sys.exit(1)

    input_data = sys.argv[1]
    algorithm = sys.argv[2]
    password = getpass.getpass('Enter the password: ')
    salt = b'salt'

    hash_value = hash_data(input_data, algorithm)
    if hash_value:
        print("Hash value: ", hash_value)

    decryption_key = derive_key(password, salt)
    decrypted_data = decrypt_data(input_data.encode(), decryption_key)
    print("Decrypted data: ", decrypted_data)

