def handle_get_request(request, write):
    etag = request.get_header('ETag')
    response_etag = request.get_header('ETag', 'None')
    if etag and etag == response_etag:
        request.set_status(304)
    else:
        content_length = len(request.get_body_string())
        request.add_header('Content-Length', str(content_length))
