import json
import re

def deserialize_json(s, **kwargs):
    obj = json.loads(s, **kwargs)
    for k, v in list(obj.items()):
        match = re.match(r"(-?\d+(?:\.\d+)?(?:e[+-]?\d+)?)", str(k))
        if match:
            obj[eval(match.group())] = v
            del obj[k]
    return obj

