import hashlib
import units


def hash_strings(strings, unit="bytes"):
    if unit == "bytes":
        return hashlib.sha256("".join(strings).encode()).hexdigest()
    elif unit in ["kilobytes", "KB"]:
        return str(int(hashlib.sha256("".join(strings).encode()).hexdigest(), 16) / (1024 ** 1))
    elif unit in ["megabytes", "MB"]:
        return str(int(hashlib.sha256("".join(strings).encode()).hexdigest(), 16) / (1024 ** 2))
    elif unit in ["gigabytes", "GB"]:
        return str(int(hashlib.sha256("".join(strings).encode()).hexdigest(), 16) / (1024 ** 3))
    else:
        raise ValueError("Invalid unit")
