import hashlib
def md5_hash(file_path):
    hash_object = hashlib.md5()
    with open(file_path,'rb') as file:
        chunk = file.read(4096)
        while chunk:
            hash_object.update(chunk)
            chunk = file.read(4096)
    return hash_object.hexdigest()

