import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class RunANTLR {
    public static void main(String[] args) {
        if (args.length < 3) {
            System.out.println("Usage: java RunANTLR <directory> <file> <options>");
            return;
        }

        String directory = args[0];
        String file = args[1];
        String options = String.join(" ", Arrays.copyOfRange(args, 2, args.length));

        ProcessBuilder processBuilder = new ProcessBuilder("antlr4", "-Dlanguage=Java", "-o", directory, "-dot", "parser", file);
        processBuilder.command().addAll(Arrays.asList(options.split(" ")));

        try {
            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            if (exitCode > 0) {
                System.out.println("ANTLR tool encountered an error");
            }
        } catch (Exception e) {
            System.out.println("Error running ANTLR: " + e.getMessage());
        }
    }
}

