import hashlib
import os

def generate_hash(message, hash_function='SHA-256', salt=None):
    if not salt:
        salt = os.urandom(16)

    if hash_function == 'MD5':
        return hashlib.md5(salt + message.encode()).hexdigest()
    elif hash_function == 'SHA-1':
        return hashlib.sha1(salt + message.encode()).hexdigest()
    elif hash_function == 'SHA-256':
        return hashlib.sha256(salt + message.encode()).hexdigest()
    else:
        raise ValueError("Invalid hash function. Supported functions are MD5, SHA-1 and SHA-256")

