fn generate_llvm_ir(file_path: &str) -> String {
    let file_contents = fs::read_to_string(file_path).unwrap();
    let lexer = crate::lexer::Lexer::new(&file_contents);
    let mut parser = crate::parser::Parser::new(lexer);

    let ast = match parser.parse() {
        Ok(ast) => ast,
        Err(_) => return "Error parsing file.".to_string(),
    };

    println!("Parsed AST: {:?}", ast);

    let mut builder = llvm::IRBuilder::new(&mut LLVMContext::create());

    fn walk_node(node: &ast::Node, builder: &mut IRBuilder) {
        match node {
            ast::Node::Number(n) => {
                let constant = builder.const_int(n as i64, 1);
                println!("Generated LLVM IR code for number: {}", constant);
            }
            ast::Node::Identifier(id) => {
                let func = builder.function(id.to_string(), LLVMI8, false);
                println!("Generated LLVM IR code for function: {}", func);
            }
            ast::Node::BinaryOperation { .. } => {
                // Generate LLVM IR code for binary operation
                // ...
            }
            _ => {
                println!("Unknown node type");
            }
        }
    }

    walk_node(&ast, &mut builder);

    let module = builder.module("Generated LLVM IR").unwrap();
    let llvm_ir = format!("{:?}", module);
    println!("Generated LLVM IR code: {}", llvm_ir);
    llvm_ir
}
