use std::boxed::Box;
use rtio::{EventLoop, Handle};
use std::marker::PhantomData;

pub trait UvHandle {
    fn handle(&self) -> &Handle;
    fn loop_ref(&self) -> &EventLoop;
}

impl UvHandle for Box<dyn rtio::EventLoop + Send> {
    fn handle(&self) -> &Handle {
        self.as_ref().handle()
    }

    fn loop_ref(&self) -> &EventLoop {
        self.as_ref()
    }
}

pub fn create_event_loop() -> Box<UvHandle + Send> {
    let mut evloop = EventLoop::new();
    if let Err(_) = evloop.init() {
        panic!("Failed to initialize event loop");
    }
    Box::new(evloop) as _
}
