enum IpType {
    V4,
    V6,
}

fn get_ip_type(sock: *const ::std::os::raw::sockaddr) -> IpType {
    if ::std::os::raw::is_ipv4_addr(sock) {
        let sock_in = unsafe { ::std::mem::transmute(sock) };
        match sock_in.sin_family {
            ::std::os::raw::AF_INET => IpType::V4,
            _ => panic!("IPv6 address but not a valid sockaddr_in6"),
        }
    } else if ::std::os::raw::is_ipv6_addr(sock) {
        let sock_in6 = unsafe { ::std::mem::transmute(sock) };
        match sock_in6.sin6_family {
            ::std::os::raw::AF_INET => IpType::V4,
            ::std::os::raw::AF_INET6 => IpType::V6,
            _ => panic!("Invalid sockaddr_in6"),
        }
    } else {
        unreachable!();
    }
}

