    let mut buttons = vec![false; 128];

    let mut state = JoystickState {
        axes: [0.0; 6],
        buttons,
        hat_switch: 0,
    };

    // Initialize button states based on button caps
    for i in 0..=127 {
        state.buttons[i] = (button_caps & (1 << i)) != 0;
    }

    // Initialize axis and hat switch states based on value caps
    state.axes[0] = ((value_caps[0] >> 3) & 0x03) as f32 / 4.0 - 0.5;
    state.axes[1] = ((value_caps[0] >> 2) & 0x01) as f32 / 4.0 - 0.5;
    state.axes[2] = (value_caps[0] & 0xfe) as f32 / 255.0 - 0.5;
    state.axes[3] = ((value_caps[1] >> 2) & 0x01) as f32 / 4.0 - 0.5;
    state.axes[4] = (value_caps[1] & 0xfe) as f32 / 255.0 - 0.5;
    state.axes[5] = ((value_caps[2] >> 3) & 0x03) as f32 / 4.0 - 0.5;

    state.hat_switch = (value_caps[1] & 0x01) as i16 - 128;

    state
}

