class DatabaseHandle {
public:
    DatabaseHandle(const std::string& dbPath) : db_(new rocksdb::DB()) {
        db_->Open(db_, dbPath, {});
    }

    ~DatabaseHandle() {
        if (db_) {
            delete db_;
            db_ = nullptr;
        }
    }

    void AddColumnFamilyHandle(const std::string& columnFamilyName) {
        columnFamilies_.push_back(std::make_unique<ColumnFamilyHandle>(columnFamilyName, db_));
    }

private:
    std::unique_ptr<rocksdb::DB> db_;
    std::vector<std::unique_ptr<ColumnFamilyHandle>> columnFamilies_;
};

class ColumnFamilyHandle {
public:
    ColumnFamilyHandle(const std::string& name, DatabaseHandle* db) : name_(name), db_(db) {
        db_->->Put(name_);
    }

    ~ColumnFamilyHandle() {
        if (db_) {
            delete db_;
            db_ = nullptr;
        }
    }

private:
    const std::string name_;
    std::unique_ptr<rocksdb::DB> db_;
};

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <path_to_db_file> <name_of_column_family>\n";
        return 1;
