use glib_sys;

pub struct Checksum {
    checksum: u32,
}

impl Checksum {
    pub fn new() -> Self {
        Checksum { checksum: 0 }
    }

    pub fn reset(&mut self) {
        self.checksum = 0;
    }

    pub fn update(&mut self, data: &[u8]) {
        let mut sum = self.checksum;
        for byte in data {
            sum = (sum << 8) | (*byte as u32);
        }
        self.checksum = sum;
    }

    pub fn get_checksum(&self) -> u32 {
        self.checksum
    }
}
