fn process_args(args: Vec<String>, path: &str) -> String {
    let mut result = String::new();

    if std::fs::metadata(path).is_ok() {
        let contents = std::fs::read_to_string(path).unwrap_or_else(|_| panic!("Failed to read file {}", path));

        result.push_str(&contents);

        for arg in &args[1..] {
            result.push(' ');
            result.push_str(arg.as_str());
        }
    } else {
        for arg in args {
            result.push(' ');
            result.push_str(&arg);
        }
    }

    result
}

