fn cstr_to_string(ptr: *const u8) -> &'static str {
    let mut len = 0;
    while *ptr != 0 {
        ptr = unsafe { ptr.offset(1) };
        len += 1;
    }
    std::string::from_utf8_unchecked(std::slice::from_raw_parts(ptr as *const u8, len)).as_str()
}

