unsafe fn copy_nonoverlapping<T: Copy>(from: &[T], to: &mut [T]) {
    let from_len = from.len();
    let to_len = to.len();

    if from_len > to_len {
        // No need to check for the other direction, since T:Copy means you can't have a larger destination
        std::ptr::copy_nonoverlapping(from.as_ptr() as *mut T, to.as_mut_ptr(), from_len);
    } else {
        std::ptr::copy_nonoverlapping(from.as_ptr() as *mut T, to.as_mut_ptr(), to_len);
    }
}
