#include <memory>
#include <string>

std::string checkMemoryLayout(void* ptr) {
    auto& mem = std::memory;
    size_t size = mem::size_of(*static_cast<typename std::remove_pointer<decltype(ptr)>::type*>(ptr));
    size_t alignment = mem::align_of(*static_cast<typename std::remove_pointer<decltype(ptr)>::type*>(ptr));

    char* field1Offset = reinterpret_cast<char*>(ptr);
    const auto& field2 = *static_cast<const typename std::remove_pointer<decltype(ptr)>::type*>(ptr);
    char* offset1 = reinterpret_cast<char*>(&field2.someField1) - field1Offset;
    char* offset2 = reinterpret_cast<char*>(&field2.someField2) - field1Offset;

    return "Size: " + std::to_string(size) +
           ", Alignment: " + std::to_string(alignment) +
           ", Offset 1 to someField1: " + std::to_string(offset1) +
           ", Offset 2 to someField2: " + std::to_string(offset2);
}

fn run_with_local_task<T>(f: impl FnOnce -> ::io::Result<T>) -> ::io::Result<T> {
    let mut local_task = ::task::LocalTask::new();

    if let Ok(result) = f() {
        result
    } else {
        match result {
            Err(e) => Err(::io::Error::new<::io::ErrorKind::Other, e.to_string())),
            _ => unreachable!(),
        }
    }
}

fn run_with_io_factory<T>(f: impl FnOnce -> ::io::Result<T>) -> ::io::Result<T> {
    let mut io_factory = ::task::LocalIoFactory::new();

    match f() {
        Ok(result) => result,
        Err(e) => {
            unsafe {
                let task = io_factory.clone();
                task.transmute_copy( &mut local_task );
            }
            Err(e)
        },
    }
}

fn unsafe_transmute<L, G>(l: L) -> G {
    let l_ptr = &mut l;
    std::ptr::read(l_ptr as *const _ as *const G);
    std::boxed::forget(l_ptr);
    std::ptr::read(l_ptr as *mut _ as *mut G)
}

