function parse_args($args) {
    $result = array();
    $arg = '';
    for ($i = 0; $i < strlen($args); $i++) {
        $char = $args[$i];
        if ($char == '"') {
            if (empty($arg)) {
                $arg = $char;
            } elseif ($arg === '"' && $args[$i+1] != '"') {
                $result[] = str_replace(array('"', '\\"'), '"', $arg);
                $arg = '';
            } else {
                $arg .= $char;
            }
        } elseif (ctype_space($char) || $char == "'") {
            if (!empty($arg)) {
                $result[] = trim($arg);
                $arg = '';
            }
        } else {
            $arg .= $char;
        }
    }
    if (!empty($arg)) {
        $result[] = trim($arg);
    }
    return $result;
}

