```rust
use std::sync::{Arc, Mutex};
use std::collections::HashSet;
use std::sync::atomic::{AtomicUsize, Ordering};

struct ConcurrentBag {
    elements: Arc<Mutex<HashSet<i32>>>,
    count: AtomicUsize,
}

impl ConcurrentBag {
    fn new() -> Self {
        ConcurrentBag {
            elements: Arc::new(Mutex::new(HashSet::new())),
            count: AtomicUsize::new(0),
        }
    }

    fn insert(&self, bag: HashSet<i32>) {
        let mut lock = self.elements.lock().unwrap();
        *lock = bag.clone();
        self.count.store(bag.len() as usize, Ordering::Relaxed);
    }

    fn collect(&self) -> HashSet<i32> {
        let lock = self.elements.lock().unwrap();
        (*lock).clone()
    }
}

fn main() {
    let bag = ConcurrentBag::new();
    // Insert some elements
    bag.insert(HashSet::from_iter([1, 2, 3].iter().cloned()));
    bag.insert(HashSet::from_iter([4, 5, 6].iter().cloned()));

    // Collect all the elements
    let collected = bag.collect();
    println!("{:?}", collected);
}
