use std::net::{UdpSocket, IpAddr, Ipv4Addr, SocketAddr};
use std::io;
use std::net::Ipv6Addr;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        panic!("Usage: {} <bind_ip_port> <num_streams>", &args[0]);
    }

    let (bind_ip, bind_port) = parse_bind_arg(&args[1]);
    let num_streams = args[2].parse::<u32>().unwrap();

    let mut socket = UdpSocket::bind(bind_ip, bind_port).unwrap();
    println!("Bound to {}:{}", &bind_ip, bind_port);

    let message = b"Hello, UDP!";
    for i in 0..num_streams {
        let destination_ip = Ipv4Addr::new(127, 0, 0, (i % 256).wrapping_add(1));
        let destination_port = i as u16;
        let destination = SocketAddr::new(destination_ip, destination_port);
        send_message(&mut socket, message, &destination).unwrap();
    }
}

fn parse_bind_arg(arg: &str) -> (IpAddr, u16) {
    let parts: Vec<&str> = arg.split(":").collect();
    if parts.len() != 2 {
        panic!("Invalid bind IP port format");
    }

    let ip = match parts[0] {
        "127.0.0.1" | "localhost" => IpAddr::V4(Ipv4Addr::new(127, 0, 0, 1)),
        _ => Ipv6Addr::from_str(&parts[0]).unwrap().into(),
    };

    let port = parts[1].parse::<u16>().unwrap();

    (ip, port)
}

fn send_message(socket: &mut UdpSocket, message: &[u8], destination: &SocketAddr) -> io::Result<()> {
    socket.send_to(message, destination)
}

