```rust
use std::io;
use std::net::TcpListener;
use std::thread;
use std::sync::{Arc, Mutex};
use flate2::write::ZlibEncoder;
useflate2::compress::threading::Pool;

const BUFFER_SIZE: usize = 4096;

fn main() {
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    println!("Listening on 127.0.0.1:8080");

    for stream in listener.incoming() {
        match stream {
            Ok(mut stream) => {
                let pool = Arc::new(Mutex::new(Pool::new()));
                thread::spawn(move || {
                    let mut buffer = [0; BUFFER_SIZE];
                    loop {
                        let n = stream.read(&mut buffer).unwrap();
                        if n == 0 {
                            break;
                        }
                        let compressed = compress(buffer[..n].to_vec(), &pool);
                        stream.write_all(&compressed).unwrap();
                    }
                });
            }
            Err(_) => {}
        }
    }
}

fn compress(data: Vec<u8>, pool: &Arc<Mutex<Pool>>) -> Vec<u8> {
    let mut encoder = ZlibEncoder::new(Vec::new(), 9);
    let mut buffer = [0; BUFFER_SIZE];
    let mut writer = io::BufWriter::new(io::stdout());
    loop {
        let n = data.split_off(0).take(BUFFER_SIZE).to_vec();
        if n.is_empty() {
            break;
        }
        encoder.write_all(&n).unwrap();
        writer.write_all(&encoder.finish().unwrap()).unwrap();
    }
    encoder.finish().unwrap()
}
