struct SimpleRemoteControl<'a> {
    command: Option<Box<dyn Command + 'a>>,
}

impl<'a> SimpleRemoteControl<'a> {
    fn new() -> Self {
        SimpleRemoteControl { command: None }
    }

    fn set_command(&mut self, f: Box<dyn Fn() + '_>) {
        *self.command.get_or_insert(Box::new(Command::new(f)));
    }

    fn press_button(&mut self) {
        if let Some(ref mut c) = self.command.take() {
            c.execute();
        }
    }
}

fn main() {
    let mut remote = SimpleRemoteControl::new();

    let f = || println!("Button pressed!");
    let command = Command::new(Box::new(f));

    remote.set_command(command);

    remote.press_button();
}
