def copy_files(src_dir, dst_dir, lib_path, compiler_path):
    for root, dirs, files in os.walk(src_dir):
        for file in files:
            src_file = os.path.join(root, file)
            dst_file = os.path.relpath(src_file, src_dir).replace(os.sep, '/')
            if not any(lib_file.startswith(lib_path) for lib_file in os.listdir(lib_path)):
                shutil.copy2(src_file, os.path.join(dst_dir, dst_file))
            elif os.path.exists(os.path.join(lib_path, file)):
                shutil.copy2(os.path.join(lib_path, file), dst_dir)
                os.chmod(os.path.join(dst_dir, file), os.stat(compiler_path).st_mode)

