use crypto::hmac::{Hmac, Mac};
use crypto::sha1::Sha1;
use std::convert::TryInto;

fn verify_signature(payload: &[u8], signature: &[u8]) -> bool {
    let key = [0; 20]; // Replace with your secret key
    let mut hmac = Hmac::<Sha1, Mac<aes::BlockIv>::new().hash_function(Sha1::new()).hash_function(Sha1::new());
    hmac.update(&key);
    hmac.update(payload);

    let mut expected_signature: [u8; 20] = [0; 20];
    expected_signature.copy_from_slice(&hmac.finalize()[..]);

    let mut actual_signature: [u8; 20] = [0; 20];
    actual_signature.copy_from_slice(signature[..].try_into().unwrap());

    for i in 0..20 {
        actual_signature[i] = actual_signature[i].wrapping_add(expected_signature[i]);
    }

    for i in 0..20 {
        if actual_signature[i] != expected_signature[i] {
            return false;
        }
    }

    true
}

