pub fn decrypt_data(encrypted_blob: &str, device_id: &str, username: &str) -> Vec<u8> {
    let mut key = [0u8; 32];
    let device_id_bytes = device_id.as_bytes();
    let username_bytes = username.as_bytes();
    randombytes(&mut key);
    secretbox::key_from_secret_key(&key).unwrap();
    let mut decrypted_blob = vec![0u8; encrypted_blob.len()];
    decrypt_box(&encrypted_blob, &device_id_bytes, &username_bytes, &mut key, &mut decrypted_blob);
    decrypted_blob
}

fn decrypt_box(encrypted_data: &str, device_id: &[u8], username: &[u8], key: &mut [u8], data: &mut Vec<u8>) {
    let encrypted_data_bytes = encrypted_data.as_bytes();
    let mut nonce = [0u8; 24];
    randombytes(&mut nonce);
    secretbox::decrypt(encrypted_data_bytes, device_id, username, nonce, key, data)
}
