use std::fs;
use std::collections::{HashMap, HashSet};

struct Task {
    deadline: i32,
    result: Option<i32>,
}

struct Menu {
    tasks: HashMap<i32, Task>,
    due_tasks: HashSet<i32>,
}

impl Menu {
    fn new() -> Self {
        Menu { tasks: HashMap::new(), due_tasks: HashSet::new() }
    }
}

fn load_data(file_name: &str) -> Menu {
    let mut menu = Menu::new();
    if let Ok(data) = fs::read_to_string(file_name) {
        for line in data.lines() {
            let parts: Vec<&str> = line.split(',').collect();
            let deadline: i32 = parts[0].parse().unwrap();
            let result: Option<i32> = match &parts[1] {
                "due" => Some(parts[2].parse().unwrap()),
                _ => None,
            };
            menu.tasks.insert(deadline, Task { deadline, result });
        }
    }
    for (deadline, task) in &menu.tasks {
        if let Some(result) = &task.result {
            if *deadline <= 0 {
                menu.due_tasks.insert(*deadline);
            }
        }
    }
    menu
}

fn check_deferred_task(menu: &Menu) -> Menu {
    let mut new_menu = Menu::new();
    for (deadline, task) in menu.tasks.iter() {
        if let Some(result) = &task.result {
            if deadline <= 0 {
                new_menu.tasks.insert(*deadline, Task { deadline: 0, result: Some(*result) });
                new_menu.due_tasks.insert(*deadline);
            }
        }
    }
    for task in menu.tasks.values() {
        if let Some(result) = &task.result {
            if *task.deadline <= 0 {
                task.result = None;
            }
        }
    }
    menu
}

fn main() {
    let file_name = "data.txt";
    let menu = load_data(file_name);
    let updated_menu = check_deferred_task(&menu);
    // Your code to update the menu here...
}
