use crypto::digest::{Digest, Md5};
use crypto::md5::Md5Encoder;

fn md5_hash(password: &str, nonce: &str) -> String {
    let mut md5 = Md5Encoder::new();
    let password_bytes = password.as_bytes();
    let nonce_bytes = nonce.as_bytes();

    unsafe {
        let ctx = SHA_CTX_new();
        SHA1_Update(ctx, password_bytes.as_ptr(), password.len());
        SHA1_Final(ctx, &mut [0; 16][..]);
        SHA_CTX_free(ctx);
    }

    md5.write_all(password_bytes).unwrap();
    md5.write_all(nonce_bytes).unwrap();

    String::from_utf8(md5.result().unwrap()).unwrap()
}
