fn executable_path(binary_name: &str) -> PathBuf {
    let current_exe = env::current_exe();
    let parent_dir = current_exe.parent().unwrap();
    let grandparent_dir = parent_dir.parent().unwrap();
    let mut path = grandparent_dir.to_path_buf();
    path.push(binary_name);
    assert!(path.exists());
    path
}

