use hmac::{Hmac, MacError};
use sha1::Sha1;
use reqwest::header::{HeaderMap, HeaderValue};

fn process_request(request: &reqwest::Request, config: &config::Config) -> reqwest::Response {
    let header_value = request.headers().get("X-HMAC-SHA1").cloned();

    if let Some(value) = header_value {
        let expected_signature = value.to_string();
        let actual_signature = match compute_signature(request.body(), config.secret()) {
            Ok(signature) => signature,
            Err(_) => return reqwest::Response::builder().status(404).body("Invalid request body").unwrap(),
        };

        if expected_signature != actual_signature {
            return reqwest::Response::builder().status(404).body("Invalid request body").unwrap();
        }
    }

    reqwest::Response::builder().status(200).body(request.body()).unwrap()
}

fn compute_signature(body: Vec<u8>, secret: &[u8]) -> Result<String, MacError> {
    let mut hmac = Hmac::<Sha1, _>::new_from_key(secret);
    hmac.update(&body);
    let signature = hmac.finalize().into_bytes();
    Ok(hex::encode(signature))
}
