#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <string.h>

void child_process(int argc, char* argv[]) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(sock, (struct sockaddr*)&addr, sizeof(addr));
    listen(sock, 3);

    FILE* pipe_writeto = fopen("/tmp/stdout", "w");
    FILE* pipe_readfrom = fopen("/tmp/stdin", "r");

    int pid = fork();
    if(pid == 0) {
        dup2(pipe_readfrom->fileno, 0);
        dup2(pipe_writeto->fileno, 1);

        char buffer[1024];
        read(0, buffer, 1023);
        printf("Child received command: %s\n", buffer);

        struct sockaddr_in client;
        socklen_t client_len = sizeof(client);
        int new_sock = accept(sock, (struct sockaddr*)&client, &client_len);
        char client_ip[16];
        inet_ntop(AF_INET, &client.sin_addr, client_ip, 15);
        printf("Child accepted connection from %s:%d\n", client_ip, ntohs(client.sin_port));

        // Simulate service start
        sleep(2);

        JSON_t* json = cJSON_CreateObject();
        cJSON_AddStringToObject(json, "status", "success");
        char* json_str = cJSON_PrintUnformatted(json);
        write(pipe_writeto->fileno, json_str, strlen(json_str));
        free(json_str);
        cJSON_Delete(json);

        close(new_sock);
        exit(0);
    } else {
        FILE* pipe_tochild = popen("sh -c 'sleep 5; echo success'", "w");
        fwrite("start\n", 1, 6, pipe_tochild);
        fclose(pipe_tochild);
    }

    fclose(pipe_writeto);
    fclose(pipe_readfrom);

    close(sock);
}

int main(int argc, char* argv[]) {
    child_process(argc, argv);
    return 0;
}
