extern crate hmac;
use hmac::{Hmac, Mac};
use percent_encoding::utf8_percent_encode;

fn compute_signature(method: &str, uri: &str, query: &str, consumer_secret: &str) -> String {
    let mut sig = Hmac::new::<sha1>(consumer_secret.as_bytes());
    sig.update(method.as_bytes());
    sig.update(b"?".as_ref());
    if !query.is_empty() {
        sig.update(uri.as_bytes());
        sig.update(query.as_bytes());
    } else {
        sig.update(uri.as_bytes());
    }
    let mut bytes = sig.finalize();
    bytes.reverse();
    let signature = utf8_percent_encode(&hex::encode(bytes), PROAGMENT_ENCODED).to_string();
    signature
}

