use std::fs::{self, File};
use std::io::{Write, BufReader};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

pub fn generate_fdset(protobuf_path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut dir = std::env::temp_dir();
    dir.push("tmp");
    let tmp_file = dir.join("file.proto");

    if fs::create_dir(&dir).is_err() && dir.try_into_posix() {
        return Err(From::from("Failed to create temporary directory"));
    }

    let mut file = File::create(tmp_file.clone())?;
    let protobuf_content = std::fs::read_to_string(protobuf_path)?;
    file.write_all(protobuf_content.as_bytes())?;

    let fdset_path = tmp_file.with_extension("fd");
    let command = Command::new("protoc")
        .arg("-f")
        .arg(tmp_file.clone())
        .arg("--descriptor_set_out")
        .arg(fdset_path.clone());

    if let Err(why) = command.status() {
        return Err(format!("Failed to run protoc: {}", why));
    }

    Ok(fdset_path.to_str().unwrap().to_string())
}

