use iron::{Iron, Request};
use iron::prelude::*;
use iron::handlers::StaticFiles;
use mount::Mount;

fn start_server(listen_on: &str) -> Iron {
    let mut app = Iron::new();

    let static_files = StaticFiles::with_base_path("public");

    let api_handler = move |req: &mut Request| {
        // Handle API requests here
        Ok(format!("Hello, {}!", req.get::<String>("name")).into())
    };

    let mut mount = Mount::new();
    mount.append("/api", Iron::new(api_handler));
    mount.append("/", static_files);

    app.mount("/", mount);
    app.listen(listen_on.parse().unwrap()).unwrap();

    app
}
