fn create_site(directory: &str, config: &Config) -> usize {
    let mut count = 0;
    if std::fs::create_dir_all(&format!("{}/site", directory)).is_ok() {
        for entry in std::fs::read_dir(directory).unwrap() {
            match entry {
                Ok(entry) => {
                    let path = entry.path();
                    if path.extension().and_then(|e| e.to_str()).map_or(false, |s| s == "md") {
                        let post = create_post(&path, config);
                        if post.is_ok() {
                            let _ = std::fs::write(format!("{}/site/{}", directory, post.unwrap().slug()), post.unwrap().content());
                            count += 1;
                        }
                    }
                },
                Err(_) => {}
            }
        }
    }
    count
}
