#[test]
fn update_hosts_file() {
    use std::fs;
    use std::io::{Write, BufReader};
    use std::io::prelude::*;
    use std::path::Path;
    use std::str;

    fn update_hosts_file(file_path: &str, ip_address: &str, hostname: &str) -> Result<(), String> {
        let mut file = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(Path::new(file_path))?;
        let mut contents = BufReader::new(file.take().unwrap())
            .lines()
            .map(|line| line.unwrap())
            .collect::<Vec<String>>();

        match &ip_address {
            "127.0.0.1" | "::1" => {}
            _ if ip_address.starts_with("127.") || ip_address.starts_with("192.") => {
                let ipv4 = ::std::str::FromBytesWithoutNul::from(ip_address.as_bytes());
                let line = format!("{} {}", ipv4, hostname);
                contents.push(line);
            }
            _ => {
                let ipv6 = ::std::str::FromBytesWithoutNul::from(ip_address.as_bytes());
                let line = format!("{} {}", ipv6, hostname);
                contents.push(line);
            }
        }

        file.seek(std::io::SeekBegin)?;
        for (i, content) in contents.into_iter().enumerate() {
            if i == 0 {
                continue;
            }
            writeln!(file, "{}", content)?;
        }
        Ok(())
    }

    // Test cases
    update_hosts_file("hosts", "192.168.1.100", "my-lan-host").unwrap();
    update_hosts_file("hosts", "2001:db8:1234:1::2", "my-v6-host").unwrap();
}

