use std::env;
use std::path::Path;

fn current_executable_path(suffix: Option<&str>) -> Option<String> {
    let path = env::current_exe();
    if let Ok(path) = path {
        let file_stem = Path::new(&path).file_name().and_then(|f| f.to_str()).unwrap_or("");
        let mut path_str = format!("{}/{}", path.parent().unwrap().to_str().unwrap(), file_stem);
        if let Some(suffix) = suffix {
            path_str.push_str("_");
            path_str.push_str(suffix);
        }
        Some(path_str)
    } else {
        None
    }
}

