use sha1::Sha1;
use std::fs::File;
use std::io::{Read, Write};
use std::path::Path;

async fn get_file_hash(repo_id: String, file_path: &str) -> Result<String, reqwest::Error> {
    let mut file = File::open(Path::new(file_path))?;
    let mut hash = Sha1::new();

    let mut buffer = [0; 4096];
    loop {
        let n = file.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        hash.update(&buffer[..n]);
    }

    let repo_id_bytes = repo_id.as_bytes();
    let file_path_bytes = file_path.as_bytes();

    let mut bytes = Vec::new();
    bytes.extend_from_slice(repo_id_bytes);
    bytes.extend_from_slice(b",".as_bytes());
    bytes.extend_from_slice(file_path_bytes);

    hash.update(&bytes);

    Ok(format!("{:x}", hash.finalize()))
}

