use crypto::{digest::Digest, md5::Md5, sha1::Sha1, sha2::{Sha224, Sha256, Sha384, Sha512}};
use crypto::sha3::{Sha3, DigestBuilder};

fn hash(algorithm: &str, data: &str) -> (String, Box<Digest>, u32) {
    match algorithm {
        "MD5" => (
            String::from("MD5"),
            Box::new(Md5::new()),
            128,
        ),
        "SHA1" => (
            String::from("SHA1"),
            Box::new(Sha1::new()),
            160,
        ),
        "SHA224" => (
            String::from("SHA224"),
            Box::new(Sha224::new()),
            224,
        ),
        "SHA256" => (
            String::from("SHA256"),
            Box::new(Sha256::new()),
            256,
        ),
        "SHA384" => (
            String::from("SHA384"),
            Box::new(Sha384::new()),
            384,
        ),
        "SHA512" => (
            String::from("SHA512"),
            Box::new(Sha512::new()),
            512,
        ),
        "SHA3" => {
            let bits = match data {
                s if s.contains("224") => 224,
                s if s.contains("256") => 256,
                s if s.contains("384") => 384,
                s if s.contains("512") => 512,
                _ => panic!("Invalid SHA3 bits"),
            };
            (
                String::from("SHA3"),
                Box::new(DigestBuilder::<Sha3>::new().build()?),
                bits,
            )
        }
        _ => panic!("Invalid algorithm"),
    }
}

fn generate_temp_file(filename_prefix: &str) -> std::io::Result<String> {
    use rand::seq::SliceRandom;
    use std::fs::OpenOptions;
    use std::path::Path;

    let mut rng = rand::thread_rng();
    let filename = format!("{}-{}.tmp", filename_prefix, rng.gen_ascii_str(8));

    let path = Path::new(&filename);
    let display = path.display();

    let file = OpenOptions::new()
        .create(true)
        .write(true)
        .temporary(true)
        .open(&path)?;
    let mut writer = file.write_vec()?;

    let message = "Hello, World!";
    writer.write_all(message.as_bytes())?;
    writer.write_all(b"\n")?;

    Ok(format!("{}", path.canonicalize().unwrap()))
}

