use crypto::digest::{Digest, Sha256};
use std::fmt;
use std::iter;

struct HashedSequence {
    input: String,
}

impl fmt::Debug for HashedSequence {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "HashedSequence {{ input: {} }}", self.input)
    }
}

impl Iterator for HashedSequence {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(hash) = hash_input(&self.input) {
            self.input.clear();
            return Some(hash);
        }
        None
    }
}

fn hash_input(input: &str) -> Option<String> {
    let mut sha256 = Sha256::new();
    sha256.update(input.as_bytes());
    let hashed_input = format!("{:x}", sha256);
    Some(hashed_input)
}
