use std::io;
use std::collections::HashSet;

struct User {
    username: String,
    password: String,
}

fn authenticate_plaintext(user: &User, input_password: &str) -> bool {
    user.password == input_password
}

fn authenticate_md5(user: &User, input_password: &str, salt: &str) -> bool {
    let hashed_input = md5::compute(input_password.as_bytes());
    let hashed_user = md5::compute((user.password + salt).as_bytes());
    hashed_input.0 == hashed_user.0
}

fn main() {
    let mut users = HashSet::<String>::new();
    users.insert("john".to_string());
    users.insert("jane".to_string());

    loop {
        println!("Enter your username:");
        let mut input_username = String::new();
        io::stdin().read_line(&mut input_username).expect("Failed to read line");
        let username = input_username.trim();

        if !users.contains(username) {
            println!("Invalid username. Please try again.");
            continue;
        }

        println!("Enter your password:");
        let mut input_password = String::new();
        io::stdin().read_line(&mut input_password).expect("Failed to read line");
        let password = input_password.trim();

        let user = users.get(username).cloned().unwrap();
        if authenticate_plaintext(&user, password) {
            println!("Authentication successful. Welcome, {}!", username);
            break;
        } else if let Some(salt) = user.password.splitn(2, |c| *c == '|') {
            if authenticate_md5(&user, password, &salt[1..]) {
                println!("Authentication successful. Welcome, {}!", username);
                break;
            }
        }

        println!("Invalid password. Please try again.");
    }
}
