use std::path::{Path, PathBuf};
use std::fs;
use std::io;

fn copy_dir(src: &Path, dst: &Path) -> io::Result<()> {
    for entry in fs::read_dir(src)? {
        let entry = entry?;
        let src_entry_path = entry.path();
        let dest_entry_path = dst.join(&src_entry_path.file_name().unwrap());

        if src_entry_path.is_file() {
            // Only copy files that don't already exist at the destination
            if !dest_entry_path.exists() {
                fs::copy(src_entry_path, &dest_entry_path)?;
            }
        } else if src_entry_path.is_dir() {
            if !dest_entry_path.exists() {
                fs::create_dir_all(&dest_entry_path)?;
                copy_dir(&src_entry_path, &dst)?
            }
        }
    }
    Ok(())
}

