fn extract_metadata(map: &HashMap<String, Bencode>) -> Metadata {
    let info = match map.get("info") {
        Some(value) => value.clone(),
        None => panic!("Expected 'info' field"),
    };
    let pieces = match info.get("pieces") {
        Some(value) => value.as_i64().unwrap() as u32,
        None => panic!("Expected 'pieces' field in 'info'"),
    };
    let length = match info.get("length") {
        Some(value) => value.as_i64().unwrap() as u32,
        None => panic!("Expected 'length' field in 'info'"),
    };
    let sha1 = {
        let mut hasher = Sha1::new();
        hasher.update(info.data());
        hasher.finalize()
    };
    Metadata { pieces, length, sha1 }
}
