use mach::Binary;
use std::fs::File;
use std::io::{Read, BufReader};

fn print_binary_info(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = File::open(path)?;
    let buf = BufReader::new(file);
    let binary = Binary::from_reader(buf)?;

    match binary {
        mach::Binary::MachO(macho) => {
            println!("MACH-O Architecture: {}", macho.header.cputype());
            println!("MACH-O Endian: {}", if macho.is_little_endian() {"little" } else { "big"});
        }
        mach::Binary::PE(pei) => {
            println!("PE Architecture: {:?}", pei.file_header.machine);
            println!("PE Endian: {}", if pei.is_little_endian() {"little"} else {"big"});
        }
    }

    Ok(())
}
