use std::fs;
use std::path::{Path, PathBuf};

fn generate_gitignore(repository_path: &str, templates: Vec<String>) -> String {
    let gitignore_file = repository_path.to_string() + "/.gitignore";

    let mut file_content = String::new();

    for template in templates {
        match fs::read_to_string(template.clone()) {
            Ok(content) => file_content.push_str(&content),
            Err(_) => panic!("Failed to read template file: {}", template),
        };

        if !template.ends_with(".txt") {
            continue;
        }

        let mut line = String::new();
        for part in template.split("/").skip(1).take_while(|s| **s != "") {
            line.push_str(format!("{}/*.{}\n", repository_path, part.replace('.','')).as_str());
        }
    }

    if file_content.is_empty() {
        return "".to_string();
    }

    fs::write(gitignore_file.clone(), file_content).unwrap_or_else(|_| panic!("Failed to write to {}: {}", gitignore_file, &file_content));

    gitignore_file.to_string()
}

