use rustc_hex::FromHex;
use sha1::{Sha1, Digest};
use std::collections::BTreeMap;
use std::io;

fn bytes_to_dict(data: Vec<u8>) -> io::Result<(BTreeMap<String, String>, usize)> {
    let mut dict = BTreeMap::<String, String>::new();
    let mut pos = 0usize;
    let chunk_size = 1024; // adjust this for better performance
    loop {
        let end_pos = pos.max(data.len()).min(pos + chunk_size);
        let chunk = &data[pos..end_pos];
        let mut sha1 = Sha1::new();
        sha1.update(chunk);
        let hash: Vec<u8> = sha1.finalize().to_vec();
        let hash_hex = format!("{:x}", hash.into_iter().collect::<Vec<_>>().try_into().unwrap());
        dict.insert(hash_hex.clone(), String::from_utf8_lossy(&chunk).into_owned());
        pos = end_pos;
        if pos >= data.len() {
            break;
        }
    }
    Ok((dict, pos))
}

