use std::fs::OpenOptions;
use std::io::{Write, BufWriter};

struct History {
    buffers: Vec<String>,
}

impl History {
    fn new(max_file_size: u32) -> Self {
        History { buffers: vec![] }
    }

    fn push(&mut self, buffer: &str) {
        self.buffers.push(buffer.to_string());
    }

    fn commit(self, file_name: &str) -> std::io::Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create(true)
            .open(file_name)?;

        let mut writer = BufWriter::new(&mut file);
        for buffer in self.buffers.iter() {
            writer.write(buffer.as_bytes())?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_history_commit() {
        let mut history = History::new(1000);
        for i in 0..10 {
            history.push(&format!("Buffer {}", i));
        }
        assert_eq!(history.commit("output.txt").is_ok(), true);
        let file = std::fs::File::open("output.txt").unwrap();
        let content = std::io::Read::read_to_string(file).unwrap();
        assert_eq!(content.lines().count(), 10);
    }
}

