extern crate crypto;
extern crate pbkdf2;

use crypto::digest::{Digest, Md5};
use crypto::hmac::{Hmac, MacResult};
use crypto::pbkdf2::{PBKDF2Result, PBKDF2Config};
use std::convert::TryInto;

fn hash_password(password: &str, salt: &[u8]) -> Result<String, String> {
    if salt.len() < 4 {
        return Err("Invalid salt length. Salt must be at least 4 bytes.".to_string());
    }

    let mut md5 = Md5::new();
    md5.update(salt);
    let md5_hash = md5.result().try_into().unwrap();

    let config = PBKDF2Config {
        password: password.as_bytes(),
        salt,
        iterations: 1000,
        key_length: 32,
    };
    let pbkdf2_result = PBKDF2Result::new(config);

    let mut hmac = Hmac::new(Md5::new(), &pbkdf2_result);
    hmac.update(salt)?;
    hmac.update(password.as_bytes())?;
    let hmac_hash = hmac.result().try_into().unwrap();

    Ok(format!("{:x}", md5_hash.iter().chain(hmac_hash).collect::<Vec<u8>>().try_into().unwrap()))
}

