int create_temp_file(int *err)
{
    int read_fd, write_fd;
    char temp_name[64];
    sprintf(temp_name, "/tmp/temp_file.XXXXXX", (int) time(NULL));
    mkstemp(temp_name);
    read_fd = fdopen(mktemp(temp_name), "r+b");
    if (!read_fd)
        return errno;
    write_fd = dup(read_fd);
    close(read_fd);
    return 0;
}

