fn get_file_associated_program(path: &str) -> Result<String, String> {
    let mut browsers = vec!["xdg-open", "gnome-open", "kde-open"];
    if let Ok(browser) = env::var("BROWSER") {
        browsers.insert(0, browser);
    }

    for program in browsers {
        match process::Command::new(program)
            .arg(path)
            .output()
        {
            Ok(_) => return Ok(program.to_string()),
            Err(_) => {}
        }
    }

    let mut error_message = String::from("Failed to find a suitable file association program. Tried: ");
    for program in browsers {
        error_message.push_str(&format!("{} ", program));
    }
    Err(error_message)
}

