async fn interact(
    provider_info: &ProviderInfo,
    interaction: &Interaction,
    verification_options: &VerificationOptions,
    state_executor: &mut ProviderStateExecutor,
) -> Result<Option<String>, MismatchResult> {
    let mut client = reqwest::Client::new();
    let mut provider_states_results = HashMap::<String, bool>::new();

    for state in futures::stream::iter(provider_info.states.iter()) {
        // Perform the necessary actions for each state
        match perform_state_action(client, &state, interaction, verification_options).await {
            Ok(_) => {}
            Err(e) => return Err(MismatchResult { error: e }),
        }
        let updated_state = update_provider_state(state);
        if let Some(result) = provider_states_results.get(&updated_state) {
            if *result {
                // State has been verified, continue with the interaction
                return Ok(interaction.result());
            } else {
                // State is not verified, skip this state and move to the next one
                continue;
            }
        }
