use sha2::{Sha256, Digest};
use base64::encode;
use guid::{guid};

fn apply_hash(input: &[u8]) -> String {
    let hash = Sha256::digest(input);
    let fixed_guid = guid().as_bytes();
    let combined_input = vec![0; input.len() + fixed_guid.len()].into_boxed_slice();
    combined_input.copy_from_slice(input);
    combined_input.copy_from_slice(fixed_guid);
    let result = Sha256::digest(&combined_input);
    encode(&result)
}
