struct ChannelMetadata {
    id: u32,
    request_channel_id: u32,
    reply_channel_id: u32,
    timeout: Duration,
    max_message_size: usize,
    temp_dir: String,
}

pub fn create_request_response_channel(
    request_channel_id: u32,
    reply_channel_id: u32,
) -> (Sender<String>, Receiver<String>, ChannelMetadata) {
    let (tx, rx): (Sender<String>, Receiver<String>) = channel(1024);
    let mut temp_dir = tempfile::tempdir().unwrap();
    let temp_dir_path = Path::new(&*temp_dir.path());
    let temp_dir_str = temp_dir_path.to_str().unwrap().to_string();

    let timeout = Duration::from_millis(5000);
    let max_message_size = 1024;

    let metadata = ChannelMetadata {
        id: 1,
        request_channel_id,
        reply_channel_id,
        timeout,
        max_message_size,
        temp_dir: temp_dir_str.clone(),
    };

    (tx, rx, metadata)
}
