use std::collections::HashMap;
use std::sync::Arc;

struct ServerSettings {
    server_port: u16,
    user_data_path: String,
    rally_point_port: u16,
}

fn parse_args(args: Vec<String>) -> Arc<ServerSettings> {
    let mut settings = HashMap::<String, String>::new();
    let mut result = ServerSettings {
        server_port: 0,
        user_data_path: "".to_string(),
        rally_point_port: 0,
    };

    for arg in &args[1..] {
        let parts: Vec<&str> = arg.splitn(2, |c| c == '=')?;
        let key = parts[0].trim();
        let value = parts[1].trim();

        match key {
            "server_port" => {
                result.server_port = value.parse().unwrap_or_default();
            }
            "user_data_path" => {
                result.user_data_path = value.to_string();
            }
            "rally_point_port" => {
                result.rally_point_port = value.parse().unwrap_or_default();
            }
            _ => {}
        }

        settings.insert(key.to_string(), value.to_string());
    }

    Arc::new(result)
}
