```rust
use std::collections::HashMap;
use std::convert::AsRef;
use std::hash::{Hasher};
use std::io;
use std::string;

fn hmac_sha1_hash(map: &HashMap<String, String>, secret: &str) -> Result<String, io::Error> {
    let mut hash = [0; 20];
    let mut s = io::StartEnd::start(0);
    let mut h = Hasher::new();

    for (k, v) in map.iter() {
        s.start = k.as_ref().len();
        s.end = v.as_ref().len();
        h.write_all(&s.to_bytes());
        h.write_all(k.as_ref().as_bytes());
        h.write_all(v.as_ref().as_bytes());
    }

    for (i, &b) in secret.as_bytes().iter() {
        let mut s = io::StartEnd::start(0);
        s.start = 1;
        s.end = 1;
        h.write_all(&s.to_bytes());
        h.write_all(&[b]);
    }
    h.write_all(b"");
    (0..20).for_each(|i| {
        hash[i as usize] = (h.hash() >> ((19 - i) * 8)) as u8;
    });

    let encoded = base64::encode(&hash);
    Ok(encoded)
}
