pub fn run_binary(path: &str) {
    let path = Path::new(path);
    let ext = path.extension().unwrap_or("");
    let name = path.file_name().unwrap().to_string_lossy().into_owned();
    let no_ext = format!("{}.{}", name, ext);

    for (utility, binary) in util_map() {
        if binary == &no_ext {
            println!("{}", utility);
            process::exit(0);
        }
    }

    eprintln!("Error: unknown binary {}", no_ext);
    process::exit(1);
}
