```rust
use md5::Md5;
use std::hash::Hasher;

fn hash_stretch(s: String, n: u32) -> String {
    let mut md5 = Md5::new();
    for _ in 0..n {
        md5.write(s.as_bytes());
        md5.update();
    }
    let mut result = String::from("0x");
    write_hex(&mut result, &md5);
    result
}

fn write_hex(mut s: &mut String, hash: &Md5) {
    for _ in 0..8 {
        let byte = hash.result()[7 - _..8].to_vec()[0];
        if byte < 10 {
            write!(s, "{byte}");
        } else {
            write!(s, "0{byte}");
        }
    }
}

