fn generate_pact(pact: &Pact, dir_path: &str) -> String {
    let temp_dir = PathBuf::from(dir_path);
    let temp_file_path = temp_dir.join("pact.json");

    let serialized_pact = serde_json::to_string_pretty(pact).unwrap();

    fs::create_dir_all(&temp_dir).expect("Failed to create directory");
    fs::write(temp_file_path, &serialized_pact).expect("Failed to write file");

    let contents = fs::read_to_string(temp_file_path).expect("Failed to read file");
    fs::remove_dir_all(temp_dir).expect("Failed to remove temporary directory");

    contents
}
