}

impl TempDir {
    fn new() -> io::Result<Self> {
        let temp_dir = env::temp_dir();
        let mut dir_path = temp_dir.clone();
        dir_path.push("tmp");
        fs::create_dir(&dir_path)?;
        Ok(TempDir { path: dir_path })
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        if let Err(_) = fs::remove_dir_all(&self.path) {
            eprintln!("Failed to remove directory: {}", self.path.display());
        }
    }
