use std::fs::File;
use std::io::{Read, BufReader};
use std::path::Path;
use md5::{Md5, Md5Result};

struct FileMetadata {
    name: String,
    path: String,
    size: u64,
    hash: String,
}

fn get_file_metadata(path: &str) -> FileMetadata {
    let path = Path::new(path);
    let file = File::open(&path).expect("Unable to open the file");
    let mut buffer = BufReader::new(file);
    let mut contents = String::new();
    buffer.read_to_string(&mut contents)
        .expect("Failed to read the file contents");
    let hash = Md5::digest(contents.as_bytes()).to_hex();

    FileMetadata {
        name: path.file_name().unwrap().into(),
        path: path.display().to_string(),
        size: file.metadata().unwrap().len() as u64,
        hash,
    }
}

