use std::process;
use std::time::{Duration, Instant};
use sysinfo::{System, SystemExt};
use synclazy::{SyncLazy, lazy_init};

fn rustc_compile() -> i32 {
    let start = Instant::now();
    let mut system = System::new_all();

    let (before_rs_size, _) = system.virtual_memory().get_resident_set_size();

    SyncLazy::init("rustc_logger", || {
        // This is the custom logging hook
        move |input| {
            println!("Custom log: {}", input);
        }
    });

    let exit_code = rustc_driver::catch_with_exit_code(|_compiler| {
        let result = process::Command::new("rustc")
            .arg("-Zcustom-logging-hook")
            .output()
            .expect("Failed to execute process");
        i32::from(result.status())
    })
    .map_err(|e| early_error!("Error while compiling: {}", e))
    .unwrap_or_else(|e| {
        panic!("Rustc compilation failed: {}", e);
    });

    let end = Instant::now();
    let (after_rs_size, _) = system.virtual_memory().get_resident_set_size();

    println!("Compilation took: {} seconds", Duration::from_millis(end.as_millis() - start.as_millis()));
    println!("Resident set size before compilation: {}", before_rs_size);
    println!("Resident set size after compilation: {}", after_rs_size);

    exit_code
}
