import os
import sys

def swap_file_contents(*args):
    non_atomic = False
    for arg in args:
        if arg.startswith('-'):
            if arg == '-h':
                print('Help message')
                exit()
            elif arg == '--version':
                print('Version information')
                exit()
            elif arg == '--non-atomic':
                non_atomic = True
        else:
            if len(args) < 2:
                print('Error: Missing file path')
                exit(1)
            paths = [os.path.abspath(p) for p in args]
            try:
                with open(paths[0], 'r') as f1, open(paths[1], 'w') as f2:
                    if not non_atomic:
                        os.replace(f1.name, f2.name)
                    else:
                        f2.write(f1.read())
                print('File contents swapped successfully')
            except (IOError, OSError) as e:
                print(f'Error: {e}')
                exit(1)

