struct IrcConfig {
    server: String,
    port: u16,
    nick: String,
}

#[derive(Serialize, Deserialize)]
struct BotConfig {
    token_file_path: String,
}

async fn load_config(token_file_path: &str) -> (IrcConfig, HashMap<String, String>) {
    let config_path = Path::new("config.toml");
    let mut tokio_runtime = tokio::runtime::Runtime::new().unwrap();
    let config_result = tokio::fs::read_to_string(config_path).await.unwrap();
    let irc_config: IrcConfig = toml::from_str(&config_result).unwrap();

    let token_file = PathBuf::from(token_file_path);
    let mut file_contents = String::new();
    tokio::fs::File::open(token_file)
        .await
        .unwrap()
        .read_to_string(&mut file_contents)
        .await
        .unwrap();

    let bot_config: BotConfig = toml::from_str(&file_contents).unwrap();
    let mut config_map = HashMap::new();
    config_map.insert("irc_server".to_string(), irc_config.server.clone());
    config_map.insert("irc_port".to_string(), irc_config.port.to_string());
    config_map.insert("token_file_path".to_string(), bot_config.token_file_path.clone());

    (irc_config, config_map)
}
