use std::path::{Path, PathBuf};
use std::fs::remove_file;

fn create_wallet(config_value: &str) -> Result<PathBuf, std::io::Error> {
    let directory_name = format!("wallet_{}", config_value);
    let wallet_path = Path::new(&directory_name);

    if wallet_path.exists() {
        remove_file(wallet_path)?;
    }

    Path::create(directory_name.as_ref())?;

    let private_key_file = Path::new("private_key");
    let mut path = PathBuf::from(wallet_path);
    path.extend(private_key_file);

    path.touch()?; // This might not be the best way to create a file, depending on your needs

    Ok(path)
}

