use std::fs::{OpenOptions, Pipe};
use std::io::{Read, Write};
use std::thread;

fn process_pipe_data() {
    let (mut read_pipe, mut write_pipe) = Pipe::open().unwrap();

    thread::spawn(move || {
        loop {
            let mut buffer = [0; 1024];
            match read_pipe.read(&mut buffer) {
                Ok(0) => break,
                Err(_) => return,
                Ok(n) => {
                    // Process the buffer
                    for i in 0..n {
                        if buffer[i] % 2 == 0 {
                            buffer[i] = buffer[i].wrapping_add(1);
                        }
                    }

                    match write_pipe.write(&buffer[..]) {
                        Ok(_) => {}
                        Err(_) => return,
                    }
                }
            }
        }
    });

    // Do something else
}
