use std::io;
use tokio_tls::{connect, TlsConnector, TlsConnectorBuilder};
use redis::RedisError;

async fn create_tls_connector(address: &str, handle: i32, client: &mut io::Cursor<String>, disable_cert_verify: bool) -> Result<TlsConnectorAsync, RedisError> {
    let mut builder = TlsConnectorBuilder::new();

    if !disable_cert_verify {
        builder.danger_accept_invalid_certs(false)?;
    } else {
        builder.danger_accept_invalid_certs(true)?;
    }

    let connector = builder.build();

    connect(address, handle, client).await.map_err(|e| RedisError::new("Failed to establish TLS connection".to_string(), e))?;
    Ok(connector)
}

