fn fold_header(line_length: usize, s: &str) -> String {
    let mut lines = vec![];
    let mut line = String::new();

    for c in s.chars() {
        if line.len() + 1 + c.len_utf8() > line_length {
            lines.push(line.clone());
            line.clear();
            line.push_str(&c.to_string());
        } else {
            line.push(c);
        }
    }

    if !line.is_empty() {
        lines.push(line);
    }

    let mut folded = String::new();

    for (i, line) in lines.iter().enumerate() {
        folded.push_str(line);
        if i < lines.len() - 1 {
            folded.push('\n');
        }
    }

    folded
}

