def add_command_group(commands):
    from argparse import ArgumentParser
    parser = ArgumentParser()
    group = parser.add_argument_group('new_group')
    def echo_exec(cmd):
        def execute(s):
            return cmd(s)
        return execute
    echo_cmd = group.add_argument('--echo', type=str, help='Echo command', action=echo_exec(parser.parse_args))
    commands[:] = [group]
    commands.initialized = True
    return commands

