use reqwest;
use reqwest::header;
use openssl::ssl::{Certificate, X509};
use std::path::Path;

fn create_custom_reqwest_client(user_agent: &str, connection_header_value: &str, certificate_path: &str) -> reqwest::Client {
    let mut certificates = Vec::new();
    if Path::new(certificate_path).exists() {
        let cert_data = std::fs::read_to_string(certificate_path).unwrap();
        let cert = Certificate::from_pem(cert_data.as_bytes()).unwrap();
        certificates.push(cert);
    }
    let tls_config = reqwest::transport::TLSConfiguration {
        default_root_certificates: certificates,
        ..Default::default()
    };
    let client = reqwest::blocking::Client::builder()
        .timeout(reqwest::time::Duration::from_millis(5000))
        .user_agent(user_agent)
        .connect_timeout(std::time::Duration::from_milliseconds(1000))
        .connection_header(header::ConnectionValue(connection_header_value.to_string()))
        .tls_config(tls_config)
        .build()
        .unwrap();
    client
}

fn open_file(path: &str) -> Option<&'static str> {
    let mut browser = std::env::var("BROWSER").ok();
    if let Some(ref path) = *browser {
        return Some(path);
    }
    let alternatives = ["xdg-open", "open", "start", "kio_open"];
    for cmd in alternatives {
        if path.starts_with(cmd) {
            return Some(cmd);
        }
    }
    None
}

