use std::io;
use std::net::SocketAddr;
use tls::{TlsConnector, TlsStream};
use url::Url;

pub fn establish_secure_connection(
    host: &str,
    port: u16,
    verify: bool,
    nodelay: bool,
) -> io::Result<TlsStream<io::BufReader<io::TcpStream>>> {
    let mut connector = TlsConnector::from_memory(1024).unwrap();
    connector.add_root_certificates(&std::fs::read_dir("/path/to/cert/file")?.flatten().collect::<Vec<_>>())?;
    let url = Url::parse("https://{}".format(host))?;
    let socket_addr: SocketAddr = (url.host_str().unwrap(), port).into();

    let stream = io::TcpStream::connect(&socket_addr)?;
    let mut tls_stream = connector.connect(socket_addr, &stream)?;

    if !verify {
        tls_stream.set_verify(None);
    }

    if nodelay {
        tls_stream.set_nodelay(true)?;
    }

    Ok(io::BufReader::new(tls_stream))
}
