use std::process;
use std::path::{Path, PathBuf};
use std::env;

fn parse_command_line(line: &str) -> process::Command {
    let mut command = line.split_once(' ').unwrap_or((&line, ""));
    let cmd = command.0.trim();
    let args = command.1.strip_prefix(" ").unwrap_or("");

    if !cmd.contains('.') && !cmd.starts_with('`') {
        // If the command is not a file or an inline script,
        // it must be a batch file and should be executed with 'cmd'
        process::Command::new("cmd").arg("/c").arg(line).spawn().unwrap()
    } else if let Some(f) = cmd.split_once('.' as char) {
        // If the command is a file, check for wasm suffix
        let (exe, _) = f;
        let flavor = if exe.ends_with("wasm") {"wasm"} else {""};

        process::Command::new(exe).args(args.trim().split(' ').map(|s| s.to_string()).collect())
    } else {
        // If the command is an inline script, execute it directly
        let mut cmd = process::Command::new("sh");
        if flavor == "wasm" {
            cmd.arg("-c").arg(format!("node -p \"require('{}.js').run();\"", line));
        } else {
            cmd.arg("-c").arg(line);
        }
        cmd.spawn().unwrap()
    }
}

