use std::process::{Command, ExitStatus};

fn get_command_for_file(path: &str) -> Result<String, String> {
    let mut commands = vec!["$BROWSER", "xdg-open", "gnome-open", "kde-open"];

    for command in commands {
        if let ExitStatus::Success = Command::new(command)
            .arg(path)
            .status()
            .unwrap_or_else(|_| panic!("Command '{}' failed to execute", command))
        {
            return Ok(command.to_string());
        }
    }

    Err("No command found that can open the file".to_string())
}

