use std::sync::{Arc, Mutex};
use std::thread;
use std::thread::ThreadPoolExecutor;
use std::time::Duration;
use chan::async_channel;

struct DBSupervisor {
    db: Arc<Mutex<i32>>,
}

impl DBSupervisor {
    fn new() -> Self {
        DBSupervisor { db: Arc::new(Mutex::new(0)) }
    }

    fn process_query(&self, query: &str) {
        let mut lock = self.db.lock().unwrap();
        *lock += 1;
        println!("Processed query '{}'", query);
    }
}

struct QueryClient {
    chan: (async_channel<String, i32>, async_channel<i32, String>),
}

impl QueryClient {
    fn new() -> Self {
        let (tx, rx) = async_channel();
        let (query_rx, query_tx) = async_channel();
        QueryClient { chan: (rx, query_tx) }
    }

    fn send_query(&self, query: &str) {
        self.chan.0.send(query.to_string()).unwrap();
    }

    fn receive_result(&self) -> i32 {
        self.chan.1.recv().unwrap()
    }
}

fn main() {
    let pool = ThreadPoolExecutor::new(4);

    let supervisor = Arc::new(Mutex::new(DBSupervisor::new()));

    let client = QueryClient::new();

    thread::spawn(move || {
        for _ in 0..10 {
            let query = format!("Query {}", _);
            client.send_query(&query);

            match pool.execute(move || {
                let mut supervisor = Arc::try_unwrap(supervisor).unwrap();
                let db_supervisor = &mut *supervisor.lock().unwrap();
                db_supervisor.process_query(&query);

                thread::sleep(Duration::from_millis(100));
            }) {
                Ok(_) => println!("Query sent!"),
                Err(err) => panic!("Error processing query: {}", err),
            }
        }
    });

    for _ in 0..10 {
        match client.receive_result() {
            Ok(result) => println!("Result: {}", result),
            Err(err) => panic!("Error receiving result: {}", err),
        }

        thread::sleep(Duration::from_millis(100));
    }
}
